INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('29ad1626-ff99-40ab-ac98-84cfdf6e3644', 'radical', '毛', 'fur', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Apakah Anda ingat radikal rambut? Begitulah, hanya saja sekarang rambutnya menempel di ekor. Namun, hewan biasanya tidak memiliki rambut. Sebaliknya, mereka mempunyai bulu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('29ad1626-ff99-40ab-ac98-84cfdf6e3644', 'Bulu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('042182be-4744-498c-8d6d-2217e15d6012', 'radical', '血', 'blood', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Ada setitik kecil sesuatu di piringmu (皿). "Apa itu?" kamu bertanya. Oh tidak... bintik itu DARAH!!! Saya harap itu darah mimisan yang Anda alami secara tiba-tiba dan bukan darah orang lain. (Pelayan Anda mungkin akan dipecat, btw.) Setidaknya trombosit Anda akan segera menghentikan pendarahan. Haha, mengerti? PLATE-ayo? Lelucon darah Jepang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('042182be-4744-498c-8d6d-2217e15d6012', 'Darah', true) ON CONFLICT DO NOTHING;
