INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1c1e913b-fb28-4809-944e-a7ec62c2d529', 'vocabulary', '丸', '丸', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Vocab kata ini dan kanji yang membuatnya mempunyai arti yang sama: Lingkaran.', 'Vocab kata ini dan kanji yang membuatnya mempunyai arti yang sama: Lingkaran.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1c1e913b-fb28-4809-944e-a7ec62c2d529', 'Lingkaran', true) ON CONFLICT DO NOTHING;
