INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1c1e913b-fb28-4809-944e-a7ec62c2d529', 'まる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c1e913b-fb28-4809-944e-a7ec62c2d529', 'これは、ピカソがえがいた丸です。', 'Ini adalah lingkaran yang dilukis oleh Picasso.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c1e913b-fb28-4809-944e-a7ec62c2d529', 'このちずにかいてある丸はなんですか。', 'Lingkaran apa yang digambar di peta ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c1e913b-fb28-4809-944e-a7ec62c2d529', 'わたしのくろラブは、おどろいて、めが丸になった。', 'Lab hitamku terkejut dan matanya melotot.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d5f55804-f723-4a33-aafb-f57d467eda91', 'vocabulary', '丸い', '丸い', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Dengan い di akhir, Anda bisa menebak bahwa kata ini adalah kata sifat い. Apa versi kata sifat dari kanji 丸? "Lingkaran" menjadi melingkar, bulat atau bulat. Dibandingkan dengan kata serupa lainnya (円), kata ini memiliki tujuan yang lebih umum dan dapat digunakan dengan objek bola 3D juga.', 'Dengan い di akhir, Anda bisa menebak bahwa kata ini adalah kata sifat い. Apa versi kata sifat dari kanji 丸? "Lingkaran" menjadi melingkar, bulat atau bulat. Dibandingkan dengan kata serupa lainnya (円), kata ini memiliki tujuan yang lebih umum dan dapat digunakan dengan objek bola 3D juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d5f55804-f723-4a33-aafb-f57d467eda91', 'Lingkaran', true) ON CONFLICT DO NOTHING;
