INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d5f55804-f723-4a33-aafb-f57d467eda91', 'まるい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5f55804-f723-4a33-aafb-f57d467eda91', '山田さんがつくったのは、丸いおにぎりです。', 'Yang dibuat Yamada adalah onigiri berbentuk bulat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5f55804-f723-4a33-aafb-f57d467eda91', 'ちきゅうは丸い。', 'Bumi itu bulat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5f55804-f723-4a33-aafb-f57d467eda91', 'わたしのかおは丸いとはいいがたい。', 'Saya tidak akan mengatakan bahwa wajah saya bulat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('71b996d8-cb48-4b22-a4ab-31f34a3dfe44', 'vocabulary', '玉', '玉', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Sebagai vocab kanji tunggal pasti kalian pasti tahu kalau kata vocab ini mempunyai arti yang sama dengan kanji induknya: Bola.', 'Sebagai vocab kanji tunggal pasti kalian pasti tahu kalau kata vocab ini mempunyai arti yang sama dengan kanji induknya: Bola.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('71b996d8-cb48-4b22-a4ab-31f34a3dfe44', 'Bola', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('71b996d8-cb48-4b22-a4ab-31f34a3dfe44', 'たま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71b996d8-cb48-4b22-a4ab-31f34a3dfe44', 'うんどうかいで玉入れをしました。', 'Saya bermain lempar bola pada hari olahraga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71b996d8-cb48-4b22-a4ab-31f34a3dfe44', 'ここに、白の玉が九つあります。', 'Ada sembilan bola putih di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71b996d8-cb48-4b22-a4ab-31f34a3dfe44', 'けいとの玉のようなどうぶつをみかけませんでしたか？', 'Pernahkah Anda melihat binatang yang bentuknya seperti bola wol?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4766ec2c-30dd-4e1b-9f7c-94326e847067', 'vocabulary', 'ビー玉', 'ビー玉', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Saat Anda melihat kata katakana, kemungkinan besar itu adalah kata pinjaman luar negeri yang berasal dari tempat lain. Yang ini menarik karena menggabungkan katakana dan kanji! Marmer pertama datang ke Jepang dari Portugal, jadi bagian ビー adalah kependekan dari "vidro", yang berarti "kaca" dalam bahasa Portugis. Pokoknya, jangan sampai terpesona oleh hal itu ビー. Mungkin bayangkan saja marmer favorit Anda berwarna hitam dan kuning seperti lebah.', 'Saat Anda melihat kata katakana, kemungkinan besar itu adalah kata pinjaman luar negeri yang berasal dari tempat lain. Yang ini menarik karena menggabungkan katakana dan kanji! Marmer pertama datang ke Jepang dari Portugal, jadi bagian ビー adalah kependekan dari "vidro", yang berarti "kaca" dalam bahasa Portugis. Pokoknya, jangan sampai terpesona oleh hal itu ビー. Mungkin bayangkan saja marmer favorit Anda berwarna hitam dan kuning seperti lebah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4766ec2c-30dd-4e1b-9f7c-94326e847067', 'Marmer', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4766ec2c-30dd-4e1b-9f7c-94326e847067', 'びーだま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4766ec2c-30dd-4e1b-9f7c-94326e847067', 'ビーだま', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4766ec2c-30dd-4e1b-9f7c-94326e847067', 'ビー玉をつかってゲームをしましょう。', 'Ayo mainkan permainan yang menggunakan kelereng.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4766ec2c-30dd-4e1b-9f7c-94326e847067', 'アメリカではまいとし一月にビー玉をつかったゲームが上手なフランス人がつどうコンテストがあります。', 'Di Amerika, setiap bulan Januari diadakan kontes yang mempertemukan orang-orang Perancis yang pandai kelereng.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4766ec2c-30dd-4e1b-9f7c-94326e847067', 'かれは、けっこんのあかしに一つぶのビー玉をくれた。', 'Dia memberiku satu kelereng sebagai bukti pernikahan kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('37ed09d5-0f90-4c4b-b4ac-74a50193e9e9', 'vocabulary', '玉ねぎ', '玉ねぎ', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'ねぎ berarti "bawang" dalam bahasa Jepang. Tapi, jenis bawangnya berbeda-beda kan? Ini kebetulan adalah "bawang bombay", yang merupakan salah satu bawang bombay berbentuk bulat, seperti Bawang Manis Walla Walla. Tahukah kamu?', 'ねぎ berarti "bawang" dalam bahasa Jepang. Tapi, jenis bawangnya berbeda-beda kan? Ini kebetulan adalah "bawang bombay", yang merupakan salah satu bawang bombay berbentuk bulat, seperti Bawang Manis Walla Walla. Tahukah kamu?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('37ed09d5-0f90-4c4b-b4ac-74a50193e9e9', 'Bawang', true) ON CONFLICT DO NOTHING;
