INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('37ed09d5-0f90-4c4b-b4ac-74a50193e9e9', 'たまねぎ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37ed09d5-0f90-4c4b-b4ac-74a50193e9e9', '玉ねぎをきっていたら、なみだが出てきた。', 'Saat saya memotong bawang, saya menangis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37ed09d5-0f90-4c4b-b4ac-74a50193e9e9', 'この玉ねぎを立たせることができたあなたは天才です。', 'Pasti kamu jenius kalau bisa membuat bawang ini berdiri sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37ed09d5-0f90-4c4b-b4ac-74a50193e9e9', 'きみは玉ねぎをいくつわきにはさめるかい？', 'Berapa banyak bawang yang bisa Anda pegang di bawah ketiak?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4267a1b0-168b-4622-b107-966bcd15ebb5', 'vocabulary', '目玉', '目玉', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Apa itu bola mata? Oh tunggu, itu mudah. Itu bola mata!', 'Apa itu bola mata? Oh tunggu, itu mudah. Itu bola mata!') ON CONFLICT (id) DO NOTHING;
