INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4267a1b0-168b-4622-b107-966bcd15ebb5', 'めだま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4267a1b0-168b-4622-b107-966bcd15ebb5', 'このじゃがいもを、ゆきだるまの目玉にします。', 'Saya akan menggunakan kentang ini untuk bola mata manusia salju.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4267a1b0-168b-4622-b107-966bcd15ebb5', '王女は目玉をコレクションするしゅみがあります。', 'Hobi sang putri adalah mengoleksi bola mata.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4267a1b0-168b-4622-b107-966bcd15ebb5', 'ようかいの目玉のようなぶどうだとおもう。', 'Menurutku buah anggur ini terlihat seperti bola mata monster.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('73a94eb1-82b4-49f1-9e91-151ac7f5a43e', 'vocabulary', '戸口', '戸口', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Apakah Anda ingat kata 出口 (keluar) dan 入り口 (pintu masuk) dari level sebelumnya?口 bisa menjadi semacam pintu keluar masuk. Kata ini secara harfiah berarti "mulut pintu" tapi saya yakin Anda bisa mengetahui bahwa ini sebenarnya berarti pintu keluar masuk.', 'Apakah Anda ingat kata 出口 (keluar) dan 入り口 (pintu masuk) dari level sebelumnya?口 bisa menjadi semacam pintu keluar masuk. Kata ini secara harfiah berarti "mulut pintu" tapi saya yakin Anda bisa mengetahui bahwa ini sebenarnya berarti pintu keluar masuk.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('73a94eb1-82b4-49f1-9e91-151ac7f5a43e', 'Pintu masuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('73a94eb1-82b4-49f1-9e91-151ac7f5a43e', 'とぐち', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73a94eb1-82b4-49f1-9e91-151ac7f5a43e', '戸口に手ぶくろがおちていました。', 'Sebuah sarung tangan dijatuhkan di ambang pintu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73a94eb1-82b4-49f1-9e91-151ac7f5a43e', 'たまたま、戸口でぬすみぎきしてしまったんです。', 'Saya mengupingnya di ambang pintu secara tidak sengaja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73a94eb1-82b4-49f1-9e91-151ac7f5a43e', '戸口に三枚のトーストがあった。', 'Ada tiga potong roti panggang di ambang pintu saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5549e86c-ded8-4b39-90a0-4ee86c705ffd', 'vocabulary', '毛', '毛', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
