INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5549e86c-ded8-4b39-90a0-4ee86c705ffd', 'あしの毛がボーボーです。', 'Bulu kakiku lebat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5549e86c-ded8-4b39-90a0-4ee86c705ffd', 'うちの犬の毛はよくぬける。', 'Bulu anjing kami banyak rontok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5549e86c-ded8-4b39-90a0-4ee86c705ffd', '今一ばん大切なのはあたまの毛だ。', 'Saat ini hal terpenting bagi saya adalah rambut di kepala saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d7065715-2a64-414b-8753-964d29f48153', 'vocabulary', '竹の子', '竹の子', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Apa itu anak bambu? Itu akan menjadi bayi bambu. Karena "bayi bambu" tidak terlalu masuk akal, kami menyebutnya dengan kata rebung. P.S. Rebung segar yang dimasak di atas api memang enak, pastikan Anda mencobanya kapan-kapan.', 'Apa itu anak bambu? Itu akan menjadi bayi bambu. Karena "bayi bambu" tidak terlalu masuk akal, kami menyebutnya dengan kata rebung. P.S. Rebung segar yang dimasak di atas api memang enak, pastikan Anda mencobanya kapan-kapan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d7065715-2a64-414b-8753-964d29f48153', 'Rebung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d7065715-2a64-414b-8753-964d29f48153', 'Bamboo Sprout', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d7065715-2a64-414b-8753-964d29f48153', 'たけのこ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d7065715-2a64-414b-8753-964d29f48153', '竹の子をゆでているところです。', 'Saya sedang merebus rebung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d7065715-2a64-414b-8753-964d29f48153', 'ふじ山の入り口から北の方にのぼっていくと、と中に竹の子が山のようにとれるところがあります。', 'Jika Anda pergi ke utara dari pintu masuk Gunung Fuji, ada tempat di mana Anda bisa menggali banyak rebung di sepanjang jalan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d7065715-2a64-414b-8753-964d29f48153', '「あ、お兄さん。わかりました。わかりました。竹の子、好きなだけ持って行ってください。」とパンダが言った。', 'Ambil semua rebung yang kamu mau,” kata panda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7b4c6680-4474-46e8-ad06-43951f52f3a4', 'vocabulary', '竹', '竹', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna!', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7b4c6680-4474-46e8-ad06-43951f52f3a4', 'Bambu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7b4c6680-4474-46e8-ad06-43951f52f3a4', 'たけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b4c6680-4474-46e8-ad06-43951f52f3a4', 'このおはしは竹でできています。', 'Sumpit ini terbuat dari bambu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b4c6680-4474-46e8-ad06-43951f52f3a4', '竹は、一メートルぐらいのたかさまで切ってしまうと、ねまでかれてしまいます。', 'Jika bambu ditebang setinggi sekitar satu meter, bambu tersebut akan mati bahkan akarnya pun layu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b4c6680-4474-46e8-ad06-43951f52f3a4', '竹細工が本当に好きなんだ！うちのテレビも俺が竹から作ったんだよ。まあ、動かないけどね。でも、見た目がいいんだよ。', 'Saya suka bekerja dengan bambu! Saya membuat televisi saya dari bambu. Itu tidak berhasil, tapi kelihatannya bagus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('57c58a34-c0d5-4768-8665-b252ff8dd564', 'vocabulary', '糸', '糸', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('57c58a34-c0d5-4768-8665-b252ff8dd564', 'Benang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('57c58a34-c0d5-4768-8665-b252ff8dd564', 'いと', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('57c58a34-c0d5-4768-8665-b252ff8dd564', '糸は、ここにまいてください。', 'Tolong gulung benangnya di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('57c58a34-c0d5-4768-8665-b252ff8dd564', 'うんめいの赤い糸をしんじますか？', 'Apakah Anda percaya pada benang merah takdir?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('57c58a34-c0d5-4768-8665-b252ff8dd564', '私は足の傷口を縫うのに針と糸を使った。', 'Saya menggunakan jarum dan benang untuk menjahit luka di kaki saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', 'vocabulary', '虫', '虫', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Kata ini sebenarnya lebih umum daripada kata dalam bahasa Inggris, Insect and Bug. Ini mencakup hal-hal seperti cacing dan laba-laba juga, jadi dalam hal ini lebih seperti binatang merayap yang menyeramkan.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Kata ini sebenarnya lebih umum daripada kata dalam bahasa Inggris, Insect and Bug. Ini mencakup hal-hal seperti cacing dan laba-laba juga, jadi dalam hal ini lebih seperti binatang merayap yang menyeramkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', 'Serangga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', 'Insect', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', 'Creepy Crawly', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', 'むし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', '虫はにが手です。', 'Saya tidak suka serangga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', 'あの虫、口から白い糸をはいているよ！', 'Serangga itu mengeluarkan benang putih dari mulutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('00165c1b-2ef0-4887-8d68-db911b08eed2', 'ううん。その虫は噛まないよ。でも、もし君がそれでもそいつを殺すって言うなら、僕が君のことを噛むよ。', 'Tidak, serangga itu tidak menggigit. Namun, aku akan menggigitmu jika kamu masih membunuhnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eabc9c76-05ca-4895-8687-728b556eed26', 'vocabulary', '村', '村', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
