INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('eabc9c76-05ca-4895-8687-728b556eed26', 'Rural Town', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('eabc9c76-05ca-4895-8687-728b556eed26', 'むら', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eabc9c76-05ca-4895-8687-728b556eed26', 'ちかくに村があります。', 'Ada sebuah desa di dekatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eabc9c76-05ca-4895-8687-728b556eed26', 'あなたのお母さんはこの村で生まれたのよ。', 'Ibumu lahir di desa ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eabc9c76-05ca-4895-8687-728b556eed26', 'ええ、私はあなたの村で一度本当に馬糞を踏んでしまったんです。', 'Ya, saya pasti pernah menginjak kotoran kuda di desa Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3e92a024-6b03-4b23-b529-144056501e3b', 'vocabulary', '村人', '村人', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Anda memiliki orang desa. Itu bukanlah seseorang yang menari sambil mengenakan pakaian pekerja konstruksi, itu adalah penduduk desa.', 'Anda memiliki orang desa. Itu bukanlah seseorang yang menari sambil mengenakan pakaian pekerja konstruksi, itu adalah penduduk desa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3e92a024-6b03-4b23-b529-144056501e3b', 'Penduduk desa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3e92a024-6b03-4b23-b529-144056501e3b', 'むらびと', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3e92a024-6b03-4b23-b529-144056501e3b', '村人は、年よりばかりです。', 'Penduduk desa semuanya adalah orang tua.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3e92a024-6b03-4b23-b529-144056501e3b', 'なんかファンタジーゲームの村人っぽいセリフだよね。', 'Kalimat itu seperti sesuatu yang diucapkan penduduk desa di game fantasi, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3e92a024-6b03-4b23-b529-144056501e3b', '悲観主義者は「もうコップ半分しかない」と言うが、その村人は「おかわり！」と言って私を驚かせた。', 'Orang yang pesimis berkata, “gelasnya setengah kosong,” tapi penduduk desa mengejutkan saya dengan berteriak “Isi ulang!”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b57368d2-b1f4-4bf3-933c-1af1eb7307c2', 'vocabulary', '貝', '貝', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
