INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b57368d2-b1f4-4bf3-933c-1af1eb7307c2', 'Clam', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b57368d2-b1f4-4bf3-933c-1af1eb7307c2', 'かい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b57368d2-b1f4-4bf3-933c-1af1eb7307c2', 'かえりに、貝をかってきましょうか。', 'Haruskah saya membeli kerang dalam perjalanan pulang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b57368d2-b1f4-4bf3-933c-1af1eb7307c2', '貝るいやこうかくるいをたべると、からだがかゆくなります。', 'Badan saya gatal kalau makan kerang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b57368d2-b1f4-4bf3-933c-1af1eb7307c2', '私は、牡蠣の貝殻の中に置かれていることに気付かずに、婚約指輪を飲み込んでしまった。', 'Saya menelan cincin pertunangan saya karena saya tidak memperhatikan dia memasukkannya ke dalam cangkang tiram.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e158abf4-4153-4435-89af-9dbaebb6dd48', 'vocabulary', '中央', '中央', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bagian tengah dari pusat... yang benar-benar berada di tengah jika Anda bertanya kepada saya (dan juga sangat sentral). Ini adalah salah satu kata yang "berlebihan dalam arti".', 'Bagian tengah dari pusat... yang benar-benar berada di tengah jika Anda bertanya kepada saya (dan juga sangat sentral). Ini adalah salah satu kata yang "berlebihan dalam arti".') ON CONFLICT (id) DO NOTHING;
