INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e158abf4-4153-4435-89af-9dbaebb6dd48', '中央に立っているのが、田中さんのおねえさんです。', 'Itu adalah kakak perempuan Tanaka yang berdiri di tengah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e158abf4-4153-4435-89af-9dbaebb6dd48', '大さかえきの、中央かいさつ口でまっています。', 'Saya menunggu Anda di gerbang tiket pusat stasiun Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e158abf4-4153-4435-89af-9dbaebb6dd48', '私の頭の中央部分には小さな凹みがある。', 'Ada sedikit penyok di bagian tengah kepalaku.') ON CONFLICT DO NOTHING;
