INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d860ce9c-a1d3-4036-b9e4-bb9095662626', 'タピオカミルクティーを氷ぬきでちゅう文した。', 'Saya memesan bubble tea tanpa es.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d860ce9c-a1d3-4036-b9e4-bb9095662626', '「どうしてあの女は俺のグラスに氷を入れるのを忘れたんだ？」「彼女は今日自動車にひかれたんです。きっと飲み物を作っている時にまだふらふらしていたんだと思います。」', '"Kenapa wanita itu lupa menaruh es di gelasku?" "Dia ditabrak mobil tadi hari. Dia pasti masih sedikit pusing saat membuatkan minumanmu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd21c0ed-2f3a-478e-8aca-bf515c2c9c21', 'vocabulary', 'かき氷', 'かき氷', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Ini es かき, yaitu es serut.', 'Ini es かき, yaitu es serut.') ON CONFLICT (id) DO NOTHING;
