INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd21c0ed-2f3a-478e-8aca-bf515c2c9c21', 'かき氷は、あついなつによくたべられます。', 'Saya banyak makan es serut di musim panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd21c0ed-2f3a-478e-8aca-bf515c2c9c21', 'この赤いシロップがかかったかき氷はトマトあじです。', 'Es serut dengan sirup merah ini rasa tomat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd21c0ed-2f3a-478e-8aca-bf515c2c9c21', '世界で一番いい気分になる時は、嫌いなやつに冷たいかき氷をぶちまけてやった時だよ。', 'Perasaan terbaik di dunia adalah ketika kamu melemparkan es serut super dingin dengan sirup pada seseorang yang kamu benci.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf2543b2-7e79-47f6-a2c3-91cf9578975d', 'vocabulary', '皮', '皮', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
