INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf2543b2-7e79-47f6-a2c3-91cf9578975d', 'らく天で、天ねんの牛の皮でできた小さいラグをかった。', 'Saya membeli permadani kecil dari kulit sapi alami di Rakuten.') ON CONFLICT DO NOTHING;
