INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a0251f63-ba68-4ad3-83a8-64c0c058c45e', 'あとは、この竹の子を皿にもりつければかんせいです。\(*皿* ) ', 'Susun rebung ini di atas piring dan selesai! \(*皿* )') ON CONFLICT DO NOTHING;
