INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1d5242d-4bc5-4e4a-a3e3-620e9ab4e88a', '小皿をテーブルにならべてください。', 'Silakan letakkan piring-piring kecil di atas meja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1d5242d-4bc5-4e4a-a3e3-620e9ab4e88a', 'かくじ、小皿にとり分けてたべましょう。', 'Mengapa kita tidak menyajikan makanan di piring kecil saja dan makan sesuai keinginan kita sendiri?') ON CONFLICT DO NOTHING;
