INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d779a9c1-4c70-44ca-abf5-a26e1390ab9f', 'はね', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d779a9c1-4c70-44ca-abf5-a26e1390ab9f', '小とりは、羽をパタパタうごかしました。', 'Burung kecil itu mengepakkan sayapnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d779a9c1-4c70-44ca-abf5-a26e1390ab9f', '手羽先のからあげはたべたことがあるけど、ちょうちょうの羽のからあげはたべたことがありません。', 'Saya pernah makan sayap ayam goreng sebelumnya, tapi saya belum pernah makan sayap kupu-kupu goreng.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d779a9c1-4c70-44ca-abf5-a26e1390ab9f', '「この羽、どの鳥の羽か分かるかな？」と彼は自分の鼻毛を持ちながら聞いてきた。', '“Tahukah kamu jenis burung apa bulu ini?” dia bertanya padaku sambil mengulurkan sebagian bulu hidungnya sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2072a383-8747-476e-a27b-c32b5cc77e7a', 'vocabulary', '皮肉', '皮肉', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kulit dagingnya seperti kulit terluar. Itu tidak terlalu baik, dan orang yang hanya makan kulit daging cenderung menggunakan sarkasme dan ironi. Meski begitu, orang Jepang tidak terlalu memahami sarkasme. Jadi mungkin itu sebabnya "kulit daging" berarti "sarkasme". Apakah ini ironis? Sekarang aku bahkan tidak yakin.', 'Kulit dagingnya seperti kulit terluar. Itu tidak terlalu baik, dan orang yang hanya makan kulit daging cenderung menggunakan sarkasme dan ironi. Meski begitu, orang Jepang tidak terlalu memahami sarkasme. Jadi mungkin itu sebabnya "kulit daging" berarti "sarkasme". Apakah ini ironis? Sekarang aku bahkan tidak yakin.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2072a383-8747-476e-a27b-c32b5cc77e7a', 'Ironi', true) ON CONFLICT DO NOTHING;
