INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2072a383-8747-476e-a27b-c32b5cc77e7a', 'ひにく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2072a383-8747-476e-a27b-c32b5cc77e7a', 'まったく皮肉なものですね。', 'Sungguh ironis bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2072a383-8747-476e-a27b-c32b5cc77e7a', 'あの肉やさんは、大した皮肉やだよ。', 'Tukang daging itu adalah orang yang sangat sarkastik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2072a383-8747-476e-a27b-c32b5cc77e7a', '「Ironic」という曲の中に、うまい皮肉はひとつも見当たらなかった。', 'Tidak ada satu hal pun dalam lagu "Ironis" yang merupakan contoh ironi yang tepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('273d6b64-6808-4008-9837-73d55a27e00e', 'vocabulary', '林', '林', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
