INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('273d6b64-6808-4008-9837-73d55a27e00e', 'はやし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('273d6b64-6808-4008-9837-73d55a27e00e', '毎あさ、林をさんぽしています。', 'Setiap pagi saya berjalan di hutan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('273d6b64-6808-4008-9837-73d55a27e00e', '林先生が早足で林をあるいているのを見ちゃった。', 'Saya kebetulan melihat Nyonya Hayashi sedang berjalan cepat di hutan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('273d6b64-6808-4008-9837-73d55a27e00e', '家に帰るまで待てずに、林の中に濡れた靴下を残した。', 'Saya tidak sabar menunggu sampai di rumah, jadi saya meninggalkan kaus kaki saya yang basah di hutan.') ON CONFLICT DO NOTHING;
