INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cce43d5c-2496-46db-bf02-c1aff38422be', '九州のりょうりはおいしいです。', 'Masakan Kyushu enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cce43d5c-2496-46db-bf02-c1aff38422be', '九州までは、フェリーでかた道一じかんです。', 'Dibutuhkan satu jam untuk sampai ke Kyushu dengan feri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cce43d5c-2496-46db-bf02-c1aff38422be', '九州には、綺麗な女性が多い。', 'Ada banyak wanita cantik di Kyushu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d3955edb-f7de-470e-a5bd-18d90130163e', 'vocabulary', '本州', '本州', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Anda memiliki negara asal Anda. Bagi Jepang (karena ini adalah kata dalam bahasa Jepang), itu adalah pulau utama, pulau besar di tengah: Honshu. Anda harus mengetahui sedikit geografi Jepang untuk ini. Lihatlah peta Jepang dan pelajari dengan cepat untuk mengetahui di mana saya bicarakan jika Anda belum mengetahuinya.', 'Anda memiliki negara asal Anda. Bagi Jepang (karena ini adalah kata dalam bahasa Jepang), itu adalah pulau utama, pulau besar di tengah: Honshu. Anda harus mengetahui sedikit geografi Jepang untuk ini. Lihatlah peta Jepang dan pelajari dengan cepat untuk mengetahui di mana saya bicarakan jika Anda belum mengetahuinya.') ON CONFLICT (id) DO NOTHING;
