INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d3955edb-f7de-470e-a5bd-18d90130163e', '本州とは、いったいぜんたい日本のどこにあるんですか？', 'Dimana sih Honshu di Jepang?') ON CONFLICT DO NOTHING;
