INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dde49c8d-b48a-42ad-b734-393175a35fbc', 'なかなか出血が止まりません。', 'Pendarahannya tidak berhenti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dde49c8d-b48a-42ad-b734-393175a35fbc', 'トーフグはぜっさん出血大サービス中です。', 'Tofugu memberi Anda diskon besar!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dde49c8d-b48a-42ad-b734-393175a35fbc', '指を抜いていれば、鼻からの出血は止まると思います。', 'Saya pikir hidung saya akan berhenti mengeluarkan darah jika saya tidak mengeluarkan jari saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9f81de35-b015-452d-9286-3618c8f2937e', 'vocabulary', '星', '星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
