INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9f81de35-b015-452d-9286-3618c8f2937e', '夜には、星がとてもきれいでした。', 'Malam itu bintang-bintang sangat cantik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9f81de35-b015-452d-9286-3618c8f2937e', '今夜はたくさんながれ星が見れるといいんですが。', 'Saya harap kita bisa melihat banyak bintang jatuh malam ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9f81de35-b015-452d-9286-3618c8f2937e', 'お父さん、どうして今日は星型のメガネをかけているの？', 'Ayah, kenapa hari ini ayah memakai kacamata berbentuk bintang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f60645fc-afee-4dcc-9925-7e51472ca593', 'vocabulary', '〜札', '〜札', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya hampir persis sama. Jika Anda melihat kata ini setelah angka, itu berarti uang kertas fisik.', 'Kanji dan kata-katanya hampir persis sama. Jika Anda melihat kata ini setelah angka, itu berarti uang kertas fisik.') ON CONFLICT (id) DO NOTHING;
