INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f60645fc-afee-4dcc-9925-7e51472ca593', '一万円札を小ぜににくずしてもらえませんか？', 'Bisakah Anda memberi saya kembalian uang 10.000 yen?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f60645fc-afee-4dcc-9925-7e51472ca593', 'この二千円札、千円札二枚と両がえしてくれない？', 'Bisakah Anda membagi uang 2.000 yen ini menjadi dua lembar uang 1.000 yen?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f60645fc-afee-4dcc-9925-7e51472ca593', 'トーフグのオフィスのあちこちに、百ドル札が隠されているらしいぜ。', 'Rupanya, ada banyak uang kertas ratusan dolar yang disembunyikan di seluruh kantor Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aa0606aa-1650-40bd-8d2a-b8298d5508b3', 'vocabulary', '千円札', '千円札', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Anda tahu apa itu 千円 (1000 yen). Jadi jika Anda menambahkan tagihan ke dalamnya, Anda mendapatkan tagihan seribu yen. Itu hanyalah uang berbentuk persegi kecil yang bernilai 1.000 yen.', 'Anda tahu apa itu 千円 (1000 yen). Jadi jika Anda menambahkan tagihan ke dalamnya, Anda mendapatkan tagihan seribu yen. Itu hanyalah uang berbentuk persegi kecil yang bernilai 1.000 yen.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aa0606aa-1650-40bd-8d2a-b8298d5508b3', 'Uang Seribu Yen', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aa0606aa-1650-40bd-8d2a-b8298d5508b3', 'Thousand Yen Note', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('aa0606aa-1650-40bd-8d2a-b8298d5508b3', 'せんえんさつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa0606aa-1650-40bd-8d2a-b8298d5508b3', '千円札のおつりが不足しています。', 'Saya tidak punya uang kembalian untuk uang seribu yen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa0606aa-1650-40bd-8d2a-b8298d5508b3', 'これは、水そうから紙のひしゃくで千円札をすくうゲームです。', 'Ini adalah permainan di mana Anda mengambil uang ribuan yen dengan sendok kertas dari tangki air.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa0606aa-1650-40bd-8d2a-b8298d5508b3', '「千ドル札を燃やしてるの？」「いや、ただの千円札だよ。」', '"Apakah kamu membakar uang seribu dolar?" "Tidak, ini hanya uang seribu yen."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c1985741-dca9-4178-b2fa-bb1acf3a2c40', 'vocabulary', '辺り', '辺り', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Ini adalah versi kata benda dari kanji untuk area. Hal ini membuatnya memiliki arti yang sama dengan kanji: area, sekitar, atau lingkungan.', 'Ini adalah versi kata benda dari kanji untuk area. Hal ini membuatnya memiliki arti yang sama dengan kanji: area, sekitar, atau lingkungan.') ON CONFLICT (id) DO NOTHING;
