INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1985741-dca9-4178-b2fa-bb1acf3a2c40', '辺りはしーんとしずまりかえっていた。', 'Daerah itu menjadi sunyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1985741-dca9-4178-b2fa-bb1acf3a2c40', 'そうだ、ちょっと言いわすれていたんだけど、この辺りにえきはないからね。', 'Oh, aku lupa memberitahumu bahwa tidak ada stasiun di lingkungan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c1985741-dca9-4178-b2fa-bb1acf3a2c40', '彼のトイレはこの辺りに違いない。', 'Kamar mandinya pasti ada di sekitar sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9ccd6701-432c-46ae-81d9-703b15d9fb81', 'vocabulary', 'この辺', 'この辺', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'この berarti "ini" jadi この辺 berarti area ini.', 'この berarti "ini" jadi この辺 berarti area ini.') ON CONFLICT (id) DO NOTHING;
