INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d626bcca-9b4e-4f63-8fcc-46ca91aa8ada', 'わたしは、あさに弱いです。', 'Saya bukan orang yang suka bangun pagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d626bcca-9b4e-4f63-8fcc-46ca91aa8ada', 'ユイは体は弱いけど、人のいたみがわかる人げんです。', 'Yui secara fisik lemah, tapi dia adalah orang yang memahami penderitaan orang lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d626bcca-9b4e-4f63-8fcc-46ca91aa8ada', 'インフルエンザにかかると、スーパーマンでさえもとても弱くなります。', 'Bahkan superman menjadi sangat lemah saat terkena flu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('09a3d0a1-489b-4701-81fe-f07f069a79ca', 'vocabulary', '弱点', '弱点', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Titik lemahnya adalah titik lemah Anda.', 'Titik lemahnya adalah titik lemah Anda.') ON CONFLICT (id) DO NOTHING;
