INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09a3d0a1-489b-4701-81fe-f07f069a79ca', 'ついにアイツの弱点を見つけたぜ！', 'Saya akhirnya menemukan titik lemahnya!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09a3d0a1-489b-4701-81fe-f07f069a79ca', 'あの体そうせん手の弱点は、せいかくがじゅうなんせいに欠けているところだ。', 'Kelemahan pesenam itu adalah kepribadiannya yang kurang fleksibel.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09a3d0a1-489b-4701-81fe-f07f069a79ca', '私の従業員としての弱点は、恐らく弱点が一つも無いことです。', 'Kelemahan saya sebagai karyawan mungkin adalah saya tidak mempunyai kelemahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a3a49416-1c1f-4920-b5ee-bb5315c0d077', 'vocabulary', '黄色', '黄色', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Warna kuning hanyalah warna kuning.', 'Warna kuning hanyalah warna kuning.') ON CONFLICT (id) DO NOTHING;
