INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a3a49416-1c1f-4920-b5ee-bb5315c0d077', 'きいろ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a3a49416-1c1f-4920-b5ee-bb5315c0d077', '黄色かみどり色のペンはありますか？', 'Apakah ada pulpen kuning atau hijau?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a3a49416-1c1f-4920-b5ee-bb5315c0d077', 'アメリカのカラスは、美しい黄色の羽をもっていることで有名です。', 'Burung gagak Amerika terkenal dengan keindahan sayap kuningnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a3a49416-1c1f-4920-b5ee-bb5315c0d077', 'もし尿のいろが透明から黄色に変わってしまったら、もっと水を飲んだ方が良いという合図です。', 'Jika urin Anda berubah dari bening menjadi kuning, Anda harus minum lebih banyak air.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('69475bc1-86b7-4050-97a7-5e0fccaa1094', 'vocabulary', '電池', '電池', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kolam untuk listrik? Mungkin tampak aneh pada awalnya, tetapi jika Anda memikirkan sesuatu yang mengumpulkan semua listrik ke dalam satu kolam... benda itu seperti baterai (dan merupakan baterai).', 'Kolam untuk listrik? Mungkin tampak aneh pada awalnya, tetapi jika Anda memikirkan sesuatu yang mengumpulkan semua listrik ke dalam satu kolam... benda itu seperti baterai (dan merupakan baterai).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('69475bc1-86b7-4050-97a7-5e0fccaa1094', 'Baterai', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('69475bc1-86b7-4050-97a7-5e0fccaa1094', 'でんち', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69475bc1-86b7-4050-97a7-5e0fccaa1094', 'このおもちゃの電車は、電池でうごきます。', 'Kereta mainan ini bergerak dengan baterai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69475bc1-86b7-4050-97a7-5e0fccaa1094', 'ママ、見てー！電池が取れちゃった。', 'Bu, lihat! Baterainya lepas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69475bc1-86b7-4050-97a7-5e0fccaa1094', '自作のロボット犬の電池を買いに、ちょっくら町へ行ってくるよ。', 'Saya menuju ke kota untuk membeli baterai untuk robot anjing yang saya buat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('46e8a26f-3af2-4172-aa2b-cadfafc74972', 'vocabulary', '角度', '角度', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Derajat sudut menunjukkan berapa sudutnya. 90 derajat? 160 derajat? Semuanya masih bersudut saat Anda melakukannya.', 'Derajat sudut menunjukkan berapa sudutnya. 90 derajat? 160 derajat? Semuanya masih bersudut saat Anda melakukannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('46e8a26f-3af2-4172-aa2b-cadfafc74972', 'Sudut', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('46e8a26f-3af2-4172-aa2b-cadfafc74972', 'かくど', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46e8a26f-3af2-4172-aa2b-cadfafc74972', 'べつの角度から、もう一度見てみましょう。', 'Mari kita coba melihat lagi dari sudut yang berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46e8a26f-3af2-4172-aa2b-cadfafc74972', 'ピサのしゃとうはたしかにへんな角度で立っている。', 'Menara Miring Pisa memang berdiri pada sudut yang aneh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46e8a26f-3af2-4172-aa2b-cadfafc74972', 'もしマイリー・サイラスが一番好きな歌を歌っているのをこの角度から見ることができたら、俺の夢を叶えてくれたってことで神様の存在を信じると思う。', 'Jika saya bisa melihat Miley Cyrus menyanyikan lagu favorit saya dari sudut ini, saya akan percaya kepada Tuhan karena itu berarti Dia membuat impian saya menjadi kenyataan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('753fb2a9-21d1-475f-965c-692cef95ec68', 'vocabulary', '終了', '終了', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Ini adalah akhirnya. Ini adalah akhir. Kata ini berarti akhir. Atau selesaikan! Betapa nyamannya.', 'Ini adalah akhirnya. Ini adalah akhir. Kata ini berarti akhir. Atau selesaikan! Betapa nyamannya.') ON CONFLICT (id) DO NOTHING;
