INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('753fb2a9-21d1-475f-965c-692cef95ec68', '大さか公えん1日目終了しました！', 'Hari pertama pertunjukan Osaka telah berakhir!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('753fb2a9-21d1-475f-965c-692cef95ec68', '主人公が死んでゲームが終了してしまいました。', 'Karakter utama meninggal dan permainan selesai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('753fb2a9-21d1-475f-965c-692cef95ec68', '「もし私がまたデブになったらどうする？」 「まぁ、俺達の関係が終了しないのは確実だね。」', '“Bagaimana kalau aku jadi gemuk lagi?” “Yah, hubungan kita tidak akan berakhir, itu sudah pasti.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1ed0b625-0477-4dae-9742-6fc94390da14', 'vocabulary', '血族', '血族', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Darah suku Anda (banyak perkawinan sedarah) adalah darah kerabat Anda. Ini adalah saudara sedarah.', 'Darah suku Anda (banyak perkawinan sedarah) adalah darah kerabat Anda. Ini adalah saudara sedarah.') ON CONFLICT (id) DO NOTHING;
