INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('05b5506f-096a-474a-8fd6-7cec34975ce3', 'キャベツに毛虫がついていました。', 'Ada ulat di kubis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('05b5506f-096a-474a-8fd6-7cec34975ce3', '毛虫かと思ったら妹のつけまだった。', 'Kupikir itu ulat bulu, tapi ternyata itu bulu mata palsu adikku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('05b5506f-096a-474a-8fd6-7cec34975ce3', '私は巨大な毛虫と巨大なムカデが戦っているところをビデオに収めた。', 'Saya merekam ulat raksasa melawan kelabang raksasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('477e4bbc-fce7-4d14-9242-0deaf27b0e6d', 'vocabulary', '毛糸', '毛糸', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Ketika Anda memiliki tali bulu (alias tali yang terbuat dari bulu), apa yang Anda pikirkan? Semoga benang wol.', 'Ketika Anda memiliki tali bulu (alias tali yang terbuat dari bulu), apa yang Anda pikirkan? Semoga benang wol.') ON CONFLICT (id) DO NOTHING;
