INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22d9238b-15cb-4d76-b222-3189d9e5fd8c', '宝をどこにかくしたんだ？', 'Di mana kamu menyembunyikan harta karun itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22d9238b-15cb-4d76-b222-3189d9e5fd8c', 'この宝のちず、三ばいにかくだいしてプリントアウトしておいてくれない？', 'Bisakah Anda memperbesar peta harta karun ini tiga kali dan mencetaknya untuk saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22d9238b-15cb-4d76-b222-3189d9e5fd8c', '宝箱に隠しておいたサマージャンボ宝くじがなくなってる！', 'Tiket Lotere Jumbo Musim Panas yang saya sembunyikan di peti harta karun hilang!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('513c59df-2394-4f0d-9deb-0a65ce774d9b', 'vocabulary', '宝石', '宝石', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Batu harta karun adalah batu yang sangat berharga. Jenis batu apa yang dianggap harta karun? Bagaimana dengan permata, atau permata?', 'Batu harta karun adalah batu yang sangat berharga. Jenis batu apa yang dianggap harta karun? Bagaimana dengan permata, atau permata?') ON CONFLICT (id) DO NOTHING;
