INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('513c59df-2394-4f0d-9deb-0a65ce774d9b', 'あの赤い宝石のゆびわは、だれかのわすれものです。', 'Cincin dengan permata merah itu adalah barang milik seseorang yang hilang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('513c59df-2394-4f0d-9deb-0a65ce774d9b', 'あの大ふごうは、メイドに宝石があしらわれたそうじどうぐをつかわせている。', 'Miliarder itu menyuruh pembantunya menggunakan alat pembersih yang dihias dengan permata.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('513c59df-2394-4f0d-9deb-0a65ce774d9b', 'お姫様は美しい宝石のついた腕輪を時計回りに回しました。', 'Sang putri memutar gelang permata indah itu searah jarum jam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0c126e00-93b2-4f37-aac5-2927fe930a56', 'vocabulary', '国宝', '国宝', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Harta suatu negara adalah harta nasionalnya.', 'Harta suatu negara adalah harta nasionalnya.') ON CONFLICT (id) DO NOTHING;
