INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ed7ff16-3188-4655-8bb6-685ca5adf0e1', '彼は弱々しいうなずいて了解の意を示して、立ち去った。', 'Dia mengungkapkan pemahamannya dengan anggukan lemah dan berjalan pergi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', 'vocabulary', '宝くじ', '宝くじ', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', '宝 adalah harta karun. くじ adalah lotere. Jadi jika Anda mempunyai lotere harta karun (Anda memenangkan harta jika Anda memenangkan lotre) maka Anda sendiri mempunyai lotere.', '宝 adalah harta karun. くじ adalah lotere. Jadi jika Anda mempunyai lotere harta karun (Anda memenangkan harta jika Anda memenangkan lotre) maka Anda sendiri mempunyai lotere.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', 'Lotere', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', 'Public Lottery', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', 'Lottery Ticket', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', 'たからくじ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', '「妹が宝くじに当たったのよ。」「すごいね！で、いくら？」「一万円。」', '"Adik perempuanku memenangkan lotre." "Oh keren! Berapa?" “10.000 yen.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', 'きぼうてきかんそくでは、来年あたりに宝くじに当たるはずです。', 'Itu hanya angan-angan saja, tapi saya mungkin akan memenangkan lotre tahun depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ed6b897d-d710-412d-9229-7d18815b9ed6', '父親の秘書が宝くじに当たったんだけど、それをフェイスブックに書いた時に秘書を秘密と書き間違えてしまい、みんなが勘違いしてたくさんおめでとうコメントを残してくれました。', 'Sekretaris ayah saya memenangkan lotre, tetapi saya membuat kesalahan ejaan saat mempostingnya di Facebook. Sekretaris dieja secara diam-diam. Itu membingungkan orang dan saya mendapat banyak ucapan selamat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b8f6015e-027d-4001-8543-48c5a82e087e', 'vocabulary', '髪の毛', '髪の毛', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bulu rambut Anda adalah bulu rambut yang khusus ada di kepala Anda. Itu rambut kepalamu.', 'Bulu rambut Anda adalah bulu rambut yang khusus ada di kepala Anda. Itu rambut kepalamu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b8f6015e-027d-4001-8543-48c5a82e087e', 'Rambut Kepala', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b8f6015e-027d-4001-8543-48c5a82e087e', 'かみのけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b8f6015e-027d-4001-8543-48c5a82e087e', '「ねえ、サーモン。今何してんの？」「髪の毛セットしてるとこ。」「終わったら、ちょっと時間ある？」「無理〜。これが終わったらネイルもしなきゃなの。」', '“Salmon, apa yang kamu lakukan sekarang?” "Aku sedang menata rambutku." “Setelah itu, apakah kamu punya waktu?” "Tidak. Aku harus merapikan kukuku selanjutnya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e0ab4c6f-f55e-48fd-b161-04dd6a0c5e54', 'vocabulary', '水星', '水星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bintang air adalah planet Merkurius. Di situlah kami menyembunyikan semua rahasia air bulan kami. Merkurius terlihat sangat mirip dengan bulan kita, jadi kami menaruhnya di sana agar tidak ada yang bisa menemukannya.', 'Bintang air adalah planet Merkurius. Di situlah kami menyembunyikan semua rahasia air bulan kami. Merkurius terlihat sangat mirip dengan bulan kita, jadi kami menaruhnya di sana agar tidak ada yang bisa menemukannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e0ab4c6f-f55e-48fd-b161-04dd6a0c5e54', 'Merkuri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e0ab4c6f-f55e-48fd-b161-04dd6a0c5e54', 'すいせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0ab4c6f-f55e-48fd-b161-04dd6a0c5e54', '水星には大気がありません。', 'Merkurius tidak memiliki atmosfer.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0ab4c6f-f55e-48fd-b161-04dd6a0c5e54', 'こんなはずじゃなかったんですが、もう十年も水星でホームレスをしています。', 'Ini bukan yang saya minta, tapi saya sudah menjadi tunawisma selama 10 tahun di Merkurius.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0ab4c6f-f55e-48fd-b161-04dd6a0c5e54', '水星は、日の出直前、または日没直後しか見ることができない。', 'Saya hanya bisa melihat Merkurius sebelum matahari terbit dan setelah matahari terbenam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('beeb39ed-e589-4a06-9d90-27cf0142b89b', 'vocabulary', '金星', '金星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bintang emasnya adalah Venus. Ini satu-satunya planet di tata surya kita yang warnanya sama dengan emas.', 'Bintang emasnya adalah Venus. Ini satu-satunya planet di tata surya kita yang warnanya sama dengan emas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('beeb39ed-e589-4a06-9d90-27cf0142b89b', 'Venus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('beeb39ed-e589-4a06-9d90-27cf0142b89b', 'きんせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('beeb39ed-e589-4a06-9d90-27cf0142b89b', 'あそこに見えているのは、金星です。', 'Apa yang Anda lihat di sana adalah Venus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('beeb39ed-e589-4a06-9d90-27cf0142b89b', '金星の学こうには、うんどう会はありますか？', 'Apakah mereka mengadakan Hari Olahraga di sekolah di Venus?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('beeb39ed-e589-4a06-9d90-27cf0142b89b', '人類はいつか金星に移住することになるだろう。', 'Suatu saat manusia akan bermigrasi ke Venus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('22554f34-948a-4b5e-bb43-1511616c77d5', 'vocabulary', '土星', '土星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bintang bumi adalah Saturnus. Itu sebabnya disebut "sat" guci. Karena orang pertama yang menemukannya duduk di tanah sana. Itu adalah bintang yang seluruhnya terbuat dari tanah yang bisa diduduki.', 'Bintang bumi adalah Saturnus. Itu sebabnya disebut "sat" guci. Karena orang pertama yang menemukannya duduk di tanah sana. Itu adalah bintang yang seluruhnya terbuat dari tanah yang bisa diduduki.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('22554f34-948a-4b5e-bb43-1511616c77d5', 'Saturnus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('22554f34-948a-4b5e-bb43-1511616c77d5', 'どせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22554f34-948a-4b5e-bb43-1511616c77d5', 'どれが土星か、分かりますか。', 'Tahukah Anda yang mana Saturnus?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22554f34-948a-4b5e-bb43-1511616c77d5', '土星にはどうやって行けばいいですか？', 'Bagaimana cara menuju Saturnus?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('22554f34-948a-4b5e-bb43-1511616c77d5', '私は土星出身の宇宙人です。', 'Saya alien dari Saturnus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dd0736a6-e13a-4f25-a82b-287113fdeb7f', 'vocabulary', '三角形', '三角形', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Anda telah mengetahui bahwa 三角 berarti "segitiga". Ini artinya segitiga juga, tapi itu istilah matematikanya. Anda harus menggunakannya di kelas matematika.', 'Anda telah mengetahui bahwa 三角 berarti "segitiga". Ini artinya segitiga juga, tapi itu istilah matematikanya. Anda harus menggunakannya di kelas matematika.') ON CONFLICT (id) DO NOTHING;
