INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e421aa8e-a87d-4281-8e46-6e2c98d027be', 'まるごと', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e421aa8e-a87d-4281-8e46-6e2c98d027be', 'わたしは、そのうたを丸ごとあんきしています。', 'Saya menghafal keseluruhan lagunya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e421aa8e-a87d-4281-8e46-6e2c98d027be', 'その牛、半分だけじゃなくて丸ごと一とう下さい。', 'Tolong beri saya seluruh sapi, bukan setengahnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e421aa8e-a87d-4281-8e46-6e2c98d027be', 'このケーキには林檎が丸ごと入っています。', 'Kue ini seluruhnya diisi dengan apel.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cbae7088-526a-4f18-8a7e-c1ce69102288', 'vocabulary', '辺', '辺', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
