INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cbae7088-526a-4f18-8a7e-c1ce69102288', 'その辺に、ホテルはありますか。', 'Apakah ada hotel di sekitar sana?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cbae7088-526a-4f18-8a7e-c1ce69102288', 'あの辺はごう雪地たいです。', 'Mereka mengalami hujan salju yang sangat lebat di wilayah itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cbae7088-526a-4f18-8a7e-c1ce69102288', '今日はこの辺で、終わりにします。', 'Saya akan mengakhirinya di sini untuk hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8ecc3211-0ab9-470c-b6f1-8f2e73deee41', 'vocabulary', '海王星', '海王星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bintang raja lautan adalah Neptunus! Jika Anda mengetahui sesuatu tentang mitologi Romawi, hal ini pasti mudah diingat!', 'Bintang raja lautan adalah Neptunus! Jika Anda mengetahui sesuatu tentang mitologi Romawi, hal ini pasti mudah diingat!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8ecc3211-0ab9-470c-b6f1-8f2e73deee41', 'Neptunus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8ecc3211-0ab9-470c-b6f1-8f2e73deee41', 'かいおうせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ecc3211-0ab9-470c-b6f1-8f2e73deee41', '海王星は、太ようから八ばん目のわく星です。', 'Neptunus adalah planet kedelapan dari matahari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ecc3211-0ab9-470c-b6f1-8f2e73deee41', '海王星に行くことをずっとゆめ見てきたんです。', 'Saya selalu bermimpi pergi ke Neptunus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ecc3211-0ab9-470c-b6f1-8f2e73deee41', '海王星は1846年9月23日に発見されました。', 'Neptunus ditemukan pada tanggal 23 September 1846.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('56f68470-d5e4-4e90-9d4e-69c77355ee56', 'vocabulary', '戸', '戸', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
