INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('56f68470-d5e4-4e90-9d4e-69c77355ee56', '戸をたたかないでください。', 'Tolong jangan mengetuk pintu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('56f68470-d5e4-4e90-9d4e-69c77355ee56', 'うちのねこは戸をカリカリするのがすきです。', 'Kucing saya suka menggaruk pintu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('56f68470-d5e4-4e90-9d4e-69c77355ee56', 'この戸は立てつけがわるい。', 'Pintu ini membuka dan menutup dengan keras.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', 'vocabulary', '札', '札', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Kata ini hampir sama dengan kanji, namun hanya setengahnya saja. Artinya tanda atau jimat. Bentuk dan ukurannya hampir sama dengan uang, tetapi Anda tidak bisa membeli rumah dengan uang tersebut (...mungkin).', 'Kata ini hampir sama dengan kanji, namun hanya setengahnya saja. Artinya tanda atau jimat. Bentuk dan ukurannya hampir sama dengan uang, tetapi Anda tidak bisa membeli rumah dengan uang tersebut (...mungkin).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', 'Tandai', true) ON CONFLICT DO NOTHING;
