INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', 'Label', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', 'Playing Card', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', 'ふだ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', 'このお札は、げんかんのドアの内がわにはっておいてください。', 'Silakan letakkan jimat ini di bagian dalam pintu depan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', '自分の札を見せないようにした方がいいよ。', 'Anda harus berhati-hati untuk tidak menunjukkan tangan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('49ea2b9b-0f75-4c26-9c12-4d8af710c02a', 'ジェロってほんとにキモい。ドクロマークの絵が描かれた札でも付けておくべきだよ。', 'Jello benar-benar menjijikkan. Harus ada gambar tengkorak dan tulang bersilang pada labelnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a6bb16e5-2266-413d-9fb4-b554e91648f5', 'vocabulary', '番号札', '番号札', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Anda tahu 番号 berarti "angka" jadi tambahkan tag padanya dan Anda akan mendapatkan tag bernomor.', 'Anda tahu 番号 berarti "angka" jadi tambahkan tag padanya dan Anda akan mendapatkan tag bernomor.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a6bb16e5-2266-413d-9fb4-b554e91648f5', 'Tag Bernomor', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a6bb16e5-2266-413d-9fb4-b554e91648f5', 'Numbered Ticket', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a6bb16e5-2266-413d-9fb4-b554e91648f5', 'ばんごうふだ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6bb16e5-2266-413d-9fb4-b554e91648f5', '番号札をとって、お待ちください。', 'Silakan ambil tiket bernomor dan tunggu giliran Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6bb16e5-2266-413d-9fb4-b554e91648f5', 'すみません、この辺りに番号札は落ちていませんでしたか？', 'Maaf, bukankah ada tanda nomor yang tertinggal di sekitar sini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6bb16e5-2266-413d-9fb4-b554e91648f5', 'こちらがお客様のお荷物の番号札となります。', 'Ini adalah label bernomor untuk bagasi Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a6546997-b227-43ec-a29c-c073d03a425e', 'vocabulary', '値札', '値札', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Label harga adalah... label harga!', 'Label harga adalah... label harga!') ON CONFLICT (id) DO NOTHING;
