INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a6546997-b227-43ec-a29c-c073d03a425e', 'ねふだ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6546997-b227-43ec-a29c-c073d03a425e', 'この品物には、値札シールがありません。', 'Barang ini tidak memiliki label harga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6546997-b227-43ec-a29c-c073d03a425e', '王様は、いつも値札を見ずに買い物をして、女王様に怒られます。', 'Raja selalu membeli barang tanpa melihat label harganya dan ratu marah padanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a6546997-b227-43ec-a29c-c073d03a425e', '値札を確かめた後に、買うのを止めました。', 'Setelah mengecek label harganya, saya memutuskan untuk tidak membelinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c2d303a-f056-43fc-b106-bb64111f67af', 'vocabulary', '御札', '御札', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Anda mempelajari kosakata lain 札 sebagai "jimat", tetapi ini adalah jimat khusus yang terhormat. Itu adalah jimat.', 'Anda mempelajari kosakata lain 札 sebagai "jimat", tetapi ini adalah jimat khusus yang terhormat. Itu adalah jimat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8c2d303a-f056-43fc-b106-bb64111f67af', 'Jimat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8c2d303a-f056-43fc-b106-bb64111f67af', 'Talisman', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8c2d303a-f056-43fc-b106-bb64111f67af', 'おふだ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c2d303a-f056-43fc-b106-bb64111f67af', 'どうしてここに御札をはっているんですか？', 'Mengapa Anda menaruh jimat itu di sini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c2d303a-f056-43fc-b106-bb64111f67af', 'これは、地元の神社でもらった御札です。', 'Ini adalah jimat yang saya dapatkan dari kuil di kampung halaman saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c2d303a-f056-43fc-b106-bb64111f67af', '英語圏の国にも、御札ってあるんですか？', 'Apakah ada juga jimat di negara-negara berbahasa Inggris?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cbf586e8-d819-426d-85ab-d5d2d54b9700', 'vocabulary', '天王星', '天王星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bintang raja surga adalah planet Uranus. Pengetahuan tentang mitologi Yunani pasti akan membantu Anda di sini, karena nama Inggris mengacu pada dewa langit Yunani, dan nama Jepang adalah terjemahan langsung dari itu!', 'Bintang raja surga adalah planet Uranus. Pengetahuan tentang mitologi Yunani pasti akan membantu Anda di sini, karena nama Inggris mengacu pada dewa langit Yunani, dan nama Jepang adalah terjemahan langsung dari itu!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cbf586e8-d819-426d-85ab-d5d2d54b9700', 'Uranus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cbf586e8-d819-426d-85ab-d5d2d54b9700', 'てんのうせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cbf586e8-d819-426d-85ab-d5d2d54b9700', 'これは天王星の画像です。', 'Ini dalam gambar Uranus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cbf586e8-d819-426d-85ab-d5d2d54b9700', '天王星の発見者はウィリアム・ハーシェルです。', 'Penemu Uranus adalah William Herschel.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cbf586e8-d819-426d-85ab-d5d2d54b9700', '天王星は太陽のまわりを回るのに八十四年かかります.', 'Uranus membutuhkan waktu delapan puluh empat tahun untuk mengelilingi matahari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d652420-f9b6-41cd-aaf9-6eb4686d6f31', 'vocabulary', '火星', '火星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bintang api adalah Mars. Hal ini mudah diingat, karena Mars adalah satu-satunya planet di tata surya kita yang memiliki warna api.', 'Bintang api adalah Mars. Hal ini mudah diingat, karena Mars adalah satu-satunya planet di tata surya kita yang memiliki warna api.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2d652420-f9b6-41cd-aaf9-6eb4686d6f31', 'Mars', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2d652420-f9b6-41cd-aaf9-6eb4686d6f31', 'かせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d652420-f9b6-41cd-aaf9-6eb4686d6f31', '今夜は火星と土星が見えるよ！', 'Mars dan Saturnus akan terlihat malam ini!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d652420-f9b6-41cd-aaf9-6eb4686d6f31', '火星には水がありますか？', 'Apakah ada air di Mars?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d652420-f9b6-41cd-aaf9-6eb4686d6f31', 'オリンポス山は、火星にある火山の名です。', 'Olympus Mons adalah nama gunung berapi di Mars.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58434a2c-9290-4c29-94bc-84c98fb2fd8f', 'vocabulary', '木星', '木星', 2, '6b5c0d7e-8f9a-0b1c-2d3e-4f5a6b7c8d9e', 'Bintang pohon adalah planet Jupiter. Bayangkan Jupiter ditumbuhi pepohonan yang sangat aneh — sejenis pohon yang mampu berakar di dalam gas! Ini gambar yang cukup aneh, tapi semoga bisa membantu Anda mengingat kata ini. Alternatifnya, pikirkan bagaimana awan di sekitar Jupiter membuat pola yang sangat mirip dengan butiran kayu.', 'Bintang pohon adalah planet Jupiter. Bayangkan Jupiter ditumbuhi pepohonan yang sangat aneh — sejenis pohon yang mampu berakar di dalam gas! Ini gambar yang cukup aneh, tapi semoga bisa membantu Anda mengingat kata ini. Alternatifnya, pikirkan bagaimana awan di sekitar Jupiter membuat pola yang sangat mirip dengan butiran kayu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('58434a2c-9290-4c29-94bc-84c98fb2fd8f', 'Yupiter', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('58434a2c-9290-4c29-94bc-84c98fb2fd8f', 'もくせい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58434a2c-9290-4c29-94bc-84c98fb2fd8f', 'いつか、木星に行きたいと思っています。', 'Saya ingin pergi ke Jupiter suatu hari nanti.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58434a2c-9290-4c29-94bc-84c98fb2fd8f', '火星と木星のあいだには、何がありますか。', 'Ada apa antara Mars dan Jupiter?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58434a2c-9290-4c29-94bc-84c98fb2fd8f', '木星や土星はこうして生まれたんですよ。', 'Beginilah asal usul planet seperti Jupiter dan Saturnus.') ON CONFLICT DO NOTHING;
