INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3920110-ffe7-41b7-a66f-ed1b79afc418', '土よう日に、森でピクニックをしました。', 'Pada hari Sabtu, kami piknik di hutan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3920110-ffe7-41b7-a66f-ed1b79afc418', 'お母さんは木を見て森を見ずなんだよ！', 'Kamu tidak bisa melihat kayu di balik pepohonan, Bu!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3920110-ffe7-41b7-a66f-ed1b79afc418', '赤ずきんちゃんが森の中を歩いていると、死んだ狼に出くわしました。赤ずきんちゃんはその場を立ち去り、訪れたおばあさんの家で素晴らしい時間を過ごしました。', 'Little Red Riding Hood sedang berjalan melewati hutan ketika dia menemukan seekor serigala mati. Kemudian dia melanjutkan perjalanannya dan mengunjungi neneknya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('344fee76-ec7a-4391-ac9a-7d1910d0d175', 'vocabulary', '雲', '雲', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
