INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c6e7ab66-d8ae-4660-af57-0b112169d39a', '何県の出身ですか。', 'Anda berasal dari prefektur mana?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c6e7ab66-d8ae-4660-af57-0b112169d39a', 'なら県の小学校では、せい服をきないといけない学校が多いです。', 'Ada banyak sekolah dasar di Nara yang mewajibkan siswanya mengenakan seragam.') ON CONFLICT DO NOTHING;
