INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('35c8164b-18a5-44e4-bf20-49a7908a822e', 'vocabulary', '軽い', '軽い', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari ringan? Ini juga ringan.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari ringan? Ini juga ringan.') ON CONFLICT (id) DO NOTHING;
