INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35c8164b-18a5-44e4-bf20-49a7908a822e', 'このはこは、あのはこよりも軽い。', 'Kotak ini lebih ringan dari kotak itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35c8164b-18a5-44e4-bf20-49a7908a822e', 'この毛ぬき、びっくりするぐらい軽いんだけど。', 'Pinset ini ternyata sangat ringan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35c8164b-18a5-44e4-bf20-49a7908a822e', '毎日軽い朝ごはんを食べる。', 'Setiap hari saya makan sarapan ringan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('efb45755-30e8-40a3-9e79-f808768cf206', 'vocabulary', '線路', '線路', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Jalur yang melintasi suatu jalan raya adalah jalur kereta api. Pertama, Anda harus ingat bahwa "jalur" yang dimaksud adalah jalur kereta api. Lalu, jalur kereta api apa yang melintasi suatu jalan dan jenis jalan apa itu? Itu adalah jalur kereta api.', 'Jalur yang melintasi suatu jalan raya adalah jalur kereta api. Pertama, Anda harus ingat bahwa "jalur" yang dimaksud adalah jalur kereta api. Lalu, jalur kereta api apa yang melintasi suatu jalan dan jenis jalan apa itu? Itu adalah jalur kereta api.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('efb45755-30e8-40a3-9e79-f808768cf206', 'Jalur Kereta Api', true) ON CONFLICT DO NOTHING;
