INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1925b999-6d3e-424d-a470-513e654d681b', '明日の算数のじゅぎょう、定ぎと分度きわすれずにね！', 'Jangan lupa penggaris dan busur derajat untuk pelajaran matematika besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1925b999-6d3e-424d-a470-513e654d681b', '立ち入ったことをお聞きしますが、よみ・かき・算数、どれが一番とくいですか？', 'Saya perlu menanyakan pertanyaan pribadi kepada Anda. Antara membaca, menulis, dan berhitung, manakah yang paling Anda kuasai?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1925b999-6d3e-424d-a470-513e654d681b', '「連絡するのに時間がかかっちゃってごめんなさい。最近、仕事で忙しかったものだから。」「君の仕事って何だっけ？」「小学校の算数の先生よ。」', '"Maaf, aku butuh waktu lama untuk menghubungimu kembali. Aku sedang sibuk dengan pekerjaan." "Apa pekerjaanmu tadi?" "Saya seorang guru matematika di sekolah dasar."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb65ecad-e270-47cb-aafb-80ee50ff9351', 'vocabulary', '算定する', '算定する', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ketika Anda menghitung dan menentukan (perhitungan), Anda sedang menentukan perhitungannya. Itu sebabnya kata ini berarti menghitung.', 'Ketika Anda menghitung dan menentukan (perhitungan), Anda sedang menentukan perhitungannya. Itu sebabnya kata ini berarti menghitung.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('eb65ecad-e270-47cb-aafb-80ee50ff9351', 'Untuk Menghitung', true) ON CONFLICT DO NOTHING;
