INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0932aab9-fa93-4a22-a061-ba1138053fed', '分数をかく時にまん中に引く線の名前は、かつ線です。', 'Garis di tengah pecahan disebut “vinculum”.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0932aab9-fa93-4a22-a061-ba1138053fed', 'しぶ谷で山手線に乗ってください。', 'Silakan naik Jalur Yamanote di Shibuya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0932aab9-fa93-4a22-a061-ba1138053fed', '本当にこの線が完璧だって思ったの？しかも、全然真っ直ぐじゃないじゃない！', 'Anda benar-benar berpikir baris ini sempurna? Itu bahkan tidak mendekati lurus!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('886a27e3-623c-45ad-9da2-2ac78c99743e', 'vocabulary', '競争', '競争', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ketika Anda bersaing sampai pada titik konflik, Anda tahu bahwa orang/entitas tersebut adalah pesaing Anda. Harus mengalahkan kompetisi itu. Misalnya, untuk memenangkan kompetisi, WaniKani memiliki maskot yang dapat memakan semua hewan berbulu kecil lainnya yang dijadikan maskot kompetisi. Kasus ditutup.', 'Ketika Anda bersaing sampai pada titik konflik, Anda tahu bahwa orang/entitas tersebut adalah pesaing Anda. Harus mengalahkan kompetisi itu. Misalnya, untuk memenangkan kompetisi, WaniKani memiliki maskot yang dapat memakan semua hewan berbulu kecil lainnya yang dijadikan maskot kompetisi. Kasus ditutup.') ON CONFLICT (id) DO NOTHING;
