INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('941d1a09-abf6-4afa-97e4-77114dde58e6', '過去のことは水に流して、仲直りしようよ。', 'Mari kita biarkan masa lalu berlalu dan berdamai saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('941d1a09-abf6-4afa-97e4-77114dde58e6', 'そんなにかんたんに仲直りは出来ないよ。', 'Aku tidak bisa berbaikan dengannya secepat itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('941d1a09-abf6-4afa-97e4-77114dde58e6', '一体全体、コウイチはどうやってマリオブラザーズを仲直りさせたの？', 'Bagaimana Koichi mewujudkan rekonsiliasi antara Mario bersaudara?') ON CONFLICT DO NOTHING;
