INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4635dd51-6e1b-476b-baba-3a6ac2096422', 'よくこんな最低最あくの酒がのめるよね。', 'Bagaimana Anda bisa meminum alkohol sampah yang begitu buruk?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4635dd51-6e1b-476b-baba-3a6ac2096422', '今までで最低のキスだったかも。', 'Mungkin itu ciuman terburuk yang pernah ada.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4635dd51-6e1b-476b-baba-3a6ac2096422', 'えぇっ！あの試験で最低点を取ったの？参ったなぁ。', 'Wow, saya tidak percaya Anda mendapat nilai terendah dalam ujian. Sungguh menyedihkan!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('974a31d5-12b5-4078-b374-b0e2d909ae1a', 'vocabulary', '命令', '命令', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Perintah nasib Anda adalah perintah yang Anda dapatkan dari atas. Anda diperintahkan dan diperintahkan untuk melaksanakan perintah tersebut.', 'Perintah nasib Anda adalah perintah yang Anda dapatkan dari atas. Anda diperintahkan dan diperintahkan untuk melaksanakan perintah tersebut.') ON CONFLICT (id) DO NOTHING;
