INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('974a31d5-12b5-4078-b374-b0e2d909ae1a', 'コウイチ王の命令には全てしたがわなくてはいけない。', 'Kita harus mengikuti setiap perintah Raja Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('974a31d5-12b5-4078-b374-b0e2d909ae1a', 'はぁ？おねがいだった？ふざけんなよ。こっちには命令にしか聞こえなかったっつーの。', 'Hah? Itu permintaan? Itu BS! Itu jelas terdengar seperti sebuah perintah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('974a31d5-12b5-4078-b374-b0e2d909ae1a', '「ほら！何をダラダラ待ってるの? 走って！」「俺に命令するんじゃねぇよ！」', '"Ayo! Tunggu apa lagi? Lari!" "Jangan suruh aku berkeliling!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b9b3e17a-1d58-408c-90e2-93f68d8ad4f8', 'vocabulary', '海岸', '海岸', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Pesisir samudera/laut adalah pantai laut. Selain itu, bisa juga di pesisir pantai.', 'Pesisir samudera/laut adalah pantai laut. Selain itu, bisa juga di pesisir pantai.') ON CONFLICT (id) DO NOTHING;
