INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9b3e17a-1d58-408c-90e2-93f68d8ad4f8', '花火大会の日に、ゆかたをきて海岸ぞいを歩いているカップルを見るのがすきです。', 'Saya suka melihat pasangan berjalan di sepanjang pantai dengan mengenakan yukata pada hari-hari ketika ada kembang api.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9b3e17a-1d58-408c-90e2-93f68d8ad4f8', '海岸にあるいいカフェを知ってるんだけど、よかったら一しょにお茶しない？', 'Saya tahu kafe yang bagus di pantai. Maukah kamu minum teh bersamaku?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9b3e17a-1d58-408c-90e2-93f68d8ad4f8', '「今日、私達と一緒に海岸に行かない？」「またの機会にするよ。」', '“Apakah kamu ingin pergi ke pantai bersama kami hari ini?” "Aku akan pergi bersamamu lain kali."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('90b5f0c3-68b7-4eda-9a1b-05f3c0fb69bd', 'vocabulary', '電波', '電波', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Gelombang listrik adalah gelombang listrik yang merambat di udara. Ada banyak kata yang dapat digunakan untuk menggambarkan hal ini, tetapi yang paling mudah adalah penerimaan (alias penerimaan di ponsel Anda, misalnya). Arti lain yang lebih teknis adalah gelombang radio dan gelombang elektromagnetik. Yang mana yang Anda suka terserah Anda, tetapi penerimaan akan menjadi arti paling umum di jalan. Untungnya orang-orang di Jepang tidak memiliki AT&T jika tidak, Anda akan lebih sering mendengar kata ini...', 'Gelombang listrik adalah gelombang listrik yang merambat di udara. Ada banyak kata yang dapat digunakan untuk menggambarkan hal ini, tetapi yang paling mudah adalah penerimaan (alias penerimaan di ponsel Anda, misalnya). Arti lain yang lebih teknis adalah gelombang radio dan gelombang elektromagnetik. Yang mana yang Anda suka terserah Anda, tetapi penerimaan akan menjadi arti paling umum di jalan. Untungnya orang-orang di Jepang tidak memiliki AT&T jika tidak, Anda akan lebih sering mendengar kata ini...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90b5f0c3-68b7-4eda-9a1b-05f3c0fb69bd', 'Penerimaan', true) ON CONFLICT DO NOTHING;
