INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90b5f0c3-68b7-4eda-9a1b-05f3c0fb69bd', 'このビルはコンクリでできてるので、む線の電波はとどきません。', 'Bangunan ini terbuat dari beton sehingga tidak bisa ditembus gelombang radio.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90b5f0c3-68b7-4eda-9a1b-05f3c0fb69bd', '公きょうの電波でそんな事言うなんて、最低だね。', 'Bagaimana dia bisa mengatakan hal seperti itu di radio publik! Brengsek jahat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90b5f0c3-68b7-4eda-9a1b-05f3c0fb69bd', 'ごめん、よく聞こえないよ。ここは電波が悪いみたい。', 'Maaf, kamu terdengar agak berombak. Sepertinya aku mendapat sambutan buruk di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('60977a9b-a764-4e24-b243-6ce59f4c2250', 'vocabulary', '拾う', '拾う', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengambil, jadi versi vocab verbanya adalah mengambil sesuatu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mengambil, jadi versi vocab verbanya adalah mengambil sesuatu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('60977a9b-a764-4e24-b243-6ce59f4c2250', 'Untuk Mengambil Sesuatu', true) ON CONFLICT DO NOTHING;
