INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60977a9b-a764-4e24-b243-6ce59f4c2250', 'すてる神あれば拾う神あり。', 'Ketika Tuhan yang satu menyingkirkanmu, Tuhan yang lain menjemputmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60977a9b-a764-4e24-b243-6ce59f4c2250', 'かえりにあそこの歩道で五百円玉を拾いました。', 'Saya menemukan koin 500 yen di trotoar dalam perjalanan pulang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60977a9b-a764-4e24-b243-6ce59f4c2250', 'だれかが道端にソファを捨ててたんだけど、まだ使えそうだったから、拾ってきたよ。', 'Seseorang membuang sofa di pinggir jalan, tapi sofa itu masih terlihat berguna, jadi saya mengambilnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('85e446f2-825b-4f9e-9281-bddc90d4bc3c', 'vocabulary', '秒', '秒', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kanji dan kata-katanya sama persis. Artinya, keduanya juga memiliki arti yang sama - yaitu satuan waktu, detik.', 'Kanji dan kata-katanya sama persis. Artinya, keduanya juga memiliki arti yang sama - yaitu satuan waktu, detik.') ON CONFLICT (id) DO NOTHING;
