INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85e446f2-825b-4f9e-9281-bddc90d4bc3c', 'コウイチにラインしたら秒で返事きてわらえた。', 'Saya mengirim pesan LINE ke Koichi dan dia membalas saya dalam hitungan detik. Itu membuatku tertawa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85e446f2-825b-4f9e-9281-bddc90d4bc3c', '大体いつも、ふとんに入ったら三秒でねてる。', 'Ketika saya pergi tidur, saya biasanya tertidur dalam tiga detik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85e446f2-825b-4f9e-9281-bddc90d4bc3c', 'あなたの発音をたったの十二秒でネイティブレベルにしてみせますよ。', 'Pengucapan Anda dapat mencapai tingkat asli hanya dalam dua belas detik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0304e242-0fab-4c0a-a0c3-640a21305f63', 'vocabulary', '競う', '競う', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berkompetisi jadi versi vocab verbanya artinya berkompetisi.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berkompetisi jadi versi vocab verbanya artinya berkompetisi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0304e242-0fab-4c0a-a0c3-640a21305f63', 'Untuk Bersaing', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0304e242-0fab-4c0a-a0c3-640a21305f63', 'きそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0304e242-0fab-4c0a-a0c3-640a21305f63', '子どもたちは、新しい先生の所に競うようにかけよった。', 'Anak-anak berlarian menuju guru baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0304e242-0fab-4c0a-a0c3-640a21305f63', 'トーフグはユニークすぎて、競う相手がいないんですよ。いわゆる一人勝ちってやつですね。', 'Tofugu sangat unik sehingga tidak ada orang lain yang bisa menandinginya. Merekalah yang disebut sebagai pemenang tunggal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0304e242-0fab-4c0a-a0c3-640a21305f63', 'コウイチとビエトは、年に一度トーフグオフィスで開かれる剣道の大会で、優れた腕前を披露しようと競い合いました。', 'Koichi dan Viet saling berkompetisi untuk menunjukkan kehebatan mereka di kompetisi Kendo tahunan yang diadakan di kantor Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5e05294e-c697-402b-8442-2d30e3783064', 'vocabulary', '仲良く', '仲良く', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Bila hubungannya baik, berarti Anda bersahabat dengan orang tersebut. Hubungan kalian juga baik-baik saja.', 'Bila hubungannya baik, berarti Anda bersahabat dengan orang tersebut. Hubungan kalian juga baik-baik saja.') ON CONFLICT (id) DO NOTHING;
