INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58420d2f-0f16-46d5-a019-5019d6956985', 'この花の根は食べられますよ。', 'Anda bisa memakan akar bunga ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58420d2f-0f16-46d5-a019-5019d6956985', 'このもんだいは相当根が深いようですね。', 'Tampaknya permasalahan ini mempunyai akar yang sangat dalam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58420d2f-0f16-46d5-a019-5019d6956985', '彼は素敵な人だと思うかもしれないが、根がひどい男なのだ。', 'Anda mungkin berpikir dia orang yang hebat, tetapi sebenarnya dia adalah pria yang buruk hatinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d6a80de3-3d00-4118-85f1-ef77e44e21a5', 'vocabulary', '根本', '根本', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Akar asal adalah akar dari sesuatu. Mungkin lebih banyak root daripada root, tapi kami akan tetap menggunakan root.', 'Akar asal adalah akar dari sesuatu. Mungkin lebih banyak root daripada root, tapi kami akan tetap menggunakan root.') ON CONFLICT (id) DO NOTHING;
