INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6a80de3-3d00-4118-85f1-ef77e44e21a5', 'そもそも、根本から間ちがってるんだよ。', 'Pertama-tama, Anda pada dasarnya salah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6a80de3-3d00-4118-85f1-ef77e44e21a5', 'そのふうふは、子どもの教育についての根本の考え方が合わなかったんです。', 'Pasangan itu memiliki gagasan yang berbeda secara mendasar tentang pendidikan anak mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d6a80de3-3d00-4118-85f1-ef77e44e21a5', 'クリステンはベーコンを食べませんが、この問題の根本の原因はどこにあると思いますか？', 'Kristen tidak makan bacon; Menurut Anda, di manakah letak akar masalah ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3d17992c-ca4c-44a2-a710-882acc10578e', 'vocabulary', '屋根', '屋根', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Akar atap Anda tetaplah atap Anda. Jika membantu, bayangkan akar tumbuh dari atap Anda. Mereka melindungi Anda dari hujan.', 'Akar atap Anda tetaplah atap Anda. Jika membantu, bayangkan akar tumbuh dari atap Anda. Mereka melindungi Anda dari hujan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3d17992c-ca4c-44a2-a710-882acc10578e', 'Atap', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3d17992c-ca4c-44a2-a710-882acc10578e', 'やね', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d17992c-ca4c-44a2-a710-882acc10578e', '来年、屋根をしゅう理する必要があります。', 'Kami harus memperbaiki atap kami tahun depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d17992c-ca4c-44a2-a710-882acc10578e', '屋根にあなが開いているので、雨もりしてるんですよ。', 'Bocor karena ada lubang di atapnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3d17992c-ca4c-44a2-a710-882acc10578e', 'お昼までに屋根の雪を取り除いて下さい。', 'Harap bersihkan salju dari atap pada siang hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', 'vocabulary', '根気', '根気', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Akar energi Anda. Anda harus menggali jauh ke dalam energi Anda, sampai ke asal dan sumbernya, agar memiliki cukup kesabaran menghadapi anak bodoh yang menggerogoti energi non-akar Anda. Hanya itu yang Anda miliki, dan Anda perlu menggunakannya.', 'Akar energi Anda. Anda harus menggali jauh ke dalam energi Anda, sampai ke asal dan sumbernya, agar memiliki cukup kesabaran menghadapi anak bodoh yang menggerogoti energi non-akar Anda. Hanya itu yang Anda miliki, dan Anda perlu menggunakannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', 'Sabar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', 'Perseverance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', 'Persistence', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', 'こんき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', 'これは根気のいる仕事だよな。', 'Pekerjaan ini memerlukan kesabaran ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', 'ほとんどの失ぱいのげんいんは、根気のなさなんだよね。', 'Alasan kegagalan dalam banyak kasus adalah kurangnya ketekunan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('45ef9162-61dd-41c0-a007-1317434a73ed', '根気よく日本語の勉強を続けていれば、いつかはペラペラになれるさ。', 'Teruslah belajar bahasa Jepang dan Anda akan fasih suatu hari nanti.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7931c3d8-a09c-4037-9dc7-aa47fe4a198c', 'vocabulary', '大根', '大根', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ini akan lebih mudah jika Anda pernah melihat atau mendengar tentang daikon sebelumnya. Ini adalah akar yang sangat besar di dalam tanah dan rasanya cukup enak. Ini sebagian besar dikenal sebagai daikon di toko kelontong, meskipun kadang-kadang Anda akan melihatnya sebagai lobak Jepang.', 'Ini akan lebih mudah jika Anda pernah melihat atau mendengar tentang daikon sebelumnya. Ini adalah akar yang sangat besar di dalam tanah dan rasanya cukup enak. Ini sebagian besar dikenal sebagai daikon di toko kelontong, meskipun kadang-kadang Anda akan melihatnya sebagai lobak Jepang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7931c3d8-a09c-4037-9dc7-aa47fe4a198c', 'Daikon', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7931c3d8-a09c-4037-9dc7-aa47fe4a198c', 'Japanese Radish', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7931c3d8-a09c-4037-9dc7-aa47fe4a198c', 'だいこん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7931c3d8-a09c-4037-9dc7-aa47fe4a198c', '一度、大根を育ててみようとしたんですが、全部かれてしまったんです。', 'Saya pernah mencoba menanam daikon, tetapi semuanya layu dan mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7931c3d8-a09c-4037-9dc7-aa47fe4a198c', 'うちの家族は、クリスマスの時期にくつ下とかんそうさせた大根をぶら下げるんだ。', 'Keluarga saya menggantung stoking dan lobak Jepang kering untuk musim Natal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7931c3d8-a09c-4037-9dc7-aa47fe4a198c', 'おお、これいいんじゃねえ？めちゃくちゃいい大根だよ。お前も、一本欲しいか？', 'Hei, lihatlah! Ini lobak Jepang yang sangat enak. Apakah Anda menginginkan salah satunya juga?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('52768be4-5502-44fe-801c-f03871b7ad76', 'vocabulary', '〜倍', '〜倍', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Lemparkan ini ke dalam angka dan Anda akan mengetahui sendiri berapa kali sesuatu telah meningkat. Misalnya, ３倍 berarti sesuatu yang meningkat "tiga kali lipat".', 'Lemparkan ini ke dalam angka dan Anda akan mengetahui sendiri berapa kali sesuatu telah meningkat. Misalnya, ３倍 berarti sesuatu yang meningkat "tiga kali lipat".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('52768be4-5502-44fe-801c-f03871b7ad76', 'Kali', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('52768be4-5502-44fe-801c-f03871b7ad76', 'Fold', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('52768be4-5502-44fe-801c-f03871b7ad76', 'ばい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('52768be4-5502-44fe-801c-f03871b7ad76', 'ワニカニのレビューの数が四倍になってしまった。', 'Jumlah ulasan WaniKani meningkat empat kali lipat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('52768be4-5502-44fe-801c-f03871b7ad76', 'クリスマスの日ぐらい、きゅうりょうを十倍にしてくれたっていいじゃないか！', 'Mengapa tidak membayar saya sepuluh kali lebih banyak dari biasanya pada hari Natal setidaknya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('52768be4-5502-44fe-801c-f03871b7ad76', '回転寿司の普及に伴い、日本におけるサーモンの消費量は輸入開始から三倍となった。', 'Sejak diperkenalkannya dan penyebaran toko sushi conveyor belt, konsumsi salmon di Jepang meningkat tiga kali lipat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('350a8537-dcec-4858-93d5-1d6bdf20b90d', 'vocabulary', '二倍', '二倍', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Sesuatu yang dua kali adalah dua kali lipat (atau hanya dua kali saja). Tentu saja, ini semua dapat digunakan dengan hal-hal seperti 三倍, 百倍, dan 四十二倍 juga.', 'Sesuatu yang dua kali adalah dua kali lipat (atau hanya dua kali saja). Tentu saja, ini semua dapat digunakan dengan hal-hal seperti 三倍, 百倍, dan 四十二倍 juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('350a8537-dcec-4858-93d5-1d6bdf20b90d', 'Ganda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('350a8537-dcec-4858-93d5-1d6bdf20b90d', 'Two Times', false) ON CONFLICT DO NOTHING;
