INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('350a8537-dcec-4858-93d5-1d6bdf20b90d', 'にばい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('350a8537-dcec-4858-93d5-1d6bdf20b90d', 'このかぶのかぶかはたったの二日で二倍になった。', 'Harga saham ini naik dua kali lipat hanya dalam dua hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('350a8537-dcec-4858-93d5-1d6bdf20b90d', 'めんつゆを二倍にうすめるのを忘れないでください。', 'Jangan lupa encerkan bahan dasar kuah mie sebanyak dua kali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('350a8537-dcec-4858-93d5-1d6bdf20b90d', 'うわ！君のお兄さんって、君の二倍の体重があるんだね！', 'Wow! Kakakmu beratnya dua kali lipat beratmu, ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9a3c9cc9-061e-4529-aae9-0f2a337f4fdc', 'vocabulary', '広島', '広島', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Pulau yang luas... ini sendiri tidak membantu, tetapi pulau yang luas ini adalah Hiroshima (pernah mendengarnya?). Ketika Anda membaca, itu akan lebih masuk akal.', 'Pulau yang luas... ini sendiri tidak membantu, tetapi pulau yang luas ini adalah Hiroshima (pernah mendengarnya?). Ketika Anda membaca, itu akan lebih masuk akal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9a3c9cc9-061e-4529-aae9-0f2a337f4fdc', 'Hiroshima', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9a3c9cc9-061e-4529-aae9-0f2a337f4fdc', 'ひろしま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9a3c9cc9-061e-4529-aae9-0f2a337f4fdc', '広島に、登山にいい山はありますか？', 'Apakah ada gunung yang bagus untuk didaki di Hiroshima?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9a3c9cc9-061e-4529-aae9-0f2a337f4fdc', '広島空港から市バスで市内に向かってるところです。', 'Saya menuju kota dari bandara Hiroshima dengan bus kota.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9a3c9cc9-061e-4529-aae9-0f2a337f4fdc', '広島と長崎に投下された原爆は、一瞬で十万人以上の人々の命を奪った。', 'Bom atom yang dijatuhkan di Hiroshima dan Nagasaki menewaskan lebih dari 100.000 orang dalam sekejap.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8a6670d0-1be4-46c4-97a3-d2d09bc822f1', 'vocabulary', '祭', '祭', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8a6670d0-1be4-46c4-97a3-d2d09bc822f1', 'Festival', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8a6670d0-1be4-46c4-97a3-d2d09bc822f1', 'まつり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8a6670d0-1be4-46c4-97a3-d2d09bc822f1', '祭の屋台で売ってるりんごあめがすきなんです。', 'Saya suka permen apel yang mereka jual dari kios makanan di festival.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8a6670d0-1be4-46c4-97a3-d2d09bc822f1', 'こないだの日よう日のお祭りで、かれ氏と初めて手をつないだんだ。', 'Pada festival hari Minggu lalu, aku dan pacarku berpegangan tangan untuk pertama kalinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8a6670d0-1be4-46c4-97a3-d2d09bc822f1', '日本の多くのお祭は、仏教や神道と結びついています。', 'Banyak festival di Jepang yang memiliki kaitan dengan agama Buddha atau Shintoisme.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('74c7e5a1-6932-4213-b6ef-3aa55b14a6b1', 'vocabulary', '文章', '文章', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Bab penulisannya sendiri lebih mirip artikel atau semacamnya. Meski kalimatnya panjang. Jadi ini mencakup hampir semua jenis tulisan yang ada.', 'Bab penulisannya sendiri lebih mirip artikel atau semacamnya. Meski kalimatnya panjang. Jadi ini mencakup hampir semua jenis tulisan yang ada.') ON CONFLICT (id) DO NOTHING;
