INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('74c7e5a1-6932-4213-b6ef-3aa55b14a6b1', 'この文章をかいたのはだれですか？', 'Siapa yang menulis artikel ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('74c7e5a1-6932-4213-b6ef-3aa55b14a6b1', 'コウイチは文章が本当に上手だ。', 'Koichi adalah penulis yang baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('74c7e5a1-6932-4213-b6ef-3aa55b14a6b1', '私は、村上春樹の気障で気取った文章があまり好きではありません。', 'Saya tidak terlalu menyukai gaya penulisan Haruki Murakami yang murahan dan sombong.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54f12d7d-4a46-444e-a3b6-113ad61f0e84', 'vocabulary', '童話', '童話', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Jangan anggap ini sebagai pembicaraan remaja. Pikirkan 話 kata vocab, yang berarti "cerita". Jika Anda melakukan itu, Anda mendapatkan "cerita remaja". Apa itu cerita remaja? Itu cerita anak-anak.', 'Jangan anggap ini sebagai pembicaraan remaja. Pikirkan 話 kata vocab, yang berarti "cerita". Jika Anda melakukan itu, Anda mendapatkan "cerita remaja". Apa itu cerita remaja? Itu cerita anak-anak.') ON CONFLICT (id) DO NOTHING;
