INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb71840f-a847-4746-98de-24473b4a7bbb', 'ヘビたちは一階でかっているんですか？', 'Apakah kamu punya ular-ular itu di lantai pertama?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb71840f-a847-4746-98de-24473b4a7bbb', '一階はまだまだびちょびちょだよ。', 'Lantai dasar masih basah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb71840f-a847-4746-98de-24473b4a7bbb', '「荷物はどこに置いたらいいかな？」「一階でも、二階でも、下でも、どこでも。あなたの好きなところに置いてくれていいよ。」「わかったわ。有難う。」', '"Di mana aku harus meletakkan barang-barangku?" "Di sini, lantai satu, lantai dua, di mana saja. Kamu bisa meletakkannya di mana pun kamu mau." Oke.Terima kasih.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('65466016-abe3-429a-935a-69775dc6671b', 'vocabulary', '二階', '二階', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Lantai dua adalah lantai dua. Naik ke atas!', 'Lantai dua adalah lantai dua. Naik ke atas!') ON CONFLICT (id) DO NOTHING;
