INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65466016-abe3-429a-935a-69775dc6671b', '歯医者さんなら、このビルの二階にあります。', 'Dokter gigi ada di lantai dua gedung ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65466016-abe3-429a-935a-69775dc6671b', '二階だてのマイホームを買いました。', 'Kami membeli rumah lantai dua.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65466016-abe3-429a-935a-69775dc6671b', '毎日午後に二階にある同じ教室に行って、英語を二時間教えます。', 'Setiap sore saya pergi ke ruang kelas yang sama di lantai dua dan mengajar bahasa Inggris selama dua jam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e99a2d4e-3c8f-4346-b23d-fb474a240b0d', 'vocabulary', '四十二階', '四十二階', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Anda tahu bahwa 四十二 berarti "empat puluh dua". Jadi, selama Anda mengetahui lantai, Anda akan mengetahui bahwa ini berarti lantai empat puluh dua.', 'Anda tahu bahwa 四十二 berarti "empat puluh dua". Jadi, selama Anda mengetahui lantai, Anda akan mengetahui bahwa ini berarti lantai empat puluh dua.') ON CONFLICT (id) DO NOTHING;
