INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e99a2d4e-3c8f-4346-b23d-fb474a240b0d', 'よんじゅうにかい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e99a2d4e-3c8f-4346-b23d-fb474a240b0d', '四十二階まで競争よ！', 'Ayo berlomba ke lantai empat puluh dua!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e99a2d4e-3c8f-4346-b23d-fb474a240b0d', 'コウイチは東京に四十二階だてのマンションを持っている。', 'Koichi memiliki kondominium empat puluh dua lantai di Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e99a2d4e-3c8f-4346-b23d-fb474a240b0d', '引っ越しって、色々事務手続きがあって結構面倒くさい上に、対応の悪い担当者とかもいたりするよね。でも、今回の引っ越しで最悪だったのは、引っ越しの日にエレベーターが故障中だったことだよ。俺の部屋、四十二階なのに。', 'Sangat menjengkelkan bahwa ada banyak birokrasi yang terlibat dalam perpindahan tersebut, dan yang lebih buruk lagi, terkadang orang yang bertanggung jawab memiliki masalah sikap. Namun, bagian terburuk dari kepindahanku kali ini adalah liftnya tidak berfungsi ketika aku pindah dan apartemenku berada di lantai empat puluh dua.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('42de05d1-64ec-42af-b243-e00e5fa125e8', 'vocabulary', '植物', '植物', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Tumbuhan adalah tumbuhan atau tumbuh-tumbuhan.', 'Tumbuhan adalah tumbuhan atau tumbuh-tumbuhan.') ON CONFLICT (id) DO NOTHING;
