INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42de05d1-64ec-42af-b243-e00e5fa125e8', 'コウイチは植物の言っている事が分かるらしい。', 'Rupanya Koichi bisa mengerti apa yang dikatakan tanaman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42de05d1-64ec-42af-b243-e00e5fa125e8', 'これは、植物でできたふ葉土です。', 'Ini adalah mulsa dari tumbuh-tumbuhan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42de05d1-64ec-42af-b243-e00e5fa125e8', '園芸の才能は無いけど植物を育てるのは好きなんですよ。', 'Saya tidak punya jempol hijau tapi saya suka menanam tanaman.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6090099b-8ec9-40bb-af49-73ea92181f12', 'vocabulary', '温かい', '温かい', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari hangat? Ini hangat.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari hangat? Ini hangat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6090099b-8ec9-40bb-af49-73ea92181f12', 'Hangat', true) ON CONFLICT DO NOTHING;
