INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6090099b-8ec9-40bb-af49-73ea92181f12', '何か温かいものが飲みたいなぁ。', 'Saya ingin minum sesuatu yang hangat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6090099b-8ec9-40bb-af49-73ea92181f12', '初心者なので、どうか温かい目で見まもってください。', 'Saya seorang pemula, jadi tolong santai saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6090099b-8ec9-40bb-af49-73ea92181f12', '「デザートに温かいアイスクリームはいかがですか？」 「いいえ、もう結構です。」', '"Apakah kamu ingin es krim hangat untuk pencuci mulut?" "Tidak, kita sudah siap."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e60ff21d-92a9-49bc-b7c2-388ad44aa8e0', 'vocabulary', '温泉', '温泉', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Mata air hangat (seperti mata air) adalah mata air panas. Ini sangat bagus. Anda harus mengunjunginya di Jepang.', 'Mata air hangat (seperti mata air) adalah mata air panas. Ini sangat bagus. Anda harus mengunjunginya di Jepang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e60ff21d-92a9-49bc-b7c2-388ad44aa8e0', 'Pemandian Air Panas', true) ON CONFLICT DO NOTHING;
