INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e60ff21d-92a9-49bc-b7c2-388ad44aa8e0', 'おんせん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e60ff21d-92a9-49bc-b7c2-388ad44aa8e0', 'この温泉は、タトゥーのある人も入よくできます。', 'Onsen ini juga terbuka untuk orang yang bertato.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e60ff21d-92a9-49bc-b7c2-388ad44aa8e0', 'かるく運動してあせを流した後、温泉に入ろう。', 'Ayo pergi ke pemandian air panas setelah sedikit berkeringat karena olahraga ringan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e60ff21d-92a9-49bc-b7c2-388ad44aa8e0', '私の父も母も温泉が好きじゃありません。', 'Baik ayah maupun ibuku tidak menyukai pemandian air panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a633296-4404-4fba-9e8d-35e15f0ab2b5', 'vocabulary', '温度', '温度', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Derajat hangat adalah berapa derajat hangatnya di sini. Tentu saja, suhu hangatnya juga sangat sedikit, sehingga sangat dingin. Apa semua ini? Itu suhunya.', 'Derajat hangat adalah berapa derajat hangatnya di sini. Tentu saja, suhu hangatnya juga sangat sedikit, sehingga sangat dingin. Apa semua ini? Itu suhunya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6a633296-4404-4fba-9e8d-35e15f0ab2b5', 'Suhu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6a633296-4404-4fba-9e8d-35e15f0ab2b5', 'おんど', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a633296-4404-4fba-9e8d-35e15f0ab2b5', 'アメリカ人と日本人って、温度のかんじ方がちがうと思いますか？', 'Apakah menurut Anda orang Amerika dan Jepang merasakan suhu secara berbeda?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a633296-4404-4fba-9e8d-35e15f0ab2b5', 'エアコンの温度を二十四度まで上げてもらえませんか？', 'Bisakah Anda menaikkan suhu AC hingga 24℃?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a633296-4404-4fba-9e8d-35e15f0ab2b5', '醸造中に天気や温度がほんの少し変化しただけで、酒の味に影響することがあるため、酒を作ることは非常に難しいと言われています。', 'Dikatakan sangat sulit membuat sake karena perubahan cuaca atau suhu sekecil apa pun selama pembuatan bir dapat memengaruhi rasanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8bc5a21f-c1e5-4def-bfb8-94fb63dab54e', 'vocabulary', '茶の湯', '茶の湯', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Air panas teh. Itu adalah bagian dari upacara yang masuk ke dalam upacara minum teh.', 'Air panas teh. Itu adalah bagian dari upacara yang masuk ke dalam upacara minum teh.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8bc5a21f-c1e5-4def-bfb8-94fb63dab54e', 'Upacara Minum Teh', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8bc5a21f-c1e5-4def-bfb8-94fb63dab54e', 'ちゃのゆ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8bc5a21f-c1e5-4def-bfb8-94fb63dab54e', '茶の湯の道具が買えるお店をさがしています。', 'Saya mencari toko di mana saya bisa membeli peralatan untuk upacara minum teh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8bc5a21f-c1e5-4def-bfb8-94fb63dab54e', 'この水は、茶の湯にてきした水として知られています。', 'Air ini dikenal baik untuk upacara minum teh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8bc5a21f-c1e5-4def-bfb8-94fb63dab54e', '茶の湯の世界には、「一つ一つの出会いを大切に」という意味の「一期一会」という言葉があります。この言葉は、映画「フォレスト・ガンプ」の副タイトルとしても使われました。', 'Dalam dunia upacara minum teh ada pepatah, "Ichi-go ichi-e," yang berarti "menghargai setiap pertemuan". Pepatah ini juga digunakan sebagai subtitle untuk Forrest Gump yang dirilis di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0b268cc1-204c-4ed7-ba57-1c61548bb1fd', 'vocabulary', '湯気', '湯気', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Energi air panas bukanlah air panas itu sendiri, melainkan apa yang keluar darinya (misalnya saat mendidih). Ini adalah uap dan uap.', 'Energi air panas bukanlah air panas itu sendiri, melainkan apa yang keluar darinya (misalnya saat mendidih). Ini adalah uap dan uap.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0b268cc1-204c-4ed7-ba57-1c61548bb1fd', 'Uap', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0b268cc1-204c-4ed7-ba57-1c61548bb1fd', 'Vapor', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0b268cc1-204c-4ed7-ba57-1c61548bb1fd', 'ゆげ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b268cc1-204c-4ed7-ba57-1c61548bb1fd', 'ビエトのおでこから出ている湯気、なんだかいいにおいがするんだよね。', 'Uap yang keluar dari dahi Viet berbau harum entah kenapa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b268cc1-204c-4ed7-ba57-1c61548bb1fd', 'それ、まだ湯気が立つほどあついから、気を付けてね。', 'Itu masih panas mengepul, jadi berhati-hatilah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b268cc1-204c-4ed7-ba57-1c61548bb1fd', '美味しい寿司飯を作るには、しゃもじを使って、湯気が立つ炊きたての熱いごはんに酢を混ぜる必要があります。信じられないかもしれませんが、実際に米一粒一粒を潰さずに酢を混ぜるには技術が必要です。', 'Untuk membuat nasi sushi yang enak, Anda perlu mencampurkan cuka ke dalam nasi panas yang baru dimasak, menggunakan pemukul. Percaya atau tidak, dibutuhkan keterampilan untuk mencampurkan cuka ke dalam nasi tanpa menghancurkan butirannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('668f6436-b243-465e-9286-6ae1edf168bb', 'vocabulary', '短い', '短い', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari pendek? Itu singkat.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari pendek? Itu singkat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('668f6436-b243-465e-9286-6ae1edf168bb', 'Pendek', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('668f6436-b243-465e-9286-6ae1edf168bb', 'みじかい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('668f6436-b243-465e-9286-6ae1edf168bb', 'そのスカート、ちょっと短すぎるんじゃない？', 'Bukankah rok itu terlalu pendek?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('668f6436-b243-465e-9286-6ae1edf168bb', '赤ちゃんが短い手足をバタバタさせてるのは本当にかわいい。', 'Lengan dan kaki bayi yang pendek dan menggapai-gapai sungguh lucu!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('668f6436-b243-465e-9286-6ae1edf168bb', 'わぁ！あんたの尻尾が私より短いなんて、知らなかったわ。', 'Wah! Aku tidak tahu ekormu lebih pendek dari ekorku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b7b29c77-efbc-42ff-a41d-c66e508a4eef', 'vocabulary', '短期', '短期', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Jangka waktu yang singkat adalah jangka pendek. Anda tahu untuk tidak berpikir jangka pendek, bukan? Lagipula, kamu sedang belajar kanji.', 'Jangka waktu yang singkat adalah jangka pendek. Anda tahu untuk tidak berpikir jangka pendek, bukan? Lagipula, kamu sedang belajar kanji.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b7b29c77-efbc-42ff-a41d-c66e508a4eef', 'Periode Singkat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b7b29c77-efbc-42ff-a41d-c66e508a4eef', 'Short Term', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b7b29c77-efbc-42ff-a41d-c66e508a4eef', 'たんき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7b29c77-efbc-42ff-a41d-c66e508a4eef', 'まずは、短期の目ひょうをいくつか作ってみてください。', 'Pertama, harap tetapkan beberapa tujuan jangka pendek.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7b29c77-efbc-42ff-a41d-c66e508a4eef', 'こんな短期間でこんなにおぼえるとか、頭がパンクするっつーの。', 'Saya tidak bisa menghafal sebanyak ini dalam waktu sesingkat itu. Kepalaku akan meledak!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7b29c77-efbc-42ff-a41d-c66e508a4eef', '私は父に、短期的なコスト削減のためにリーダーシップ研修を縮小している企業は、一文惜しみの百知らずだと教えられました。', 'Ayah saya mengatakan kepada saya bahwa perusahaan yang mengurangi pelatihan kepemimpinan untuk menghemat uang dalam jangka pendek adalah tindakan yang bijaksana dan bodoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b0b9a06-4ced-476e-b733-3651850f3042', 'vocabulary', '泉', '泉', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
