INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5b0b9a06-4ced-476e-b733-3651850f3042', 'Fountain', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5b0b9a06-4ced-476e-b733-3651850f3042', 'いずみ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b0b9a06-4ced-476e-b733-3651850f3042', 'わたしたちは、泉からのわき水を飲んでいます。', 'Kami minum air dari mata air.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b0b9a06-4ced-476e-b733-3651850f3042', 'その泉にはがちょうがたくさんいます。', 'Ada banyak angsa di musim semi itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b0b9a06-4ced-476e-b733-3651850f3042', 'わぁ！すごく綺麗。何か特別なダイエットでもしたの？それとも、若返りの泉でも見つけたとか？', 'Wow! Kamu terlihat cantik! Apakah Anda melakukan diet khusus? Atau apakah Anda menemukan Sumber Awet Muda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b2d63d85-c825-4346-b2da-2eb7805bb7a7', 'vocabulary', '福島', '福島', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Pulau keberuntungan sebenarnya tidak terlalu beruntung. Ini adalah Fukushima tempat krisis nuklir terjadi setelah gempa bumi tahun 2011. Jadi, ketika Anda memikirkan "pulau keberuntungan", di sinilah Anda harus berpikir.', 'Pulau keberuntungan sebenarnya tidak terlalu beruntung. Ini adalah Fukushima tempat krisis nuklir terjadi setelah gempa bumi tahun 2011. Jadi, ketika Anda memikirkan "pulau keberuntungan", di sinilah Anda harus berpikir.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b2d63d85-c825-4346-b2da-2eb7805bb7a7', 'Fukushima', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b2d63d85-c825-4346-b2da-2eb7805bb7a7', 'ふくしま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b2d63d85-c825-4346-b2da-2eb7805bb7a7', 'このバンドのボーカルは、福島の出身です。', 'Vokalis band ini berasal dari Fukushima.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b2d63d85-c825-4346-b2da-2eb7805bb7a7', '福島の子どもたちがかいた絵の中の、この銀色の星空を見て下さい。', 'Lihatlah langit keperakan berbintang dalam gambar dari seorang anak di Fukushima ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b2d63d85-c825-4346-b2da-2eb7805bb7a7', '福島問題に関するメールは、全て私をCCに入れてもらえますか？', 'Tolong CC saya di semua email mengenai masalah Fukushima.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e326bd80-a958-4466-a578-a2347eb46c3d', 'vocabulary', '私鉄', '私鉄', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Setrika pribadi (ingat bagaimana 鉄 sering kali berkaitan dengan rel kereta api dan sejenisnya? Hal yang sama berlaku di sini) adalah kereta api pribadi. Ada banyak sekali jenis ini di Jepang.', 'Setrika pribadi (ingat bagaimana 鉄 sering kali berkaitan dengan rel kereta api dan sejenisnya? Hal yang sama berlaku di sini) adalah kereta api pribadi. Ada banyak sekali jenis ini di Jepang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e326bd80-a958-4466-a578-a2347eb46c3d', 'Kereta Api Swasta', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e326bd80-a958-4466-a578-a2347eb46c3d', 'してつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e326bd80-a958-4466-a578-a2347eb46c3d', '東京の私鉄はふくざつでよく分かりません。', 'Kereta api swasta di Tokyo terlalu rumit untuk dipahami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e326bd80-a958-4466-a578-a2347eb46c3d', 'JRで新宿駅まで行ったら私鉄に乗りかえてください。', 'Ketika Anda tiba di Stasiun Shinjuku dengan JR, silakan transfer ke kereta pribadi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e326bd80-a958-4466-a578-a2347eb46c3d', '私は、とある日本の大手私鉄会社で働いております。', 'Saya bekerja di salah satu perusahaan kereta api swasta besar di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6dd80801-a02a-4cd2-8c3c-749c214fc768', 'vocabulary', '計算', '計算', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Saat Anda mengukur dan kemudian menghitung sesuatu, Anda sedang membuat perhitungan. Misalnya, Anda mengukur panjang seekor katak, lalu menghitung berapa banyak katak yang Anda perlukan untuk mencapai bulan. Apa itu? Tentu saja sebuah perhitungan.', 'Saat Anda mengukur dan kemudian menghitung sesuatu, Anda sedang membuat perhitungan. Misalnya, Anda mengukur panjang seekor katak, lalu menghitung berapa banyak katak yang Anda perlukan untuk mencapai bulan. Apa itu? Tentu saja sebuah perhitungan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6dd80801-a02a-4cd2-8c3c-749c214fc768', 'Perhitungan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6dd80801-a02a-4cd2-8c3c-749c214fc768', 'けいさん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6dd80801-a02a-4cd2-8c3c-749c214fc768', 'ビエトは今、飲み放題のパーティーにかかるひ用を計算しています。', 'Viet sedang menghitung biaya pesta minuman sepuasnya sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6dd80801-a02a-4cd2-8c3c-749c214fc768', 'ああ見えて、コウイチは計算がものすごく速いんです。', 'Koichi sangat cepat dalam perhitungan, meskipun dia tidak melihatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6dd80801-a02a-4cd2-8c3c-749c214fc768', 'お母さん！こんなに沢山の計算をしたら、数学の天才になるかわりに逆に頭がおかしくなっちゃうよ。', 'Mama! Jika saya melakukan semua perhitungan ini, alih-alih menjadi jenius matematika, saya malah kehilangan akal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('64df6ab6-3417-447a-82dc-4af57adce42d', 'vocabulary', '温める', '温める', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Anda tahu bahwa kanji 温 berarti hangat, dan kata kerja ini terkait. Artinya memanaskan sesuatu atau menghangatkan sesuatu. Ini semua tentang Anda melakukan sesuatu pada benda lain untuk membuatnya panas, seperti memasukkannya ke dalam microwave.', 'Anda tahu bahwa kanji 温 berarti hangat, dan kata kerja ini terkait. Artinya memanaskan sesuatu atau menghangatkan sesuatu. Ini semua tentang Anda melakukan sesuatu pada benda lain untuk membuatnya panas, seperti memasukkannya ke dalam microwave.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('64df6ab6-3417-447a-82dc-4af57adce42d', 'Untuk Memanaskan Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('64df6ab6-3417-447a-82dc-4af57adce42d', 'To Warm Something Up', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('64df6ab6-3417-447a-82dc-4af57adce42d', 'あたためる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64df6ab6-3417-447a-82dc-4af57adce42d', 'その器は電子レンジで温めないでください。', 'Tolong jangan panaskan mangkuk itu di microwave.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64df6ab6-3417-447a-82dc-4af57adce42d', '夜ねる前に牛乳を温めてホットミルクにして飲むのが好きです。', 'Sebelum tidur, saya suka memanaskan susu dan meminumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('64df6ab6-3417-447a-82dc-4af57adce42d', '水に入れて温めると、昆布のうまみ成分がしみ出てきます。', 'Rumput laut kombu mengeluarkan rasa manisnya saat direndam dalam air dan dipanaskan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9709c6db-d8c6-4523-a167-8aa19c6c8eac', 'vocabulary', '愛知県', '愛知県', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Prefektur Cinta Tahu! Saya ingin tinggal di sini, karena orang harus mengenal cinta! Tentu saja, kami tidak menyebutnya demikian dalam bahasa Inggris. Anda harus mengetahui bacaan kanji untuk mengetahui bacaan di prefektur ini, yaitu Prefektur Aichi (lompat ke bacaan untuk mengetahuinya).', 'Prefektur Cinta Tahu! Saya ingin tinggal di sini, karena orang harus mengenal cinta! Tentu saja, kami tidak menyebutnya demikian dalam bahasa Inggris. Anda harus mengetahui bacaan kanji untuk mengetahui bacaan di prefektur ini, yaitu Prefektur Aichi (lompat ke bacaan untuk mengetahuinya).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9709c6db-d8c6-4523-a167-8aa19c6c8eac', 'Prefektur Aichi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9709c6db-d8c6-4523-a167-8aa19c6c8eac', 'あいちけん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9709c6db-d8c6-4523-a167-8aa19c6c8eac', '愛知県には、美しい梅林があります。', 'Ada hutan ume yang indah di Prefektur Aichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9709c6db-d8c6-4523-a167-8aa19c6c8eac', '愛知県は、そろそろ梅雨入りです。', 'Prefektur Aichi secara bertahap memasuki musim hujan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9709c6db-d8c6-4523-a167-8aa19c6c8eac', 'フグが日本の愛知県に引っ越した後、サーモンが切ない思いをしていることを、誰一人知らなかった。', 'Setelah Fugu pindah ke Prefektur Aichi di Jepang, tidak ada seorang pun yang mengetahui kerinduan Salmon terhadapnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d904047f-a872-42ba-9644-80c543fadb9a', 'vocabulary', '曲線', '曲線', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Sebuah tikungan pada sebuah garis hanyalah sebuah kurva.', 'Sebuah tikungan pada sebuah garis hanyalah sebuah kurva.') ON CONFLICT (id) DO NOTHING;
