INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('abfefde5-24d0-4268-90dc-5e6ab12724ed', '気温が急に下がった。', 'Suhu turun secara tiba-tiba.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('abfefde5-24d0-4268-90dc-5e6ab12724ed', '今日の最高気温は四十度です。', 'Suhu tertinggi hari ini adalah 40 derajat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('abfefde5-24d0-4268-90dc-5e6ab12724ed', '朝ばんの気温のさがはげしいんです。', 'Ada kesenjangan suhu yang besar antara pagi dan malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d1cae4d-23ff-46c6-be63-2366bb243bfd', 'vocabulary', '階段', '階段', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Lantai yang membentuk anak tangga adalah tangga. Jangan bingung dengan kata serupa 段階, yaitu tangga yang menaiki lantai ke tingkat tertentu.', 'Lantai yang membentuk anak tangga adalah tangga. Jangan bingung dengan kata serupa 段階, yaitu tangga yang menaiki lantai ke tingkat tertentu.') ON CONFLICT (id) DO NOTHING;
