INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7d1cae4d-23ff-46c6-be63-2366bb243bfd', '充は、私が階段の掃除を手伝った事に礼を述べた。', 'Mitsuru berterima kasih padaku karena membantunya membersihkan tangga.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('51b0b721-6fa0-4ea4-a906-91d8b2407df5', 'vocabulary', '段階', '段階', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Anak tangga saat ini berada pada tahap kedua. Sekarang sudah pada tahap ketiga. Sekarang sudah dalam tahap terakhir! Bagus!', 'Anak tangga saat ini berada pada tahap kedua. Sekarang sudah pada tahap ketiga. Sekarang sudah dalam tahap terakhir! Bagus!') ON CONFLICT (id) DO NOTHING;
