INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('51b0b721-6fa0-4ea4-a906-91d8b2407df5', '彼氏は、私が妊娠からかなり経った段階まで妊娠の事実を伝えなかったことについて私を責めました。', 'Pacar saya menuduh saya tidak memberi tahu dia bahwa saya hamil sampai kehamilan saya memasuki tahap lanjut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0b4f548d-9601-4e25-a675-f7eebed666c5', 'vocabulary', '誤算', '誤算', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kesalahan dalam menghitung adalah salah perhitungan.', 'Kesalahan dalam menghitung adalah salah perhitungan.') ON CONFLICT (id) DO NOTHING;
