INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0b4f548d-9601-4e25-a675-f7eebed666c5', '彼女は英語がペラペラだと思ったが、とんだ誤算だった。', 'Saya salah dalam berpikir bahwa dia akan berbicara bahasa Inggris dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e837963e-30d9-48b3-b4cb-8528155c8f8d', 'vocabulary', '〜階', '〜階', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Anda tahu bahwa kanji mengacu pada lantai (seperti dalam "lantai lima"). Kata ini mewakili versi yang muncul setelah angka, ditunjukkan dengan tanda 〜. Pada dasarnya, ini memiliki arti yang sama dengan kanji yang Anda pelajari, sehingga membuatnya bagus dan mudah.', 'Anda tahu bahwa kanji mengacu pada lantai (seperti dalam "lantai lima"). Kata ini mewakili versi yang muncul setelah angka, ditunjukkan dengan tanda 〜. Pada dasarnya, ini memiliki arti yang sama dengan kanji yang Anda pelajari, sehingga membuatnya bagus dan mudah.') ON CONFLICT (id) DO NOTHING;
