INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e837963e-30d9-48b3-b4cb-8528155c8f8d', '「何階ですか？」「四階をおねがいします。」「このエレベーターはその階には止まりませんよ。」', '"Lantai berapa?" "Tolong yang keempat." “Lift ini tidak berhenti di lantai itu.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e837963e-30d9-48b3-b4cb-8528155c8f8d', 'コウイチは、九十九階だてのマンションの最上階に住んでいます。', 'Koichi tinggal di lantai paling atas sebuah gedung apartemen berlantai sembilan puluh sembilan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e837963e-30d9-48b3-b4cb-8528155c8f8d', 'このアパートの十三階に住んでいます。', 'Saya tinggal di lantai tiga belas apartemen ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('28dd3483-5cfe-49e0-aad8-0bc01300a053', 'vocabulary', '波', '波', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
