INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28dd3483-5cfe-49e0-aad8-0bc01300a053', '今日の波、すごく高いね。', 'Ombak hari ini tinggi sekali ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28dd3483-5cfe-49e0-aad8-0bc01300a053', '大へんだ！コウイチが波に飲みこまれたぞー！', 'YA AMPUN! Koichi telah ditelan ombak!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28dd3483-5cfe-49e0-aad8-0bc01300a053', '波にゆらゆら揺られるのが気持ちいい。', 'Goyangan ombak kesana kemari terasa nikmat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e12b8e21-9d11-44a5-b60b-ebd3b0982aeb', 'vocabulary', '田代島', '田代島', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Sawah digunakan sebagai pengganti pulau. Pulau manakah itu? Itu benar, Tashirojima. Bayangkan sebuah sawah di tengah laut, berdiri di atas Pulau Tashiro', 'Sawah digunakan sebagai pengganti pulau. Pulau manakah itu? Itu benar, Tashirojima. Bayangkan sebuah sawah di tengah laut, berdiri di atas Pulau Tashiro') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e12b8e21-9d11-44a5-b60b-ebd3b0982aeb', 'Tashirojima', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e12b8e21-9d11-44a5-b60b-ebd3b0982aeb', 'たしろじま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e12b8e21-9d11-44a5-b60b-ebd3b0982aeb', '田代島の人口は百人以下です。', 'Populasi Tashirojima kurang dari seratus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e12b8e21-9d11-44a5-b60b-ebd3b0982aeb', '田代島にはガソリンスタンドがありません。', 'Tidak ada pompa bensin di Tashirojima.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e12b8e21-9d11-44a5-b60b-ebd3b0982aeb', '最も有名な「猫島」といえば、日本の宮城県にある田代島という島です。', '"Pulau kucing" yang paling terkenal adalah Pulau Tashiro di prefektur Miyagi, Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e43f44a8-2d21-45dd-af9b-6b122d680598', 'vocabulary', '島', '島', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
