INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e43f44a8-2d21-45dd-af9b-6b122d680598', 'しま', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e43f44a8-2d21-45dd-af9b-6b122d680598', 'この島のはま辺では、水着は着用できません。', 'Anda tidak bisa mengenakan pakaian renang di pantai pulau ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e43f44a8-2d21-45dd-af9b-6b122d680598', 'わたしの家内は、この島で一番の美人です。', 'Istriku adalah wanita tercantik di pulau ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e43f44a8-2d21-45dd-af9b-6b122d680598', 'この島で一週間生活をしてもらいます。', 'Aku akan membiarkanmu tinggal di pulau ini selama seminggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f73463d2-8492-4b40-82e3-fbe5a3240c65', 'vocabulary', '農場', '農場', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Tempat Anda bertani adalah sebuah peternakan!', 'Tempat Anda bertani adalah sebuah peternakan!') ON CONFLICT (id) DO NOTHING;
