INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f73463d2-8492-4b40-82e3-fbe5a3240c65', 'のうじょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f73463d2-8492-4b40-82e3-fbe5a3240c65', '日よう日、小麦のしゅうかくを体験しに、農場へ行ってきました。', 'Saya pergi ke pertanian pada hari Minggu untuk menikmati panen gandum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f73463d2-8492-4b40-82e3-fbe5a3240c65', '農場で、引きつづきはたらかないかと聞かれました。', 'Saya ditanya apakah saya ingin tetap bekerja di pertanian.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f73463d2-8492-4b40-82e3-fbe5a3240c65', 'オーガニック農場を始めるつもりです。', 'Saya berencana memulai pertanian organik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9d74291c-04ca-4d21-a977-cd0e102fb8e6', 'vocabulary', '植える', '植える', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menanam, jadi versi verbanya adalah menanam sesuatu atau menumbuhkan sesuatu.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti menanam, jadi versi verbanya adalah menanam sesuatu atau menumbuhkan sesuatu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9d74291c-04ca-4d21-a977-cd0e102fb8e6', 'Menanam Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9d74291c-04ca-4d21-a977-cd0e102fb8e6', 'To Grow Something', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9d74291c-04ca-4d21-a977-cd0e102fb8e6', 'うえる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d74291c-04ca-4d21-a977-cd0e102fb8e6', 'トーフグオフィスの屋上にはサボテンが植えてあります。', 'Ada beberapa kaktus yang ditanam di rooftop kantor Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d74291c-04ca-4d21-a977-cd0e102fb8e6', 'チューリップ、ちょっと植えすぎなぐらい植えたんじゃない？', 'Saya pikir Anda sudah menanam lebih dari cukup tulip.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d74291c-04ca-4d21-a977-cd0e102fb8e6', 'この種をどこに植えるつもりだい。', 'Di mana Anda berencana menanam benih itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', 'vocabulary', '文化祭', '文化祭', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ingat bagaimana 文化 berarti "budaya?" Tambahkan festival ke dalamnya dan Anda akan mendapatkan festival budaya! Hal ini selalu terjadi di sekolah-sekolah Jepang, jadi terkadang disebut juga festival sekolah.', 'Ingat bagaimana 文化 berarti "budaya?" Tambahkan festival ke dalamnya dan Anda akan mendapatkan festival budaya! Hal ini selalu terjadi di sekolah-sekolah Jepang, jadi terkadang disebut juga festival sekolah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', 'Festival Sekolah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', 'Culture Festival', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', 'Arts Festival', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', 'ぶんかさい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', 'うちの学校の文化祭にもあそびに来てくださいね。', 'Silakan datang mengunjungi festival budaya sekolah saya!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', '「文化祭の練習、何時にする？」「おれは一日中ひまだから、そっちの都合の良い時なら何時でもいいよ。」', '"Jam berapa kita harus memulai latihan festival sekolah?" "Saya tersedia sepanjang hari, jadi kapan pun itu yang paling cocok untuk Anda."') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a769ce4d-0485-4593-87b6-bb0ecb087071', '文化祭の管理諸経費は全体の約三十五パーセントになると見積っています。', 'Kami memperkirakan biaya administrasi dan overhead sekitar 35 persen dari total biaya festival budaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8701bb9d-d4ee-4861-9d5b-7f66a8e6f5e7', 'vocabulary', '足し算', '足し算', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ingat bagaimana 足す berarti "menambahkan?" Tambahkan perhitungan ke dalamnya dan Anda akan mendapat tambahan! Ini adalah jenis penghitungan yang Anda lakukan saat menambahkan.', 'Ingat bagaimana 足す berarti "menambahkan?" Tambahkan perhitungan ke dalamnya dan Anda akan mendapat tambahan! Ini adalah jenis penghitungan yang Anda lakukan saat menambahkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8701bb9d-d4ee-4861-9d5b-7f66a8e6f5e7', 'Tambahan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8701bb9d-d4ee-4861-9d5b-7f66a8e6f5e7', 'たしざん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8701bb9d-d4ee-4861-9d5b-7f66a8e6f5e7', 'わたしは足し算ができない。', 'Saya tidak bisa melakukan penambahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8701bb9d-d4ee-4861-9d5b-7f66a8e6f5e7', 'その足し算コンテストに、かん客としてさんかすることはできますか？', 'Bisakah saya berpartisipasi dalam kontes penambahan sebagai penonton?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8701bb9d-d4ee-4861-9d5b-7f66a8e6f5e7', '今日、学校で足し算の勉強をしました。', 'Hari ini kami belajar penjumlahan di sekolah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c06b93d5-1f51-45d5-b2bb-f487978e47ff', 'vocabulary', '引き算', '引き算', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Ingat bagaimana 引く berarti "mengurangi?" Tambahkan perhitungan ke dalamnya dan Anda akan mendapatkan pengurangan! Ini adalah jenis perhitungan yang Anda lakukan saat mengurangi.', 'Ingat bagaimana 引く berarti "mengurangi?" Tambahkan perhitungan ke dalamnya dan Anda akan mendapatkan pengurangan! Ini adalah jenis perhitungan yang Anda lakukan saat mengurangi.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c06b93d5-1f51-45d5-b2bb-f487978e47ff', 'Pengurangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c06b93d5-1f51-45d5-b2bb-f487978e47ff', 'ひきざん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c06b93d5-1f51-45d5-b2bb-f487978e47ff', 'もちろん、わたしは引き算ができます！', 'Tentu saja saya bisa melakukan pengurangan!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c06b93d5-1f51-45d5-b2bb-f487978e47ff', 'この引き算のじゅぎょうは長すぎて、あくびが止まりません。', 'Kelas pengurangan sangat lama sehingga saya tidak bisa berhenti menguap.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c06b93d5-1f51-45d5-b2bb-f487978e47ff', '引き算を習うのは、小学校何年生ですか？', 'Di sekolah dasar tahun berapa kita akan belajar pengurangan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b1fcb35c-cc57-49de-ab18-c8177dfe26fe', 'vocabulary', '湯', '湯', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b1fcb35c-cc57-49de-ab18-c8177dfe26fe', 'Air Panas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b1fcb35c-cc57-49de-ab18-c8177dfe26fe', 'ゆ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1fcb35c-cc57-49de-ab18-c8177dfe26fe', 'お湯であらってみたら、落ちるかもしれないよ。', 'Jika Anda mencucinya dengan air panas, Anda mungkin bisa menghilangkannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1fcb35c-cc57-49de-ab18-c8177dfe26fe', 'コウイチは大きい方をした後、お湯と石けんで手をあらいます。', 'Setelah ke nomor dua, Koichi mencuci tangannya dengan air panas dan sabun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b1fcb35c-cc57-49de-ab18-c8177dfe26fe', 'お湯を沸かしてくれないか？', 'Bisakah Anda merebus air?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0600bf7d-96f9-41cb-88cc-c96c62e185c6', 'vocabulary', '割り算', '割り算', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Bagilah dan hitung? Wah, itu hanya perpecahan!', 'Bagilah dan hitung? Wah, itu hanya perpecahan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0600bf7d-96f9-41cb-88cc-c96c62e185c6', 'Divisi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0600bf7d-96f9-41cb-88cc-c96c62e185c6', 'わりざん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0600bf7d-96f9-41cb-88cc-c96c62e185c6', 'こんな簡単な割り算の問題を間違えちゃったよ。', 'Saya membuat kesalahan pada soal pembagian yang sederhana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('46f896ff-2e9c-4544-ab4a-bc879e6d9644', 'vocabulary', '掛け算', '掛け算', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Jika Anda mencoba menghitung sesuatu, tetapi Anda malah merasa ingin menggantung guru Anda, Anda tahu bahwa Anda sedang melakukan perkalian. Itu sulit, teman-teman. Sangat sulit. Jenis matematika yang paling sulit dari semuanya. Tapi Anda bisa melakukannya! Tidak ada yang perlu digantung. Dan jangan pula menundukkan kepala karena kekalahan. Lipat gandakan angka-angka itu seperti bos! Gantungkan nomornya!!', 'Jika Anda mencoba menghitung sesuatu, tetapi Anda malah merasa ingin menggantung guru Anda, Anda tahu bahwa Anda sedang melakukan perkalian. Itu sulit, teman-teman. Sangat sulit. Jenis matematika yang paling sulit dari semuanya. Tapi Anda bisa melakukannya! Tidak ada yang perlu digantung. Dan jangan pula menundukkan kepala karena kekalahan. Lipat gandakan angka-angka itu seperti bos! Gantungkan nomornya!!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('46f896ff-2e9c-4544-ab4a-bc879e6d9644', 'Perkalian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('46f896ff-2e9c-4544-ab4a-bc879e6d9644', 'かけざん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('46f896ff-2e9c-4544-ab4a-bc879e6d9644', '明日、塾で掛け算のテストがあるんです。', 'Besok ada tes perkalian di sekolah menjejalkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f834e90-be29-401d-a150-8b2b8bf007d1', 'vocabulary', '祭日', '祭日', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Hari dimana Anda mengadakan festival adalah hari libur nasional. Dengan begitu semua orang bisa ikut merayakannya tanpa perlu khawatir pergi ke sekolah atau bekerja. Ini juga dikenal sebagai hari festival (cukup jelas, bukan?).', 'Hari dimana Anda mengadakan festival adalah hari libur nasional. Dengan begitu semua orang bisa ikut merayakannya tanpa perlu khawatir pergi ke sekolah atau bekerja. Ini juga dikenal sebagai hari festival (cukup jelas, bukan?).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2f834e90-be29-401d-a150-8b2b8bf007d1', 'Hari Libur Nasional', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2f834e90-be29-401d-a150-8b2b8bf007d1', 'Festival Day', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2f834e90-be29-401d-a150-8b2b8bf007d1', 'さいじつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f834e90-be29-401d-a150-8b2b8bf007d1', 'その祭日の予定はまだありません。', 'Saya tidak punya rencana untuk hari festival itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f834e90-be29-401d-a150-8b2b8bf007d1', '祭日なのに、仕事なの？', 'Apakah harus tetap bekerja padahal hari libur nasional?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f834e90-be29-401d-a150-8b2b8bf007d1', '祭日だってことを忘れていて、会社に来てしまった。', 'Saya lupa ini hari libur dan saya datang ke kantor.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dcda8e5f-a62f-4a4b-affa-d19ae3e9be8d', 'vocabulary', '温まる', '温まる', 2, '7c6d1e8f-9a0b-1c2d-3e4f-5a6b7c8d9e0f', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu bahwa kata tersebut adalah kata kerja. Lebih khusus lagi, kata kerja ini diakhiri dengan まる, dan sebagian besar kata kerja dengan akhiran ini bersifat intransitif, artinya tindakan atau perubahan terjadi dengan sendirinya.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dcda8e5f-a62f-4a4b-affa-d19ae3e9be8d', 'Untuk Pemanasan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('dcda8e5f-a62f-4a4b-affa-d19ae3e9be8d', 'To Get Warm', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('dcda8e5f-a62f-4a4b-affa-d19ae3e9be8d', 'あたたまる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dcda8e5f-a62f-4a4b-affa-d19ae3e9be8d', 'シャワーの水が温まるまで、ここで待ちます。', 'Sampai air pancurannya menghangat, aku akan menunggu di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dcda8e5f-a62f-4a4b-affa-d19ae3e9be8d', 'このヒーターだと、部屋が温まるのにかなり時間がかかる。', 'Dengan pemanas ini, dibutuhkan banyak waktu agar ruangan menjadi hangat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dcda8e5f-a62f-4a4b-affa-d19ae3e9be8d', '一キロ走って、体が温まってきた。', 'Setelah berlari 1km, badan saya mulai menghangat.') ON CONFLICT DO NOTHING;
