INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('344211e9-03fd-4a4e-937e-579e409a3d6b', 'radical', '東', 'east', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Radikal ini sama dengan kanji. Artinya timur.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('344211e9-03fd-4a4e-937e-579e409a3d6b', 'Timur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0e81ef52-aa9b-4578-8c14-f9de713d6788', 'radical', '意', 'idea', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Radikal ini sama dengan kanji. Artinya ide.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0e81ef52-aa9b-4578-8c14-f9de713d6788', 'Ide', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('2aa4e586-ec0d-46f6-b535-72c72c7277c0', 'radical', '象', 'elephant', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Hewan apa yang menjadi alasan menyedihkan bagi babi? Seekor gajah. Bayangkan seekor gajah mencoba berpura-pura menjadi babi. Warnanya abu-abu, bukan merah muda. Dan mereka mempunyai belalai yang sangat panjang, bukan babi pengendus kecil. Dan mereka jauh lebih besar. Gajah konyol.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2aa4e586-ec0d-46f6-b535-72c72c7277c0', 'Gajah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('172da0f3-1388-4dd0-9d48-9f2a2782a9bb', 'radical', '井', 'well', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Bayangkan radikal ini seperti peta yang Anda anggap remeh. Ada empat jalan yang melewati kota kecil ini. Tepat di tengah adalah hal yang paling penting—sumur. Setiap orang melewati empat jalan tersebut untuk sampai ke sumur dan mendapatkan air yang mereka idamkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('172da0f3-1388-4dd0-9d48-9f2a2782a9bb', 'Baik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('036a5b0a-141c-4c81-9494-da62d62915c1', 'radical', '男', 'man', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Radikal ini sama dengan kanji. Artinya laki-laki.') ON CONFLICT (id) DO NOTHING;
