INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cfa8e638-f8ea-40b1-a373-5499e008b9cb', 'vocabulary', '想像する', '想像する', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Untuk membuat konsep suatu gambar (dalam pikiran Anda) tentu mengharuskan Anda membayangkannya, karena itu hanya sebuah konsep dan tidak nyata.', 'Untuk membuat konsep suatu gambar (dalam pikiran Anda) tentu mengharuskan Anda membayangkannya, karena itu hanya sebuah konsep dan tidak nyata.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cfa8e638-f8ea-40b1-a373-5499e008b9cb', 'Membayangkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cfa8e638-f8ea-40b1-a373-5499e008b9cb', 'そうぞうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cfa8e638-f8ea-40b1-a373-5499e008b9cb', 'コウイチは仕事中、たまに想像できないような動きをする。', 'Sesekali Koichi akan bergerak dengan cara yang tidak terbayangkan saat dia sedang bekerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cfa8e638-f8ea-40b1-a373-5499e008b9cb', 'てらや神社をめぐってごしゅいんちょうにごしゅいんを集める仕事って、想像できる？', 'Dapatkah Anda membayangkan memiliki pekerjaan di mana Anda mengunjungi kuil dan tempat suci untuk mengumpulkan stempel tinta merahnya dalam sebuah buku?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cfa8e638-f8ea-40b1-a373-5499e008b9cb', 'もし指を喉に突っ込む以外でゲロを吐く方法を学びたいなら、裸のコウイチを想像するといいよ。', 'Jika Anda ingin belajar cara muntah tanpa memasukkan jari ke tenggorokan, bayangkan saja Koichi telanjang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8b06938c-60dd-4b49-acf9-ef3092c74c6c', 'vocabulary', '映像', '映像', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Sebuah bayangan terpantul di cermin. Anda sedang melihat ke cermin, bingung. Jangan khawatir, itu hanya gambar, gambar, atau mungkin video. Itu tidak nyata.', 'Sebuah bayangan terpantul di cermin. Anda sedang melihat ke cermin, bingung. Jangan khawatir, itu hanya gambar, gambar, atau mungkin video. Itu tidak nyata.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8b06938c-60dd-4b49-acf9-ef3092c74c6c', 'Gambar', true) ON CONFLICT DO NOTHING;
