INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('06dc5945-c603-46bc-a1a0-23695e9670d0', 'がぞう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06dc5945-c603-46bc-a1a0-23695e9670d0', '勝手にわたしの画像を使わないでくださいよ！', 'Jangan gunakan gambar saya tanpa izin saya!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06dc5945-c603-46bc-a1a0-23695e9670d0', 'けいさつにコウイチの暗殺事けんにかんするしょうこ画像をてい出しました。', 'Saya menyerahkan gambar sebagai bukti kepada polisi terkait kasus pembunuhan Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('06dc5945-c603-46bc-a1a0-23695e9670d0', '残念。この画像はちょっとボケてるので使えないよ。', 'Sayang sekali. Gambar ini sedikit tidak fokus sehingga tidak dapat digunakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eafe5939-53f8-4a19-90bc-4f441426edb0', 'vocabulary', '一億', '一億', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Seratus juta adalah seratus juta. Itu banyak sekali angka nolnya.', 'Seratus juta adalah seratus juta. Itu banyak sekali angka nolnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('eafe5939-53f8-4a19-90bc-4f441426edb0', 'Seratus Juta', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('eafe5939-53f8-4a19-90bc-4f441426edb0', 'いちおく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eafe5939-53f8-4a19-90bc-4f441426edb0', 'コウイチは東京に一億円のマンションを持っています。', 'Koichi memiliki kondominium seharga seratus juta yen di Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eafe5939-53f8-4a19-90bc-4f441426edb0', '日本という小さな島国に一億もの人が住んでいることがしんじられない。', 'Saya tidak percaya Jepang, sebuah negara kepulauan kecil, memiliki seratus juta orang yang tinggal di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eafe5939-53f8-4a19-90bc-4f441426edb0', '宝くじで一億ドル当たったけど、私は既に兆万長者なので全部慈善活動に寄付したよ。', 'Saya memenangkan lotere seratus juta dolar, tetapi saya menyumbangkan semuanya untuk amal karena saya seorang triliuner.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('44ce9f99-d02d-46d7-a31a-ec2276fc3a2f', 'vocabulary', '一億円', '一億円', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Seratus juta yen! Sangat kaya! Anda memiliki seratus juta yen!', 'Seratus juta yen! Sangat kaya! Anda memiliki seratus juta yen!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('44ce9f99-d02d-46d7-a31a-ec2276fc3a2f', 'Seratus Juta Yen', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('44ce9f99-d02d-46d7-a31a-ec2276fc3a2f', 'いちおくえん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44ce9f99-d02d-46d7-a31a-ec2276fc3a2f', '一億円とか大きな注文は入ってないけど、コンスタントに注文はあるよ。', 'Kami tidak mendapat pesanan dalam jumlah besar seperti seratus juta yen, tapi kami mendapat pesanan tetap.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44ce9f99-d02d-46d7-a31a-ec2276fc3a2f', 'トーフグがわたしに一億円をめぐんでくれることが決定したというお知らせを受けとりました。', 'Saya menerima pemberitahuan yang mengatakan Tofugu telah memutuskan untuk menyumbangkan seratus juta yen kepada saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('44ce9f99-d02d-46d7-a31a-ec2276fc3a2f', '「さっき一億円が入ったスーツケースを無くしちゃったんだけど。」「えぇっ！見つかるといいね。」', '“Saya baru saja kehilangan sebuah koper yang berisi seratus juta yen.” "Apa! Kuharap kamu menemukannya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bd5d9ab6-6c26-45c2-8cd1-af3cdd0a75d5', 'vocabulary', '億', '億', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
