INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bd5d9ab6-6c26-45c2-8cd1-af3cdd0a75d5', 'おく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd5d9ab6-6c26-45c2-8cd1-af3cdd0a75d5', 'このおく歯までしっかりとどく歯ブラシで、今年は五億円を売り上げました。', 'Kami menjual sikat gigi ini senilai lima ratus juta yen tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd5d9ab6-6c26-45c2-8cd1-af3cdd0a75d5', 'あんなに小さかった子がこんなに大きくなって、今や毎年三億ドルをかせぐ大物になっているなんて、本当にしんじられないよ。', 'Saya benar-benar tidak percaya anak kecil itu menjadi begitu besar dan sekarang menghasilkan tiga ratus juta dolar setiap tahunnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd5d9ab6-6c26-45c2-8cd1-af3cdd0a75d5', '出張の領収書は全部とっておいてください。経費は二億円までなら後で精算されますので。', 'Harap simpan semua tanda terima dari perjalanan bisnis Anda. Anda akan mendapatkan penggantian biaya bisnis Anda nanti, asalkan jumlahnya di bawah dua ratus juta yen.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cdfa3090-fc3e-4da3-90ac-c60c25ad0816', 'vocabulary', '橋', '橋', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cdfa3090-fc3e-4da3-90ac-c60c25ad0816', 'Jembatan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cdfa3090-fc3e-4da3-90ac-c60c25ad0816', 'はし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cdfa3090-fc3e-4da3-90ac-c60c25ad0816', 'かれに橋の上でキスされちゃった。', 'Woah, dia menciumku di jembatan!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cdfa3090-fc3e-4da3-90ac-c60c25ad0816', '橋をわたる間、むすめと歌を一しょに歌ってくれませんか？', 'Bisakah kamu menyanyikan sebuah lagu bersama putriku saat melintasi jembatan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cdfa3090-fc3e-4da3-90ac-c60c25ad0816', 'その1603年に建てられた橋の名前は日本橋といいます。日本橋は、その名の通りまさに日本の中心でした。', 'Nama jembatan yang dibangun pada tahun 1603 adalah Nihonbashi dan merupakan titik pusat Jepang, sesuai dengan namanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('02347fe5-9fc4-45d4-8826-35a952f3ba12', 'vocabulary', '緑', '緑', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('02347fe5-9fc4-45d4-8826-35a952f3ba12', 'Hijau', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('02347fe5-9fc4-45d4-8826-35a952f3ba12', 'みどり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02347fe5-9fc4-45d4-8826-35a952f3ba12', 'わたしの主人の目の色は、緑がかったはい色です。', 'Warna mata suamiku abu-abu badai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02347fe5-9fc4-45d4-8826-35a952f3ba12', '緑のじゅうたんとか、ちょっと悪しゅ味だよね。', 'Memilih karpet hijau menunjukkan selera Anda cukup buruk bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02347fe5-9fc4-45d4-8826-35a952f3ba12', 'A:「僕はこの赤いのが気に入ったよ。」 B:「私は緑の方がいいわ。」 A:「ああ、そうかい。じゃあ、好きなようにしろよ。」', 'Jawaban: Saya suka yang merah. B: Saya lebih suka hijau. J: Oh. Baiklah kalau begitu, lakukan sesuai keinginanmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'vocabulary', '緑色', '緑色', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Warna hijau adalah warna hijau.', 'Warna hijau adalah warna hijau.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'Hijau', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'Color Green', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'Green Color', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'みどりいろ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'この緑色なゆで玉子は、ちょっと食べる気になれませんね。', 'Telur rebus berwarna hijau ini bikin nafsu makanmu hilang ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'これはかん全にこ人てきな好みなんですけど、コウイチにはかみを緑色にそめてもらいたいんですよねー。', 'Ini hanya preferensi pribadiku, tapi aku ingin Koichi mewarnai rambutnya menjadi hijau.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6a9b3d1c-2338-4ca3-97cd-c9c41d4c40b0', 'A:「このネクタイ、どうかな？」 B:「そうねぇ。こっちの緑色のをしてみてよ。」 A:「わかったよ。これでどう？」 B:「うん。そっちの方がいいわね。」', 'A: Bagaimana kamu menyukai dasi ini? B: Hmm... Ini. Coba yang hijau ini. J: Oke. Bagaimana ini? B: Ya. Itu lebih seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1eda77a-e3c4-471a-bf33-f677844d2c93', 'vocabulary', '練習', '練習', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda mempraktikkan sesuatu untuk mempelajarinya. Itu masih disebut latihan! Bagian penting tentang ini adalah Anda juga belajar sambil berlatih. Itu benar dalam kata-katanya. Jadi, ketika Anda berlatih kanji dan kosakata bahasa Jepang, pastikan Anda belajar sekaligus berlatih. Jika Anda tidak belajar, berarti Anda tidak benar-benar berlatih, bukan?', 'Anda mempraktikkan sesuatu untuk mempelajarinya. Itu masih disebut latihan! Bagian penting tentang ini adalah Anda juga belajar sambil berlatih. Itu benar dalam kata-katanya. Jadi, ketika Anda berlatih kanji dan kosakata bahasa Jepang, pastikan Anda belajar sekaligus berlatih. Jika Anda tidak belajar, berarti Anda tidak benar-benar berlatih, bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1eda77a-e3c4-471a-bf33-f677844d2c93', 'Latihan', true) ON CONFLICT DO NOTHING;
