INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f793a8b1-49d0-4810-9d6d-cda3b12017ec', 'かちょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f793a8b1-49d0-4810-9d6d-cda3b12017ec', '先月、課長にしょう進しました。', 'Saya dipromosikan menjadi manajer bagian bulan lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f793a8b1-49d0-4810-9d6d-cda3b12017ec', '課長になれたのはうれしいんだけど、ざん業代が出ないから実はきゅう料が下がったんだよね。', 'Senang rasanya bisa menjadi kepala bagian, tapi gajiku malah berkurang karena tidak mendapat upah lembur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f793a8b1-49d0-4810-9d6d-cda3b12017ec', '課長が少しうざいんだよね。他の社員に良い印象を与えようといつも頑張っちゃってさ。', 'Manajer bagian saya agak menyebalkan. Dia selalu berusaha mengesankan pekerja lainnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('85bf09a8-b6cf-4f02-bd5b-6bc74e091155', 'vocabulary', '賞金', '賞金', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Hadiah emas sudah sangat kuno. Sekarang kita menggunakan uang tunai, itulah sebabnya kata ini berarti hadiah uang tunai.', 'Hadiah emas sudah sangat kuno. Sekarang kita menggunakan uang tunai, itulah sebabnya kata ini berarti hadiah uang tunai.') ON CONFLICT (id) DO NOTHING;
