INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('04c37c89-e739-42d6-a9ee-a1cdaacc968c', 'バイクの車輪が外れてしまいました。', 'Ban sepeda motor saya lepas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('04c37c89-e739-42d6-a9ee-a1cdaacc968c', '暗殺のきょうきには車輪が使われたそうです。', 'Saya mendengar bahwa roda mobil digunakan dalam pembunuhan tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('04c37c89-e739-42d6-a9ee-a1cdaacc968c', '今日、ちょっと自転車貸してもらえないかな？今、車輪を取り替えてもらっているので、自分のが無いんだよね。', 'Bisakah saya meminjam sepeda Anda hari ini? Saya tidak memiliki ban saya saat ini karena ban saya sedang diganti.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('84ae0417-163a-451a-b9d5-a72c46b6a5fc', 'vocabulary', '輪', '輪', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
