INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84ae0417-163a-451a-b9d5-a72c46b6a5fc', '早くこの輪投げの輪をなげてくださいよ！', 'Tolong lempar cincin Quoits ini dengan cepat!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84ae0417-163a-451a-b9d5-a72c46b6a5fc', 'パーティーに行くと、友だちの輪が広がります。', 'Jika saya pergi ke pesta, lingkaran pertemanan saya bertambah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('84ae0417-163a-451a-b9d5-a72c46b6a5fc', 'うわっ！コウイチ、なんで金の輪っかのイヤリングなんて付けてるの？', 'Aduh! Kenapa kamu memakai anting-anting emas, Koichi?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('39305989-3ade-423c-8038-c28818682c27', 'vocabulary', '協会', '協会', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Ketika Anda bertemu untuk bekerja sama, Anda berkumpul untuk saling membantu. Salah satu bentuknya adalah ketika masyarakat membentuk perkumpulan. Mereka semua bekerja sama dan bersatu untuk membantu satu sama lain dan diri mereka sendiri.', 'Ketika Anda bertemu untuk bekerja sama, Anda berkumpul untuk saling membantu. Salah satu bentuknya adalah ketika masyarakat membentuk perkumpulan. Mereka semua bekerja sama dan bersatu untuk membantu satu sama lain dan diri mereka sendiri.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('39305989-3ade-423c-8038-c28818682c27', 'Asosiasi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('39305989-3ade-423c-8038-c28818682c27', 'Organization', false) ON CONFLICT DO NOTHING;
