INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('39305989-3ade-423c-8038-c28818682c27', 'きょうかい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39305989-3ade-423c-8038-c28818682c27', 'コウイチ会長はミーチングで話しすぎるけど、ワニカニ協会の会員になればさまざまなメリットがあるよ。', 'Presiden Koichi berbicara terlalu banyak di pertemuan, tetapi ada banyak manfaat menjadi anggota Masyarakat WaniKani.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39305989-3ade-423c-8038-c28818682c27', '明日は協会の集まりがあるので、六時に起こしてください。', 'Saya harus menghadiri rapat organisasi besok, jadi tolong bangunkan saya jam enam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('39305989-3ade-423c-8038-c28818682c27', 'こんにちは。僕はコウイチといいます。オレゴン州ポートランド市のポートランド剣道協会で、イベントマネージャーをしています。', 'Halo. Nama saya Koichi dan saya manajer acara untuk Portland Kendo Association di Portland, Oregon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', 'vocabulary', '協力', '協力', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kekuatan kerja sama adalah tingkat kerja sama Anda. Seberapa besar kolaborasi atau bantuan yang Anda berikan.', 'Kekuatan kerja sama adalah tingkat kerja sama Anda. Seberapa besar kolaborasi atau bantuan yang Anda berikan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', 'Kerjasama', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', 'Collaboration', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', 'Assistance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', 'きょうりょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', 'これは皆様のご協力のたまものです。', 'Ini adalah hasil kerja sama semua orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', 'コウイチが協力したかいもあって、ビエトはぶ事にシアトル市の市ぎ会ぎ員になることができました。', 'Berkat kerjasama Koichi, Viet berhasil menjadi anggota dewan kota di Seattle.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5c5babe1-ce40-4b47-90da-3f4f67314161', '我々に協力するか、少なくとも協力するふりをしてくれませんか？', 'Bisakah Anda bekerja sama atau setidaknya berpura-pura bekerja sama dengan kami?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('229f812c-d47f-4213-b3b5-15d403f77de8', 'vocabulary', '一周', '一周', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Satu keliling adalah satu kali putaran. Berapa kali kamu akan mengelilingi bulan? Hanya 一周?', 'Satu keliling adalah satu kali putaran. Berapa kali kamu akan mengelilingi bulan? Hanya 一周?') ON CONFLICT (id) DO NOTHING;
