INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('229f812c-d47f-4213-b3b5-15d403f77de8', 'いっしゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('229f812c-d47f-4213-b3b5-15d403f77de8', 'コウイチは、最後の一周で十人のランナーをゴボウぬきした。', 'Koichi melewati sepuluh pelari di lap terakhir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('229f812c-d47f-4213-b3b5-15d403f77de8', 'コウイチはグラウンド一周を三分台で走ります。', 'Koichi dapat berlari satu putaran lintasan dalam tiga hingga empat menit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('229f812c-d47f-4213-b3b5-15d403f77de8', 'トーフグチームは世界一周旅行に出かけるので、オフィスは約一年間不在となります。', 'Tim Tofugu akan melakukan perjalanan keliling dunia, sehingga kantor akan tutup selama kurang lebih satu tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('07e86b2d-7a0e-4e50-8575-8a042eea5533', 'vocabulary', '周囲', '周囲', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Keliling yang mengelilingi kita adalah keliling luas tersebut. Jangan melewatinya.', 'Keliling yang mengelilingi kita adalah keliling luas tersebut. Jangan melewatinya.') ON CONFLICT (id) DO NOTHING;
