INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('07e86b2d-7a0e-4e50-8575-8a042eea5533', 'しゅうい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('07e86b2d-7a0e-4e50-8575-8a042eea5533', 'あの女性の周囲にはいつもヤクザ風の男がいる。', 'Selalu ada pria tipe yakuza yang mengelilingi wanita itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('07e86b2d-7a0e-4e50-8575-8a042eea5533', 'コウイチは周囲の目を注意しながら黒いビルに入っていきました。', 'Koichi memasuki gedung berwarna hitam, berhati-hati terhadap sekelilingnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('07e86b2d-7a0e-4e50-8575-8a042eea5533', '富士山の火口の周囲は約三キロメートルで、深さは二百三十七メートルだと聞きました。', 'Saya diberitahu bahwa kawah Gunung Fuji memiliki lebar sekitar tiga kilometer dan kedalaman dua ratus tiga puluh tujuh meter.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7fb44b79-54ae-4523-919b-6528b4d2f44c', 'vocabulary', '周年', '周年', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Saat Anda mengelilingi seluruh keliling tahun, Anda kembali ke awal tahun. Ini adalah hari jadinya.', 'Saat Anda mengelilingi seluruh keliling tahun, Anda kembali ke awal tahun. Ini adalah hari jadinya.') ON CONFLICT (id) DO NOTHING;
