INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd44d34c-2967-44f2-a8c5-289b7f1cc6a1', 'このお肉、ちょっと固い。', 'Daging ini agak keras.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd44d34c-2967-44f2-a8c5-289b7f1cc6a1', '父の決心は固いと思います。', 'Saya pikir keputusan ayah saya tegas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd44d34c-2967-44f2-a8c5-289b7f1cc6a1', '兄は、口が固いことで有名です。', 'Kakak laki-laki saya dikenal sebagai orang yang bisa menjaga rahasia.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('83c94041-09ed-4eba-8227-dbb6714e477e', 'vocabulary', '四季', '四季', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Empat musim adalah empat musim. Entah mengapa banyak orang Jepang berpikir bahwa Jepang adalah satu-satunya tempat dengan empat musim yang berbeda. Tentu saja mereka belum mengunjungi separuh tempat di garis lintang mereka di seluruh dunia.', 'Empat musim adalah empat musim. Entah mengapa banyak orang Jepang berpikir bahwa Jepang adalah satu-satunya tempat dengan empat musim yang berbeda. Tentu saja mereka belum mengunjungi separuh tempat di garis lintang mereka di seluruh dunia.') ON CONFLICT (id) DO NOTHING;
