INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('595cfb90-8bc1-43cc-ba89-c6bba5065720', 'これはまたきわどい技をマスターしたね！', 'Anda sudah menguasai seni rumit seperti itu, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('595cfb90-8bc1-43cc-ba89-c6bba5065720', 'コウイチはニッカに新しい技を仕こんでいるんですか？', 'Apakah Koichi mengajari Nikka sebuah trik baru?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('595cfb90-8bc1-43cc-ba89-c6bba5065720', '柔道では力より技のほうが大切であります。', 'Dalam judo, teknik lebih penting daripada kekuatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('10d973ff-c37b-4020-ade3-2c8a45aff971', 'vocabulary', '技能', '技能', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Keahlian dan kemampuan Anda serupa. Itu sebabnya kata ini berarti salah satu atau. Kemampuan keterampilan Anda adalah keterampilan dan kemampuan Anda.', 'Keahlian dan kemampuan Anda serupa. Itu sebabnya kata ini berarti salah satu atau. Kemampuan keterampilan Anda adalah keterampilan dan kemampuan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('10d973ff-c37b-4020-ade3-2c8a45aff971', 'Keterampilan', true) ON CONFLICT DO NOTHING;
