INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('10d973ff-c37b-4020-ade3-2c8a45aff971', 'ぎのう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10d973ff-c37b-4020-ade3-2c8a45aff971', 'カナエは、先月末にウェブデザイン技能検定に合格した。', 'Kanae lulus tes keterampilan teknis untuk desain web pada akhir bulan lalu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10d973ff-c37b-4020-ade3-2c8a45aff971', 'リーディング、ライティング、リスニング、スピーキングの四つの技能をバランスよく上たつさせるのはむずかしい。', 'Sulit untuk meningkatkan keempat kemampuan membaca, menulis, mendengarkan, dan berbicara agar seimbang dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('10d973ff-c37b-4020-ade3-2c8a45aff971', '逃走するために、俺はCIA諜報員としての年月で習得した技能を駆使した。', 'Untuk melarikan diri, saya menggunakan keterampilan yang saya peroleh selama bertahun-tahun sebagai agen CIA.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('41f463a9-002c-40db-9777-b8761d746a21', 'vocabulary', '特技', '特技', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Keahlian khusus Anda adalah keahlian khusus Anda. Jadi, apa 特技mu?', 'Keahlian khusus Anda adalah keahlian khusus Anda. Jadi, apa 特技mu?') ON CONFLICT (id) DO NOTHING;
