INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('41f463a9-002c-40db-9777-b8761d746a21', 'とくぎ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41f463a9-002c-40db-9777-b8761d746a21', 'わたしの特技は、お湯をわかすことです。それ以外の特技は何一つありません。', 'Spesialisasi saya adalah air mendidih. Saya tidak memiliki satu pun keterampilan di luar itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41f463a9-002c-40db-9777-b8761d746a21', '私の六人ぐらい後ろにならんでる青い服の男の子、高校の同級生なんだけど、なんとオナラでセーラームーンのテーマをかなでるという特技を持ってるのよ。', 'Pria berkemeja biru sekitar enam orang di belakangku dalam antrean adalah salah satu teman sekelasku di sekolah menengah dan dia memiliki keahlian khusus di mana dia bisa memainkan lagu tema Sailor Moon dengan kentutnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('41f463a9-002c-40db-9777-b8761d746a21', 'コウイチの特技はお菓子作りです。お菓子作りが好きな理由は、みんなの嬉しそうな顔を見るのが好きだからだそうです。', 'Spesialisasi Koichi adalah membuat makanan penutup. Dia bilang dia suka membuatnya karena dia suka melihat wajah bahagia semua orang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dbffa63e-409e-4d80-abb1-b8cb266c40da', 'vocabulary', '骨折', '骨折', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Ketika tulang Anda patah, Anda akan mengalami patah tulang atau patah tulang.', 'Ketika tulang Anda patah, Anda akan mengalami patah tulang atau patah tulang.') ON CONFLICT (id) DO NOTHING;
