INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('dbffa63e-409e-4d80-abb1-b8cb266c40da', 'こっせつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dbffa63e-409e-4d80-abb1-b8cb266c40da', 'これはふくざつ骨折ですね。', 'Ini adalah patah tulang majemuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dbffa63e-409e-4d80-abb1-b8cb266c40da', 'コウイチは去年ひどい自動車事こにあってね。足を骨折しただけじゃなく、頭まで失くしてしまって、今はロボットになっちゃったんですよ。', 'Koichi mengalami kecelakaan mobil yang parah tahun lalu. Dia tidak hanya mematahkan kakinya, tapi dia juga kehilangan kepalanya dan sekarang dia menjadi robot.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dbffa63e-409e-4d80-abb1-b8cb266c40da', 'しばらくみんなで一緒に会ってないよね〜。最近どうしてるの？私は足の小指を骨折した以外は特に変わりないよ〜。（笑）', 'Sudah lama sejak kita semua berkumpul. Bagaimana kabarmu? Segalanya hampir sama dengan saya kecuali jari kelingking saya patah. Tertawa terbahak-bahak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1548528b-88e8-43ec-84f3-b0b9bb3c9b35', 'vocabulary', '取材', '取材', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Tugas Anda adalah mengambil materi dari sekelompok orang yang berbeda karena Anda sedang meliput suatu acara. Pengumpulan data ini harus menyeluruh, jadi usahakan Anda mengambil semua bahan dari sebanyak mungkin orang yang Anda temukan.', 'Tugas Anda adalah mengambil materi dari sekelompok orang yang berbeda karena Anda sedang meliput suatu acara. Pengumpulan data ini harus menyeluruh, jadi usahakan Anda mengambil semua bahan dari sebanyak mungkin orang yang Anda temukan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1548528b-88e8-43ec-84f3-b0b9bb3c9b35', 'Meliput Suatu Acara', true) ON CONFLICT DO NOTHING;
