INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1548528b-88e8-43ec-84f3-b0b9bb3c9b35', 'しゅざい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1548528b-88e8-43ec-84f3-b0b9bb3c9b35', '取材にご協力いただけませんか。', 'Saya ingin tahu apakah Anda mengizinkan kami melakukan wawancara?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1548528b-88e8-43ec-84f3-b0b9bb3c9b35', 'テレビの取材を受けた時に、金が全てではないと答えたところが、ニュース番組に使われていました。', 'Klip di mana saya diwawancarai oleh kru TV dan saya mengatakan bahwa uang bukanlah segalanya digunakan untuk sebuah program berita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1548528b-88e8-43ec-84f3-b0b9bb3c9b35', '無理は承知なんですが、どうにかご主人を取材させてもらうことはできないでしょうか？もし何とかして頂ければ、本当に本当に感謝します。', 'Saya tahu ini sulit, tetapi adakah cara agar saya bisa mengumpulkan data tentang suami Anda? Jika Anda dapat membantu saya mengatur wawancara, saya akan sangat menghargainya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2330b1a7-ae3d-47aa-9668-c7373154daa8', 'vocabulary', '木材', '木材', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kayu yang merupakan kayu adalah kayu kayu.', 'Kayu yang merupakan kayu adalah kayu kayu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2330b1a7-ae3d-47aa-9668-c7373154daa8', 'Kayu', true) ON CONFLICT DO NOTHING;
