INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28a0798c-2f55-4f5d-bfd0-6e38893cdf8f', 'かれが材料調たつのたん当者です。', 'Dia orang yang bertanggung jawab atas persiapan material.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28a0798c-2f55-4f5d-bfd0-6e38893cdf8f', '材料の二倍の水を入れてください。', 'Silakan tuangkan dua bagian air untuk satu bagian bahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('28a0798c-2f55-4f5d-bfd0-6e38893cdf8f', '私の好きな食べ物は饂飩ですが、麺の材料は、小麦粉と塩と水だけなんですよ。', 'Makanan favorit saya adalah mie udon dan bahannya hanya tepung terigu, garam, dan air.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c24efff-33f6-45cb-a8fc-7c5532ede9c9', 'vocabulary', '材木', '材木', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Pohon kayu adalah apa yang Anda gunakan untuk membuat kayu dan kayu.', 'Pohon kayu adalah apa yang Anda gunakan untuk membuat kayu dan kayu.') ON CONFLICT (id) DO NOTHING;
