INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c24efff-33f6-45cb-a8fc-7c5532ede9c9', 'なんで材木にクイックルワイパーをかけてるの？', 'Mengapa Anda mengepel kayu itu dengan penghapus Quickle?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c24efff-33f6-45cb-a8fc-7c5532ede9c9', 'あの材木おき場に夜の八時に行くと、神様に会えるらしいよ。', 'Saya mendengar bahwa jika Anda pergi ke tempat penebangan kayu pada jam 8 malam. kamu akan bisa bertemu Tuhan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c24efff-33f6-45cb-a8fc-7c5532ede9c9', '材木が来たらすぐに犬小屋作りに取り掛からないとな。', 'Kita harus mulai membangun rumah anjing segera setelah kayunya tiba.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f388175f-c1bd-4058-ba87-90914dafb2fc', 'vocabulary', '骨格', '骨格', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Status tulang Anda (alias bagaimana semuanya tersusun dan disatukan) sama dengan kerangka Anda. Status tulang itu terlihat bagus untukmu!', 'Status tulang Anda (alias bagaimana semuanya tersusun dan disatukan) sama dengan kerangka Anda. Status tulang itu terlihat bagus untukmu!') ON CONFLICT (id) DO NOTHING;
