INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f388175f-c1bd-4058-ba87-90914dafb2fc', 'ガッシリした骨格の男性がタイプです。', 'Saya suka pria dengan tubuh kokoh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f388175f-c1bd-4058-ba87-90914dafb2fc', '昨日は、この記事の骨格をまとめ終えました。', 'Kemarin, saya menyelesaikan garis besar artikel ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f388175f-c1bd-4058-ba87-90914dafb2fc', 'コーラが骨格の発育に悪影響を与えるという噂は本当ですか？', 'Apakah rumor bahwa cola merugikan perkembangan tulang benar?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2868543c-03f4-4586-84af-81b600a7b433', 'vocabulary', '芸能界', '芸能界', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Dunia kemampuan akting adalah dunia bisnis pertunjukan atau dengan kata lain industri hiburan.', 'Dunia kemampuan akting adalah dunia bisnis pertunjukan atau dengan kata lain industri hiburan.') ON CONFLICT (id) DO NOTHING;
