INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea43f4e3-30df-4cbd-8dbb-220939d4f8eb', 'あの骨を的にしてねらおう！', 'Ayo bidik dengan tulang itu sebagai target kita!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea43f4e3-30df-4cbd-8dbb-220939d4f8eb', 'クリステンは、転んでうでの骨を折った時もれいせいに行動していました。', 'Kristen bersikap tenang bahkan ketika dia terjatuh dan lengannya patah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ea43f4e3-30df-4cbd-8dbb-220939d4f8eb', '昨夜、トーフグのオフィスに放火する夢を見たんだけど、焼け跡の灰には、大量の魚の骨があったよ。', 'Tadi malam, saya bermimpi sedang membakar kantor Tofugu. Di antara abu reruntuhan, saya melihat segunung tulang ikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fd498d97-7e6c-4e2b-8274-534b19d25ccf', 'vocabulary', '仏', '仏', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
