INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fd498d97-7e6c-4e2b-8274-534b19d25ccf', 'ほとけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd498d97-7e6c-4e2b-8274-534b19d25ccf', 'ビエトはヤクザをやめて、仏の道に入ることを決意しました。', 'Viet telah memutuskan untuk keluar dari kelompok Yakuza dan mengikuti ajaran Buddha.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd498d97-7e6c-4e2b-8274-534b19d25ccf', 'コウイチは、いつも仏のようにれいせいで、えんま大王のようにきびしい。', 'Koichi selalu sekeren Buddha dan seketat Enma, Raja Neraka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fd498d97-7e6c-4e2b-8274-534b19d25ccf', '「知らぬが仏」や「仏の顔も三度まで」など、仏に関する諺はいくつかありますね。', 'Ada beberapa pepatah yang berhubungan dengan Buddha seperti, "apa yang kamu tidak tahu tidak akan menyakitimu," dan, "cacing yang hancur akan berubah."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b07d723-9db0-4513-944a-bc754699f984', 'vocabulary', '仏教', '仏教', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Ajaran buddha adalah apa yang harus Anda pelajari ketika Anda mempelajari agama Buddha.', 'Ajaran buddha adalah apa yang harus Anda pelajari ketika Anda mempelajari agama Buddha.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5b07d723-9db0-4513-944a-bc754699f984', 'agama Buddha', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5b07d723-9db0-4513-944a-bc754699f984', 'ぶっきょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b07d723-9db0-4513-944a-bc754699f984', '仏教とヒンドゥー教のちがいを正かくにせつ明できますか？', 'Bisakah Anda menjelaskan perbedaan antara agama Buddha dan Hindu secara akurat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b07d723-9db0-4513-944a-bc754699f984', 'そんなに信心深い人間じゃないんですが、一おう神道と仏教を信こうしています。', 'Saya bukan orang yang sangat religius, tapi saya menganut agama Shinto dan Budha.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b07d723-9db0-4513-944a-bc754699f984', '仏教に伴って、お香は六世紀に日本に伝来しました。', 'Seiring dengan agama Buddha, dupa dibawa ke Jepang pada abad ke-6.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', 'vocabulary', '大仏', '大仏', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Patung Buddha berukuran besar tidak masuk akal jika Anda tidak mengetahui konteksnya. Terdapat patung Buddha raksasa yang disebut Daibutsu, sehingga kata ini diterjemahkan menjadi Buddha Besar atau Patung Buddha Raksasa.', 'Patung Buddha berukuran besar tidak masuk akal jika Anda tidak mengetahui konteksnya. Terdapat patung Buddha raksasa yang disebut Daibutsu, sehingga kata ini diterjemahkan menjadi Buddha Besar atau Patung Buddha Raksasa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', 'Patung Buddha Raksasa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', 'Daibutsu', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', 'Great Buddha', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', 'だいぶつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', '昨日、ならの大仏をおとずれました。', 'Saya mengunjungi Buddha Agung di Nara kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', '大仏をすんげーしんけんに見つめてるあの男、だれ？', 'Siapa pria yang menatap patung Buddha raksasa itu dengan begitu serius?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df00570e-aed2-46b8-a63a-6e8c1eb24a42', '「彼女、大仏さんと付き合っているのよ。」「とても信じられないわね。だって、彼女の父親と言ってもいいくらい年上でしょ？」', '"Dia berkencan dengan Tuan Patung Buddha Raksasa." "Kau bisa saja membodohiku. Dia sudah cukup umur untuk menjadi ayahnya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', 'vocabulary', '勇気', '勇気', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Perasaan keberanian itu adalah keberanian.', 'Perasaan keberanian itu adalah keberanian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', 'Keberanian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', 'Bravery', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', 'Valour', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', 'Valor', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', 'ゆうき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', 'ワニカニユーザーは、コウイチのスピーチに勇気づけられました。', 'Pengguna WaniKani terdorong oleh pidato Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', '他の人の意見に反対するにはふ通は勇気がいると思うけど、トーフグで働いている時はそんな心配はいらないよ。', 'Biasanya dibutuhkan keberanian untuk menentang orang lain, tapi Anda tidak perlu khawatir tentang hal itu ketika Anda bekerja di Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2f71aabc-fb09-4681-b9ab-63392a675c14', '「フグ、私のお父さんは素晴らしい人だったのよ。いつも私に、流れに逆らって泳ぐには力と勇気が必要だ。浮かぶだけなら死んだ魚でもできるって言ってたわ。」「サーモン、それって、サミュエル・スマイルズの名言じゃなかったっけ。」', '“Fugu, ayahku adalah orang yang hebat. Dia selalu mengatakan kepadaku bahwa berenang melawan arus membutuhkan kekuatan dan keberanian, sementara ikan mati pun bisa mengapung bersamanya.” "Salmon, bukankah itu kutipan dari Samuel Smiles?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b07c7f3d-08d3-4c70-948d-1eb9826fdd70', 'vocabulary', '区', '区', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b07c7f3d-08d3-4c70-948d-1eb9826fdd70', 'Distrik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b07c7f3d-08d3-4c70-948d-1eb9826fdd70', 'Ward', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b07c7f3d-08d3-4c70-948d-1eb9826fdd70', 'く', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b07c7f3d-08d3-4c70-948d-1eb9826fdd70', '私のおじは、中央区の区役所で働いています。', 'Paman saya bekerja di kantor lingkungan Chuo-ku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b07c7f3d-08d3-4c70-948d-1eb9826fdd70', 'ここはちゅう車きん止区なので、車は止められませんよ。', 'Anda tidak dapat parkir di sini karena ini adalah distrik dilarang parkir.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b07c7f3d-08d3-4c70-948d-1eb9826fdd70', 'ここ最近、横浜の外国人居留区では、暴力行為がかつてないほど横行している。', 'Baru-baru ini, kawasan asing di Yokohama mengalami tingkat kekerasan yang belum pernah terjadi sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', 'vocabulary', '区分', '区分', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Pikirkan tentang bagian dari distrik tersebut. Pisahkan mereka dalam pikiran Anda (bagian-bagian ini). Masing-masing bagian merupakan pemekaran distrik. Anda juga dapat mengambil setiap divisi dan membuat klasifikasinya. Silakan klasifikasikan masing-masing.', 'Pikirkan tentang bagian dari distrik tersebut. Pisahkan mereka dalam pikiran Anda (bagian-bagian ini). Masing-masing bagian merupakan pemekaran distrik. Anda juga dapat mengambil setiap divisi dan membuat klasifikasinya. Silakan klasifikasikan masing-masing.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', 'Divisi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', 'Section', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', 'Classification', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', 'くぶん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', 'この町では、校区が三つに区分されています。', 'Di kota ini, distrik sekolah dibagi menjadi tiga divisi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', 'これは予算区分の問題なので、私にはどうしようもありません。', 'Ini masalah klasifikasi anggaran, jadi saya tidak bisa berbuat apa-apa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08165920-b849-42aa-8879-6eccd4a81504', '私は、テロ行為と合法的な戦争を区分する必要は無いと思います。', 'Saya rasa tidak perlu membedakan terorisme dengan peperangan yang sah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', 'vocabulary', '地区', '地区', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Distrik bumi bukanlah tata surya kita atau semacamnya. Kita berbicara tentang bagian tertentu dari bumi, dan menamainya sebagai sebuah distrik. Jadi, apa sepetak bumi ini? Itu adalah distrik, area, atau zona.', 'Distrik bumi bukanlah tata surya kita atau semacamnya. Kita berbicara tentang bagian tertentu dari bumi, dan menamainya sebagai sebuah distrik. Jadi, apa sepetak bumi ini? Itu adalah distrik, area, atau zona.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', 'Distrik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', 'Area', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', 'Zone', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', 'ちく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', '来月から、この地区のたん当者が変わるので、あらかじめお知らせさせていただきます。', 'Saya ingin memberi tahu Anda sebelumnya bahwa penanggung jawab zona ini akan berganti bulan depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', 'この地区には、りん時ふくしきゅう付金を受きゅうしている人が三十八人います。', 'Terdapat tiga puluh delapan orang yang menerima tunjangan kesejahteraan sementara di distrik ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf1d7585-566d-4672-b39d-8eccbc3c2629', 'コウイチは、近日中に地区検察局に自白内容を収めたビデオテープを送ることを計画しているようですよ。', 'Tampaknya Koichi berencana untuk segera memberikan pengakuan dalam rekaman video ke kantor kejaksaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b10cb66e-050c-4b5e-9be7-86e3403a9201', 'vocabulary', '坂', '坂', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
