INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b10cb66e-050c-4b5e-9be7-86e3403a9201', 'Hill', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b10cb66e-050c-4b5e-9be7-86e3403a9201', 'さか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b10cb66e-050c-4b5e-9be7-86e3403a9201', 'その寺なら、この坂を上ったところにありますよ。', 'Kuil itu berdiri di puncak bukit ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b10cb66e-050c-4b5e-9be7-86e3403a9201', 'ビエトは自転車でゆるやかな坂を下るのが好きです。', 'Viet suka menuruni lereng yang landai dengan sepedanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b10cb66e-050c-4b5e-9be7-86e3403a9201', 'スター選手であったフグを失ってから、トーフグ野球チームの調子は下り坂となってしまった。', 'Tim bisbol Tofugu berada dalam kondisi terpuruk sejak kehilangan pemain bintangnya, Fugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f66ff3a3-5b64-4902-aa1e-2dd8fb75f197', 'vocabulary', '岩', '岩', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f66ff3a3-5b64-4902-aa1e-2dd8fb75f197', 'Batu besar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f66ff3a3-5b64-4902-aa1e-2dd8fb75f197', 'Rock', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f66ff3a3-5b64-4902-aa1e-2dd8fb75f197', 'いわ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f66ff3a3-5b64-4902-aa1e-2dd8fb75f197', 'あの岩のところまでどっちが先に着けるか競争しよう！', 'Ayo berlomba dan lihat siapa di antara kita yang bisa mencapai batu itu terlebih dahulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f66ff3a3-5b64-4902-aa1e-2dd8fb75f197', 'トーフグにはコウイチが岩みたいなかおをしている時は、話しかけないでそっとしておくという決まりがあります。', 'Di Tofugu, ada peraturan bahwa orang harus meninggalkan Koichi sendirian ketika wajahnya terlihat seperti batu besar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f66ff3a3-5b64-4902-aa1e-2dd8fb75f197', 'コウイチは、夢の中で大きな岩が頭上に落ちてくるところで、目が覚めた。', 'Koichi terbangun ketika sebuah batu besar jatuh ke arahnya dalam mimpi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bd22c4ac-f187-4410-a4d1-cd545cea1442', 'vocabulary', '毒', '毒', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bd22c4ac-f187-4410-a4d1-cd545cea1442', 'Racun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bd22c4ac-f187-4410-a4d1-cd545cea1442', 'どく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd22c4ac-f187-4410-a4d1-cd545cea1442', '働きすぎは体に毒ですよ。', 'Bekerja terlalu banyak berbahaya bagi tubuh Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd22c4ac-f187-4410-a4d1-cd545cea1442', 'ビエトのつくえの引き出しには、コウイチをいつでも暗殺できるように毒の矢が仕こんである。', 'Viet menyembunyikan panah beracun di laci mejanya sehingga dia bisa membunuh Koichi kapan saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd22c4ac-f187-4410-a4d1-cd545cea1442', 'フグはとても美味しく、食べる人の心を豊かにしてくれますが、一方で猛毒も持っています。', 'Meskipun ikan buntal sangat lezat dan memberikan pengalaman kuliner yang sangat memuaskan, ikan buntal juga membawa racun yang mematikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('91455ea0-6bfc-4d90-a61a-758e156390e2', 'vocabulary', '中毒', '中毒', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Ketika racun dimasukkan ke dalam sesuatu, itu adalah keracunan.', 'Ketika racun dimasukkan ke dalam sesuatu, itu adalah keracunan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91455ea0-6bfc-4d90-a61a-758e156390e2', 'Keracunan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('91455ea0-6bfc-4d90-a61a-758e156390e2', 'Addiction', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('91455ea0-6bfc-4d90-a61a-758e156390e2', 'ちゅうどく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91455ea0-6bfc-4d90-a61a-758e156390e2', '食中毒でかこきゅうになり、きゅうきゅう病院へはん送されました。', 'Saya mengalami hiperventilasi karena keracunan makanan dan harus dibawa ke ruang gawat darurat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91455ea0-6bfc-4d90-a61a-758e156390e2', 'ガス中毒にならないよう気を付けてくださいね。', 'Hati-hati jangan sampai keracunan gas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('91455ea0-6bfc-4d90-a61a-758e156390e2', 'フグは麻薬中毒から逃れようとしてリハビリセンターに行ったが、結局また麻薬中毒になってしまった。', 'Fugu mencoba melepaskan diri dari kecanduan narkoba dan pergi ke rehabilitasi, namun akhirnya kambuh lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'vocabulary', '有毒', '有毒', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Ketika sesuatu mengandung racun, itu beracun dan beracun.', 'Ketika sesuatu mengandung racun, itu beracun dan beracun.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'Beracun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'Toxic', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'Venomous', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'ゆうどく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'ガラガラヘビって有毒なんですか？', 'Apakah ular derik itu berbisa?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'ダリンが道ばたに生えていた有毒キノコを間ちがって食べて、病院にはこばれてしまいました。', 'Darin secara tidak sengaja memakan jamur beracun yang tumbuh di pinggir jalan dan dikirim ke rumah sakit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1c02e1ed-c05b-4d2e-9d7d-ae03552cb40d', 'ビエトだけがコウイチのオナラが有毒ガスのような臭いがすることを知っている。', 'Hanya Viet yang tahu kalau kentut Koichi berbau seperti asap beracun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa192385-1aad-4029-9469-a481b35465fb', 'vocabulary', '食中毒', '食中毒', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Racun yang ada di dalam makanan adalah keracunan makanan. Tidak menyenangkan ketika kamu mendapatkan ini :(', 'Racun yang ada di dalam makanan adalah keracunan makanan. Tidak menyenangkan ketika kamu mendapatkan ini :(') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fa192385-1aad-4029-9469-a481b35465fb', 'Keracunan Makanan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fa192385-1aad-4029-9469-a481b35465fb', 'しょくちゅうどく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa192385-1aad-4029-9469-a481b35465fb', '食中毒で会社を休んでしまい、大変申しわけありません。', 'Saya sangat menyesal telah mengambil cuti karena keracunan makanan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa192385-1aad-4029-9469-a481b35465fb', 'ハーゲンダッツを食べて食中毒を乗りこえるというとても役立つ情ほうを教えてくれて、本当にありがとうございました。', 'Terima kasih banyak atas informasi bermanfaat Anda tentang cara mengatasi keracunan makanan karena mengonsumsi Häagen-Dazs.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa192385-1aad-4029-9469-a481b35465fb', 'フグが私に食中毒の危険性をレクチャーしてくれたんだけどさぁ、説明がすっごく分かりにくかったんだよね。', 'Fugu memberi saya ceramah tentang risiko keracunan makanan, namun penjelasannya sangat sulit untuk dipahami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('27185159-77c2-4835-b3e4-ae0b11fd3d01', 'vocabulary', '毒ガス', '毒ガス', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Gas Beracun adalah hal yang buruk. Itu adalah gas beracun.', 'Gas Beracun adalah hal yang buruk. Itu adalah gas beracun.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('27185159-77c2-4835-b3e4-ae0b11fd3d01', 'Gas Beracun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('27185159-77c2-4835-b3e4-ae0b11fd3d01', 'どくがす', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('27185159-77c2-4835-b3e4-ae0b11fd3d01', 'どくガス', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27185159-77c2-4835-b3e4-ae0b11fd3d01', '毒ガスは第一次世界大戦で使われ始めたらしいです。', 'Saya membaca bahwa gas beracun pertama kali digunakan pada Perang Dunia I.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27185159-77c2-4835-b3e4-ae0b11fd3d01', '午前十時からの毒ガスの使い方のレッスンを取っていたはずなんですが、もう一度かくにんしてもらえますか？', 'Maaf, tapi saya yakin saya telah mengambil pelajaran tentang cara menggunakan gas beracun pada pukul 10.00. Bisakah Anda memeriksanya kembali?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27185159-77c2-4835-b3e4-ae0b11fd3d01', '「この野郎！また屁をこきやがったな！毒ガスのように臭いじゃねえか。」「すみません。もう二度とおならはしません。」「いいや、きっとまたこくさ。もう堪忍袋の緒が切れた。お前は首だ。」「そんな〜。」', '"Dasar bajingan! Kamu kentut lagi. Baunya seperti gas beracun!" “Saya minta maaf. Saya tidak akan pernah melakukannya lagi.” "Tidak, saya yakin Anda akan melakukannya. Itu keputusan terakhir. Anda dipecat." "Oh tidak~!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('afee8a66-8eb2-420e-a273-bccdd8252788', 'vocabulary', '浅い', '浅い', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari dangkal? Itu dangkal.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari dangkal? Itu dangkal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('afee8a66-8eb2-420e-a273-bccdd8252788', 'Dangkal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('afee8a66-8eb2-420e-a273-bccdd8252788', 'あさい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afee8a66-8eb2-420e-a273-bccdd8252788', 'この海は浅いから子どもも安心して泳げます。', 'Pantai ini dangkal, sehingga anak-anak pun bisa berenang dengan aman di sini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afee8a66-8eb2-420e-a273-bccdd8252788', '考えの浅い人間にはなりたくありません。', 'Saya tidak ingin menjadi orang yang berpikiran dangkal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('afee8a66-8eb2-420e-a273-bccdd8252788', '酔っ払うと、眠りが浅くなっちゃって、早朝覚醒しちゃうんだよね。', 'Setiap kali saya mabuk, saya hanya tidur sebentar dan bangun pagi-pagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9c8cd3fd-f205-4fc1-ad7d-92eb18a21585', 'vocabulary', '軍人', '軍人', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Seorang tentara adalah seseorang di tentara. Apa sebutan orang-orang itu? Mereka tentara.', 'Seorang tentara adalah seseorang di tentara. Apa sebutan orang-orang itu? Mereka tentara.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9c8cd3fd-f205-4fc1-ad7d-92eb18a21585', 'Tentara', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9c8cd3fd-f205-4fc1-ad7d-92eb18a21585', 'ぐんじん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c8cd3fd-f205-4fc1-ad7d-92eb18a21585', 'おきなわにはアメリカ軍のき地があるから、軍人さんがたくさんいます。', 'Karena ada pangkalan militer Amerika di Okinawa, jumlah tentaranya banyak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c8cd3fd-f205-4fc1-ad7d-92eb18a21585', 'その軍人の勇気ある行動が、多くの人の命をすくいました。', 'Tindakan berani prajurit itu menyelamatkan banyak nyawa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9c8cd3fd-f205-4fc1-ad7d-92eb18a21585', '昨日、上司に俺はリストラで首になるって言われちゃってさ。だから、今、軍人になることを真剣に考えてるんだ。', 'Kemarin bos saya memberi tahu saya bahwa saya akan dipecat, jadi sekarang saya serius berpikir untuk menjadi tentara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('05f810f0-5b2d-4fbd-8f40-e2efc9f60aff', 'vocabulary', '海軍', '海軍', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Tentara laut adalah cabang militer yang memiliki perahu dan melakukan urusan laut/laut. Apa itu? Angkatan Laut.', 'Tentara laut adalah cabang militer yang memiliki perahu dan melakukan urusan laut/laut. Apa itu? Angkatan Laut.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('05f810f0-5b2d-4fbd-8f40-e2efc9f60aff', 'Angkatan laut', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('05f810f0-5b2d-4fbd-8f40-e2efc9f60aff', 'かいぐん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('05f810f0-5b2d-4fbd-8f40-e2efc9f60aff', '海軍にいた時、おれ的にはお前には十分すぎるぐらいやさしくしてたつもりなんだけどな。', 'Menurut standarku, aku hampir terlalu baik padamu saat kita masih di angkatan laut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('05f810f0-5b2d-4fbd-8f40-e2efc9f60aff', 'この海軍のしきたりでは、本当に悪かったなと思って反せいしている人は、自らすすんでトイレそうじをすることでせい意を見せることになっています。', 'Sebagai institusi angkatan laut ini, jika seseorang benar-benar menyesali suatu hal, mereka harus dengan sukarela membersihkan toilet untuk menunjukkan itikad baik mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('05f810f0-5b2d-4fbd-8f40-e2efc9f60aff', '電話に出れなくてごめん。信じられないかもしれないけど、実は今海軍の船の上なんだよね。降りたら電話するね。', 'Maaf saya tidak dapat menerima telepon Anda. Percaya atau tidak, saat ini saya sebenarnya berada di kapal angkatan laut. Aku akan meneleponmu saat aku turun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('411a1552-bff3-4f73-94a9-7b9c1c192320', 'vocabulary', '仏像', '仏像', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda memiliki gambar Buddha. Apa itu? Itu adalah patung Buddha. Itu juga bisa berarti gambar Buddha.', 'Anda memiliki gambar Buddha. Apa itu? Itu adalah patung Buddha. Itu juga bisa berarti gambar Buddha.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('411a1552-bff3-4f73-94a9-7b9c1c192320', 'Patung Buddha', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('411a1552-bff3-4f73-94a9-7b9c1c192320', 'Image Of Buddha', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('411a1552-bff3-4f73-94a9-7b9c1c192320', 'ぶつぞう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('411a1552-bff3-4f73-94a9-7b9c1c192320', '日本で仏像を買ったら、申告しないといけませんか？', 'Apakah saya harus menyatakan jika saya membeli patung Budha di Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('411a1552-bff3-4f73-94a9-7b9c1c192320', '仏像はよく金色に作られています。', 'Patung Buddha seringkali terbuat dari emas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('411a1552-bff3-4f73-94a9-7b9c1c192320', '誰かがうちのオフィスに毎月仏像を一体ずつ送ってくるんです。心当たりのある方は、どうか名乗り出て下さい。', 'Seseorang mengirimkan patung Buddha ke kantor kami setiap bulan. Jika Anda adalah orang tersebut, silakan maju ke depan dan identifikasikan diri Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bc0c1a35-4da6-4d4f-bc4c-99f498512d00', 'vocabulary', '指輪', '指輪', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Cincin di jari adalah jenis cincin yang akan Anda pasang di jari Anda. Itu hanyalah sebuah "dering", jadi Anda harus mengetahui apa "dering" itu melalui konteksnya.', 'Cincin di jari adalah jenis cincin yang akan Anda pasang di jari Anda. Itu hanyalah sebuah "dering", jadi Anda harus mengetahui apa "dering" itu melalui konteksnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bc0c1a35-4da6-4d4f-bc4c-99f498512d00', 'Dering', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bc0c1a35-4da6-4d4f-bc4c-99f498512d00', 'ゆびわ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc0c1a35-4da6-4d4f-bc4c-99f498512d00', '大事な指輪を失くしてしまい、気分が晴れません。', 'Saya kehilangan cincin berharga saya dan saya merasa tidak enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc0c1a35-4da6-4d4f-bc4c-99f498512d00', '指輪が指から外れなくなってしまいました。', 'Aku tidak bisa melepaskan cincin ini dari jariku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bc0c1a35-4da6-4d4f-bc4c-99f498512d00', '「ボーナスが出たら、ダイヤモンドの指輪を買ってやるよ。」「あなたはいつも口先ばかりでしょ。」', '"Saat aku mendapat bonus, aku akan membelikanmu cincin berlian." “Kamu selalu mengatakan itu, tapi kata-kata hanyalah kata-kata.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', 'vocabulary', '輪ゴム', '輪ゴム', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Cincin permen karet (ゴム) (yang sering disebut orang Jepang sebagai karet) adalah cincin karet. Cincin karet apa yang sering digunakan orang? Itu adalah karet gelang.', 'Cincin permen karet (ゴム) (yang sering disebut orang Jepang sebagai karet) adalah cincin karet. Cincin karet apa yang sering digunakan orang? Itu adalah karet gelang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', 'Karet Gelang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', 'Elastic Band', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', 'わごむ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', 'わゴム', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', 'この輪ゴムはとても丈夫です。', 'Pita elastis ini sangat tahan lama.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', '輪ゴムどろぼうのうたがいをかけられていたが、ついに晴れの身となりました。', 'Mereka mencurigai saya adalah perampok karet gelang, namun kini saya telah dibebaskan dari semua tuduhan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7841c2a5-09a8-4b47-baf4-274e583ee645', 'わぁ！そのワンピマジで可愛い！カラフルな輪ゴムの絵がたくさんプリントしてあるんだね！そんなワンピ初めてみたよ。', 'Ya Tuhan, aku sangat menyukai gaunmu! Banyak sekali gambar karet gelang warna-warni yang tercetak di atasnya ya? Saya belum pernah melihat gaun seperti ini sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9aaa7361-0f61-45d0-9d0b-0f5238704e20', 'vocabulary', '練習する', '練習する', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda mungkin pernah melihat 練習, yang artinya "latihan". Jadi, kalau kamu menjadikannya kata kerja, kamu harus berlatih.', 'Anda mungkin pernah melihat 練習, yang artinya "latihan". Jadi, kalau kamu menjadikannya kata kerja, kamu harus berlatih.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9aaa7361-0f61-45d0-9d0b-0f5238704e20', 'Untuk Berlatih', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9aaa7361-0f61-45d0-9d0b-0f5238704e20', 'れんしゅうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9aaa7361-0f61-45d0-9d0b-0f5238704e20', '昨日、肉って言葉の発音を六時間も練習したんだぜ。', 'Saya berlatih mengucapkan kata "daging" selama enam jam kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9aaa7361-0f61-45d0-9d0b-0f5238704e20', '「おんをあだで返すような子に育てたおぼえはないよ！」というしばいのセリフを言うのを練習しています。', 'Saya sedang melatih kalimat dalam drama yang berbunyi, "Saya tidak membesarkanmu menjadi anak yang tidak tahu berterima kasih!"') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9aaa7361-0f61-45d0-9d0b-0f5238704e20', '「俺達、惨敗しちまったな。」「ああ、惨敗しちまった。もっとたくさん練習しないとな。」', '"Bung, kami benar-benar hancur." “Ya, itu gagal total. Saya kira kita perlu lebih banyak latihan.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('029725f8-c132-4fc4-b9be-b8cc4df9e998', 'vocabulary', '芸術家', '芸術家', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda tahu bahwa 芸術 adalah seni, jadi Anda akan berpikir bahwa 芸術家 adalah sesuatu seperti "rumah seni". Ya, ternyata tidak. Coba pikirkan seperti ini: Siapakah orang yang bekerja untuk "House Art"? Itu artisnya.', 'Anda tahu bahwa 芸術 adalah seni, jadi Anda akan berpikir bahwa 芸術家 adalah sesuatu seperti "rumah seni". Ya, ternyata tidak. Coba pikirkan seperti ini: Siapakah orang yang bekerja untuk "House Art"? Itu artisnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('029725f8-c132-4fc4-b9be-b8cc4df9e998', 'Artis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('029725f8-c132-4fc4-b9be-b8cc4df9e998', 'げいじゅつか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('029725f8-c132-4fc4-b9be-b8cc4df9e998', 'この芸術家の作品には、苦笑いがかくせません。', 'Saya tidak bisa menyembunyikan senyum masam saya pada karya seniman ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('029725f8-c132-4fc4-b9be-b8cc4df9e998', 'その芸術家は、弟子に留守番をたのんで、ヨーロッパに留学しました。', 'Seniman tersebut meminta muridnya untuk menjaga rumahnya selama dia pergi dan berangkat ke Eropa untuk belajar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('029725f8-c132-4fc4-b9be-b8cc4df9e998', '再来月のマラソン大会、芸術家達と一緒に参加するってのはどう？', 'Bagaimana kalau lari maraton dengan sekelompok artis pada bulan berikutnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('795bc89d-e001-463d-8a77-39f52a053213', 'vocabulary', '卒業', '卒業', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Urusan kelulusanmu adalah kelulusanmu. Kalau dipikir-pikir, ini semacam bisnis besar, membuat Anda lulus dari sekolah mahal. Bisnis wisuda berfokus pada wisuda, dan membawa Anda ke sana (petunjuk: bisnis ini mungkin adalah sekolah).', 'Urusan kelulusanmu adalah kelulusanmu. Kalau dipikir-pikir, ini semacam bisnis besar, membuat Anda lulus dari sekolah mahal. Bisnis wisuda berfokus pada wisuda, dan membawa Anda ke sana (petunjuk: bisnis ini mungkin adalah sekolah).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('795bc89d-e001-463d-8a77-39f52a053213', 'Wisuda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('795bc89d-e001-463d-8a77-39f52a053213', 'そつぎょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('795bc89d-e001-463d-8a77-39f52a053213', '日本では三月が卒業のシーズンです。', 'Di Jepang, bulan Maret adalah musim kelulusan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('795bc89d-e001-463d-8a77-39f52a053213', 'ビエトはTFG48というアイドルグループを作ってずっとセンターをつとめているが、いつまでたっても卒業する気配がない。もう58才なのに。', 'Viet membuat grup idola bernama TFG48 dan sudah lama tampil sebagai centernya, tapi sepertinya dia masih belum lulus. Dia sudah berusia 58 tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('795bc89d-e001-463d-8a77-39f52a053213', '先生は、日本語が話せると、卒業生の就職の可能性が高くなると思いますか？', 'Guru, menurut Anda apakah kemampuan berbicara bahasa Jepang meningkatkan peluang lulusan untuk mendapatkan pekerjaan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e7baf0e6-59da-4385-9ba0-aa4c5b76d067', 'vocabulary', '卒業式', '卒業式', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda tahu bahwa 卒業 adalah wisuda, jadi bagaimana jika Anda menambahkan upacara ke dalamnya? Itu menjadikannya upacara wisuda.', 'Anda tahu bahwa 卒業 adalah wisuda, jadi bagaimana jika Anda menambahkan upacara ke dalamnya? Itu menjadikannya upacara wisuda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e7baf0e6-59da-4385-9ba0-aa4c5b76d067', 'Upacara Wisuda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e7baf0e6-59da-4385-9ba0-aa4c5b76d067', 'Graduation', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e7baf0e6-59da-4385-9ba0-aa4c5b76d067', 'そつぎょうしき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e7baf0e6-59da-4385-9ba0-aa4c5b76d067', '卒業式の後で、橋の上で一しょに写真をとろうよ！', 'Usai upacara wisuda, yuk berfoto bersama di jembatan!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e7baf0e6-59da-4385-9ba0-aa4c5b76d067', 'はあ？卒業式にビヨンセが来て歌を歌ってくれた？まさか！冗談でしょう？', 'Hah? Apakah Anda mengatakan bahwa Beyonce datang ke pesta wisuda dan bernyanyi untuk kalian? Mustahil! Anda pasti bercanda!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e7baf0e6-59da-4385-9ba0-aa4c5b76d067', '卒業式の後の旅行超楽しみだよ〜！ゆっくり露天風呂に入って、山の幸をいっぱい食べ尽くそうね。ところで、念のため確認だけど、宿の予約してくれたんだよね？', 'Saya sangat bersemangat untuk perjalanan ini setelah upacara wisuda kami! Mari bersantai di sumber air panas dan makan banyak makanan lokal yang lezat. Ngomong-ngomong, hanya memastikan tapi kamu sudah membuat reservasi di cottage, kan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('38658e14-cd7d-4d2c-9426-b95a28ea1870', 'vocabulary', '希望', '希望', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Harapan dan keinginan Anda terkandung dalam kosakata ini. Jadi, apa arti kata ini? Itu adalah harapan dan harapan. Keduanya akan berhasil.', 'Harapan dan keinginan Anda terkandung dalam kosakata ini. Jadi, apa arti kata ini? Itu adalah harapan dan harapan. Keduanya akan berhasil.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('38658e14-cd7d-4d2c-9426-b95a28ea1870', 'Harapan', true) ON CONFLICT DO NOTHING;
