INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38658e14-cd7d-4d2c-9426-b95a28ea1870', '回転し金がそこをついてしまったが、まだ希望はあるとしんじているんだ。', 'Kami kehabisan dana bergulir, tapi saya yakin kami masih punya harapan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38658e14-cd7d-4d2c-9426-b95a28ea1870', 'この方は、とく名を希望しているようですね。', 'Rupanya dia ingin tetap anonim.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38658e14-cd7d-4d2c-9426-b95a28ea1870', '「お座席のご希望はございますか？」「はい。窓側の席を取っていただけますか？」「かしこまりました。」', '"Apakah kamu punya preferensi tempat duduk?" "Ya, bolehkah saya mendapatkan tempat duduk dekat jendela?" "Tentu."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb2aee35-a965-429f-880c-975e8fe32a91', 'vocabulary', '希望する', '希望する', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda tahu bahwa 希望 adalah "keinginan" atau "harapan". Jadi, ketika Anda "melakukan sebuah keinginan" atau "melakukan sebuah harapan". Ketika Anda melakukan itu, itu berarti meminta atau berharap.', 'Anda tahu bahwa 希望 adalah "keinginan" atau "harapan". Jadi, ketika Anda "melakukan sebuah keinginan" atau "melakukan sebuah harapan". Ketika Anda melakukan itu, itu berarti meminta atau berharap.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('eb2aee35-a965-429f-880c-975e8fe32a91', 'Untuk Meminta', true) ON CONFLICT DO NOTHING;
