INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('eb2aee35-a965-429f-880c-975e8fe32a91', 'きぼうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb2aee35-a965-429f-880c-975e8fe32a91', '日本への留学を希望しています。', 'Saya berharap untuk belajar di luar negeri di Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb2aee35-a965-429f-880c-975e8fe32a91', '希望していた大学に入学することができました。', 'Saya bisa masuk ke universitas yang saya idam-idamkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb2aee35-a965-429f-880c-975e8fe32a91', '雨が降っているので、待ち合わせを地下に変更することを希望しますが、どう思われますか？', 'Saat ini hujan, jadi saya meminta agar kita mengubah janji temu kita dan mengadakannya di bawah tanah, bagaimana menurut Anda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', 'vocabulary', '技術', '技術', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda pernah melihat 技 sebagai kosakata yang berarti "teknik". Ini semacam menggunakan makna itu. Jadi, suatu teknik seni tetaplah seni, tapi itu juga keahlian Anda, teknik Anda.', 'Anda pernah melihat 技 sebagai kosakata yang berarti "teknik". Ini semacam menggunakan makna itu. Jadi, suatu teknik seni tetaplah seni, tapi itu juga keahlian Anda, teknik Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', 'Seni', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', 'Craft', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', 'Technique', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', 'Technology', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', 'ぎじゅつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', '私は医者ではありませんが、ある医者から、心ぞういしょくの技術を学びました。', 'Saya bukan seorang dokter tetapi saya belajar teknik transplantasi jantung dari seorang dokter.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', '以前に働いていた会社で、えい業技術を身につけました。', 'Saya belajar seni menjual dari perusahaan tempat saya dulu bekerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ef8fb5f-1ea5-40fe-baba-9dd1228b8204', '私は技術的に優れたボクサーと結婚した。', 'Saya menikah dengan seorang petinju yang secara teknis brilian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('062f47be-d3af-4198-aa34-4986dc7dc341', 'vocabulary', '卒業する', '卒業する', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda tahu bahwa 卒業 adalah "wisuda". Jadikan itu kata kerja, dan Anda harus lulus.', 'Anda tahu bahwa 卒業 adalah "wisuda". Jadikan itu kata kerja, dan Anda harus lulus.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('062f47be-d3af-4198-aa34-4986dc7dc341', 'Untuk Lulus', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('062f47be-d3af-4198-aa34-4986dc7dc341', 'そつぎょうする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('062f47be-d3af-4198-aa34-4986dc7dc341', '大学を卒業した後、ぶ事に第一希望の会社にしゅうしょくすることができました。', 'Setelah lulus dari universitas, dengan lancar saya bisa mendapatkan pekerjaan di perusahaan pilihan saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('062f47be-d3af-4198-aa34-4986dc7dc341', '出せき日数が足りなくて高校を卒業できないだって？冗談だろう？', 'Apakah Anda mengatakan bahwa Anda tidak dapat lulus SMA karena Anda kurang bersekolah? Jangan konyol.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('062f47be-d3af-4198-aa34-4986dc7dc341', '私の兄は障害を乗り越え、大学を卒業しました。私は兄をとても誇りに思います。大学卒業は彼の決意と努力の賜物です。', 'Adikku mengatasi kecacatannya dan lulus perguruan tinggi. Saya sangat bangga padanya. Kelulusannya adalah hasil dari tekad dan usahanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ab06c180-3c63-4a0c-82f4-71ee7ab2238a', 'vocabulary', '固める', '固める', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya keras jadi versi vocab verbanya? Untuk membuat sesuatu menjadi sulit. Namun, Anda perlu membedakannya dengan 固まる, yang berarti "mengeras" (pengerasan terjadi dengan sendirinya). Kata ini berarti "membuat sesuatu menjadi keras", karena Andalah yang melakukan pengerasan tersebut. Anda dapat mengingat ini karena Anda ingin membuat sesuatu menjadi keras. Dan untuk melakukan itu, Anda mengirim "surat" khusus (める) ke hal yang ingin Anda buat menjadi sulit, dan surat ini melakukannya untuk Anda.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya keras jadi versi vocab verbanya? Untuk membuat sesuatu menjadi sulit. Namun, Anda perlu membedakannya dengan 固まる, yang berarti "mengeras" (pengerasan terjadi dengan sendirinya). Kata ini berarti "membuat sesuatu menjadi keras", karena Andalah yang melakukan pengerasan tersebut. Anda dapat mengingat ini karena Anda ingin membuat sesuatu menjadi keras. Dan untuk melakukan itu, Anda mengirim "surat" khusus (める) ke hal yang ingin Anda buat menjadi sulit, dan surat ini melakukannya untuk Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ab06c180-3c63-4a0c-82f4-71ee7ab2238a', 'Untuk Membuat Sesuatu Menjadi Sulit', true) ON CONFLICT DO NOTHING;
