INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab06c180-3c63-4a0c-82f4-71ee7ab2238a', 'ねん土は熱で固めることができるよ。', 'Anda bisa mengeraskan tanah liat dengan panas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab06c180-3c63-4a0c-82f4-71ee7ab2238a', 'ビエトは毎朝一時間かけてリーゼントをワックスで固めます。', 'Viet membutuhkan waktu satu jam untuk membuat pompadournya keras setiap pagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ab06c180-3c63-4a0c-82f4-71ee7ab2238a', 'コウイチは、日本に軍隊を派遣する決意を固めた。', 'Koichi memutuskan untuk memperkuat posisinya dan mengirim pasukannya ke Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('85e72fff-964b-4101-8e44-bf5915a1118f', 'vocabulary', '寺', '寺', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
