INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('efb26d49-8e4f-4390-9497-16ced1c29b66', 'vocabulary', '演芸', '演芸', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Seni pertunjukan adalah pertunjukan. Itu adalah hiburan! Lampu, aksi! Selamat datang di Broadway!', 'Seni pertunjukan adalah pertunjukan. Itu adalah hiburan! Lampu, aksi! Selamat datang di Broadway!') ON CONFLICT (id) DO NOTHING;
