INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26df8f24-ad4e-4a8e-a44e-78285eab67eb', '周りがギザギザになっているコインを集めています。', 'Saya mengumpulkan koin dengan tepi bergerigi.') ON CONFLICT DO NOTHING;
