INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae723886-74c4-4127-9d42-846390107bed', 'あんなに勇んでたら、あの馬は買えないなぁ。', 'Kuda itu bertingkah terlalu lincah untuk aku pertaruhkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae723886-74c4-4127-9d42-846390107bed', 'コウイチとビエトは、勇んでオフィスに入って来ました。', 'Koichi dan Viet datang ke kantor dengan semangat tinggi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae723886-74c4-4127-9d42-846390107bed', '少年は、喜び勇んで旅に出発した。', 'Anak laki-laki itu berangkat perjalanannya dengan semangat tinggi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('48c90823-57a6-45eb-b20a-9f95d5da4f53', 'vocabulary', '周期', '周期', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Jika Anda mengikuti keliling suatu periode waktu, Anda akan kembali ke awal dan membuat satu siklus penuh. Peristiwa dalam sejarah selalu terulang bukan?', 'Jika Anda mengikuti keliling suatu periode waktu, Anda akan kembali ke awal dan membuat satu siklus penuh. Peristiwa dalam sejarah selalu terulang bukan?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('48c90823-57a6-45eb-b20a-9f95d5da4f53', 'Siklus', true) ON CONFLICT DO NOTHING;
