INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48c90823-57a6-45eb-b20a-9f95d5da4f53', 'ふり子の周期についてのお返事、お待ちいたしております。', 'Saya menunggu tanggapan Anda mengenai siklus pendulum.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48c90823-57a6-45eb-b20a-9f95d5da4f53', '実はさぁ、クリステンにきいてもらいたくて、「月の周期」っていう曲を練習してるんだよね。', 'Sebenarnya aku sedang berlatih lagu berjudul "The Moon Cycle" karena aku ingin memainkannya untukmu, Kristen.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('48c90823-57a6-45eb-b20a-9f95d5da4f53', '東北の天気は短い周期で変わる。', 'Cuaca di Tohoku berubah dalam waktu singkat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('adb7b912-1bee-42d3-9265-27d1326c8329', 'vocabulary', '固まる', '固まる', 2, '8d7e2f9a-0b1c-2d3e-4f5a-6b7c8d9e0f1a', 'Anda telah melihat bagaimana 固める berarti "menyusahkan". Kata ini berarti sesuatu yang mengeras dengan sendirinya, artinya mengeras atau memadat.', 'Anda telah melihat bagaimana 固める berarti "menyusahkan". Kata ini berarti sesuatu yang mengeras dengan sendirinya, artinya mengeras atau memadat.') ON CONFLICT (id) DO NOTHING;
