INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adb7b912-1bee-42d3-9265-27d1326c8329', 'みんな何でそんなすみっこに固まってるの？', 'Kenapa kalian berkumpul di pojok seperti ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adb7b912-1bee-42d3-9265-27d1326c8329', 'ようやくトーフグをやめる決心が固まりました。', 'Keputusan saya untuk keluar dari Tofugu akhirnya menguat.') ON CONFLICT DO NOTHING;
