INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('94f39854-d6f9-4dae-8551-4c2a614c51ec', 'radical', '付', 'attach', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Radikal ini sama dengan kanji. Artinya melampirkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('94f39854-d6f9-4dae-8551-4c2a614c51ec', 'Lampirkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3a05110c-2190-42ad-9150-17a161f8c02b', 'radical', '虍', 'tiger', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda kehilangan tujuh jari kaki di tebing, tetapi Anda menganggap diri Anda beruntung mengingat jari-jari kaki Anda diambil oleh harimau tebing yang hidup di daerah tersebut. Bayangkan seekor harimau mengambil ketujuh jari kaki Anda saat Anda bergelantungan di tepi tebing jika itu membantu. Seru! (Dan juga menyakitkan!)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3a05110c-2190-42ad-9150-17a161f8c02b', 'Harimau', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('53be4d2a-03dd-4796-847f-14f41b6a8092', 'radical', '尭', 'gambler', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Penjudi memegang salib saat dia bermain blackjack. Dia berdiri dengan kedua kakinya penuh harap, berharap dia bisa memukul yang besar. Dia hanya menaruh semua uangnya. Jika dia tidak memenangkan yang satu ini, penjudi kehilangan segalanya, termasuk kedua kaki yang dia pijak.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('53be4d2a-03dd-4796-847f-14f41b6a8092', 'Penjudi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('a32ab382-619e-41b2-a7d7-080029c3de2f', 'radical', '凶', 'treasure-chest', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ada harta karun radikal di dalam kotak ini. Apa yang menyimpan harta karun? Peti harta karun.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a32ab382-619e-41b2-a7d7-080029c3de2f', 'Peti Harta Karun', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('c4ec0b95-2d50-486f-9a92-b81a166a4ece', 'radical', '[grass]', 'grass', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Jangan bingung membedakannya dengan triceratops. Rumputnya lebih rapat, dan sedikit lebih lebat, seperti ini. Ini juga lebih acak dan terjepit di beberapa bagian. Jika Anda melihat semak dengan garis seperti ini, kemungkinan besar itu adalah rumput.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c4ec0b95-2d50-486f-9a92-b81a166a4ece', 'Rumput', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5489f596-2de5-413a-8c59-c63610335940', 'radical', '司', 'director', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Radikal ini sama dengan kanji. Artinya direktur.') ON CONFLICT (id) DO NOTHING;
