INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('60aa3d23-c6c8-40a3-ba6b-2c6f9737befa', 'けんちく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60aa3d23-c6c8-40a3-ba6b-2c6f9737befa', 'あの会社が建築したビルは、たいしん基じゅんをみたしていません。', 'Bangunan yang dibangun oleh perusahaan tersebut tidak memenuhi standar tahan gempa saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60aa3d23-c6c8-40a3-ba6b-2c6f9737befa', 'この建築ひ用の内わけを教えてもらえますか？', 'Bisakah saya melihat rincian biaya konstruksi ini?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('60aa3d23-c6c8-40a3-ba6b-2c6f9737befa', '多くの人が京都や奈良に残る日本の伝統建築に魅了されますが、私もその一人です。', 'Banyak orang terpesona dengan arsitektur tradisional yang terdapat di tempat-tempat seperti Kyoto dan Nara dan saya salah satunya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('989b166a-5fdd-4ae8-bff9-2bd90badd872', 'vocabulary', '新築', '新築', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Sesuatu yang baru dibangun adalah sesuatu yang baru dibangun.', 'Sesuatu yang baru dibangun adalah sesuatu yang baru dibangun.') ON CONFLICT (id) DO NOTHING;
