INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a990e3f2-2060-4d73-9b08-a06572cf1a83', 'あびる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a990e3f2-2060-4d73-9b08-a06572cf1a83', '晩飯の前に、ひとっ風ろ浴びてくるよ。', 'Aku akan mandi sebelum makan malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a990e3f2-2060-4d73-9b08-a06572cf1a83', '放しゃ能を浴びるのが怖くて、この町ににげてきました。', 'Kami takut terkena radioaktivitas dan kami lari ke kota ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a990e3f2-2060-4d73-9b08-a06572cf1a83', 'フグは私に親友の天然鯛を紹介してくれました。鯛君は、深海に住んでいるので日光をあまり浴びないんだと言っていました。', 'Fugu memperkenalkanku pada sahabatnya, Wild Red Sea Bream. Dia memberi tahu saya bahwa Ikan Bream hidup di kedalaman yang sangat dalam dan hampir tidak terkena sinar matahari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5b6cff84-2a0f-452a-b622-e75d5ea87f86', 'vocabulary', '日光浴', '日光浴', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda tahu bahwa 日光 adalah sinar matahari, jadi ketika Anda menambahkan mandi, Anda mendapatkan "mandi sinar matahari" ... tapi kedengarannya bodoh, jadi sebut saja kata ini berjemur!', 'Anda tahu bahwa 日光 adalah sinar matahari, jadi ketika Anda menambahkan mandi, Anda mendapatkan "mandi sinar matahari" ... tapi kedengarannya bodoh, jadi sebut saja kata ini berjemur!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5b6cff84-2a0f-452a-b622-e75d5ea87f86', 'Berjemur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5b6cff84-2a0f-452a-b622-e75d5ea87f86', 'にっこうよく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b6cff84-2a0f-452a-b622-e75d5ea87f86', 'トトロの大きなおなかの上に乗って日光浴がしたいです。', 'Saya ingin berjemur di perut buncit Totoro.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b6cff84-2a0f-452a-b622-e75d5ea87f86', '私は平日は日光浴だけで入浴はしない主ぎなんです。', 'Kebijakan saya bukan mandi, tapi berjemur di hari kerja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5b6cff84-2a0f-452a-b622-e75d5ea87f86', 'トーフグのワンコは、ベランダで日光浴をするのが大好きです。', 'Anjing Tofugu suka berjemur di balkon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79a88208-4e21-4feb-a18e-07361888b8b9', 'vocabulary', '荷物', '荷物', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Barang bawaan adalah barang bawaan Anda. Itu juga bagasi dan muatan Anda juga.', 'Barang bawaan adalah barang bawaan Anda. Itu juga bagasi dan muatan Anda juga.') ON CONFLICT (id) DO NOTHING;
