INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('79a88208-4e21-4feb-a18e-07361888b8b9', 'ぜい関で荷物を調べられないか心配です。', 'Saya khawatir bagasi saya diperiksa di bea cukai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('79a88208-4e21-4feb-a18e-07361888b8b9', '荷物でいっぱいのベビーカーが公園におきっ放しになっていました。', 'Kereta dorong penuh barang bawaan tertinggal di taman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('79a88208-4e21-4feb-a18e-07361888b8b9', '「誰かが車から荷物を降ろさないといけないんだけど…。」 「わかったから、それ以上言わなくていいよ。」', '"Seseorang harus membongkar barang bawaan dari mobil..." "Baiklah. Jangan katakan lagi."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('71d425fc-392b-49ba-be02-5a5878c10303', 'vocabulary', '入門', '入門', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Jika Anda dapat memasuki gerbang maka Anda telah memperoleh izin masuk dan masuk ke fasilitas tersebut.', 'Jika Anda dapat memasuki gerbang maka Anda telah memperoleh izin masuk dan masuk ke fasilitas tersebut.') ON CONFLICT (id) DO NOTHING;
