INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('71d425fc-392b-49ba-be02-5a5878c10303', 'にゅうもん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71d425fc-392b-49ba-be02-5a5878c10303', 'コウイチは有名な剣道の先生のところに入門するそうですよ。', 'Kudengar Koichi akan menjadi murid master kendo terkenal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71d425fc-392b-49ba-be02-5a5878c10303', '入門手つづきをまだ終えていません。', 'Saya belum menyelesaikan prosedur penerimaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('71d425fc-392b-49ba-be02-5a5878c10303', '日本語に馴染みのない私にとっても、テキストフグは絶好の入門書だと思う？買った方がいいかな？', 'Menurut Anda, apakah TextFugu adalah pengantar bahasa Jepang terbaik, bahkan untuk orang seperti saya yang belum terbiasa dengannya? Haruskah saya membelinya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6213e1d4-709f-483a-8ec9-0396ce734173', 'vocabulary', '建築家', '建築家', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda tahu bahwa 建築 adalah arsitektur. Jadi, seseorang yang berarsitektur rumah adalah seseorang yang mengerjakan arsitektur. Mereka adalah seorang arsitek.', 'Anda tahu bahwa 建築 adalah arsitektur. Jadi, seseorang yang berarsitektur rumah adalah seseorang yang mengerjakan arsitektur. Mereka adalah seorang arsitek.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6213e1d4-709f-483a-8ec9-0396ce734173', 'Arsitek', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6213e1d4-709f-483a-8ec9-0396ce734173', 'けんちくか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6213e1d4-709f-483a-8ec9-0396ce734173', 'お父さん、あんたが建築家になったから、鼻が高いのよ。', 'Ayah sangat bangga padamu karena kamu menjadi seorang arsitek.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6213e1d4-709f-483a-8ec9-0396ce734173', '医者は、その建築家をあやまって胃がんだとしんだんしました。', 'Dokter salah mendiagnosis arsitek tersebut menderita kanker perut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6213e1d4-709f-483a-8ec9-0396ce734173', '私の家は有名な建築家によって設計されたんですよ。', 'Rumah saya dirancang oleh seorang arsitek terkenal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b616d6b3-c2cc-42d4-9208-c6233b1c93c9', 'vocabulary', '兵員', '兵員', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anggota prajurit (atau anggota prajurit) adalah orang yang berasal dari personel militer. Ini juga menunjukkan jumlah kekuatan militer yang dimiliki suatu angkatan bersenjata. Semakin banyak anggota prajurit, semakin banyak kekuatan militer dan personel militer yang dimilikinya!', 'Anggota prajurit (atau anggota prajurit) adalah orang yang berasal dari personel militer. Ini juga menunjukkan jumlah kekuatan militer yang dimiliki suatu angkatan bersenjata. Semakin banyak anggota prajurit, semakin banyak kekuatan militer dan personel militer yang dimilikinya!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b616d6b3-c2cc-42d4-9208-c6233b1c93c9', 'Personil Militer', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b616d6b3-c2cc-42d4-9208-c6233b1c93c9', 'Military Strength', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b616d6b3-c2cc-42d4-9208-c6233b1c93c9', 'へいいん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b616d6b3-c2cc-42d4-9208-c6233b1c93c9', '兵員たちはみんな、かぜにかかって鼻がつまっている。', 'Semua personel militer menderita pilek dan hidung tersumbat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b616d6b3-c2cc-42d4-9208-c6233b1c93c9', '兵員がにげ出さないよう、ドアには外側からかぎがかけられていた。', 'Pintu dikunci dari luar agar personel militer tidak melarikan diri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b616d6b3-c2cc-42d4-9208-c6233b1c93c9', 'トーフグ軍の改革のため、コウイチは兵員の数を削減をしなくてはならなかった。', 'Akibat reformasi tentara Tofugu, Koichi harus mengurangi jumlah kekuatan militer yang mereka miliki.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ac560b97-0383-4899-87ce-05019934331b', 'vocabulary', '米兵', '米兵', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ingat bagaimana 米国 adalah "Amerika". Ya, lebih dari itu lagi. Dengan 米 mewakili "Amerika" Anda dapat menggabungkannya dengan 兵 (prajurit) untuk menjadikan diri Anda seorang tentara AS / tentara Amerika.', 'Ingat bagaimana 米国 adalah "Amerika". Ya, lebih dari itu lagi. Dengan 米 mewakili "Amerika" Anda dapat menggabungkannya dengan 兵 (prajurit) untuk menjadikan diri Anda seorang tentara AS / tentara Amerika.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ac560b97-0383-4899-87ce-05019934331b', 'Tentara AS', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ac560b97-0383-4899-87ce-05019934331b', 'American Soldier', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ac560b97-0383-4899-87ce-05019934331b', 'べいへい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac560b97-0383-4899-87ce-05019934331b', 'あの米兵は、どうして鼻めがねをかけているの？', 'Mengapa tentara AS itu memakai kacamata pince-nez?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac560b97-0383-4899-87ce-05019934331b', 'ここは米兵がたくさん通るから、通行のじゃまをしないようにしてください。', 'Banyak tentara Amerika lewat sini, jadi harap pastikan Anda tidak menghalangi mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac560b97-0383-4899-87ce-05019934331b', '「すごい。今日は本当にいいお天気だね！今日こそ腹筋三百回が出来そうな気がする。」と、米兵は言った。', '"Wow. Cuacanya indah sekali! Saya merasa akhirnya bisa melakukan 300 sit up hari ini," kata seorang tentara Amerika.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('529e70e3-ce6d-433b-92ba-057534446355', 'vocabulary', '塩', '塩', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('529e70e3-ce6d-433b-92ba-057534446355', 'garam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('529e70e3-ce6d-433b-92ba-057534446355', 'しお', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('529e70e3-ce6d-433b-92ba-057534446355', 'もう少し塩が多い方が良いかもしれませんね。', 'Mungkin lebih baik jika diberi sedikit garam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('529e70e3-ce6d-433b-92ba-057534446355', '一才になるまで赤ちゃんには塩をあげない方がいいですよ。', 'Sampai bayi Anda berusia satu tahun, Anda tidak boleh memberinya garam apa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('529e70e3-ce6d-433b-92ba-057534446355', 'けしからん！一体どうやってそんなに馬鹿なことが出来るんだ？砂糖と塩を入れ替えるなんて、いくら今日がエイプリルフールだからといっても、ちっともおもしろくないぞ。馬鹿！ ', 'Astaga! Aku tidak percaya kamu bisa sebodoh itu! Mengganti garam dan gula sama sekali tidak lucu, meskipun hari ini adalah Hari April Mop. Kamu bodoh!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1bd58549-0f3f-4caf-968f-8c32b36e5c51', 'vocabulary', '塩水', '塩水', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Air yang mengandung garam adalah air asin. Sebaiknya jangan minum 塩水.', 'Air yang mengandung garam adalah air asin. Sebaiknya jangan minum 塩水.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1bd58549-0f3f-4caf-968f-8c32b36e5c51', 'Air Garam', true) ON CONFLICT DO NOTHING;
