INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1bd58549-0f3f-4caf-968f-8c32b36e5c51', 'えんすい', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bd58549-0f3f-4caf-968f-8c32b36e5c51', '鼻が利く方だと思っていたんだが、どちらが塩水か分からなかった。', 'Kupikir hidungku bagus, tapi aku tidak tahu yang mana air asin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bd58549-0f3f-4caf-968f-8c32b36e5c51', '塩水につけて天日干ししたフグってきっと美味しくなると思うんだけどなあ。', 'Menurut saya ikan buntal yang dicelupkan ke dalam air garam dan dijemur di bawah sinar matahari akan cukup enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1bd58549-0f3f-4caf-968f-8c32b36e5c51', '気温はそんなに高くないけど、日差しは強いから、熱射病対策で塩水を持って行った方がいいんじゃない？', 'Suhunya sendiri tidak terlalu tinggi, namun sinar matahari sangat terik, jadi mengapa Anda tidak meminum air garam untuk mencegah sengatan panas?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9911c84e-6ec1-4da5-b033-051dd75a47ed', 'vocabulary', '塩味', '塩味', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Rasa garam adalah rasa yang asin (begitu juga bila ada sesuatu yang terasa asin).', 'Rasa garam adalah rasa yang asin (begitu juga bila ada sesuatu yang terasa asin).') ON CONFLICT (id) DO NOTHING;
