INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('643ffc99-e26f-404d-84a6-7fc8d8bc001f', 'セーターはかんそうきに入れないで、干してねって言ったじゃない。', 'Sudah kubilang jangan masukkan sweter ke dalam pengering, tapi jemur saja.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('643ffc99-e26f-404d-84a6-7fc8d8bc001f', 'あの芸人、ぜっ対最近干されてるよね。', 'Menurutku komedian itu sudah kehilangan kesempatan untuk tampil di televisi akhir-akhir ini. Apakah kamu tidak setuju?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('643ffc99-e26f-404d-84a6-7fc8d8bc001f', '洗濯物を外に干したかったんだけど、物干し竿が壊れちゃって。', 'Aku ingin menjemur cucian kami di luar, tapi tali jemuran kami putus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ab351bc7-c1da-4bef-9e17-a66b47aafcfe', 'vocabulary', '干天', '干天', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ingat bagaimana 天気 adalah cuaca (dan seberapa sering 天 mengacu pada benda langit?). Nah, ketika langit kering, cuacanya kering.', 'Ingat bagaimana 天気 adalah cuaca (dan seberapa sering 天 mengacu pada benda langit?). Nah, ketika langit kering, cuacanya kering.') ON CONFLICT (id) DO NOTHING;
