INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38d4bfc6-c4ef-4699-ae76-d4588958fe62', 'くつの底にガムがついてるよ。', 'Ada permen karet yang menempel di bagian bawah sepatu Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38d4bfc6-c4ef-4699-ae76-d4588958fe62', '底無しぬまに泳ぎに行くなんて、無茶だよ。', 'Sungguh konyol berenang di rawa tanpa dasar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('38d4bfc6-c4ef-4699-ae76-d4588958fe62', 'トーフグのお陰で、日本語がペラペラになりました。心の底から感謝しています。', 'Berkat Tofugu, saya sekarang fasih berbahasa Jepang. Saya berterima kasih kepada mereka dari lubuk hati saya yang paling dalam.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f671d32e-d1c6-4180-a69e-bb122ba11c13', 'vocabulary', '心底', '心底', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Dasar hati adalah dasar hati seseorang. Apakah Anda ingin belajar kanji? Apakah Anda ingin mempelajarinya dari 心底? Oke, baiklah, kalau begitu Anda bisa melanjutkan ke bacaan.', 'Dasar hati adalah dasar hati seseorang. Apakah Anda ingin belajar kanji? Apakah Anda ingin mempelajarinya dari 心底? Oke, baiklah, kalau begitu Anda bisa melanjutkan ke bacaan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f671d32e-d1c6-4180-a69e-bb122ba11c13', 'Lubuk Hati Seseorang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f671d32e-d1c6-4180-a69e-bb122ba11c13', 'Bottom Of My Heart', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f671d32e-d1c6-4180-a69e-bb122ba11c13', 'しんそこ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f671d32e-d1c6-4180-a69e-bb122ba11c13', 'コウイチの不治の病が治って、心底うれしいよ。', 'Saya sangat senang karena penyakit Koichi yang tidak dapat disembuhkan sebenarnya telah disembuhkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f671d32e-d1c6-4180-a69e-bb122ba11c13', 'コウイチには心底からきらわれていると思います。', 'Saya pikir Koichi membenci saya dari lubuk hatinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f671d32e-d1c6-4180-a69e-bb122ba11c13', '新しい部署、優しい人がいっぱいで、心底ホッとしたよ。', 'Ada banyak orang baik di departemen baru saya dan saya merasa sangat lega.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b73888a3-0ffb-4918-865f-23fe432a4385', 'vocabulary', '川底', '川底', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Dasar sungai adalah dasar sungai yang disebut juga dasar sungai.', 'Dasar sungai adalah dasar sungai yang disebut juga dasar sungai.') ON CONFLICT (id) DO NOTHING;
