INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b73888a3-0ffb-4918-865f-23fe432a4385', 'あの辺りは川底が深いので気を付けてください。', 'Sungai di sekitar sana dalam, jadi berhati-hatilah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b73888a3-0ffb-4918-865f-23fe432a4385', 'この川は、川底にかなりのすながたまってしまっています。', 'Ada banyak pasir di dasar sungai ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b73888a3-0ffb-4918-865f-23fe432a4385', '「サーモンはゴールデンウィーク期間中何してたの？」「結婚指輪を川で無くしちゃって、ずっと探してたの。三日もかかったけど、ようやく川底に沈んでいる指輪を見つけたわ。」', '"Apa yang kamu lakukan selama Golden Week, Salmon?" “Saya kehilangan cincin kawin saya di sungai, jadi saya mencarinya. Butuh waktu tiga hari, tapi akhirnya saya menemukannya terkubur di dasar sungai.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aba990ca-da5b-43c1-bbd0-1d3804a676b6', 'vocabulary', '恋', '恋', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ketika Anda memiliki romansa, Anda juga memiliki cinta! Jenis cinta romantis yang lembek dan mengalir. Namun berhati-hatilah. Kata ini tidak memiliki arti yang sama dengan kanjinya. Tapi, begitulah romantisme. Semuanya menjadi gila dan berubah menjadi cinta dengan sangat cepat.', 'Ketika Anda memiliki romansa, Anda juga memiliki cinta! Jenis cinta romantis yang lembek dan mengalir. Namun berhati-hatilah. Kata ini tidak memiliki arti yang sama dengan kanjinya. Tapi, begitulah romantisme. Semuanya menjadi gila dan berubah menjadi cinta dengan sangat cepat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aba990ca-da5b-43c1-bbd0-1d3804a676b6', 'Cinta', true) ON CONFLICT DO NOTHING;
