INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aba990ca-da5b-43c1-bbd0-1d3804a676b6', '私はまだ、恋をしたことがない。', 'Aku belum benar-benar jatuh cinta.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aba990ca-da5b-43c1-bbd0-1d3804a676b6', 'サーモンちゃん、なんかかわいくなったよな。恋する女って感じじゃない？', 'Tidakkah menurutmu Salmon menjadi lebih cantik? Menurutku itu karena dia wanita yang sedang jatuh cinta, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aba990ca-da5b-43c1-bbd0-1d3804a676b6', 'フグのことが頭から離れないの。これって恋の始まりなのかな？', 'Aku tidak bisa menghilangkan Fugu dari kepalaku! Apakah ada cinta di udara?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5579e553-ba5a-470f-bc28-2236c91248b0', 'vocabulary', '失恋', '失恋', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kesalahan dalam percintaan bukanlah pada percintaan itu sendiri, melainkan ketika semuanya berantakan. Saat itulah Anda mengalami patah hati atau cinta bertepuk sebelah tangan. Pernahkah Anda merasakan kesalahan dalam percintaan? Jika ya, ingatlah kembali masa itu, dan pikirkan betapa buruknya kesalahan itu.', 'Kesalahan dalam percintaan bukanlah pada percintaan itu sendiri, melainkan ketika semuanya berantakan. Saat itulah Anda mengalami patah hati atau cinta bertepuk sebelah tangan. Pernahkah Anda merasakan kesalahan dalam percintaan? Jika ya, ingatlah kembali masa itu, dan pikirkan betapa buruknya kesalahan itu.') ON CONFLICT (id) DO NOTHING;
