INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('17d805c0-0583-41fd-bdf6-68552c8caa6a', 'この街はもっと栄えてるのかと思ってました。', 'Saya pikir kota ini akan lebih makmur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('17d805c0-0583-41fd-bdf6-68552c8caa6a', 'この町は、かつては銀山で栄えていました。', 'Dulunya kota ini merupakan kota pertambangan perak yang makmur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('17d805c0-0583-41fd-bdf6-68552c8caa6a', '中国には、覚せい剤の生産で栄えていた村がありました。', 'Ada sebuah desa di Tiongkok yang berkembang dari produksi stimulan mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a77b3ce5-da3e-46e5-b828-8f7ec1ed38b8', 'vocabulary', '光栄', '光栄', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ketika sebuah cahaya menyinari seberapa banyak Anda telah makmur, itu adalah suatu kehormatan besar. Anda tidak merasa telah melakukan sesuatu yang begitu istimewa, tetapi sungguh suatu kehormatan bagi Anda untuk mendapat pencerahan seperti ini.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a77b3ce5-da3e-46e5-b828-8f7ec1ed38b8', 'Kehormatan', true) ON CONFLICT DO NOTHING;
