INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a77b3ce5-da3e-46e5-b828-8f7ec1ed38b8', 'こうえい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a77b3ce5-da3e-46e5-b828-8f7ec1ed38b8', 'あべさんにインタビューさせていただけることをとても光栄に思っています。', 'Sungguh suatu kehormatan bagi kami dapat mewawancarai Anda, Pak Abe.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a77b3ce5-da3e-46e5-b828-8f7ec1ed38b8', 'コウイチ王と直せつお話ができることは、大変光栄なことなんですよ。', 'Anda harus tahu bahwa merupakan suatu kehormatan bagi Anda untuk mengobrol langsung dengan Raja Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a77b3ce5-da3e-46e5-b828-8f7ec1ed38b8', 'トーフグの本社で勤務する機会を頂いたことを、とても光栄に思います。皆さんのお役に立てるよう精一杯頑張りますので、どうぞよろしくお願いいたします。', 'Saya sangat tersanjung mendapat kesempatan bekerja di kantor pusat Tofugu. Saya akan melakukan yang terbaik untuk berguna bagi Anda semua.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('25e60233-f28e-4be1-96ed-0868c703584e', 'vocabulary', '栄光', '栄光', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda membantu kota Anda menjadi makmur, dan seberkas cahaya menyinari Anda, sehingga seluruh kota dapat menikmati kemuliaan Anda.', 'Anda membantu kota Anda menjadi makmur, dan seberkas cahaya menyinari Anda, sehingga seluruh kota dapat menikmati kemuliaan Anda.') ON CONFLICT (id) DO NOTHING;
