INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('25e60233-f28e-4be1-96ed-0868c703584e', 'えいこう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25e60233-f28e-4be1-96ed-0868c703584e', '今回、勝利の栄光にかがやいたのは、トーフグチームです！', 'Tim yang meraih kemenangan gemilang kali ini adalah Tim Tofugu!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25e60233-f28e-4be1-96ed-0868c703584e', 'か去の栄光をなつかしそうに語る大人にだけはなりたくありません。', 'Saya tidak pernah ingin menjadi orang dewasa yang bernostalgia tentang masa-masa kejayaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('25e60233-f28e-4be1-96ed-0868c703584e', 'コウイチの栄光の瞬間は、二十二歳でブロガーのチャンピオンになった時にやって来た。', 'Pada usia dua puluh dua tahun, momen kejayaan Koichi datang ketika ia menjadi seorang blogger juara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d223df3-8281-487b-ae4e-1c7c9a29e292', 'vocabulary', '細い', '細い', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari kurus? Ini juga tipis, meski bisa juga ramping.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari kurus? Ini juga tipis, meski bisa juga ramping.') ON CONFLICT (id) DO NOTHING;
