INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2075859b-86b4-4967-9d8c-daafcd994103', 'チーズケーキを百こ焼くという目標を達しました。', 'Saya mencapai tujuan saya untuk membuat seratus kue keju.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2075859b-86b4-4967-9d8c-daafcd994103', 'その手紙は焼いもと一しょに焼いてしまいました。', 'Saya membakar surat itu ketika saya membuat ubi panggang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2075859b-86b4-4967-9d8c-daafcd994103', 'あなたの旦那さんも、ケーキを焼くの？', 'Apakah suami Anda juga membuat kue?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4456bbb7-a912-4c56-a679-555863ecd580', 'vocabulary', '日焼け', '日焼け', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ketika matahari memasak sesuatu, dan sesuatu itu adalah Anda, ia membuat Anda terbakar sinar matahari.', 'Ketika matahari memasak sesuatu, dan sesuatu itu adalah Anda, ia membuat Anda terbakar sinar matahari.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4456bbb7-a912-4c56-a679-555863ecd580', 'Terbakar sinar matahari', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4456bbb7-a912-4c56-a679-555863ecd580', 'Suntan', false) ON CONFLICT DO NOTHING;
