INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4456bbb7-a912-4c56-a679-555863ecd580', 'ひやけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4456bbb7-a912-4c56-a679-555863ecd580', 'どうやらうちの娘は、あの日焼けした青年への恋に胸をこがしているようです。', 'Sepertinya putriku sangat mencintai pemuda berkulit coklat itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4456bbb7-a912-4c56-a679-555863ecd580', '日焼けでせ中が真っ赤になってるよ。', 'Punggungmu sangat merah karena sengatan matahari.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4456bbb7-a912-4c56-a679-555863ecd580', 'ハワイでは強い日焼け止めが必需品で、人達を日焼けから守るのにシートで覆ったりもします。', 'Di Hawaii, tabir surya yang kuat sangat penting dan penutup juga digunakan untuk melindungi orang agar tidak terbakar sinar matahari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', 'vocabulary', '焼き鳥', '焼き鳥', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Burung panggang bukan sembarang burung, melainkan ayam panggang atau ayam panggang. Anda mungkin juga mengenalnya dengan nama Jepangnya yang diromanisasi: yakitori.', 'Burung panggang bukan sembarang burung, melainkan ayam panggang atau ayam panggang. Anda mungkin juga mengenalnya dengan nama Jepangnya yang diromanisasi: yakitori.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', 'Ayam Bakar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', 'Roast Chicken', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', 'Yakitori', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', 'やきとり', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', '焼き鳥は私の生活に不可欠です。', 'Yakitori sangat penting bagi hidupku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', '主人は焼き鳥屋のけいえいが忙しすぎて、けっこん記念日のことはすっかり忘れていました。', 'Suamiku terlalu sibuk menjalankan restoran yakitori-nya dan dia benar-benar lupa tentang ulang tahun pernikahan kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d185e0ff-075d-4113-96e6-0a6ba1d9898e', '私のせいにしないで。あなたの焼き鳥なんか食べてないわよ！', 'Jangan salahkan saya! Aku tidak memakan yakitorimu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', 'vocabulary', '焼き肉', '焼き肉', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Mmmmm, enak! Ambil sedikit daging dan masak. Kemudian Anda memiliki daging panggang atau yakiniku. Jika Anda pergi ke Jepang, carilah tempat 焼肉 (arti/bacaan yang sama). Mereka enak, setidaknya jika Anda menyukai daging.', 'Mmmmm, enak! Ambil sedikit daging dan masak. Kemudian Anda memiliki daging panggang atau yakiniku. Jika Anda pergi ke Jepang, carilah tempat 焼肉 (arti/bacaan yang sama). Mereka enak, setidaknya jika Anda menyukai daging.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', 'Daging Panggang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', 'Roast Meat', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', 'Yakiniku', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', 'やきにく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', '焼き肉屋にカメラをおいてきちゃった。', 'Aku meninggalkan kameraku di restoran yakiniku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', '去る者より残る者の方がつらいというのは、焼き肉を食べてる時には当てはまらないよね。', 'Katanya orang yang ditinggalkan lebih berat daripada orang yang pergi, tapi ini tidak berlaku saat kita makan daging panggang, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f1149970-c439-410e-9d64-a4fe0f8c22ab', '私が特にイライラするのは、焼き肉をクチャクチャ音を立てて食べる人です。', 'Saya merasa sangat menjengkelkan ketika orang mengunyah yakiniku dengan keras.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6890a1f7-e4e4-4087-9cf0-6c13d9217267', 'vocabulary', '夕焼け', '夕焼け', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ketika sore hari terik matahari, matahari terbenam, mendekati cakrawala dan bumi. Inilah matahari terbenam, atau lebih spesifiknya, cahaya senja yang bisa Anda lihat saat matahari terbenam.', 'Ketika sore hari terik matahari, matahari terbenam, mendekati cakrawala dan bumi. Inilah matahari terbenam, atau lebih spesifiknya, cahaya senja yang bisa Anda lihat saat matahari terbenam.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6890a1f7-e4e4-4087-9cf0-6c13d9217267', 'Matahari terbenam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6890a1f7-e4e4-4087-9cf0-6c13d9217267', 'Evening Glow', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6890a1f7-e4e4-4087-9cf0-6c13d9217267', 'ゆうやけ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6890a1f7-e4e4-4087-9cf0-6c13d9217267', '夕焼けを見ていると何だか虚しい気持ちになります。', 'Saat saya melihat matahari terbenam, entah kenapa saya merasa hampa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6890a1f7-e4e4-4087-9cf0-6c13d9217267', '私の友達はずっと朝焼けのことも夕焼けだと言ってはばからない。', 'Teman saya sangat yakin bahwa matahari terbit sebenarnya adalah matahari terbenam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6890a1f7-e4e4-4087-9cf0-6c13d9217267', '昨日、海岸から見た夕焼けはとても眩しくて天国のようだったわ。そのせいで左目を失明しちゃったけどね。', 'Matahari terbenam di pantai tadi malam begitu cerahnya bagaikan surga. Dan karena itu saya menjadi buta pada mata kiri saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e94f8fda-188c-495e-baa6-a55faab3f0f0', 'vocabulary', '祈る', '祈る', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berdoa dan kata kerja ini bersifat transitif, jadi artinya mendoakan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berdoa dan kata kerja ini bersifat transitif, jadi artinya mendoakan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e94f8fda-188c-495e-baa6-a55faab3f0f0', 'Untuk Berdoa Untuk', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e94f8fda-188c-495e-baa6-a55faab3f0f0', 'いのる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e94f8fda-188c-495e-baa6-a55faab3f0f0', 'ハリケーンのひがい者のために祈りました。', 'Saya berdoa untuk para korban badai.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e94f8fda-188c-495e-baa6-a55faab3f0f0', '国家試験に無事合格できるように祈っています。', 'Saya doakan semoga kalian lulus ujian nasional dengan sukses.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e94f8fda-188c-495e-baa6-a55faab3f0f0', '日本の国技である相撲が、かつては米の豊作を祈る儀式だったことを知ってる日本人がたくさんいるとは思えないな。', 'Saya rasa tidak banyak orang Jepang yang mengetahui olahraga nasional Jepang "sumo" dulunya merupakan ritual berdoa agar panen padi melimpah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9bf1eed8-5142-427b-8181-cb65e78d05ce', 'vocabulary', '祈念', '祈念', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Pikiranmu adalah doa. Pikiran berdoa ini adalah doa.', 'Pikiranmu adalah doa. Pikiran berdoa ini adalah doa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9bf1eed8-5142-427b-8181-cb65e78d05ce', 'Doa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9bf1eed8-5142-427b-8181-cb65e78d05ce', 'A Prayer', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9bf1eed8-5142-427b-8181-cb65e78d05ce', 'きねん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bf1eed8-5142-427b-8181-cb65e78d05ce', '世界中の全ての人が、祈念しています。', 'Semua orang di seluruh dunia berdoa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bf1eed8-5142-427b-8181-cb65e78d05ce', '明日は原ばくぎせい者いれい平和祈念式典に出席します。', 'Saya akan menghadiri upacara peringatan perdamaian bagi para korban bom atom besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9bf1eed8-5142-427b-8181-cb65e78d05ce', 'トーフグの益々の発展と繁栄を祈念して、乾杯！', 'Mari kita doakan agar Tofugu semakin tumbuh dan sejahtera, bersorak!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7cc04eca-e5c5-493d-ba37-4998b693de0c', 'vocabulary', '祈願', '祈願', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda berdoa dan meminta. Ini adalah doamu.', 'Anda berdoa dan meminta. Ini adalah doamu.') ON CONFLICT (id) DO NOTHING;
