INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('326d997a-95e0-4f11-b43c-685a7d4b352b', 'ビエトは手下たちに、とばくは禁止だと言い聞かせた。', 'Viet menegur tentaranya karena perjudian dilarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('326d997a-95e0-4f11-b43c-685a7d4b352b', 'トーフグは、Youtubeのけんえつによって動画の公開を禁止されました。', 'Tofugu dilarang menerbitkan video oleh sensor Youtube.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('326d997a-95e0-4f11-b43c-685a7d4b352b', '宇宙服を脱ぎっぱなしにするんじゃない！禁止事項の一つだろうが！', 'Jangan melepas pakaian antariksa Anda! Itu salah satu hal yang dilarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb8f681b-f3ac-45ae-b1fb-a434719ecbdd', 'vocabulary', '訓練', '訓練', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda sudah mendapatkan instruksi dan latihan. Saatnya memulai pelatihan Anda, atau sekadar latihan Anda.', 'Anda sudah mendapatkan instruksi dan latihan. Saatnya memulai pelatihan Anda, atau sekadar latihan Anda.') ON CONFLICT (id) DO NOTHING;
