INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb8f681b-f3ac-45ae-b1fb-a434719ecbdd', '昨日、トーフグのオフィスで、火さい訓練をしました。', 'Kami mengadakan latihan kebakaran di kantor Tofugu kemarin.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb8f681b-f3ac-45ae-b1fb-a434719ecbdd', '今日は学校で、おはしの使い方を訓練しました。', 'Kami berlatih cara menggunakan sumpit di sekolah hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eb8f681b-f3ac-45ae-b1fb-a434719ecbdd', '日本語の訓練所を破壊する秘密組織があると聞きました。', 'Kudengar ada organisasi rahasia yang menghancurkan kamp pelatihan bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a3120966-7169-4327-9c94-4ac73e0baff0', 'vocabulary', '胸', '胸', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
