INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4174bb5-7459-45fd-8fe3-070ad44c2340', 'コウイチの話から、どんな教訓がえられましたか？', 'Pesan moral apa yang bisa kamu ambil dari cerita Koichi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4174bb5-7459-45fd-8fe3-070ad44c2340', 'この教訓を無だにはしません。', 'Saya akan mengingat pelajaran ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b4174bb5-7459-45fd-8fe3-070ad44c2340', '前職から学んだ最大の教訓を教えてください。', 'Ceritakan tentang pelajaran terbesar yang Anda pelajari dari perusahaan Anda sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bd72d519-21a9-4665-b033-be379ad8fdb1', 'vocabulary', 'いい加減', 'いい加減', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda menambah dan mengurangi. Ini membawa Anda kembali ke nol. Sama sekali tidak ada gunanya melakukan tindakan tersebut. Sama sekali tidak ada gunanya. Faktanya, menurut saya itu adalah tindakan Anda yang tidak bertanggung jawab. Tambahan いい berarti "bagus", seperti dalam kalimat "bagus, kamu sudah tahu betapa tidak ada gunanya hal itu, sekarang berhenti."', 'Anda menambah dan mengurangi. Ini membawa Anda kembali ke nol. Sama sekali tidak ada gunanya melakukan tindakan tersebut. Sama sekali tidak ada gunanya. Faktanya, menurut saya itu adalah tindakan Anda yang tidak bertanggung jawab. Tambahan いい berarti "bagus", seperti dalam kalimat "bagus, kamu sudah tahu betapa tidak ada gunanya hal itu, sekarang berhenti."') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('bd72d519-21a9-4665-b033-be379ad8fdb1', 'Tidak bertanggung jawab', true) ON CONFLICT DO NOTHING;
