INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('bd72d519-21a9-4665-b033-be379ad8fdb1', 'いいかげん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd72d519-21a9-4665-b033-be379ad8fdb1', 'このサービスはいい加減すぎます。いい加減、改善をするべきですよ。', 'Layanan ini kikuk. Sudah waktunya untuk beberapa perbaikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd72d519-21a9-4665-b033-be379ad8fdb1', 'あんないい加減な人とけっこんして二十年もけっこん生活が続けられるなんて信じられない。', 'Bagaimana Anda bisa tetap menikah dengan pria yang tidak bertanggung jawab selama dua puluh tahun? Saya tidak percaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bd72d519-21a9-4665-b033-be379ad8fdb1', 'ねえ、お父さん。お母さんさぁ、近所の井戸端会議で仕入れたいい加減な情報に踊らされるの、いい加減に止めるべきだと思わない？', 'Hei, Ayah. Bukankah sudah waktunya bagi ibu untuk berhenti dimanipulasi oleh gosip-gosip tak berguna yang berasal dari obrolan iseng dengan tetangga?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c5e2ee9-fdc3-49ef-9dc5-69122fe4499e', 'vocabulary', '形容詞', '形容詞', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Bagian pidato yang menciptakan bentuk dan wujud suatu kata adalah sesuatu yang bersifat deskriptif (bagaimanapun, bentuk dan wujudnya ada di sana!). Bentuk dan bentuk bagian pidato ini adalah kata sifat. Kamu cantik sekali!', 'Bagian pidato yang menciptakan bentuk dan wujud suatu kata adalah sesuatu yang bersifat deskriptif (bagaimanapun, bentuk dan wujudnya ada di sana!). Bentuk dan bentuk bagian pidato ini adalah kata sifat. Kamu cantik sekali!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8c5e2ee9-fdc3-49ef-9dc5-69122fe4499e', 'Kata sifat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8c5e2ee9-fdc3-49ef-9dc5-69122fe4499e', 'けいようし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c5e2ee9-fdc3-49ef-9dc5-69122fe4499e', '形容詞は、な形容詞、い形容詞、の形容詞の三つに分けられます。', 'Kata sifat dapat dipisahkan menjadi tiga kategori: kata sifat na, kata sifat i, dan tanpa kata sifat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c5e2ee9-fdc3-49ef-9dc5-69122fe4499e', 'このシチュエーションにぴったりのいい形容詞が思いつきません。', 'Saya tidak dapat menemukan kata sifat yang bagus yang dapat menggambarkan situasi ini dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c5e2ee9-fdc3-49ef-9dc5-69122fe4499e', 'その面接試験で、自分を表現するのに最も適した形容詞を選んで、その理由を説明しなくちゃいけなかったんだ。', 'Saat wawancara kerja, saya harus memilih kata sifat yang paling cocok untuk menggambarkan diri saya, dan menjelaskan alasannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e4a0ee4e-f8e9-4dee-ab9f-1daf4c9cf2f0', 'vocabulary', '若布', '若布', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kain muda entah kenapa adalah wakame rumput laut. Jika Anda belum pernah mendengar tentang wakame sebelumnya, carilah. Ini enak dan sangat baik untukmu. Rumput laut itu seperti kain di laut ya? Nah, kain muda ini bagus dan lembut serta tipis, seperti wakame. Saya membayangkan anak muda juga lembut dan kurus, itulah sebabnya pakaian muda disebut wakame.', 'Kain muda entah kenapa adalah wakame rumput laut. Jika Anda belum pernah mendengar tentang wakame sebelumnya, carilah. Ini enak dan sangat baik untukmu. Rumput laut itu seperti kain di laut ya? Nah, kain muda ini bagus dan lembut serta tipis, seperti wakame. Saya membayangkan anak muda juga lembut dan kurus, itulah sebabnya pakaian muda disebut wakame.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e4a0ee4e-f8e9-4dee-ab9f-1daf4c9cf2f0', 'Wakame', true) ON CONFLICT DO NOTHING;
