INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e4a0ee4e-f8e9-4dee-ab9f-1daf4c9cf2f0', 'わかめ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4a0ee4e-f8e9-4dee-ab9f-1daf4c9cf2f0', 'かん国ではたん生日には若布スープを飲む習かんがあります。', 'Di Korea, merupakan kebiasaan untuk menyantap sup wakame pada hari ulang tahun Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4a0ee4e-f8e9-4dee-ab9f-1daf4c9cf2f0', '忙しいので、かん単に若布ときゅうりの和え物を作りました。', 'Saya sibuk jadi saya hanya membuat wakame dan mentimun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e4a0ee4e-f8e9-4dee-ab9f-1daf4c9cf2f0', '私のお母さんが、若布と豆腐のお味噌汁を作ったんだけど、食べる？', 'Ibuku membuat sup miso dengan rumput laut wakame dan tahu. Apakah kamu mau beberapa?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2e94a257-29f4-4c71-99d2-b4afd400e7e8', 'vocabulary', '布', '布', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
