INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e94a257-29f4-4c71-99d2-b4afd400e7e8', 'その布、新しい布に変えてもらえるかな？', 'Bisakah Anda mengganti kain ini dengan yang baru?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e94a257-29f4-4c71-99d2-b4afd400e7e8', '布が絡んじゃって、チャックがうまく開かないのよ。', 'Kainnya tersangkut di ritsleting saya dan tidak bisa bergerak dengan benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2e94a257-29f4-4c71-99d2-b4afd400e7e8', '布おむつの方が紙おむつよりも健康にいいと聞いたことがあります。', 'Saya pernah mendengar bahwa popok kain lebih baik untuk kesehatan Anda dibandingkan popok sekali pakai.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3570b1a0-663e-4b5c-8c36-12f9d9d96655', 'vocabulary', '財布', '財布', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kain kekayaan Anda adalah dompet Anda. Sungguh, dompet hanyalah sehelai kain yang kamu simpan di saku yang didalamnya terdapat harta kekayaanmu, bukan? Ini juga bisa menjadi dompet Anda, terutama jika Anda tinggal di Inggris.', 'Kain kekayaan Anda adalah dompet Anda. Sungguh, dompet hanyalah sehelai kain yang kamu simpan di saku yang didalamnya terdapat harta kekayaanmu, bukan? Ini juga bisa menjadi dompet Anda, terutama jika Anda tinggal di Inggris.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3570b1a0-663e-4b5c-8c36-12f9d9d96655', 'Dompet', true) ON CONFLICT DO NOTHING;
