INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3570b1a0-663e-4b5c-8c36-12f9d9d96655', 'さいふ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3570b1a0-663e-4b5c-8c36-12f9d9d96655', '財布を家に忘れたおかげで、十ドル得をしました。', 'Saya lupa dompet saya di rumah, tapi itu menghemat sepuluh dolar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3570b1a0-663e-4b5c-8c36-12f9d9d96655', '母は風水の教えにしたがって、毎年財布を買いかえています。', 'Ibu saya mengikuti fengshui dan mengganti dompetnya setiap tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3570b1a0-663e-4b5c-8c36-12f9d9d96655', '「ちょっと待って。財布を落としましたよ！」「ありがとう。でも、もし私がわざと落としたって言ったら、どうしますか？」', '"Tunggu! Dompetmu terjatuh!" “Terima kasih, tapi apa yang akan kamu lakukan jika aku bilang aku sengaja menjatuhkannya?”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('daeb1146-20cd-4a22-9d7b-1e3beb7c3f92', 'vocabulary', '毛布', '毛布', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kain bulu bukanlah sesuatu yang bisa Anda buang begitu saja. Anda mungkin akan mengubah kain bulu hangat ini menjadi selimut yang bagus.', 'Kain bulu bukanlah sesuatu yang bisa Anda buang begitu saja. Anda mungkin akan mengubah kain bulu hangat ini menjadi selimut yang bagus.') ON CONFLICT (id) DO NOTHING;
