INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('daeb1146-20cd-4a22-9d7b-1e3beb7c3f92', '母が、毛布を忘れないようにすることを思い出させてくれました。', 'Ibuku mengingatkanku untuk tidak melupakan selimutku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('daeb1146-20cd-4a22-9d7b-1e3beb7c3f92', 'その毛布、ダンボール箱に入れてもらっていい？', 'Bisakah Anda memasukkan selimut ke dalam kotak karton?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('daeb1146-20cd-4a22-9d7b-1e3beb7c3f92', '毎日毛布を百枚も洗うなんて想像もつかないよ。', 'Saya tidak dapat membayangkan diri saya mencuci seratus selimut setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2b2b4d54-c1cf-4a38-8ac5-22bfbc0d31e4', 'vocabulary', '恋人', '恋人', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Orang yang romantis adalah seseorang yang melakukan hal-hal romantis bersama Anda. Orang itu adalah kekasihmu.', 'Orang yang romantis adalah seseorang yang melakukan hal-hal romantis bersama Anda. Orang itu adalah kekasihmu.') ON CONFLICT (id) DO NOTHING;
