INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73147b3f-a2ce-4ca2-811b-ac1ff75f4ebb', '十日で体重がニキロ減りました。', 'Berat badan saya turun dua kilogram dalam sepuluh hari.') ON CONFLICT DO NOTHING;
