INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73147b3f-a2ce-4ca2-811b-ac1ff75f4ebb', 'いつも右の靴の踵が左よりも速く擦り減るんだ。', 'Sepatu kanan saya selalu lebih cepat rusak di bagian tumit dibandingkan sepatu kiri saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6aa57cd6-7b83-492b-8379-91f7e032e93e', 'vocabulary', '減法', '減法', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Apa metode untuk mengurangi sesuatu? Nah, Anda mengambil sesuatu. Anda melakukan pengurangan.', 'Apa metode untuk mengurangi sesuatu? Nah, Anda mengambil sesuatu. Anda melakukan pengurangan.') ON CONFLICT (id) DO NOTHING;
