INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f44b215-d8d5-4d0e-99a3-ae8823eaf1de', 'この名詞は、の形容詞になりますか。', 'Bisakah kata benda ini menjadi tanpa kata sifat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f44b215-d8d5-4d0e-99a3-ae8823eaf1de', 'これは可算名詞ですか、不可算名詞ですか？', 'Apakah ini kata benda yang dapat dihitung atau tidak dapat dihitung?') ON CONFLICT DO NOTHING;
