INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7fb0a7be-6694-490e-aefb-7914e9cca7f8', 'vocabulary', '動詞', '動詞', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Part of Speech yang melambangkan gerak adalah Part of Speech yang menggambarkan tindakan. Itu adalah kata kerja.', 'Part of Speech yang melambangkan gerak adalah Part of Speech yang menggambarkan tindakan. Itu adalah kata kerja.') ON CONFLICT (id) DO NOTHING;
