INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7fb0a7be-6694-490e-aefb-7914e9cca7f8', '英語は「主語ー動詞ー目的語」の言語です。', 'Bahasa Inggris adalah bahasa "subjek-kata kerja-objek".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7fb0a7be-6694-490e-aefb-7914e9cca7f8', 'あなたの日本語で一番お気に入りの動詞は何？', 'Apa kata kerja favoritmu dalam bahasa Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7fb0a7be-6694-490e-aefb-7914e9cca7f8', 'もし自分を表現するために動詞を一つだけ選ばなくてはいけないとしたら、どの動詞を選びますか？', 'Jika Anda harus memilih satu kata kerja untuk mendeskripsikan diri Anda, kata kerja manakah yang akan Anda pilih?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79adb610-00db-4f0f-9274-7fc22dc1899f', 'vocabulary', '歌詞', '歌詞', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Bagian pidato suatu lagu adalah bagian lagu yang Anda gunakan untuk berbicara (alias bernyanyi). Ini adalah bagian kata dari lagu tersebut. Ini adalah lirik lagunya. Adakah yang siap untuk beberapa カラオケ?', 'Bagian pidato suatu lagu adalah bagian lagu yang Anda gunakan untuk berbicara (alias bernyanyi). Ini adalah bagian kata dari lagu tersebut. Ini adalah lirik lagunya. Adakah yang siap untuk beberapa カラオケ?') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('79adb610-00db-4f0f-9274-7fc22dc1899f', 'Lirik Lagu', true) ON CONFLICT DO NOTHING;
