INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('85705184-01d0-4efb-b1e9-f1f5aefa0228', 'すうし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85705184-01d0-4efb-b1e9-f1f5aefa0228', '日本語には数詞がたくさんありすぎて、ちょっとパニクってます。', 'Saya sedikit panik karena banyak sekali kata angka dalam bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85705184-01d0-4efb-b1e9-f1f5aefa0228', 'コウイチは、どうやって数詞を覚えたんですか？', 'Bagaimana kamu menghafal angka, Koichi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85705184-01d0-4efb-b1e9-f1f5aefa0228', '日本語の数詞が勉強できるゲームがあればいいのに。', 'Saya berharap ada permainan yang bisa membantu saya mempelajari angka Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cd167cb4-4c87-4c2e-bbef-8a0faf3f735d', 'vocabulary', '自動詞', '自動詞', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Bagian ucapan otomatis adalah kata kerja intransitif. Kata kerja intransitif merupakan tindakan yang terjadi begitu saja alias bukan Anda yang melakukan tindakan atau hal tersebut. Ini adalah kata-kata seperti 付く atau 消える, yang mana Anda tidak melakukan tindakan tersebut. Itu sebabnya mereka otomatis!', 'Bagian ucapan otomatis adalah kata kerja intransitif. Kata kerja intransitif merupakan tindakan yang terjadi begitu saja alias bukan Anda yang melakukan tindakan atau hal tersebut. Ini adalah kata-kata seperti 付く atau 消える, yang mana Anda tidak melakukan tindakan tersebut. Itu sebabnya mereka otomatis!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cd167cb4-4c87-4c2e-bbef-8a0faf3f735d', 'Kata Kerja Intransitif', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('cd167cb4-4c87-4c2e-bbef-8a0faf3f735d', 'じどうし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd167cb4-4c87-4c2e-bbef-8a0faf3f735d', '自動詞「進む」の可能形は、「進める」です。', 'Bentuk potensial dari kata kerja intransitif “to advance” adalah “sesuatu yang maju.”') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd167cb4-4c87-4c2e-bbef-8a0faf3f735d', '私が大の苦手としていることの一つに、他動詞と自動詞の使い分けがあります。', 'Salah satu hal yang sangat saya takuti adalah menggunakan kata kerja transitif dan intransitif dengan benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cd167cb4-4c87-4c2e-bbef-8a0faf3f735d', '「受動態にできるかどうか？」で判断すると、自動詞と他動詞が簡単に見分けられますよ。', 'Anda dapat dengan mudah menilai apakah itu kata kerja intransitif atau kata kerja transitif ketika Anda memikirkan apakah Anda dapat mengubahnya ke bentuk pasif atau tidak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e52e725b-e5e4-4ae0-b1bd-a4b37df36a9c', 'vocabulary', '順位', '順位', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Urutan peringkat Anda adalah peringkat atau posisi Anda di antara peringkat lainnya dalam daftar. Kalahkan skor tinggi itu, Ryu!', 'Urutan peringkat Anda adalah peringkat atau posisi Anda di antara peringkat lainnya dalam daftar. Kalahkan skor tinggi itu, Ryu!') ON CONFLICT (id) DO NOTHING;
