INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e52e725b-e5e4-4ae0-b1bd-a4b37df36a9c', '順位なんかいちいち気にしてたらやってられないよ。', 'Saya tidak dapat melakukannya jika saya harus mengkhawatirkan setiap peringkat secara terpisah.') ON CONFLICT DO NOTHING;
