INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('dde7ce2c-e457-4720-b4c0-01e2a7d86725', 'コウイチは順番にEmailに返信をします。', 'Koichi membalas emailnya secara berurutan.') ON CONFLICT DO NOTHING;
