INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('062815e9-1142-4a1f-ab35-82f86e1c3390', 'vocabulary', '小さい順', '小さい順', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ketika sesuatu mulai dari yang kecil dan berjalan secara berurutan, maka urutannya semakin meningkat, atau yang terkecil terlebih dahulu.', 'Ketika sesuatu mulai dari yang kecil dan berjalan secara berurutan, maka urutannya semakin meningkat, atau yang terkecil terlebih dahulu.') ON CONFLICT (id) DO NOTHING;
