INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('18d4dfaf-b697-41f9-8fe0-feb4ae2f5edf', 'vocabulary', '年代順', '年代順', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda mengurutkan tahun berdasarkan periode kemunculannya dan Anda benar-benar mengurutkannya dalam urutan kronologis.', 'Anda mengurutkan tahun berdasarkan periode kemunculannya dan Anda benar-benar mengurutkannya dalam urutan kronologis.') ON CONFLICT (id) DO NOTHING;
