INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('abbba0aa-2fe3-4061-99ce-ebbe96737423', '町名は五十音順にならんでいます。', 'Nama-nama kota dicantumkan dalam urutan aiueo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('abbba0aa-2fe3-4061-99ce-ebbe96737423', 'この名ぼでは、学生の名前は名字で五十音順に記さいされています。', 'Dalam daftar ini, nama siswa ditempatkan dalam urutan aiueo berdasarkan nama belakang.') ON CONFLICT DO NOTHING;
