INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2a64c57c-6414-405e-adb7-c259d03afda3', 'vocabulary', '立入禁止', '立入禁止', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Berdiri dan masuk keduanya 禁止 (dilarang). Jika Anda melihat tanda ini, pada dasarnya itu berarti jangan masuk atau dilarang masuk.', 'Berdiri dan masuk keduanya 禁止 (dilarang). Jika Anda melihat tanda ini, pada dasarnya itu berarti jangan masuk atau dilarang masuk.') ON CONFLICT (id) DO NOTHING;
