INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a64c57c-6414-405e-adb7-c259d03afda3', 'このドアには、関係者以外立入禁止って書かれているよ。', 'Pintu ini bertuliskan Hanya Personil yang Berwenang.') ON CONFLICT DO NOTHING;
