INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2a64c57c-6414-405e-adb7-c259d03afda3', 'それは大胆だね！君が本当に立入禁止って書いてる場所に入ってションベンしたなんて信じられないよ！', 'Itu liar! Saya tidak percaya Anda masuk ke tempat bertanda "Dilarang Masuk" lalu pipis di sana!') ON CONFLICT DO NOTHING;
