INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae826104-5b51-46a4-8b78-fd629cb33d0b', '胸焼けしている時に、なわとびで何回飛べますか？', 'Berapa kali Anda bisa lompat tali saat Anda menderita sakit maag?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae826104-5b51-46a4-8b78-fd629cb33d0b', '年を取ったせいか、あげ物を食べると胸焼けがするんです。', 'Mungkin karena usiaku, tapi aku mulas saat makan makanan yang digoreng.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ae826104-5b51-46a4-8b78-fd629cb33d0b', '朝からカツ丼なんて、胸焼けしないの？', 'Apakah Anda tidak merasa mulas karena makan katsu-don di pagi hari?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('56fc4885-4170-43b2-80b1-660159a8c5c1', 'vocabulary', '音訓', '音訓', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda pernah melihat (semoga) 音読み dan 訓読み. Ini adalah kombinasi keduanya. Ini on''yomi dan kun''yomi alias bacaan Cina dan Jepang.', 'Anda pernah melihat (semoga) 音読み dan 訓読み. Ini adalah kombinasi keduanya. Ini on''yomi dan kun''yomi alias bacaan Cina dan Jepang.') ON CONFLICT (id) DO NOTHING;
