INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('56fc4885-4170-43b2-80b1-660159a8c5c1', '漢字の音訓の見分け方を教えてください。', 'Tolong ajari saya cara membedakan on''yomi dan kun''yomi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('56fc4885-4170-43b2-80b1-660159a8c5c1', 'これは常用漢字の音訓表です。', 'Ini adalah bagan pembacaan kanji yang umum digunakan dalam bahasa Mandarin dan Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('56fc4885-4170-43b2-80b1-660159a8c5c1', '漢字の音訓ってすごく紛らわしいので嫌いです。', 'Pembacaan kanji dalam bahasa Jepang dan Cina sangat membingungkan, saya benci keduanya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5fe45ae2-da08-4811-bbb9-c5240e8198e8', 'vocabulary', '焼ける', '焼ける', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Anda tahu bagaimana 焼く memasak? Ya, 焼ける harus dimasak. Ini adalah saat Anda tidak sedang memasak sebenarnya, dan proses memasak baru saja terjadi. Bisa juga merujuk pada saat sesuatu terbakar, sehingga menyebabkannya ikut terbakar.', 'Anda tahu bagaimana 焼く memasak? Ya, 焼ける harus dimasak. Ini adalah saat Anda tidak sedang memasak sebenarnya, dan proses memasak baru saja terjadi. Bisa juga merujuk pada saat sesuatu terbakar, sehingga menyebabkannya ikut terbakar.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5fe45ae2-da08-4811-bbb9-c5240e8198e8', 'Untuk Dimasak', true) ON CONFLICT DO NOTHING;
