INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('57d387cd-0acd-47fb-99be-c94f8a0156d1', 'いいかげんにしろ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('57d387cd-0acd-47fb-99be-c94f8a0156d1', 'ビエトはあまりにも怒っていたので、コウイチを殴って「いい加減にしろ！」と叫ばずにはいられなかった。', 'Viet sangat marah sehingga dia tidak bisa menahan diri untuk tidak meninju Koichi dan berteriak, "Hentikan!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7010cdd1-7fc6-4a17-83ea-8cf72708c5e4', 'vocabulary', '減給', '減給', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Penurunan gaji adalah pemotongan gaji.', 'Penurunan gaji adalah pemotongan gaji.') ON CONFLICT (id) DO NOTHING;
