INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7010cdd1-7fc6-4a17-83ea-8cf72708c5e4', '減給されるし、上司も嫌な奴だし、会社を辞めて転職先を探すことを本気で考えてるんだよね。', 'Gaji saya dipotong dan atasan saya jahat, jadi saya serius berpikir untuk berhenti dan mencari pekerjaan lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9678ae6d-d023-4375-818f-43dd7cc03545', 'vocabulary', '腹が減った', '腹が減った', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ketika perut Anda berkurang jumlah barang yang ada di dalamnya, Anda menjadi lapar.', 'Ketika perut Anda berkurang jumlah barang yang ada di dalamnya, Anda menjadi lapar.') ON CONFLICT (id) DO NOTHING;
