INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9678ae6d-d023-4375-818f-43dd7cc03545', '腹が減ったな。この件については、昼飯を食べながら話さないか？', 'saya lapar. Apakah Anda ingin melanjutkan ini saat makan siang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ebc818d-8d97-48be-bd11-acc6c33dea7b', 'vocabulary', '劇', '劇', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kanji dan kata-katanya sama persis. Artinya mereka berbagi makna juga (drama). Bisa juga berarti bermain atau pertunjukan juga.', 'Kanji dan kata-katanya sama persis. Artinya mereka berbagi makna juga (drama). Bisa juga berarti bermain atau pertunjukan juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ebc818d-8d97-48be-bd11-acc6c33dea7b', 'Drama', true) ON CONFLICT DO NOTHING;
