INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ebc818d-8d97-48be-bd11-acc6c33dea7b', 'オペラ劇を観劇しに行く天皇へい下をお見送りしました。', 'Saya mengantar kaisar, yang akan menonton opera.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ebc818d-8d97-48be-bd11-acc6c33dea7b', 'この劇の第2幕第3場で馬の役をしているのがオレの兄貴なんだ。', 'Orang yang berperan sebagai kuda dalam Babak II Adegan III lakon ini adalah kakak laki-laki saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ebc818d-8d97-48be-bd11-acc6c33dea7b', '隣の席の人が劇の最中にずっと指をポキポキ鳴らしてて、すっごく苛々しました。', 'Orang di sebelah saya terus-menerus meretakkan buku-buku jarinya selama pertunjukan dan itu sangat menjengkelkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('29e933a0-f7d9-4651-96b7-c145a4a8fad1', 'vocabulary', '喜劇', '喜劇', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Bersukacitalah drama bukanlah drama melainkan komedi, karena itu membuat Anda bersukacita.', 'Bersukacitalah drama bukanlah drama melainkan komedi, karena itu membuat Anda bersukacita.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('29e933a0-f7d9-4651-96b7-c145a4a8fad1', 'Komedi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('29e933a0-f7d9-4651-96b7-c145a4a8fad1', 'きげき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29e933a0-f7d9-4651-96b7-c145a4a8fad1', 'その映画は悲しすぎて、喜劇というよりは悲劇だ。', 'Filmnya terlalu menyedihkan. Ini harusnya disebut tragedi, bukan komedi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29e933a0-f7d9-4651-96b7-c145a4a8fad1', '喜劇王チャップリンのドキュメンタリーを観て自分もお笑いの道を目指そうと思いました。', 'Setelah menonton film dokumenter tentang Chaplin, raja komedi, saya memutuskan untuk mengejar karir di bidang komedi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('29e933a0-f7d9-4651-96b7-c145a4a8fad1', 'すごく暑かったので、喜劇を観ながらずっと自分をうちわで扇いでいました。', 'Cuacanya sangat panas sehingga saya terus mengipasi diri sambil menonton acara komedi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('65853157-fbac-4607-9ed5-afcc5913955b', 'vocabulary', '悲劇', '悲劇', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Drama sedih selalu berakhir dengan tragedi. Itu yang membuatnya sedih.', 'Drama sedih selalu berakhir dengan tragedi. Itu yang membuatnya sedih.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('65853157-fbac-4607-9ed5-afcc5913955b', 'Tragedi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('65853157-fbac-4607-9ed5-afcc5913955b', 'ひげき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65853157-fbac-4607-9ed5-afcc5913955b', 'それが悲劇の始まりだった。', 'Itu adalah awal dari tragedi saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65853157-fbac-4607-9ed5-afcc5913955b', 'あんた、悲劇の主人公にでもなったつもり？いつまでもクヨクヨしてたって仕方ないでしょ？', 'Apakah Anda mencoba bersikap seperti pahlawan dalam suatu tragedi? Murung selamanya tidak akan membantu siapa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('65853157-fbac-4607-9ed5-afcc5913955b', 'あなたには悲劇がお似合いよ。', 'Tragedi cocok untukmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('50cf04af-c460-4fc0-83cc-b766441a23d0', 'vocabulary', '劇的', '劇的', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Sesuatu yang dramatis dan dramatis.', 'Sesuatu yang dramatis dan dramatis.') ON CONFLICT (id) DO NOTHING;
