INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08b9f3a4-d043-4468-b024-4de27d05a49d', '劇場のロビーで待ち合わせしましょう。', 'Mari kita bertemu di lobi teater.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08b9f3a4-d043-4468-b024-4de27d05a49d', 'それでは劇場のトイレで会いましょう。', 'Sampai jumpa di kamar mandi di teater.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('08b9f3a4-d043-4468-b024-4de27d05a49d', '劇場までの毎日の通勤に、片道二時間以上かかります。', 'Perjalanan harian saya ke teater memakan waktu lebih dari dua jam sekali jalan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('884d3b76-a0fd-4386-a762-fae7bada4d26', 'vocabulary', '歌劇', '歌劇', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Sebuah drama lagu. Ugh, aku benci ini. Mereka banyak bernyanyi dan sangat dramatis. Ini adalah sebuah opera.', 'Sebuah drama lagu. Ugh, aku benci ini. Mereka banyak bernyanyi dan sangat dramatis. Ini adalah sebuah opera.') ON CONFLICT (id) DO NOTHING;
