INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('884d3b76-a0fd-4386-a762-fae7bada4d26', 'その歌劇の主人公は生粋のフランス人です。', 'Tokoh utama opera ini adalah orang Prancis kelahiran alami.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('884d3b76-a0fd-4386-a762-fae7bada4d26', 'とある歌劇で、奴隷の役を演じました。', 'Saya memainkan peran sebagai budak dalam sebuah opera.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('884d3b76-a0fd-4386-a762-fae7bada4d26', '歌劇のチケットの値段を2%値上げします。', 'Kami akan menaikkan harga tiket opera sebesar 2%.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bab39a7d-dde3-4d05-b895-83298abf6218', 'vocabulary', '〜枚', '〜枚', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Ini adalah penghitung yang dapat digunakan dengan berbagai benda "datar", oleh karena itu mengacu pada benda datar. Hal-hal lain yang dapat dirujuk termasuk item pakaian, seprai, kertas, perangko, piring, dan banyak lagi. Perhatikan bagaimana semuanya berbentuk datar?', 'Ini adalah penghitung yang dapat digunakan dengan berbagai benda "datar", oleh karena itu mengacu pada benda datar. Hal-hal lain yang dapat dirujuk termasuk item pakaian, seprai, kertas, perangko, piring, dan banyak lagi. Perhatikan bagaimana semuanya berbentuk datar?') ON CONFLICT (id) DO NOTHING;
