INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bab39a7d-dde3-4d05-b895-83298abf6218', '日曜日のサッカーの試合のチケットを十枚持っています。', 'Saya punya sepuluh tiket untuk pertandingan sepak bola pada hari Minggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bab39a7d-dde3-4d05-b895-83298abf6218', 'いつもは朝ご飯は食パン一枚だけです。', 'Sarapan saya biasanya hanya sepotong roti panggang.') ON CONFLICT DO NOTHING;
