INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('03ea4e17-4492-42bc-9a38-e2d6610aac49', 'vocabulary', '品詞', '品詞', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Produk part of Speech lebih merupakan bagian dari pidato. Kejahatan menghasilkan kejahatan, begitulah.', 'Produk part of Speech lebih merupakan bagian dari pidato. Kejahatan menghasilkan kejahatan, begitulah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('03ea4e17-4492-42bc-9a38-e2d6610aac49', 'Bagian Pidato', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('03ea4e17-4492-42bc-9a38-e2d6610aac49', 'ひんし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('03ea4e17-4492-42bc-9a38-e2d6610aac49', '品詞にはどんなものがあるか教えてください。', 'Tolong beri tahu saya hal-hal apa saja yang kami miliki untuk bagian pidato.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('03ea4e17-4492-42bc-9a38-e2d6610aac49', '品詞についての本を書いたんですが、今、どうすればたくさんの冊数を売ることができるのか考えています。', 'Saya menulis buku tentang bagian-bagian pidato dan saat ini saya sedang memikirkan bagaimana saya bisa menjual banyak salinannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('03ea4e17-4492-42bc-9a38-e2d6610aac49', 'この文章を品詞に分解しなさい。', 'Silakan uraikan kalimat ini berdasarkan bagian-bagian pidatonya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('69074785-af43-41d3-8b21-cc37b60b9246', 'vocabulary', '形容動詞', '形容動詞', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', '形容詞 adalah kata sifat. Lalu bagaimana dengan kata sifat yang mengandung 動詞 (kata kerja)? Bagaimana hal itu masuk akal? Saya juga tidak sepenuhnya yakin, tapi kata sifat dengan gerakan di dalamnya adalah kata sifat na. Ini adalah kata sifat yang bisa diakhiri dengan な (便利な, misalnya). Faktanya, kata-kata tersebut lebih mirip kata benda daripada kata kerja, jadi apa penyebabnya? Apapun itu, putuskan saja Anda tidak ingin berurusan dengan kegilaan ini. Katakan saja nah, aku tidak peduli lagi dengan hal ini.', '形容詞 adalah kata sifat. Lalu bagaimana dengan kata sifat yang mengandung 動詞 (kata kerja)? Bagaimana hal itu masuk akal? Saya juga tidak sepenuhnya yakin, tapi kata sifat dengan gerakan di dalamnya adalah kata sifat na. Ini adalah kata sifat yang bisa diakhiri dengan な (便利な, misalnya). Faktanya, kata-kata tersebut lebih mirip kata benda daripada kata kerja, jadi apa penyebabnya? Apapun itu, putuskan saja Anda tidak ingin berurusan dengan kegilaan ini. Katakan saja nah, aku tidak peduli lagi dengan hal ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('69074785-af43-41d3-8b21-cc37b60b9246', 'Na Kata Sifat', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('69074785-af43-41d3-8b21-cc37b60b9246', 'けいようどうし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69074785-af43-41d3-8b21-cc37b60b9246', '今日の授業は形容動詞でした。', 'Kelas hari ini membahas tentang kata sifat na.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69074785-af43-41d3-8b21-cc37b60b9246', '頭の中で、形容動詞と形容詞が混ぜこぜになってしまっていて、かなり混乱しています。', 'Saya mencampurkan kata sifat na dengan kata sifat i dan sekarang saya benar-benar bingung.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('69074785-af43-41d3-8b21-cc37b60b9246', 'それが形容動詞なのかただの形容詞なのか、判断にまよいました。', 'Saya kesulitan menilai apakah itu kata sifat na atau hanya kata sifat i.') ON CONFLICT DO NOTHING;
