INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('63865135-09d0-4d55-8b42-11025344fb50', 'こんな長い台詞、よく覚えられるわね。', 'Bagaimana Anda bisa mengingat pidato yang begitu panjang?') ON CONFLICT DO NOTHING;
