INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d8f04f4-e452-4b08-908d-f89740c94ec6', '私たちの家は、茶色い門のある家のすぐとなりです。', 'Rumah kami bersebelahan dengan rumah yang gerbangnya berwarna coklat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d8f04f4-e452-4b08-908d-f89740c94ec6', 'あそこの大きい門をくぐると神でんが見えるよ。', 'Jika Anda lewat di bawah gerbang besar, Anda akan melihat tempat suci.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d8f04f4-e452-4b08-908d-f89740c94ec6', '門には鍵がかかっているんだ。', 'Gerbangnya terkunci.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('19038d57-8b98-42e5-81c7-0f41e0b1966d', 'vocabulary', '禁じる', '禁じる', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti larangan, jadi versi verbanya berarti melarang atau melarang.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti larangan, jadi versi verbanya berarti melarang atau melarang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('19038d57-8b98-42e5-81c7-0f41e0b1966d', 'Melarang', true) ON CONFLICT DO NOTHING;
