INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19038d57-8b98-42e5-81c7-0f41e0b1966d', 'これは、コウイチが自分の禁じられた恋について書いた私小説です。', 'Ini adalah novel otobiografi yang ditulis Koichi tentang cinta terlarangnya sendiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19038d57-8b98-42e5-81c7-0f41e0b1966d', '医者は、にんぷにアルコールと喫煙を禁じた。', 'Dokter melarang ibu hamil tersebut mengonsumsi alkohol dan rokok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('19038d57-8b98-42e5-81c7-0f41e0b1966d', 'この部屋では、私語を禁じる。', 'Di ruangan ini dilarang berbisik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('dc93f0a5-7fb0-4105-8c3d-8cfb08484d06', 'vocabulary', '荷札', '荷札', 2, '9e8f3a0b-1c2d-3e4f-5a6b-7c8d9e0f1a2b', 'Label bagasi adalah label yang Anda pasang pada bagasi. Ini juga merupakan label yang dapat Anda tempelkan pada paket sebelum mengirimkannya, seperti label pengiriman.', 'Label bagasi adalah label yang Anda pasang pada bagasi. Ini juga merupakan label yang dapat Anda tempelkan pada paket sebelum mengirimkannya, seperti label pengiriman.') ON CONFLICT (id) DO NOTHING;
