INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d9069ba-40d6-4d2f-8355-bbabd8e460a5', '最近、校風が乱れています。', 'Moral sekolah sedang kacau saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d9069ba-40d6-4d2f-8355-bbabd8e460a5', 'トーフグ社員はコウイチの前で一糸乱れぬおどりをひろうしなければならない。', 'Para karyawan Tofugu harus menampilkan tarian tanpa menjadi kusut di depan Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d9069ba-40d6-4d2f-8355-bbabd8e460a5', 'サーモンと離婚した後、フグは生活が乱れた。', 'Setelah perceraiannya dengan Salmon, kehidupan Fugu berantakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('429cd7ab-e888-4dad-a7f9-4ee6f8c1f20a', 'vocabulary', '乱戦', '乱戦', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kerusuhan perang adalah saat segalanya menjadi kacau. Ini adalah pertarungan jarak dekat! Gratis untuk semua!', 'Kerusuhan perang adalah saat segalanya menjadi kacau. Ini adalah pertarungan jarak dekat! Gratis untuk semua!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('429cd7ab-e888-4dad-a7f9-4ee6f8c1f20a', 'Jarak dekat', true) ON CONFLICT DO NOTHING;
