INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('429cd7ab-e888-4dad-a7f9-4ee6f8c1f20a', 'らんせん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('429cd7ab-e888-4dad-a7f9-4ee6f8c1f20a', 'あの試合はまれに見る乱戦だった。', 'Permainan itu gratis untuk semua yang jarang kita lihat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('429cd7ab-e888-4dad-a7f9-4ee6f8c1f20a', 'コウイチのスピーチのせいでかん客の間に乱戦が起こってしまった。', 'Terjadi huru-hara di antara penonton akibat ucapan Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('429cd7ab-e888-4dad-a7f9-4ee6f8c1f20a', 'セール初日、モールは人でごった返しになり、まるで大乱戦のようだった。', 'Di hari pertama penjualan, mal menjadi sangat ramai, seperti semacam battle royale.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('27093aff-457d-4a6f-af1f-a8d2f6a4410c', 'vocabulary', '混乱', '混乱', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Terjadi kerusuhan dan semuanya jadi campur aduk! Tentu saja ada banyak kebingungan di dalamnya.', 'Terjadi kerusuhan dan semuanya jadi campur aduk! Tentu saja ada banyak kebingungan di dalamnya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('27093aff-457d-4a6f-af1f-a8d2f6a4410c', 'Kebingungan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('27093aff-457d-4a6f-af1f-a8d2f6a4410c', 'Disorder', false) ON CONFLICT DO NOTHING;
