INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('27093aff-457d-4a6f-af1f-a8d2f6a4410c', 'こんらん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27093aff-457d-4a6f-af1f-a8d2f6a4410c', 'はん人は、混乱にまぎれてにげてしまった。', 'Pelakunya lolos dalam kebingungan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27093aff-457d-4a6f-af1f-a8d2f6a4410c', 'その町は、山火事で大混乱となっていた。', 'Kebakaran hutan membawa kekacauan besar di kota.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('27093aff-457d-4a6f-af1f-a8d2f6a4410c', '申し訳ないけど、そんな中途半端なやり方じゃ新入社員が混乱しちゃう気がします。', 'Saya khawatir kebijakan Anda yang setengah matang dapat menimbulkan kebingungan di kalangan karyawan baru.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('431ca500-bf30-48c4-b79f-23098e9d319b', 'vocabulary', '乱交', '乱交-4169', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Berkumpulnya banyak orang membentuk semacam kerusuhan. Anda mungkin berpikir ini akan menjadi sesuatu yang lebih kejam, tapi sebenarnya ini hanya pesta seks. Saya kira banyak pencampuran, dan tidak terlalu banyak pengorganisasian di pihak penyelenggara pesta, setidaknya menurut urutan kanji ini.', 'Berkumpulnya banyak orang membentuk semacam kerusuhan. Anda mungkin berpikir ini akan menjadi sesuatu yang lebih kejam, tapi sebenarnya ini hanya pesta seks. Saya kira banyak pencampuran, dan tidak terlalu banyak pengorganisasian di pihak penyelenggara pesta, setidaknya menurut urutan kanji ini.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('431ca500-bf30-48c4-b79f-23098e9d319b', 'Pesta', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('431ca500-bf30-48c4-b79f-23098e9d319b', 'Promiscuity', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('431ca500-bf30-48c4-b79f-23098e9d319b', 'らんこう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('431ca500-bf30-48c4-b79f-23098e9d319b', 'かの女は、乱交のと中で、舌をだらりと出して気ぜつしてしまったんです。', 'Lidahnya terjulur dan dia pingsan saat pesta seks.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('431ca500-bf30-48c4-b79f-23098e9d319b', 'いい加減、乱交するのは止めなよ。みんなドン引きだよ。', 'Hei, sudah saatnya kamu berhenti melakukan pergaulan bebas, kamu sudah membuat semua orang menjauhinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('431ca500-bf30-48c4-b79f-23098e9d319b', '「何か今日の俺、マジでイケてる。ひょっとしたらアイツらの乱交パーティにも誘われちゃうかも。」「ははは〜。そうだといいね。」', '"Aku terlihat sangat baik hari ini, aku mungkin diminta untuk ikut pesta seks." "Haha. Kamu berharap!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('04facc93-8876-468f-a612-a0f9af12e5e6', 'vocabulary', '〜冊', '〜冊', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
