INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('04facc93-8876-468f-a612-a0f9af12e5e6', 'さつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('04facc93-8876-468f-a612-a0f9af12e5e6', '市立図書館には、三万三千三百冊以上のぞう書があります。', 'Perpustakaan kota memiliki lebih dari 33.300 volume.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('04facc93-8876-468f-a612-a0f9af12e5e6', '友達にもあげたかったので、その本を十冊買いました。', 'Saya ingin memberikan buku itu kepada teman-teman saya juga, jadi saya membeli sepuluh eksemplar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('04facc93-8876-468f-a612-a0f9af12e5e6', 'すみません、ちょっとお声が遠いようなのですが。日本語の教科書が何冊いるとおっしゃいましたか？', 'Maaf, saya kesulitan mendengarkan Anda. Apakah Anda menyebutkan berapa banyak buku pelajaran bahasa Jepang yang Anda inginkan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5d890bce-bfdc-44d8-aa7b-c66450277dfd', 'vocabulary', '三冊', '三冊', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Tiga buku sama dengan tiga buku.', 'Tiga buku sama dengan tiga buku.') ON CONFLICT (id) DO NOTHING;
