INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5d890bce-bfdc-44d8-aa7b-c66450277dfd', 'さんさつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d890bce-bfdc-44d8-aa7b-c66450277dfd', 'この図書館では、本は三冊まで借りれます。', 'Di perpustakaan ini, Anda dapat meminjam hingga tiga buku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d890bce-bfdc-44d8-aa7b-c66450277dfd', 'コウイチは、ヌード写真集を三冊だけ発行しました。', 'Koichi hanya merilis tiga volume buku fotografi telanjangnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d890bce-bfdc-44d8-aa7b-c66450277dfd', '「今日は日本の小説を三冊読むぞ！」「はは。出来るもんならやってみな。」', '"Aku akan membaca tiga novel Jepang hari ini!" "Haha. Kamu berharap."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e57a1905-61c7-4da1-9d4f-f49e00889b0c', 'vocabulary', '八冊', '八冊', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Ketika Anda memiliki delapan buku, Anda memiliki delapan buku. Ini adalah contoh cara menghitung buku, jadi jika Anda memiliki delapan buku, inilah yang akan Anda katakan.', 'Ketika Anda memiliki delapan buku, Anda memiliki delapan buku. Ini adalah contoh cara menghitung buku, jadi jika Anda memiliki delapan buku, inilah yang akan Anda katakan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e57a1905-61c7-4da1-9d4f-f49e00889b0c', 'Delapan Buku', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e57a1905-61c7-4da1-9d4f-f49e00889b0c', 'Eight Volumes', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e57a1905-61c7-4da1-9d4f-f49e00889b0c', 'はっさつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e57a1905-61c7-4da1-9d4f-f49e00889b0c', '学生は八人だから、教科書は八冊必要です。', 'Karena jumlah siswanya delapan, maka diperlukan delapan buku pelajaran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e57a1905-61c7-4da1-9d4f-f49e00889b0c', 'お金がなくていすが買えないので、本を八冊つみ上げていすの代わりにしています。', 'Saya tidak punya uang dan tidak bisa membeli kursi, jadi saya menggunakan delapan buku sebagai kursi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e57a1905-61c7-4da1-9d4f-f49e00889b0c', '小説をたった八冊出版したからって、自分の事を小説家だなんて呼びませんよ。五十冊出版すれば、もしかするとそう呼ぶかもしれないけどね。', 'Saya tidak akan menyebut diri saya penulis fiksi setelah hanya menerbitkan delapan buku. Jika saya menerbitkan lima puluh buku, maka saya akan menyebut diri saya demikian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('40adc49f-1c7c-4321-9372-26c537f711b2', 'vocabulary', '一冊', '一冊', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Ketika Anda memiliki satu buku, Anda sebenarnya hanya memiliki satu buku.', 'Ketika Anda memiliki satu buku, Anda sebenarnya hanya memiliki satu buku.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('40adc49f-1c7c-4321-9372-26c537f711b2', 'Satu Buku', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('40adc49f-1c7c-4321-9372-26c537f711b2', 'One Volume', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('40adc49f-1c7c-4321-9372-26c537f711b2', 'いっさつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40adc49f-1c7c-4321-9372-26c537f711b2', 'このざっしは一冊四百八十円です。', 'Majalah ini berharga 480 yen untuk satu volume.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40adc49f-1c7c-4321-9372-26c537f711b2', 'これは、世界に一冊しかない絵本です。', 'Hanya satu salinan buku bergambar khusus ini yang ada di dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('40adc49f-1c7c-4321-9372-26c537f711b2', 'あなたのために旅の間に読める本を一冊買っておいたの。タイトルは『地図』よ。', 'Aku membelikanmu buku untuk dibaca selama perjalananmu. Judulnya adalah "Peta".') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1d718582-5ed8-4c40-acd1-9a5a8ac7b6e6', 'vocabulary', '別冊', '別冊', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Biasanya Anda menyebut buku sebagai "volume" jika buku tersebut berbentuk set, bukan? Ini memang seperti itu, tapi terpisah, menjadikannya volume terpisah.', 'Biasanya Anda menyebut buku sebagai "volume" jika buku tersebut berbentuk set, bukan? Ini memang seperti itu, tapi terpisah, menjadikannya volume terpisah.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1d718582-5ed8-4c40-acd1-9a5a8ac7b6e6', 'Volume Terpisah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1d718582-5ed8-4c40-acd1-9a5a8ac7b6e6', 'べっさつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d718582-5ed8-4c40-acd1-9a5a8ac7b6e6', '別冊の付ろくをいつも楽しみにしています。', 'Saya selalu menantikan volume terpisah gratis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d718582-5ed8-4c40-acd1-9a5a8ac7b6e6', 'かつて、別冊少年ジャンプというざっしがありました。', 'Suatu ketika, ada majalah bernama "Separate Volume Shonen Jump".') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d718582-5ed8-4c40-acd1-9a5a8ac7b6e6', '1985年、雑誌トーフグの別冊本に、生まれたばかりのコウイチの写真が掲載されました。', 'Pada tahun 1985, foto Koichi yang baru lahir diterbitkan dalam edisi tambahan Majalah Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3257165a-1166-4b29-b4ad-3b103202cb67', 'vocabulary', '集団', '集団', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kelompok yang berkumpul adalah sekumpulan orang. Itu adalah kelompok atau kerumunan.', 'Kelompok yang berkumpul adalah sekumpulan orang. Itu adalah kelompok atau kerumunan.') ON CONFLICT (id) DO NOTHING;
