INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3257165a-1166-4b29-b4ad-3b103202cb67', '集団で行動するのが苦手なんです。', 'Aku tidak pandai berakting dalam kelompok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3257165a-1166-4b29-b4ad-3b103202cb67', 'その国に行くなら、テロリスト集団に気をつけなくちゃいけませんよ。', 'Jika Anda pergi ke negara itu, Anda harus berhati-hati terhadap kelompok teroris.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3257165a-1166-4b29-b4ad-3b103202cb67', 'コウイチは終盤で集団を抜け出し、ホノルルマラソンで優勝した。', 'Koichi unggul dari penonton di akhir balapan dan memenangkan Maraton Honolulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5637d71d-8084-4415-bbcf-5dce3137fa88', 'vocabulary', '入団', '入団', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Jika Anda masuk ke dalam grup, itu disebut pendaftaran atau pendaftaran. Anda bergabung dengan grup.', 'Jika Anda masuk ke dalam grup, itu disebut pendaftaran atau pendaftaran. Anda bergabung dengan grup.') ON CONFLICT (id) DO NOTHING;
