INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1077ea17-9a2e-4013-a692-b4839278adfb', 'あらたまる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1077ea17-9a2e-4013-a692-b4839278adfb', '日本の年号が、豆河豚に改まりました。', 'Nama era Jepang diubah menjadi Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1077ea17-9a2e-4013-a692-b4839278adfb', 'ビエトの生活たい度が改まって、コウイチはとてもよろこびました。', 'Koichi sangat senang melihat Viet telah berubah dari cara hidupnya yang jahat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1077ea17-9a2e-4013-a692-b4839278adfb', 'そう改まるなよ。コウイチ大統領は、とても気さくなんだから。', 'Jangan terlalu formal! Presiden Koichi sangat ramah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('059cd54f-be55-4703-b11d-b3fce6ca6574', 'vocabulary', '改正', '改正', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Perbarui dan perbaiki sesuatu. Ketika Anda melakukan ini, Anda sedang melakukan revisi, amandemen atau perubahan. Ah, jauh lebih baik sekarang.', 'Perbarui dan perbaiki sesuatu. Ketika Anda melakukan ini, Anda sedang melakukan revisi, amandemen atau perubahan. Ah, jauh lebih baik sekarang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('059cd54f-be55-4703-b11d-b3fce6ca6574', 'Revisi', true) ON CONFLICT DO NOTHING;
