INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cca2af59-eda5-4695-91dc-3badb30f2276', 'コウイチに暴力でたまごっちを取られました。', 'Koichi mengambil tamagotchiku dengan paksa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cca2af59-eda5-4695-91dc-3badb30f2276', '家庭内暴力にたえかねて、家を出ました。', 'Saya tidak tahan dengan kekerasan dalam rumah tangga, jadi saya meninggalkan rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cca2af59-eda5-4695-91dc-3badb30f2276', '親は本当に、暴力的な映画やビデオゲームが子供の目に触れる事を制限すべきなのでしょうか？', 'Apakah menurut Anda orang tua harus membatasi anak-anak mereka menonton film dan video game kekerasan?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a90c5def-8d40-43e7-bf4b-6f89a18234f4', 'vocabulary', '乱暴', '乱暴', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kerusuhan dan kekerasan. Kedengarannya buruk! Kedengarannya seperti tempat yang penuh kekerasan, karena kerusuhan adalah kekerasan dan kekerasan juga merupakan kekerasan!', 'Kerusuhan dan kekerasan. Kedengarannya buruk! Kedengarannya seperti tempat yang penuh kekerasan, karena kerusuhan adalah kekerasan dan kekerasan juga merupakan kekerasan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a90c5def-8d40-43e7-bf4b-6f89a18234f4', 'Kekerasan', true) ON CONFLICT DO NOTHING;
