INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a90c5def-8d40-43e7-bf4b-6f89a18234f4', 'らんぼう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a90c5def-8d40-43e7-bf4b-6f89a18234f4', '乱暴なやつは大きらいだ！', 'Aku benci orang yang kejam!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a90c5def-8d40-43e7-bf4b-6f89a18234f4', 'その男は少女に乱暴したつみでたいほされた。', 'Pria itu ditangkap karena menyerang seorang gadis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a90c5def-8d40-43e7-bf4b-6f89a18234f4', '「父さん、友達が僕のこと、乱暴だって言うんだ。」「それがどうした。そんな奴の言うことなんかどうでもいいよ。そんな馬鹿たれ、こてんぱにしてやれ！」', '"Ayah, temanku bilang aku kasar." "Terus kenapa? Siapa yang peduli dengan apa yang dia pikirkan? Hajar saja orang bodoh itu!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f6e32b97-0045-4aad-9e69-cfb6a9df87e7', 'vocabulary', '暴走', '暴走', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Lari dengan kekerasan... terdengar seperti maraton yang salah. Tidak, ini adalah saat Anda berlarian dan Anda semua melakukan kekerasan. Cara yang lebih baik untuk mendeskripsikan hal ini adalah dengan mengatakan "menjadi liar" atau "keluar kendali".', 'Lari dengan kekerasan... terdengar seperti maraton yang salah. Tidak, ini adalah saat Anda berlarian dan Anda semua melakukan kekerasan. Cara yang lebih baik untuk mendeskripsikan hal ini adalah dengan mengatakan "menjadi liar" atau "keluar kendali".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f6e32b97-0045-4aad-9e69-cfb6a9df87e7', 'Jalankan Liar', true) ON CONFLICT DO NOTHING;
