INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f6e32b97-0045-4aad-9e69-cfb6a9df87e7', 'ぼうそう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f6e32b97-0045-4aad-9e69-cfb6a9df87e7', 'フグは最近ちょっと暴走気味だよね。', 'Fugu menjadi sedikit liar akhir-akhir ini, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f6e32b97-0045-4aad-9e69-cfb6a9df87e7', '暴走しているコウイチをビエトはやさしくつつみこんだ。', 'Viet dengan lembut memeluk Koichi yang sudah lepas kendali.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f6e32b97-0045-4aad-9e69-cfb6a9df87e7', '暴走したトラックが、トーフグオフィスに突っ込んで来る夢を見た。', 'Saya bermimpi sebuah truk yang melaju menabrak kantor Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9d96e3a3-dd75-439a-b3b7-19958ad955da', 'vocabulary', '歴史', '歴史', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kelanjutan sejarah adalah sejarah itu sendiri. Ini adalah kata utama untuk "sejarah" dan Anda akan sering melihatnya jika Anda berada di sekolah atau semacamnya.', 'Kelanjutan sejarah adalah sejarah itu sendiri. Ini adalah kata utama untuk "sejarah" dan Anda akan sering melihatnya jika Anda berada di sekolah atau semacamnya.') ON CONFLICT (id) DO NOTHING;
