INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('9d96e3a3-dd75-439a-b3b7-19958ad955da', 'れきし', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d96e3a3-dd75-439a-b3b7-19958ad955da', '歴史を勉強しておくと、しょう来得をするよ。', 'Anda akan mendapat manfaat dari mempelajari sejarah di masa depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d96e3a3-dd75-439a-b3b7-19958ad955da', 'そのころは、高校の歴史の先生になりたいと思っていたんです。', 'Sekitar waktu itu, saya ingin menjadi guru sejarah di sekolah menengah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('9d96e3a3-dd75-439a-b3b7-19958ad955da', 'トーフグの歴史について簡単に説明させてください。', 'Izinkan saya memberi Anda penjelasan singkat tentang sejarah Tofugu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', 'vocabulary', '学歴', '学歴', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kelanjutan belajar adalah waktu yang berlalu dimana kita belajar. Ini adalah sejarah akademis, jadi perhatikan baik-baik!', 'Kelanjutan belajar adalah waktu yang berlalu dimana kita belajar. Ini adalah sejarah akademis, jadi perhatikan baik-baik!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', 'Sejarah Akademik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', 'Academic Background', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', 'Academic Record', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', 'がくれき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', '日本やかん国は学歴社会ですが、アメリカはちがうんですか？', 'Jepang dan Korea adalah masyarakat yang berorientasi pada latar belakang akademis, tetapi bukankah Amerika juga seperti itu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', '学歴はほとんど無いけど、立ぱな人もいるよ。', 'Ada orang-orang terpuji yang hanya memiliki sedikit sejarah akademis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a5a9bad-04a8-4dfc-96ca-9837896c108f', '「お母さん、私ね、今日もテストで満点とったの。」「それがどうしたのよ？あんた本気で学歴が全てだと思ってるわけ？」', '"Hai, Bu! Aku mendapat nilai sempurna lagi dalam ulanganku." "Terus kenapa? Apakah kamu benar-benar percaya bahwa prestasi akademis seseorang adalah segalanya?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4beaf340-901d-4111-b4ba-c76139de9dfb', 'vocabulary', '比べる', '比べる', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membandingkan jadi versi vocab verbanya adalah membandingkan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membandingkan jadi versi vocab verbanya adalah membandingkan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4beaf340-901d-4111-b4ba-c76139de9dfb', 'Untuk Membandingkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4beaf340-901d-4111-b4ba-c76139de9dfb', 'くらべる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4beaf340-901d-4111-b4ba-c76139de9dfb', '去年と比べてワニカニユーザーの数が減っているんです。どうしましょう？', 'Jumlah pengguna WaniKani lebih rendah dibandingkan tahun lalu. Apa yang harus kita lakukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4beaf340-901d-4111-b4ba-c76139de9dfb', 'このコウイチのつめのあかが入ったお茶と鼻くそが入ったお茶を飲み比べて感想を言ってください。', 'Bandingkan teh yang mengandung kotoran kuku Koichi ini dengan teh yang mengandung booger Koichi dan beri tahu saya kesan Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4beaf340-901d-4111-b4ba-c76139de9dfb', '主人と私は、私達の双子をできるだけ比べないようにはしていますが、やっぱり難しいですね。', 'Saya dan suami telah berusaha untuk tidak membandingkan saudara kembar kami satu sama lain, namun itu sulit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f0f8daef-b432-4769-afd0-401256f182fe', 'vocabulary', '比例', '比例', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Ini adalah hal yang sulit. Saat Anda membandingkan contoh (dalam hal ini angka), Anda mengetahui proporsi/rasio. Suatu rasio, misalnya, mempunyai satu angka di atas angka lainnya. Itu adalah contoh yang dibandingkan. Sama dengan proporsi. Tanpa dua hal yang bisa dibandingkan, proporsi tidak masuk akal. Itu sebabnya ketika Anda membandingkan contoh, Anda berurusan dengan proporsi atau rasio.', 'Ini adalah hal yang sulit. Saat Anda membandingkan contoh (dalam hal ini angka), Anda mengetahui proporsi/rasio. Suatu rasio, misalnya, mempunyai satu angka di atas angka lainnya. Itu adalah contoh yang dibandingkan. Sama dengan proporsi. Tanpa dua hal yang bisa dibandingkan, proporsi tidak masuk akal. Itu sebabnya ketika Anda membandingkan contoh, Anda berurusan dengan proporsi atau rasio.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f0f8daef-b432-4769-afd0-401256f182fe', 'Proporsi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f0f8daef-b432-4769-afd0-401256f182fe', 'Ratio', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f0f8daef-b432-4769-afd0-401256f182fe', 'ひれい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f0f8daef-b432-4769-afd0-401256f182fe', '芸能人は比例代表制のシステムを利用して政治家になるケースが多い。', 'Selebritis menjadi politisi dengan memanfaatkan keterwakilan proporsional dalam sistem pemilu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f0f8daef-b432-4769-afd0-401256f182fe', 'コウイチの美しさに比例してワニカニユーザーの数もふえるってこと、ちゃんと自覚してくださいね。', 'Perlu diketahui bahwa kecantikan Anda berbanding lurus dengan peningkatan jumlah pengguna WaniKani, Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f0f8daef-b432-4769-afd0-401256f182fe', '外国語能力は、いつでも時間変化率に比例するという訳ではない。', 'Kemampuan berbahasa asing tidak selalu meningkat seiring dengan laju perubahan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('944da872-340d-45ad-a638-9f3765e08bdd', 'vocabulary', '対比', '対比', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Saat Anda melihat sesuatu versus sesuatu yang lain, Anda membandingkannya satu sama lain. Anda melihat perbedaan di antara keduanya dan membuat perbandingan.', 'Saat Anda melihat sesuatu versus sesuatu yang lain, Anda membandingkannya satu sama lain. Anda melihat perbedaan di antara keduanya dan membuat perbandingan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('944da872-340d-45ad-a638-9f3765e08bdd', 'Kontras', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('944da872-340d-45ad-a638-9f3765e08bdd', 'Comparison', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('944da872-340d-45ad-a638-9f3765e08bdd', 'たいひ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('944da872-340d-45ad-a638-9f3765e08bdd', 'りょうしは、二ひきの魚を対比してみました。', 'Nelayan membandingkan kedua ikan tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('944da872-340d-45ad-a638-9f3765e08bdd', '日本の生活とアメリカの生活じゃ、いい対比にならないよ。', 'Kehidupan orang Jepang dan kehidupan orang Amerika bukanlah perbandingan yang baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('944da872-340d-45ad-a638-9f3765e08bdd', '誰がコウイチの鼻の写真を撮ったの？その光と影の対比がすごく好きなんだけど。', 'Siapa yang memotret hidung Koichi? Saya sangat menyukai kontras antara cahaya dan bayangan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('592301f6-09af-4ad6-9326-2daf54a0a06e', 'vocabulary', '混ぜる', '混ぜる', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mencampur jadi versi vocab verbanya adalah mencampur sesuatu, mengaduk sesuatu, atau memblender sesuatu. Ini adalah saat Anda melakukan pencampuran. Anda dapat mengingat ini karena "ada (ぜる) banyak mixing yang harus dilakukan, jadi sebaiknya Anda melakukannya saja karena tidak ada orang lain yang mau."
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('592301f6-09af-4ad6-9326-2daf54a0a06e', 'Untuk Mencampur Sesuatu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('592301f6-09af-4ad6-9326-2daf54a0a06e', 'To Stir Something', false) ON CONFLICT DO NOTHING;
