INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('592301f6-09af-4ad6-9326-2daf54a0a06e', 'まぜる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('592301f6-09af-4ad6-9326-2daf54a0a06e', '混ぜるな危険！', 'Jangan mencampurnya. Itu berbahaya!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('592301f6-09af-4ad6-9326-2daf54a0a06e', 'トンカツソースとマヨネーズを混ぜたら最強に美味しいよ！', 'Rasanya luar biasa enak jika Anda mencampurkan saus tonkatsu dengan mayones.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('592301f6-09af-4ad6-9326-2daf54a0a06e', 'ねぇ、気をつけた方がいいよ。あの男がさっきあんたの飲み物に何か混ぜてたのを見たよ。', 'Hei, kamu harus hati-hati, aku melihat pria itu mencampurkan sesuatu ke dalam minumanmu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', 'vocabulary', '混ざる', '混ざる', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya campur jadi versi vocab verbanya adalah bercampur atau bercampur. Ini adalah saat sesuatu tercampur dan Anda tidak langsung melakukan tindakan mencampur apa pun. Anda dapat mengingat hal ini karena Tzar (ざる) dari Rusia sangat terkesan bahwa segala sesuatunya akan tercampur dengan sendirinya dan Anda tidak melakukan pencampuran tersebut.
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', 'Agar Tercampur', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', 'To Be Mixed', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', 'To Be Blended With', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', 'まざる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', '水と油は混ざりません。', 'Minyak tidak bercampur dengan air.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', '色が混ざってにじんでしまいました。', 'Warna-warna itu bercampur.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3cf10ecd-c720-4120-bab7-818ec5b86d41', 'みんなの会話に混ざることができなくてとても悲しかったし、寂しかったよ。', 'Saya merasa sangat sedih dan kesepian karena saya tidak dapat berkontribusi sama sekali dalam percakapan tersebut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fba79324-61e7-47c0-9e7d-f48960d1e993', 'vocabulary', '絡む', '絡む', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjerat, jadi versi vocab verbanya adalah terjerat. Inilah saat sesuatu terjerat dengan sendirinya (Anda tidak melakukan keterikatan secara langsung). Anda dapat mengingat ini karena む, yaitu Anda mengatakan minggir (む), saya harus mengurus kekacauan keterikatan yang terjadi dengan sendirinya.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menjerat, jadi versi vocab verbanya adalah terjerat. Inilah saat sesuatu terjerat dengan sendirinya (Anda tidak melakukan keterikatan secara langsung). Anda dapat mengingat ini karena む, yaitu Anda mengatakan minggir (む), saya harus mengurus kekacauan keterikatan yang terjadi dengan sendirinya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fba79324-61e7-47c0-9e7d-f48960d1e993', 'Terjerat', true) ON CONFLICT DO NOTHING;
