INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fba79324-61e7-47c0-9e7d-f48960d1e993', 'からむ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fba79324-61e7-47c0-9e7d-f48960d1e993', 'よっぱらって絡んでくるやつが大きらいなんだよ。', 'Aku benci orang yang mabuk lalu berkelahi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fba79324-61e7-47c0-9e7d-f48960d1e993', 'かみにボタンが絡んじゃって取れないの。', 'Rambutku kusut di sekitar kancing dan aku tidak bisa mengeluarkannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fba79324-61e7-47c0-9e7d-f48960d1e993', '最悪！ネチャネチャの風船ガムが釣り糸に絡んじゃった！どうやって取ればいいんだろう。', 'Oh tidak! Permen karet yang lengket tersangkut di tali pancingku! Bagaimana cara mengeluarkannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('df080b07-26f0-440a-95a4-e6a939ce41e5', 'vocabulary', '個人', '個人', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kalau dari segi individu... yah, itu pribadi, dan tergantung individunya. Apa pun itu, setiap orang memiliki selera pribadi, jadi pastikan untuk memikirkan hal itu.', 'Kalau dari segi individu... yah, itu pribadi, dan tergantung individunya. Apa pun itu, setiap orang memiliki selera pribadi, jadi pastikan untuk memikirkan hal itu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('df080b07-26f0-440a-95a4-e6a939ce41e5', 'Pribadi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('df080b07-26f0-440a-95a4-e6a939ce41e5', 'Individual', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('df080b07-26f0-440a-95a4-e6a939ce41e5', 'こじん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df080b07-26f0-440a-95a4-e6a939ce41e5', '私個人の意見ですが、ビエトにはいいおよめさんが見つかってほしいです。', 'Ini pendapat pribadi saya, tapi saya berharap Viet menemukan istri yang baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df080b07-26f0-440a-95a4-e6a939ce41e5', 'アメリカ人の国民性なのか個人の問題なのかは分からないけど、コウイチはビールが大好きだよね。', 'Saya tidak tahu apakah itu karena dia orang Amerika, atau hanya dia, tapi Koichi sangat suka bir, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('df080b07-26f0-440a-95a4-e6a939ce41e5', '個人主義と自分勝手の違いがよく分かりません。', 'Saya tidak begitu melihat perbedaan antara menjadi seorang individualis dan sekadar menjadi egois.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'vocabulary', '一個', '一個', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kata ganti 個, yang berarti individu, mengacu pada "sesuatu yang bersifat individual". Ini biasanya merupakan hal yang kecil, jadi digunakan untuk menghitung hal-hal kecil. Kata ini di sini berbicara tentang satu individu. Cara yang lebih baik untuk menerjemahkannya adalah dengan menyebutnya sebagai satu hal kecil.', 'Kata ganti 個, yang berarti individu, mengacu pada "sesuatu yang bersifat individual". Ini biasanya merupakan hal yang kecil, jadi digunakan untuk menghitung hal-hal kecil. Kata ini di sini berbicara tentang satu individu. Cara yang lebih baik untuk menerjemahkannya adalah dengan menyebutnya sebagai satu hal kecil.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'Satu Hal Kecil', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'One Thing', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'One Small Object', false) ON CONFLICT DO NOTHING;
