INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'いっこ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'おく歯に一個、大きな穴が空いているね。', 'Anda punya satu lubang besar di gigi belakang Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'そのイチゴは、一個百円にもかかわらず、飛ぶように売れました。', 'Stroberi itu masing-masing berharga seratus yen, tapi laris manis di pasaran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('adaf3dad-4b0e-4ccf-a55f-a7c77c44aada', 'ビエトはシュークリームがとっても好きなので、毎日少なくとも一個は食べます。', 'Viet sangat menyukai kue krim sehingga dia makan setidaknya satu kue setiap hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0aeb9a8f-514b-4610-ada3-aeda29815158', 'vocabulary', '個室', '個室', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kamar individual khusus untuk Anda adalah kamar pribadi Anda sendiri. Bagus sekali!', 'Kamar individual khusus untuk Anda adalah kamar pribadi Anda sendiri. Bagus sekali!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0aeb9a8f-514b-4610-ada3-aeda29815158', 'Kamar Pribadi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0aeb9a8f-514b-4610-ada3-aeda29815158', 'One''s Own Room', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0aeb9a8f-514b-4610-ada3-aeda29815158', 'こしつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0aeb9a8f-514b-4610-ada3-aeda29815158', '小さい子がいると個室い酒屋の存在はありがたいです。', 'Jika Anda memiliki anak kecil, keberadaan izakaya dengan kamar pribadi sangat diapresiasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0aeb9a8f-514b-4610-ada3-aeda29815158', 'コウイチはシェアハウスで自分の個室がないという生活をもう五年も続けている。', 'Koichi sudah tinggal di rumah bersama tanpa kamar sendiri selama lebih dari lima tahun sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0aeb9a8f-514b-4610-ada3-aeda29815158', '忘年会に個室を予約しました。', 'Saya memesan kamar pribadi untuk pesta akhir tahun kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a79d5ce8-2097-4781-a0d8-2dcc7896c65a', 'vocabulary', '三個', '三個', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Tiga individu adalah tiga hal kecil. Kanji 個 bisa digunakan untuk menghitung benda kecil, seperti ini! Coba nomor lain juga.', 'Tiga individu adalah tiga hal kecil. Kanji 個 bisa digunakan untuk menghitung benda kecil, seperti ini! Coba nomor lain juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a79d5ce8-2097-4781-a0d8-2dcc7896c65a', 'Tiga Hal Kecil', true) ON CONFLICT DO NOTHING;
