INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a79d5ce8-2097-4781-a0d8-2dcc7896c65a', 'さんこ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a79d5ce8-2097-4781-a0d8-2dcc7896c65a', 'コーヒーにはミルクとシロップを三個ずつ入れます。', 'Saya memasukkan tiga cangkir susu dan tiga cangkir sirup ke dalam kopi saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a79d5ce8-2097-4781-a0d8-2dcc7896c65a', '三個入りの石けんを一箱買いました。', 'Saya membeli sekotak sabun yang berisi tiga batang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a79d5ce8-2097-4781-a0d8-2dcc7896c65a', 'チーズバーガー三個と照り焼きバーガー三個とナゲットをいくつか食べたので、今とても気持ちが悪い。', 'Setelah makan tiga burger keju, tiga burger teriyaki, dan beberapa nugget, saya merasa sangat tidak enak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('109b8568-18f8-432e-a9a5-dfdaea0c5610', 'vocabulary', '厚い', '厚い', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari tebal? Juga tebal.', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari tebal? Juga tebal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('109b8568-18f8-432e-a9a5-dfdaea0c5610', 'Tebal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('109b8568-18f8-432e-a9a5-dfdaea0c5610', 'あつい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('109b8568-18f8-432e-a9a5-dfdaea0c5610', 'どうやってこの厚いへいに穴が空いたんだろう。', 'Saya bertanya-tanya bagaimana lubang bisa dibuat di pagar tebal ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('109b8568-18f8-432e-a9a5-dfdaea0c5610', 'トーフグオフィスをおとずれたさい、とても厚いもてなしを受けました。', 'Saat saya berkunjung ke kantor Tofugu, saya mendapat sambutan yang sangat hangat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('109b8568-18f8-432e-a9a5-dfdaea0c5610', 'コウイチは、厚い苔の上で休んでいる病気のミミズを見つけた。', 'Koichi menemukan cacing tanah yang sakit sedang bertumpu pada lumut tebal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4d4fb224-453b-4ee9-80a8-a4182d2796c6', 'vocabulary', '圧力', '圧力', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kekuatan tekanan adalah tekanan. Ini juga bisa menjadi stres.', 'Kekuatan tekanan adalah tekanan. Ini juga bisa menjadi stres.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4d4fb224-453b-4ee9-80a8-a4182d2796c6', 'Tekanan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4d4fb224-453b-4ee9-80a8-a4182d2796c6', 'Stress', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('4d4fb224-453b-4ee9-80a8-a4182d2796c6', 'あつりょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4d4fb224-453b-4ee9-80a8-a4182d2796c6', '圧力なべをばく発させてしまいましたが、幸いケガはありませんでした。', 'Saya membuat pressure cookernya meledak, tapi untungnya saya tidak terluka.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4d4fb224-453b-4ee9-80a8-a4182d2796c6', 'ロケットが大気にとつ入するときの圧力は相当なものだ。', 'Tekanan yang dialami roket saat memasuki atmosfer sangat kuat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4d4fb224-453b-4ee9-80a8-a4182d2796c6', 'ワニカニがベータ版から脱するよう、我々はコウイチに圧力をかけ続けなくてはいけない。', 'Kita harus terus menekan Koichi agar WaniKani keluar dari versi beta.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('361fd4ba-3cfe-4ba9-9ae1-b6dc4484019f', 'vocabulary', '血圧', '血圧', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Periksa tekanan darah Anda. Itu tekanan darahmu.', 'Periksa tekanan darah Anda. Itu tekanan darahmu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('361fd4ba-3cfe-4ba9-9ae1-b6dc4484019f', 'Tekanan Darah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('361fd4ba-3cfe-4ba9-9ae1-b6dc4484019f', 'けつあつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('361fd4ba-3cfe-4ba9-9ae1-b6dc4484019f', 'お互い年だし血圧が上がっちゃうから、もう非難し合うのは止めにしない？', 'Jangan saling menyalahkan karena kita sama-sama sudah tua dan tekanan darah kita mungkin akan naik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('361fd4ba-3cfe-4ba9-9ae1-b6dc4484019f', '低血圧だから朝起きられなくて困っているんです。今日は血圧をはかってもらったら、上が85で下が30でした。コウイチ先生、何とかしてもらえませんか？', 'Saya sulit bangun di pagi hari karena tekanan darah saya rendah. Saat tekanan darah saya diukur hari ini, angkanya 85 per 30. Bisakah Anda melakukan sesuatu untuk saya, Dr. Koichi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('361fd4ba-3cfe-4ba9-9ae1-b6dc4484019f', '血圧の薬を飲んでも血圧が高いままであることを医者に言うと、血圧を抑えるにはストレスを減らすことが重要だよと教えられました。', 'Ketika saya memberi tahu dokter bahwa saya masih menderita tekanan darah tinggi, bahkan setelah mengonsumsi obat tekanan darah, dia memberi tahu saya pentingnya mengurangi stres untuk mengendalikannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9f99a093-f4be-4c02-8de3-ecb552e6bdb6', 'vocabulary', '指圧', '指圧', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Tekanan jari menyenangkan untuk dimiliki. Kalau ada yang menekan jarimu, pijatan macam apa itu? Itu shiatsu.', 'Tekanan jari menyenangkan untuk dimiliki. Kalau ada yang menekan jarimu, pijatan macam apa itu? Itu shiatsu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9f99a093-f4be-4c02-8de3-ecb552e6bdb6', 'Shiatsu', true) ON CONFLICT DO NOTHING;
