INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73304d81-f1fc-4611-a292-4c9d314aa5ed', 'どうやって事こを防ぐかについて、議論する必要があります。', 'Kita perlu mendiskusikan bagaimana mencegah kecelakaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73304d81-f1fc-4611-a292-4c9d314aa5ed', 'ビエト達がてきを防いでいる間に、クリステンはコウイチ王子を日本へにがしました。', 'Saat Viet dan yang lainnya mempertahankan diri dari musuh, Kristen menyuruh Pangeran Koichi melarikan diri ke Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('73304d81-f1fc-4611-a292-4c9d314aa5ed', 'このダウンジャケットは、寒さをとってもよく防いでくれますよ。', 'Jaket bawah ini akan sangat melindungi Anda dari hawa dingin.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b7c923c1-4ce7-46cd-9619-80fe874e4d59', 'vocabulary', '防水', '防水', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Sesuatu yang menghalangi air bersifat kedap air dan kedap air. Waktunya mandi pakai 防水 ponselku...', 'Sesuatu yang menghalangi air bersifat kedap air dan kedap air. Waktunya mandi pakai 防水 ponselku...') ON CONFLICT (id) DO NOTHING;
