INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e5ed80d8-7bdc-4404-90d5-dd9f6e05c77c', 'よぼう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5ed80d8-7bdc-4404-90d5-dd9f6e05c77c', '危機かん理がもっとしっかりしていたら、この事故は事前に予防することができたはずだ。', 'Jika kita memiliki manajemen risiko yang lebih baik, kita akan mampu mencegah kecelakaan ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5ed80d8-7bdc-4404-90d5-dd9f6e05c77c', 'その国に行くなら、事前に必ずマラリア予防の薬を飲んでください。', 'Jika Anda pergi ke negara tersebut, pastikan untuk minum obat untuk mencegah malaria terlebih dahulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e5ed80d8-7bdc-4404-90d5-dd9f6e05c77c', '日本人も十年ごとに破傷風の予防接種を受けるのですか？', 'Apakah orang Jepang juga mendapat vaksinasi tetanus setiap sepuluh tahun?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54b66928-ec7f-46aa-9b3b-667530078952', 'vocabulary', '地震', '地震', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Gempa bumi hanyalah cara lain untuk mengatakan gempa bumi.', 'Gempa bumi hanyalah cara lain untuk mengatakan gempa bumi.') ON CONFLICT (id) DO NOTHING;
