INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54b66928-ec7f-46aa-9b3b-667530078952', '新聞は、政府の地震対さくをはげしく非難しました。', 'Pers mengkritik keras kesiapsiagaan pemerintah terhadap gempa bumi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54b66928-ec7f-46aa-9b3b-667530078952', 'ふだん地震のない所でごくたまに地震が起きると警察に電話してくる人が出る。', 'Ketika gempa bumi terjadi di tempat yang jarang terjadi, beberapa orang memanggil polisi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54b66928-ec7f-46aa-9b3b-667530078952', '「昨夜の地震について話したいんだけど。」「ぜひ聞きたいから話してよ。」', '“Saya ingin berbicara dengan Anda tentang gempa tadi malam.” "Saya akan mendengarkan sepenuhnya apa yang Anda katakan."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('56e753b6-4b43-4ca0-b9cc-7a3cf85fb7e8', 'vocabulary', '震度', '震度', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Derajat gempa adalah cara Anda mengukur gempa.震度 adalah intensitas gempa, besaran gempa AKA, intensitas seismik, atau skala seismik.', 'Derajat gempa adalah cara Anda mengukur gempa.震度 adalah intensitas gempa, besaran gempa AKA, intensitas seismik, atau skala seismik.') ON CONFLICT (id) DO NOTHING;
