INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9742e3a-8f00-4205-9b1a-c9a4884bf36e', 'まだ余震が続いているので、予だんは許されない。', 'Gempa susulan masih terus terjadi sehingga kita perlu berhati-hati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b9742e3a-8f00-4205-9b1a-c9a4884bf36e', '今日は何回ぐらい余震を感じましたか？', 'Berapa kali gempa susulan yang Anda rasakan hari ini?') ON CONFLICT DO NOTHING;
