INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8b91de45-670b-4362-a459-555cb4dc37c8', '会社を首になったら連絡するよ。', 'Saya akan menghubungi Anda setelah saya dipecat.') ON CONFLICT DO NOTHING;
