INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7cf2bbcf-b182-4586-bf05-d1f377b671b9', 'そういう発言がみんなの和を乱しているってこと、気づいてないの？', 'Sadarkah Anda kalau komentar seperti itu mengganggu keharmonisan semua orang?') ON CONFLICT DO NOTHING;
