INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2d519a7d-de1d-4599-b1da-e3485f11927a', '大勢の人の前で話す事に慣れていないので、今からもう手が震えています。', 'I’m not used to speaking in front of crowds, so my hands are already shaking.') ON CONFLICT DO NOTHING;
