INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('619b3dab-44be-4f7a-b1cf-627e935813a9', 'vocabulary', '営む', '営む', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'The kanji means manage, but when you manage something, what are you usually managing? How about a business? So this word means to run a business even though the kanji is manage.', 'The kanji means manage, but when you manage something, what are you usually managing? How about a business? So this word means to run a business even though the kanji is manage.') ON CONFLICT (id) DO NOTHING;
