INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ec9f1989-3656-4cc9-b5e7-2b2b0c872538', 'vocabulary', '営業', '営業', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Managing a business? That''s business!', 'Managing a business? That''s business!') ON CONFLICT (id) DO NOTHING;
