INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0a312d75-58ac-47bf-ade1-ac2465e8bd1d', 'vocabulary', '委員会', '委員会', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Ada anggota komite (委員) yang berkumpul untuk bertemu. Ini adalah panitia itu sendiri.', 'Ada anggota komite (委員) yang berkumpul untuk bertemu. Ini adalah panitia itu sendiri.') ON CONFLICT (id) DO NOTHING;
