INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0a312d75-58ac-47bf-ade1-ac2465e8bd1d', 'いい加減、委員会での重要な問題に対して意見をころころ変えるのをやめてくれないか。みんなにいい迷惑だよ。', 'Sebaiknya berhenti jungkir balik soal hal-hal penting di panitia, itu tidak bertanggung jawab. Semua orang menganggapnya menjengkelkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fba2b09d-11fa-40d2-b27f-f2c3440c8a26', 'vocabulary', '領収書', '領収書', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Saya memperoleh suatu wilayah, jadi saya ingin catatan tertulis tentangnya. Bagaimana saya mendapatkan catatan tertulis mengenai wilayah yang saya peroleh? Bagaimana dengan kwitansi? Mengirim email ke seseorang sudah cukup.', 'Saya memperoleh suatu wilayah, jadi saya ingin catatan tertulis tentangnya. Bagaimana saya mendapatkan catatan tertulis mengenai wilayah yang saya peroleh? Bagaimana dengan kwitansi? Mengirim email ke seseorang sudah cukup.') ON CONFLICT (id) DO NOTHING;
