INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4b9a8486-8a47-43f8-a17e-727a70dd3986', 'ビエト財務省国際局次長は現在ダイエット中であり、砂糖の代わりにサッカリンを用いているため、彼の食事には砂糖を使用しないでください。', 'Pak Viet, Wakil Direktur Jenderal Senior, Biro Internasional, Kementerian Keuangan, saat ini sedang melakukan diet dan mengganti gula dengan sakarin, jadi jangan gunakan gula dalam makanannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6ea3664f-7395-483b-a5c0-779bbb1c2166', 'vocabulary', '総理府', '総理府', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Pemerintahan perdana menteri (総理) adalah tempat dia menjalankan semua pemerintahannya. Di situlah kantor Perdana Menteri juga berada.', 'Pemerintahan perdana menteri (総理) adalah tempat dia menjalankan semua pemerintahannya. Di situlah kantor Perdana Menteri juga berada.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('6ea3664f-7395-483b-a5c0-779bbb1c2166', 'Kantor Perdana Menteri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('6ea3664f-7395-483b-a5c0-779bbb1c2166', 'そうりふ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6ea3664f-7395-483b-a5c0-779bbb1c2166', '彼女のことについては、総理府で働いているという以外には何も知らなかった。', 'Saya tidak tahu apa-apa tentang dia kecuali dia bekerja di kantor perdana menteri.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fb62e47c-7aba-43e4-b860-3dcd6ac48cbc', 'vocabulary', '営業中', '営業中', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', '営業 artinya menjalankan bisnis. Anda sedang menjalankan bisnis, artinya Anda terbuka untuk bisnis (jika tidak, Anda tidak akan berada di tengah-tengah menjalankannya, Anda akan berada di awal atau semacamnya).', '営業 artinya menjalankan bisnis. Anda sedang menjalankan bisnis, artinya Anda terbuka untuk bisnis (jika tidak, Anda tidak akan berada di tengah-tengah menjalankannya, Anda akan berada di awal atau semacamnya).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fb62e47c-7aba-43e4-b860-3dcd6ac48cbc', 'Terbuka Untuk Bisnis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fb62e47c-7aba-43e4-b860-3dcd6ac48cbc', 'えいぎょうちゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb62e47c-7aba-43e4-b860-3dcd6ac48cbc', '営業中に電話しないでって言ったじゃない。', 'Saya meminta Anda untuk tidak menelepon saya saat toko buka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('13e9ba74-523a-4763-b986-e778ba9e9c75', 'vocabulary', '劇団', '劇団', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Grup drama adalah rombongan drama atau rombongan teater.', 'Grup drama adalah rombongan drama atau rombongan teater.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('13e9ba74-523a-4763-b986-e778ba9e9c75', 'Rombongan Drama', true) ON CONFLICT DO NOTHING;
