INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('13e9ba74-523a-4763-b986-e778ba9e9c75', 'げきだん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('13e9ba74-523a-4763-b986-e778ba9e9c75', '練習の後、劇団員はみんな汗だくだった。', 'Semua anggota rombongan drama berkeringat setelah latihan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('13e9ba74-523a-4763-b986-e778ba9e9c75', '劇団四季に入るのが私の目標です。', 'Tujuan saya adalah bergabung dengan Perusahaan Teater Shiki.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('13e9ba74-523a-4763-b986-e778ba9e9c75', 'ドラマでとある劇団に所属する俳優を好きになってから、彼の出演する舞台を観に劇場にまで足を運ぶようになりました。', 'Aku mulai menyukai seorang aktor yang tergabung dalam grup teater saat menonton drama, jadi aku mulai pergi ke teater untuk menonton pertunjukannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a212a120-879a-497a-ba53-a7dff2a22ccb', 'vocabulary', '震える', '震える', 2, '0f9a4b1c-2d3e-4f5a-6b7c-8d9e0f1a2b3c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti gempa bumi, jadi kata kerjanya berarti menggigil dan gemetar, seperti yang Anda lakukan jika saat ini sedang terjadi gempa bumi.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti gempa bumi, jadi kata kerjanya berarti menggigil dan gemetar, seperti yang Anda lakukan jika saat ini sedang terjadi gempa bumi.') ON CONFLICT (id) DO NOTHING;
