INSERT INTO public.vocabulary_kanjis (vocabulary_id, kanji_id) VALUES ('a258c567-3516-47df-9a02-bd788d7411c3', 'd6803321-b40c-424f-b874-144f68047112') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('90a643cc-ec6d-4d83-9ab4-7fecc5a57af6', 'radical', '亭', 'restaurant', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Anda melihat tutup di jalan dengan gambar dahi dan mulut di atasnya. Hmm aneh. Anda membuka tutupnya dan mengungkap... sebuah restoran rahasia bawah tanah! Kombo mulut + dahi adalah kode rahasia restoran jalanan untuk, "Ada makanan enak di lubang restoran ini!"') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('90a643cc-ec6d-4d83-9ab4-7fecc5a57af6', 'Restoran', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('a0b068ff-ffe6-4df1-9904-ee17fa68c130', 'radical', '道', 'road', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Radikal ini sama dengan kanji. Artinya jalan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a0b068ff-ffe6-4df1-9904-ee17fa68c130', 'Jalan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('adc55493-a45a-42cc-b99a-d4fe2e592f10', 'radical', '旦', 'dawn', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Matahari terbit dari bawah tanah, membuat fajar yang radikal ini. Tentu saja, jangan bingung membedakannya dengan senja! Hal itu bisa dilakukan dengan berpikir bahwa matahari adalah sesuatu yang optimis dan cerah, sehingga cenderung terbit, bukan terbenam. (Juga, Jepang adalah Negeri Matahari Terbit. Maksudku, ayolah!)') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('adc55493-a45a-42cc-b99a-d4fe2e592f10', 'Fajar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('fee111b6-1c96-40a1-b716-e068273d2a22', 'radical', '客', 'guest', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Radikal ini sama dengan kanji. Artinya tamu.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fee111b6-1c96-40a1-b716-e068273d2a22', 'Tamu', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('03342944-8017-4d3c-9c80-efb3ac685708', 'radical', '[death-star]', 'death-star', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Ada topi yang menutupi bulan dan memegang pisau. Tunggu, itu bukan bulan. Itu adalah stasiun luar angkasa! Itu adalah Bintang Kematian! Itu berpura-pura menjadi bulan di bawah topi itu. Dan itu bersenjata! Jangan biarkan Death Star menusuk planet Anda sampai mati.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('03342944-8017-4d3c-9c80-efb3ac685708', 'Bintang Kematian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('f8232b11-caad-4980-b0cc-201135810d04', 'radical', '然', 'nature', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Radikal ini sama dengan kanji. Artinya alam.') ON CONFLICT (id) DO NOTHING;
