INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c655bd4c-0bde-4fbe-ba65-56b6d5f8f020', 'vocabulary', '規律', '規律', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Hukum standar adalah aturan atau hukum yang harus Anda ikuti. Dengan hukum standar ini muncullah disiplin. Jika Anda tidak memilikinya maka akan terjadi kekacauan!', 'Hukum standar adalah aturan atau hukum yang harus Anda ikuti. Dengan hukum standar ini muncullah disiplin. Jika Anda tidak memilikinya maka akan terjadi kekacauan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c655bd4c-0bde-4fbe-ba65-56b6d5f8f020', 'Aturan', true) ON CONFLICT DO NOTHING;
