INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5a98a407-45d3-4315-997e-30f15fc6633b', '学校では日本語でしか話してはいけないという不文律のようなものがあります。', 'Ada semacam peraturan tidak tertulis yang mengatakan bahwa orang hanya diperbolehkan berbicara bahasa Jepang di sekolah ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8f7c975a-0878-4edc-908b-d10295f90a2b', 'vocabulary', '反則', '反則', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Anti aturan adalah ketika Anda melanggar aturan. Saat itulah Anda melakukan pelanggaran.', 'Anti aturan adalah ketika Anda melanggar aturan. Saat itulah Anda melakukan pelanggaran.') ON CONFLICT (id) DO NOTHING;
