INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f7c975a-0878-4edc-908b-d10295f90a2b', 'つけ睫毛を付けるなんて反則だよ。ほとんど別人みたいじゃないか。', 'Mengenakan bulu mata palsu tidaklah adil. Tidakkah menurutmu kamu hampir terlihat seperti orang yang berbeda?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a7b1c70b-4920-4664-bf14-0a116ae24d01', 'vocabulary', '法則', '法則', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Itu adalah hukum dan aturan. Ini biasanya mengacu pada sesuatu yang merupakan hukum fisik, tetapi juga bisa menjadi hukum. Pokoknya banyak aturan. Banyak hukum. Itu dua-duanya, jadi yang lebih kuat (hukum) diutamakan.', 'Itu adalah hukum dan aturan. Ini biasanya mengacu pada sesuatu yang merupakan hukum fisik, tetapi juga bisa menjadi hukum. Pokoknya banyak aturan. Banyak hukum. Itu dua-duanya, jadi yang lebih kuat (hukum) diutamakan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a7b1c70b-4920-4664-bf14-0a116ae24d01', 'Hukum Fisika', true) ON CONFLICT DO NOTHING;
