INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c6ca2693-a76f-44c8-a472-afb32831e8d2', 'じゅんび', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c6ca2693-a76f-44c8-a472-afb32831e8d2', 'おはよう。朝ご飯の準備ができてるわよ。', 'Selamat pagi, sarapanmu sudah siap!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bcfcb5d9-113d-4dc8-afed-e9f5a1b07668', 'vocabulary', '導く', '導く', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memimpin jadi versi vocab verbanya adalah memimpin.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya memimpin jadi versi vocab verbanya adalah memimpin.') ON CONFLICT (id) DO NOTHING;
