INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ff7dfcc5-ea92-44de-a030-b4cd48345442', 'あんたの乳首から血が噴き出しているのを見て、思わずパニクッちゃったよ！', 'Ketika saya melihat semua darah muncrat dari puting Anda, saya panik!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f2160e1-ec5f-41b8-975c-25819fd009ce', 'vocabulary', '城', '城', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
