INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7f2160e1-ec5f-41b8-975c-25819fd009ce', 'もし宝くじが当たったら、裏庭に自分のお城を建てるね。', 'Jika saya memenangkan lotre, saya akan membangun kastil saya sendiri di halaman belakang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('371e8c5e-e706-4cb2-aa75-dbe3c1c7d29b', 'vocabulary', '可燃ゴミ', '可燃ゴミ', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Kemungkinan untuk membakar ゴミ (sampah). Ini adalah sampah yang bisa dibakar.', 'Kemungkinan untuk membakar ゴミ (sampah). Ini adalah sampah yang bisa dibakar.') ON CONFLICT (id) DO NOTHING;
