INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('43a94b83-417b-4707-9afe-320d0651223a', 'vocabulary', '祝う', '祝う', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya merayakan, jadi versi vocab verbanya adalah merayakan. Saat Anda membakar kata ini, Anda harus 祝う!', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya merayakan, jadi versi vocab verbanya adalah merayakan. Saat Anda membakar kata ini, Anda harus 祝う!') ON CONFLICT (id) DO NOTHING;
