INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('43a94b83-417b-4707-9afe-320d0651223a', '日曜日におじいちゃんの還暦を祝うために、中華を食べに行きます。', 'Kami akan pergi ke restoran Cina untuk merayakan ulang tahun kakek yang ke-60 pada hari Minggu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f710e673-2842-4536-9637-4f706cc24a81', 'vocabulary', '祝日', '祝日', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Hari perayaan adalah hari di mana Anda berangkat untuk merayakan sesuatu yang luar biasa. Lebih spesifiknya, ini dikenal sebagai hari libur nasional atau hari libur umum. Festivus untuk restivusnya!', 'Hari perayaan adalah hari di mana Anda berangkat untuk merayakan sesuatu yang luar biasa. Lebih spesifiknya, ini dikenal sebagai hari libur nasional atau hari libur umum. Festivus untuk restivusnya!') ON CONFLICT (id) DO NOTHING;
