INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f710e673-2842-4536-9637-4f706cc24a81', 'コウイチは祝日はいつもかなり派手な格好をしている。', 'Koichi selalu mengenakan pakaian paling mencolok di hari libur.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3d645ddd-a6ee-4d02-9635-4283dca72966', 'vocabulary', '届く', '届く', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menyampaikan jadi versi vocab verbanya disini adalah diantar atau tiba. Kamu tahu yang ini "akan diantar" (alias baru saja diantar, kamu tidak melakukan pengantaran) karena saat barang ini sampai di rumahmu kamu bilang "coo''" (く), barangnya sudah sampai.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menyampaikan jadi versi vocab verbanya disini adalah diantar atau tiba. Kamu tahu yang ini "akan diantar" (alias baru saja diantar, kamu tidak melakukan pengantaran) karena saat barang ini sampai di rumahmu kamu bilang "coo''" (く), barangnya sudah sampai.') ON CONFLICT (id) DO NOTHING;
