INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bcbafcea-49df-464c-baf1-19d55eed200a', '定量オーバーですよ。', 'Itu sudah melebihi jumlah yang ditentukan.') ON CONFLICT DO NOTHING;
