INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e9b9cc5d-bf12-44bc-9762-81e4bda2867e', 'vocabulary', '国境', '国境', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Batas negara adalah batas negara negara tersebut. Berhati-hatilah saat melintasinya jika Anda membawa pisang. Polisi perbatasan sepertinya benci jika Anda memberi tahu mereka bahwa Anda membawa pisang di celana, padahal mereka bertanya apakah Anda akan membawa buah-buahan kembali. Tidak tahu kenapa.', 'Batas negara adalah batas negara negara tersebut. Berhati-hatilah saat melintasinya jika Anda membawa pisang. Polisi perbatasan sepertinya benci jika Anda memberi tahu mereka bahwa Anda membawa pisang di celana, padahal mereka bertanya apakah Anda akan membawa buah-buahan kembali. Tidak tahu kenapa.') ON CONFLICT (id) DO NOTHING;
