INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf48b377-78f5-4423-891d-f0e4cd883c9a', 'vocabulary', '武道', '武道', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Jika Anda mengambil jalan militer, Anda harus banyak berjuang. Dahulu, ini melibatkan pembelajaran seni bela diri untuk bertarung. Ingat, waxing saja.', 'Jika Anda mengambil jalan militer, Anda harus banyak berjuang. Dahulu, ini melibatkan pembelajaran seni bela diri untuk bertarung. Ingat, waxing saja.') ON CONFLICT (id) DO NOTHING;
