INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee9fe940-9ed0-480e-9c1d-908095af7225', '革命家になりたければ、まずは効果的な話し方を身につけないといけないよ。', 'Jika Anda ingin menjadi seorang revolusioner, pertama-tama Anda harus mampu berbicara secara efektif.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee9fe940-9ed0-480e-9c1d-908095af7225', '彼女は情熱的なフランス人革命家と恋に落ちた。', 'Dia jatuh cinta dengan seorang revolusioner Perancis yang bersemangat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3fa858ae-af76-4837-b1f4-088a56f76318', 'vocabulary', '革ジャン', '革ジャン', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', '革 terbuat dari kulit dan ジャン adalah kependekan dari ジャンパー (Jumper, seperti jaket). Jadi, satukan semuanya dan Anda akan mendapatkan jaket kulit.', '革 terbuat dari kulit dan ジャン adalah kependekan dari ジャンパー (Jumper, seperti jaket). Jadi, satukan semuanya dan Anda akan mendapatkan jaket kulit.') ON CONFLICT (id) DO NOTHING;
