INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3fa858ae-af76-4837-b1f4-088a56f76318', 'お洒落大好き人間にアドバイスされたってだけで、あんな高い革ジャンは買うわけないじゃん。', 'Saya tidak akan membeli jaket kulit semahal itu hanya karena seorang fashionista menyuruh saya melakukannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('23e8c825-c003-46b3-85e3-173e295098e5', 'vocabulary', '気象庁', '気象庁', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Badan Fenomena Energi terdengar seperti sesuatu yang sangat keren, tetapi sebenarnya itu hanyalah badan cuaca/badan meteorologi. Tidak ada hal mencurigakan yang terjadi di sini.', 'Badan Fenomena Energi terdengar seperti sesuatu yang sangat keren, tetapi sebenarnya itu hanyalah badan cuaca/badan meteorologi. Tidak ada hal mencurigakan yang terjadi di sini.') ON CONFLICT (id) DO NOTHING;
