INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('63c9fa99-9a82-4790-ada3-dd9f32e8b470', 'vocabulary', '額', '額', 2, '1a0b5c2d-3e4f-5a6b-7c8d-9e0f1a2b3c4d', 'Anda sebelumnya mempelajari kanji ini dengan tiga arti berbeda. Dalam bentuk kosa kata, itu hanya memiliki salah satu arti berikut, gambar berbingkai! Demikian pula, ini bisa berarti gambar atau bingkai juga.', 'Anda sebelumnya mempelajari kanji ini dengan tiga arti berbeda. Dalam bentuk kosa kata, itu hanya memiliki salah satu arti berikut, gambar berbingkai! Demikian pula, ini bisa berarti gambar atau bingkai juga.') ON CONFLICT (id) DO NOTHING;
