INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8bb15646-ec0f-4c36-b492-93ecbefda443', 'vocabulary', '状況', '状況', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Kondisi kondisi adalah kondisi. Itu juga keadaannya jika kamu bisa mengingatnya. Ini seperti mengatakan "Apa kondisinya!??" yang mirip dengan mengatakan "Bagaimana situasinya?"', 'Kondisi kondisi adalah kondisi. Itu juga keadaannya jika kamu bisa mengingatnya. Ini seperti mengatakan "Apa kondisinya!??" yang mirip dengan mengatakan "Bagaimana situasinya?"') ON CONFLICT (id) DO NOTHING;
