INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8bb15646-ec0f-4c36-b492-93ecbefda443', 'しっかりしろよ。状況はお前が思っているほど悪くないみたいだぜ。', 'Dapatkan pegangan! Situasinya tidak seburuk yang Anda kira.') ON CONFLICT DO NOTHING;
