INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8236053-e759-43ef-a73f-178313f2f835', 'vocabulary', '記述', '記述', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Tulis dan sebutkan apa yang terjadi. Saat Anda melakukan ini, Anda sedang menulis deskripsi dan penjelasan tentang apa yang terjadi.', 'Tulis dan sebutkan apa yang terjadi. Saat Anda melakukan ini, Anda sedang menulis deskripsi dan penjelasan tentang apa yang terjadi.') ON CONFLICT (id) DO NOTHING;
