INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9d288df-60d8-49c0-8c3d-8e86c3ef535c', '上述のように、雇用者、従業員のどちらも、いついかなる理由においても契約を終了することができる。', 'Sebagaimana dinyatakan di atas, baik pekerja maupun pemberi kerja dapat memutuskan kontrak kerja kapan saja dengan alasan apa pun.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fe634aca-78fe-4dbf-b085-356da50847e2', 'vocabulary', '販売', '販売', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Jual, jual, jual. Sikap inilah yang Anda butuhkan jika Anda ingin bekerja di bidang penjualan atau melakukan penjualan. Anda harus bekerja pada penjualan Anda.', 'Jual, jual, jual. Sikap inilah yang Anda butuhkan jika Anda ingin bekerja di bidang penjualan atau melakukan penjualan. Anda harus bekerja pada penjualan Anda.') ON CONFLICT (id) DO NOTHING;
