INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fe634aca-78fe-4dbf-b085-356da50847e2', '我が社の販売員の多くは、八月に休暇を取ります。', 'Banyak tenaga penjualan di perusahaan kami mengambil cuti kerja di bulan Agustus.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('54e38364-7532-49ca-aded-958262d065e7', 'vocabulary', '自動販売機', '自動販売機', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Mesin jual jual otomatis (自動). Pada dasarnya, mesin itu menjual barang dengan sendirinya. Ini adalah mesin penjual otomatis. Ada versi yang lebih pendek, tapi ada baiknya mempelajari yang panjang dulu :)', 'Mesin jual jual otomatis (自動). Pada dasarnya, mesin itu menjual barang dengan sendirinya. Ini adalah mesin penjual otomatis. Ada versi yang lebih pendek, tapi ada baiknya mempelajari yang panjang dulu :)') ON CONFLICT (id) DO NOTHING;
