INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('54e38364-7532-49ca-aded-958262d065e7', '10月23日の自動販売機に関する会議は、コウイチの誕生日会のため、10月24日に変更されました。', 'Pertemuan tanggal dua puluh tiga Oktober tentang mesin penjual otomatis telah dijadwalkan ulang ke tanggal dua puluh empat Oktober karena pesta ulang tahun Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf591152-e390-4379-bac8-b021318df3fe', 'vocabulary', '通販', '通販', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Barang-barang yang Anda jual yang melewati dunia untuk sampai ke Anda mungkin merupakan pesanan lewat pos. Anda memesannya dan mereka diperbesar ke arah Anda, melewati semua jenis ruang untuk sampai di depan pintu Anda.', 'Barang-barang yang Anda jual yang melewati dunia untuk sampai ke Anda mungkin merupakan pesanan lewat pos. Anda memesannya dan mereka diperbesar ke arah Anda, melewati semua jenis ruang untuk sampai di depan pintu Anda.') ON CONFLICT (id) DO NOTHING;
