INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f4cb685-fb35-40a2-905a-fc66f9a6a913', 'vocabulary', '不況', '不況', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Sebuah "kondisi tidak" adalah ketika tidak ada yang berjalan dengan baik. Bagaimana kabarnya? Tidak baik. Kondisinya buruk. Kita berada dalam resesi.', 'Sebuah "kondisi tidak" adalah ketika tidak ada yang berjalan dengan baik. Bagaimana kabarnya? Tidak baik. Kondisinya buruk. Kita berada dalam resesi.') ON CONFLICT (id) DO NOTHING;
