INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d14b8601-f9a8-4663-b030-467c9fdb55d4', 'vocabulary', '景況', '景況', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Lihatlah pemandangan ini dan kondisinya. Ini adalah iklim dari situasi tersebut, namun lebih khusus lagi adalah iklim bisnis. Kata ini sebenarnya hanya digunakan untuk membicarakan keadaan bisnis dan perekonomian, dan cenderung muncul dalam tulisan teknis.', 'Lihatlah pemandangan ini dan kondisinya. Ini adalah iklim dari situasi tersebut, namun lebih khusus lagi adalah iklim bisnis. Kata ini sebenarnya hanya digunakan untuk membicarakan keadaan bisnis dan perekonomian, dan cenderung muncul dalam tulisan teknis.') ON CONFLICT (id) DO NOTHING;
