INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('35c9d62e-2094-4196-a6d9-2af3b605121f', 'vocabulary', '候補者', '候補者', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Kandidat adalah seseorang yang merupakan pelengkap dari keseluruhan sistem politik. Meski hanya pelengkap, mereka tetaplah kandidat, kecuali mereka bisa menang!', 'Kandidat adalah seseorang yang merupakan pelengkap dari keseluruhan sistem politik. Meski hanya pelengkap, mereka tetaplah kandidat, kecuali mereka bisa menang!') ON CONFLICT (id) DO NOTHING;
