INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('35c9d62e-2094-4196-a6d9-2af3b605121f', '学歴的には、候補者として十分通用するはずが、彼は性格に難があるからね。', 'Secara akademis, kandidat tersebut akan sangat berguna, tetapi dia memiliki kepribadian yang buruk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9e924dae-df49-4ee7-bd5e-d8aaaf706d8a', 'vocabulary', '効く', '効く', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya efektif. Versi kosakata kata kerjanya adalah menjadi efektif (karena "menjadi efektif" tidak masuk akal).', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya efektif. Versi kosakata kata kerjanya adalah menjadi efektif (karena "menjadi efektif" tidak masuk akal).') ON CONFLICT (id) DO NOTHING;
