INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7e2d3913-91c4-43fc-8eb1-105689183efc', 'vocabulary', '効力', '効力', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Kekuatan efektif sesuatu adalah efektivitasnya. Jika mempunyai kekuatan efektif, maka tetap berlaku.', 'Kekuatan efektif sesuatu adalah efektivitasnya. Jika mempunyai kekuatan efektif, maka tetap berlaku.') ON CONFLICT (id) DO NOTHING;
