INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e2d3913-91c4-43fc-8eb1-105689183efc', 'あなたの今日のプレゼンテーションは、前回に比べて効力が少し弱いような気がしました。', 'Presentasi Anda hari ini sepertinya efektivitasnya sedikit lebih lemah dibandingkan presentasi sebelumnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('098fab94-91e5-45e5-8eb5-ba412019def0', 'vocabulary', '豊か', '豊か', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Ini sama dengan kanji 豊, membuatnya banyak. Bisa juga berarti kaya atau kaya.', 'Ini sama dengan kanji 豊, membuatnya banyak. Bisa juga berarti kaya atau kaya.') ON CONFLICT (id) DO NOTHING;
