INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('098fab94-91e5-45e5-8eb5-ba412019def0', '80年前と比べると、日本は本当に豊かになりました。', 'Dibandingkan dengan 80 tahun yang lalu, Jepang telah menjadi sangat kaya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('098fab94-91e5-45e5-8eb5-ba412019def0', '九州は自然が豊かな所です。', 'Kyushu adalah tempat yang kaya akan alam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('098fab94-91e5-45e5-8eb5-ba412019def0', '本を読むと心が豊かになりますよ。', 'Membaca buku akan memperkaya pikiran Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3e09ecd0-317c-491c-8d61-04992e2e73ed', 'vocabulary', '豊満', '豊満', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Jika Anda banyak dan kenyang, bisa dibilang Anda montok atau bertubuh penuh... dengan kata lain, Anda bukan camilan, Anda adalah Utuh. Berengsek. Makanan.', 'Jika Anda banyak dan kenyang, bisa dibilang Anda montok atau bertubuh penuh... dengan kata lain, Anda bukan camilan, Anda adalah Utuh. Berengsek. Makanan.') ON CONFLICT (id) DO NOTHING;
