INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('04baa030-8471-4f25-9926-fb6bf5029f27', '二時間かけて髪を巻いたが、それでもあまりうまく巻けなかった。', 'Aku menghabiskan dua jam mengeriting rambutku, tapi tetap saja tidak bisa dikeriting dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d4a15cc-8c4b-4cae-b286-833f0801eade', 'vocabulary', '一巻', '一巻', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Satu gulungan adalah satu gulungan di masa lalu, tetapi sekarang mengacu pada buku dan berarti satu volume.', 'Satu gulungan adalah satu gulungan di masa lalu, tetapi sekarang mengacu pada buku dan berarti satu volume.') ON CONFLICT (id) DO NOTHING;
