INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bf0b71f0-1ffb-4a4e-a922-34a1a5704cb9', 'vocabulary', '下巻', '下巻', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Gulungan di bawah adalah gulungan terakhir yang Anda baca, menjadikannya volume terakhir.', 'Gulungan di bawah adalah gulungan terakhir yang Anda baca, menjadikannya volume terakhir.') ON CONFLICT (id) DO NOTHING;
