INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf0b71f0-1ffb-4a4e-a922-34a1a5704cb9', '上巻を買ったつもりが下巻を買ってしまっていた。', 'Kukira aku membeli jilid pertama, tapi sebenarnya itu jilid terakhir.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('93c07e5d-1b39-469f-9361-06a1e2bf7573', 'vocabulary', '上巻', '上巻', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Scroll di atas adalah scroll paling atas, yang pertama kali Anda baca. Ini jilid pertama. Banyak buku Jepang yang tersedia dalam beberapa bagian, jadi carilah ini jika Anda ingin mendapatkan yang pertama.', 'Scroll di atas adalah scroll paling atas, yang pertama kali Anda baca. Ini jilid pertama. Banyak buku Jepang yang tersedia dalam beberapa bagian, jadi carilah ini jika Anda ingin mendapatkan yang pertama.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('93c07e5d-1b39-469f-9361-06a1e2bf7573', 'Jilid Pertama', true) ON CONFLICT DO NOTHING;
