INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('121783ff-616c-4b81-94ba-3a7764b869c5', 'vocabulary', '捜す', '捜す', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mencari, jadi versi vocab verbanya adalah mencari atau mencari.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mencari, jadi versi vocab verbanya adalah mencari atau mencari.') ON CONFLICT (id) DO NOTHING;
