INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('72fd3e96-3751-43f9-bf9c-bf7ce29e6982', 'vocabulary', '捜査', '捜査', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Saat Anda menggeledah dan memeriksa sesuatu, Anda mungkin menjadi bagian dari investigasi kriminal. Anda bahkan mungkin menjadi sasaran perburuan.', 'Saat Anda menggeledah dan memeriksa sesuatu, Anda mungkin menjadi bagian dari investigasi kriminal. Anda bahkan mungkin menjadi sasaran perburuan.') ON CONFLICT (id) DO NOTHING;
