INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a2ebdb10-254d-4b0c-8b61-51358ff06fff', 'vocabulary', '再来月', '再来月', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Bulan depan (来月) tidaklah cukup... satu bulan lagi, tolong. Ayo lakukan lagi. Bulan itu adalah bulan berikutnya.', 'Bulan depan (来月) tidaklah cukup... satu bulan lagi, tolong. Ayo lakukan lagi. Bulan itu adalah bulan berikutnya.') ON CONFLICT (id) DO NOTHING;
