INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1cf5d955-6075-4449-ab23-ac9c177df01f', 'vocabulary', '再来年', '再来年', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Anda punya tahun depan (来年), tapi kemudian Anda punya tahun lagi. Itu tahun berikutnya.', 'Anda punya tahun depan (来年), tapi kemudian Anda punya tahun lagi. Itu tahun berikutnya.') ON CONFLICT (id) DO NOTHING;
