INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ba81e4fa-0ed0-4597-9bb0-847dc9408963', 'vocabulary', '面接', '面接', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Wajah kami telah menyatu dalam satu ruangan ini untuk berbicara. Anda melakukan wawancara telepon di mana Anda tidak menunjukkan wajah Anda. Sekarang Anda menunjukkannya, jadi kita bisa memulai wawancara sebenarnya.', 'Wajah kami telah menyatu dalam satu ruangan ini untuk berbicara. Anda melakukan wawancara telepon di mana Anda tidak menunjukkan wajah Anda. Sekarang Anda menunjukkannya, jadi kita bisa memulai wawancara sebenarnya.') ON CONFLICT (id) DO NOTHING;
