INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5761b26c-7fc0-4430-bff2-addd2a360a21', 'vocabulary', '河童', '河童', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Remaja sungai... tidak seperti yang Anda pikirkan. Itu adalah kappa, makhluk mitologi Jepang. Meskipun demikian, ia hidup di/sekitar sungai dan berukuran sebesar remaja, jadi mungkin ini masuk akal.', 'Remaja sungai... tidak seperti yang Anda pikirkan. Itu adalah kappa, makhluk mitologi Jepang. Meskipun demikian, ia hidup di/sekitar sungai dan berukuran sebesar remaja, jadi mungkin ini masuk akal.') ON CONFLICT (id) DO NOTHING;
