INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9b3a3e45-1f6d-4387-ae6c-570ed3924a18', 'vocabulary', '氷河', '氷河', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Sungai es adalah es yang bergerak (sangat lambat) seperti sungai. Itu adalah gletser. Faktanya, banyak lubang masuk dan suara tercipta dari gletser, karena gletser bergerak melaluinya seperti sungai... namun tidak terlalu cepat.', 'Sungai es adalah es yang bergerak (sangat lambat) seperti sungai. Itu adalah gletser. Faktanya, banyak lubang masuk dan suara tercipta dari gletser, karena gletser bergerak melaluinya seperti sungai... namun tidak terlalu cepat.') ON CONFLICT (id) DO NOTHING;
