INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ea8838e-6dc6-4c1a-b9dc-f8f897ee7df0', '小さい頃、お菓子の家に住むことが夢でした。', 'Ketika saya masih kecil, impian saya adalah tinggal di rumah yang terbuat dari permen.') ON CONFLICT DO NOTHING;
