INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ac695aa-808a-4b7d-bce4-30735373baf6', 'vocabulary', '自販機', '自販機', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Ingat mesin penjual otomatis super panjang yaitu 自動販売機? Ini adalah versi lebih pendek yang lebih mudah diingat dan diucapkan. Pada dasarnya setiap kanji lainnya dihilangkan, menjadikannya 自販機.', 'Ingat mesin penjual otomatis super panjang yaitu 自動販売機? Ini adalah versi lebih pendek yang lebih mudah diingat dan diucapkan. Pada dasarnya setiap kanji lainnya dihilangkan, menjadikannya 自販機.') ON CONFLICT (id) DO NOTHING;
