INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('28493f21-e1f6-4290-9dd9-315e97730f8c', 'vocabulary', '限定販売', '限定販売', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Penjualan (販売) sesuatu mempunyai batas (限定). Barang semacam ini adalah salah satu edisi terbatas.', 'Penjualan (販売) sesuatu mempunyai batas (限定). Barang semacam ini adalah salah satu edisi terbatas.') ON CONFLICT (id) DO NOTHING;
