INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('96298efa-140b-4e97-b731-be56440d89a9', '「どうしたの？何を悩んでいるの？」「昨日、彼女に振られたんだ。」', '"Hei! Apa yang mengganggumu?" "Pacarku mencampakkanku tadi malam."') ON CONFLICT DO NOTHING;
