INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2951fe7e-b728-4cd8-a6fe-50f0eb01809e', 'vocabulary', '昇進', '昇進', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Naik dan maju! Selamat, Anda naik dan maju dengan mendapatkan promosi pekerjaan baru.', 'Naik dan maju! Selamat, Anda naik dan maju dengan mendapatkan promosi pekerjaan baru.') ON CONFLICT (id) DO NOTHING;
