INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2951fe7e-b728-4cd8-a6fe-50f0eb01809e', '「聞いて聞いて、昇進したんだ！」「本当？すごいね！おめでとう！」', '"Coba tebak? Aku mendapat promosi di tempat kerja!" "Benarkah? Luar biasa! Selamat!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('77e22754-f84d-47d6-b36f-ac9b3ca401c7', 'vocabulary', '両替', '両替', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Saya dapat mengganti kedua uang Anda dengan uang lain di penukaran uang ini. Saya juga bisa membuat perubahan untuk Anda, jika Anda mau. Anda mungkin akan paling sering melihat kata ini di Arkade tempat Anda bisa pergi ke mesin 両替 dan mendapatkan koin untuk memenuhi kecanduan penangkap UFO Anda.', 'Saya dapat mengganti kedua uang Anda dengan uang lain di penukaran uang ini. Saya juga bisa membuat perubahan untuk Anda, jika Anda mau. Anda mungkin akan paling sering melihat kata ini di Arkade tempat Anda bisa pergi ke mesin 両替 dan mendapatkan koin untuk memenuhi kecanduan penangkap UFO Anda.') ON CONFLICT (id) DO NOTHING;
