INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fbb288dc-6a42-4ba9-b92d-96ef4cffdb6c', 'vocabulary', '濃度', '濃度', 2, '2b1c6d3e-4f5a-6b7c-8d9e-0f1a2b3c4d5e', 'Derajat kepadatan manusia di suatu daerah akan menunjukkan jumlah penduduknya. Tingkat ketebalan manusia yang lebih tinggi = lebih banyak orang. Tingkat ketebalan manusia yang lebih rendah = lebih sedikit orang. Yaitu kepadatan penduduk suatu wilayah, atau konsentrasi penduduk.', 'Derajat kepadatan manusia di suatu daerah akan menunjukkan jumlah penduduknya. Tingkat ketebalan manusia yang lebih tinggi = lebih banyak orang. Tingkat ketebalan manusia yang lebih rendah = lebih sedikit orang. Yaitu kepadatan penduduk suatu wilayah, atau konsentrasi penduduk.') ON CONFLICT (id) DO NOTHING;
