INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('fab122c4-9edc-48c9-a7d8-3fb0a66adb43', 'radical', '屯', 'barracks', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Anda menempelkan payung dengan perosotan besar ke lereng gunung untuk membuat barak Anda. Anda akan menggunakan barak ini untuk mengajari tentara cara meluncur dan bersembunyi dari cuaca buruk. Itu cerdik!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fab122c4-9edc-48c9-a7d8-3fb0a66adb43', 'Barak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1f155289-f074-439f-b324-40de0c191279', 'radical', '巨', 'giant', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Jika Anda melihat raksasa dari atas, inilah yang akan Anda lihat. Apakah Anda melihat kepala dan kedua lengan? Raksasa itu menghadap ke arah kanan.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1f155289-f074-439f-b324-40de0c191279', 'Raksasa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('be6a11ca-de63-4b36-bd7c-c3ea475a69e5', 'radical', '[morning]', 'morning', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Ini adalah sisi kiri kanji 朝, jadi kita sebut saja pagi juga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('be6a11ca-de63-4b36-bd7c-c3ea475a69e5', 'Pagi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('836e5eed-0cc1-4338-a548-8cbe23d97154', 'radical', '乙', 'nose', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Jika Anda melihat ke kanan radikal ini, Anda akan melihat HIDUNG (dengan mata sipit di sebelah kiri).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('836e5eed-0cc1-4338-a548-8cbe23d97154', 'Hidung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7ba196fd-84a0-4cb6-be1f-db97dc341e15', 'radical', '区', 'district', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Radikal ini sama dengan kanji. Artinya distrik.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ba196fd-84a0-4cb6-be1f-db97dc341e15', 'Distrik', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('a47cce38-5d17-4d0c-abe0-a1795733bcea', 'radical', '臣', 'servant', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Hei, itu raksasa yang kamu pelajari sebelumnya. Tapi... tapi lengannya dirantai. Mereka dirantai karena kamu menangkap raksasa itu dan sekarang dia menjadi pelayanmu!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a47cce38-5d17-4d0c-abe0-a1795733bcea', 'Hamba', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4aa587be-187b-4ba1-8643-d3730805a00a', 'radical', '吉', 'good-luck', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Ini adalah samurai radikal di atas mulut radikal. Jika Anda mendengar apa yang dikatakan seorang samurai, Anda akan sangat beruntung. Samurai cukup sulit ditemukan saat ini, mungkin itulah sebabnya nasibku sangat buruk...') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4aa587be-187b-4ba1-8643-d3730805a00a', 'Semoga Sukses', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('40578822-de6a-40f0-8234-d33b2dd36277', 'radical', '片', 'one-sided', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Ini terlihat seperti seorang pelayan yang berjalan ke arah Anda dengan piring di tangannya... tapi tunggu. Itu hanya setengah dari seorang pelayan. Itu adalah pelayan satu sisi!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('40578822-de6a-40f0-8234-d33b2dd36277', 'Satu Sisi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7764168f-f9cb-4f79-bfaf-59e686735a30', 'radical', '扁', 'library', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Ada pintu di atas rak buku. Itu menjadikan ini perpustakaan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7764168f-f9cb-4f79-bfaf-59e686735a30', 'Perpustakaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3bdd2a84-31e1-41b1-9662-7798d5318c1d', 'radical', '並', 'line-up', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Radikal ini sama dengan kanji. Artinya berbaris.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3bdd2a84-31e1-41b1-9662-7798d5318c1d', 'Berbaris', true) ON CONFLICT DO NOTHING;
