INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('21fac9c1-448c-4596-8f35-1a14bef4d2a5', 'vocabulary', '巨大', '巨大', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Sesuatu yang sangat besar adalah sesuatu yang sangat besar dan raksasa.', 'Sesuatu yang sangat besar adalah sesuatu yang sangat besar dan raksasa.') ON CONFLICT (id) DO NOTHING;
