INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('21fac9c1-448c-4596-8f35-1a14bef4d2a5', '彼はとっても忙しい巨大企業の社長さんなんだから、アポの約束は絶対に早目に取っておいた方がいいよ。', 'Saya sangat menyarankan agar Anda menjadwalkan janji temu dengannya jauh-jauh hari karena dia adalah presiden sebuah perusahaan besar dan dia sangat, sangat sibuk.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('528d2e91-c27f-47cf-892f-49a29a2c812d', 'vocabulary', '巨人', '巨人', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Manusia raksasa adalah raksasa.', 'Manusia raksasa adalah raksasa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('528d2e91-c27f-47cf-892f-49a29a2c812d', 'Raksasa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('528d2e91-c27f-47cf-892f-49a29a2c812d', 'Giant', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('528d2e91-c27f-47cf-892f-49a29a2c812d', 'きょじん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('528d2e91-c27f-47cf-892f-49a29a2c812d', 'ある巨人が別の巨人をヘッドロックで締めつけているのを見ました。', 'Saya melihat seekor raksasa mencengkeram kepala lainnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('528d2e91-c27f-47cf-892f-49a29a2c812d', 'あいつは巨人だが、胃弱体質だ。', 'Dia raksasa, tapi perutnya lemah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('528d2e91-c27f-47cf-892f-49a29a2c812d', '「何してるの？」「俺達、進撃の巨人を見てるんだよ。って、あぁ、しまった。最後の字幕見逃しちゃった。ちょっと巻き戻してくれない？」', '"Apa yang sedang kalian lakukan?" "Kami sedang menonton Attack on Titan. Ups. Saya benar-benar melewatkan subtitle terakhir. Bisakah Anda memundurkannya sedikit?"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8c751371-4d16-42b7-b487-7fd43522b27b', 'vocabulary', '究極', '究極', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Anda mencoba meneliti hal-hal ekstrem. Jika kamu melakukan itu, kamu akan bisa mengetahui senjata pamungkasnya. Hanya meneliti hal-hal yang aman di tengah-tengah tidak akan membuat Anda menjadi yang terbaik. Namun, penelitian ekstrem akan berhasil.', 'Anda mencoba meneliti hal-hal ekstrem. Jika kamu melakukan itu, kamu akan bisa mengetahui senjata pamungkasnya. Hanya meneliti hal-hal yang aman di tengah-tengah tidak akan membuat Anda menjadi yang terbaik. Namun, penelitian ekstrem akan berhasil.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8c751371-4d16-42b7-b487-7fd43522b27b', 'Terakhir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8c751371-4d16-42b7-b487-7fd43522b27b', 'きゅうきょく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8c751371-4d16-42b7-b487-7fd43522b27b', 'あの榊氏までもが、私が宇宙の究極の原理を解明したことに祝いの言葉を述べてくれました。', 'Bahkan Pak Sakaki mengucapkan selamat kepada saya karena telah menemukan kebenaran mendasar alam semesta.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('baedc5eb-b286-4b16-b3fa-b89a0fd42220', 'vocabulary', '極める', '極める', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya ekstrim. Versi kosakata kata kerjanya tidak "terlalu ekstrim" karena itu tidak masuk akal. Sebaliknya, Anda membawanya secara ekstrem, membuat kata ini diterapkan secara ekstrem, atau dikuasai.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya ekstrim. Versi kosakata kata kerjanya tidak "terlalu ekstrim" karena itu tidak masuk akal. Sebaliknya, Anda membawanya secara ekstrem, membuat kata ini diterapkan secara ekstrem, atau dikuasai.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('baedc5eb-b286-4b16-b3fa-b89a0fd42220', 'Untuk Melakukan Ekstrem', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('baedc5eb-b286-4b16-b3fa-b89a0fd42220', 'To Master', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('baedc5eb-b286-4b16-b3fa-b89a0fd42220', 'きわめる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('baedc5eb-b286-4b16-b3fa-b89a0fd42220', '日本語を極めるのは、生易しい事ではない。', 'Menguasai bahasa Jepang bukanlah tugas yang mudah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('baedc5eb-b286-4b16-b3fa-b89a0fd42220', '法律関係の職に就いて法律を極めることが夢でしたが、それよりも仕事で多忙を極めることになりました。', 'Impian saya adalah memasuki profesi hukum dan menguasai hukum, namun saya menjadi sangat sibuk dengan pekerjaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5c21a4e1-8433-4fd2-8adc-d4fdefb336eb', 'vocabulary', '極楽', '極楽', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Tempat ini memiliki kenyamanan yang luar biasa. Ini adalah surga.', 'Tempat ini memiliki kenyamanan yang luar biasa. Ini adalah surga.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5c21a4e1-8433-4fd2-8adc-d4fdefb336eb', 'Surga', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5c21a4e1-8433-4fd2-8adc-d4fdefb336eb', 'ごくらく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5c21a4e1-8433-4fd2-8adc-d4fdefb336eb', '間違いで極楽に行った男についての小説が、映画化されました。', 'Novel tentang seorang pria yang masuk surga secara tidak sengaja diangkat menjadi film.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f65947da-8ade-4670-810e-97333a4d2464', 'vocabulary', '南極', '南極', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Bagian paling selatan adalah bagian paling selatan. Jaraknya sejauh mungkin ke selatan. Tempat itu dikenal sebagai Antartika.', 'Bagian paling selatan adalah bagian paling selatan. Jaraknya sejauh mungkin ke selatan. Tempat itu dikenal sebagai Antartika.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f65947da-8ade-4670-810e-97333a4d2464', 'Antartika', true) ON CONFLICT DO NOTHING;
