INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d8ccf5df-3519-41c4-83c5-df232df84b88', 'vocabulary', '並ぶ', '並ぶ', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbaris jadi versi vocab verbanya adalah berbaris. Kamu tahu ini adalah versi di mana segala sesuatunya hanya berbaris (kamu tidak mengantri) karena kamu terus mengatakan boo (ぶ), kenapa semua orang sudah mengantri? Harusnya aku sudah sampai di sini lebih awal supaya tidak perlu menunggu (kalau kamu yang antri sendiri, kamu akan menempatkan dirimu di depan, ya).', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berbaris jadi versi vocab verbanya adalah berbaris. Kamu tahu ini adalah versi di mana segala sesuatunya hanya berbaris (kamu tidak mengantri) karena kamu terus mengatakan boo (ぶ), kenapa semua orang sudah mengantri? Harusnya aku sudah sampai di sini lebih awal supaya tidak perlu menunggu (kalau kamu yang antri sendiri, kamu akan menempatkan dirimu di depan, ya).') ON CONFLICT (id) DO NOTHING;
