INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('313ade86-547d-4106-bb47-100b1794ad40', '「昨日、幼年時代の友人に偶然会ったの。彼には何年も会っていなかったんだけど。」「そう言えば、サーモンって、幼年時代の友人のフグと結婚したのよね。」', '“Aku bertemu dengan teman masa kecilku kemarin. Aku sudah bertahun-tahun tidak melihatnya.” “Omong-omong, Salmon menikah dengan teman masa kecilnya, Fugu.”') ON CONFLICT DO NOTHING;
