INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b5076389-9a61-42ab-9a47-78c0e9f50e0a', 'vocabulary', '移住者', '移住者', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Seseorang yang harus berpindah tempat tinggal adalah seseorang yang memindahkan rumahnya (dan dalam hal ini) ke negara lain. Mereka adalah seorang emigran/imigran. Selamat datang di negara ini, kawan!', 'Seseorang yang harus berpindah tempat tinggal adalah seseorang yang memindahkan rumahnya (dan dalam hal ini) ke negara lain. Mereka adalah seorang emigran/imigran. Selamat datang di negara ini, kawan!') ON CONFLICT (id) DO NOTHING;
