INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('437870de-7230-462a-a95a-16cec3a1a1eb', '私はホットドッグのことが好きで、逆もまた同じ。こないだ夢であるホットドッグに’好きだ’ってちゃっかり言われちゃったんだから。', 'Saya suka hotdog, dan juga berlaku sebaliknya. Aku diberitahu oleh seekor hotdog bahwa mereka sangat menyukaiku malam itu dalam mimpiku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b78feca1-6753-4293-a99e-8cb4d6afd855', 'vocabulary', '逆効果', '逆効果', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', '効果 adalah "efek", jadi kebalikan dari efek tersebut adalah efek sebaliknya. Ups!', '効果 adalah "efek", jadi kebalikan dari efek tersebut adalah efek sebaliknya. Ups!') ON CONFLICT (id) DO NOTHING;
