INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0f61f15-c69c-4eeb-8bb2-45962a72e1d7', '時代精神に逆らうのは難しい。', 'Sulit untuk melawan semangat zaman.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0f61f15-c69c-4eeb-8bb2-45962a72e1d7', 'フグは流れに逆らって川を上って行くサーモンに感動を覚えた。', 'Fugu terkesan dengan ikan salmon yang berenang di sungai melawan arus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0f61f15-c69c-4eeb-8bb2-45962a72e1d7', '「うわ！お前目のとこに青たんできてるじゃん。」「そうなんだよ。昨日の夜お袋に逆らったら、こてんぱに殴られてさ。」', '"Wow! Ada memar di atas matamu." "Ya, aku tidak menaati ibuku tadi malam dan membuatku diusir."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('38166bcf-4a8a-4b79-8029-f613df4d1ce2', 'vocabulary', '逆説', '逆説', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Ini kebalikan dari teori! Apa yang sedang terjadi? Ada yang tidak beres. Pasti ada semacam paradoks yang terjadi, di mana semua teori dibalik! D:', 'Ini kebalikan dari teori! Apa yang sedang terjadi? Ada yang tidak beres. Pasti ada semacam paradoks yang terjadi, di mana semua teori dibalik! D:') ON CONFLICT (id) DO NOTHING;
