INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('955529d0-8570-48c5-b310-601e62e7cabb', 'vocabulary', '見極める', '見極める', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', '極める berarti "melakukan hal yang ekstrem." Jika Anda mengambil tindakan untuk melihat sesuatu yang ekstrem, Anda akan memahami apa pun itu. Anda akan dapat mengidentifikasi sesuatu, seperti kebenaran.', '極める berarti "melakukan hal yang ekstrem." Jika Anda mengambil tindakan untuk melihat sesuatu yang ekstrem, Anda akan memahami apa pun itu. Anda akan dapat mengidentifikasi sesuatu, seperti kebenaran.') ON CONFLICT (id) DO NOTHING;
