INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2487cae6-7a04-4f72-a458-25205d00b2a5', 'vocabulary', '略す', '略す', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya singkatan, jadi versi vocab verbanya adalah menyingkat atau menghilangkan.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya singkatan, jadi versi vocab verbanya adalah menyingkat atau menghilangkan.') ON CONFLICT (id) DO NOTHING;
