INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2487cae6-7a04-4f72-a458-25205d00b2a5', '日本の若者はすぐ単語やフレーズを略したがる。', 'Anak muda Jepang cenderung menyingkat kata dan frasa.') ON CONFLICT DO NOTHING;
