INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2487cae6-7a04-4f72-a458-25205d00b2a5', '略して話されても部外者の私には何のことか全然分かりません。', 'Sebagai orang luar, saya tidak mengerti apa yang Anda bicarakan ketika Anda berbicara dalam bentuk singkatan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('363ef91a-32cb-4a42-bba3-70d3f663b19d', 'vocabulary', '省略', '省略', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Simpan huruf-huruf itu dengan singkatan dan itu... sebuah singkatan! Dengan menggunakan kelalaian Anda dapat menyingkat kata tersebut menjadi kata yang lebih kecil.', 'Simpan huruf-huruf itu dengan singkatan dan itu... sebuah singkatan! Dengan menggunakan kelalaian Anda dapat menyingkat kata tersebut menjadi kata yang lebih kecil.') ON CONFLICT (id) DO NOTHING;
