INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cffbbef2-ae85-460f-9d39-968f2f0de786', 'vocabulary', '略図', '略図', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Versi singkatan dari sebuah diagram bukanlah diagram yang lengkap, juga bukan diagram yang menghabiskan banyak waktu Anda. Itu versi singkatnya, jadi lebih mirip sketsa kasar atau peta kasar.', 'Versi singkatan dari sebuah diagram bukanlah diagram yang lengkap, juga bukan diagram yang menghabiskan banyak waktu Anda. Itu versi singkatnya, jadi lebih mirip sketsa kasar atau peta kasar.') ON CONFLICT (id) DO NOTHING;
