INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cffbbef2-ae85-460f-9d39-968f2f0de786', 'あなたの家からうちまでの略図を書いて、メールでお送りします。', 'Saya akan menggambar peta kasar dari rumah Anda ke rumah saya dan mengirimkannya melalui email kepada Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cffbbef2-ae85-460f-9d39-968f2f0de786', 'あなたが書いた略図のメモをちょっと見せてもらえませんか？', 'Bolehkah Anda mengizinkan saya melihat sketsa memo kasar yang Anda buat?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cffbbef2-ae85-460f-9d39-968f2f0de786', '略図を書いたのはいいんですが、略しすぎて自分でもよく分からなくなってしまいました。', 'Saya menggambar sketsa kasar, tetapi saya menghilangkan terlalu banyak dan sekarang saya sendiri tidak dapat memahaminya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cabd9b2b-2ea8-447f-bada-e0cc20382090', 'vocabulary', '大略', '大略', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Singkatan besar adalah tempat Anda mengambil semuanya dan menyingkatnya untuk menampilkan gambaran besarnya. Singkatan ini merupakan rangkuman atau garis besar dari sesuatu yang lebih besar.', 'Singkatan besar adalah tempat Anda mengambil semuanya dan menyingkatnya untuk menampilkan gambaran besarnya. Singkatan ini merupakan rangkuman atau garis besar dari sesuatu yang lebih besar.') ON CONFLICT (id) DO NOTHING;
