INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cabd9b2b-2ea8-447f-bada-e0cc20382090', 'まずは事件の大略を説明してくれないか？', 'Bisa dijelaskan dulu garis besar kejadiannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6dcb21d7-50a4-454a-8b8a-1c43da5b35be', 'vocabulary', '大臣', '大臣', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Seorang pelayan besar lebih besar dari pelayan lainnya. Salah satu jenis pelayan adalah orang yang melayani masyarakat (seperti halnya yang satu ini). Seorang pelayan besar adalah seseorang yang berkedudukan tinggi dalam bidang melayani rakyat. Jadi, sebut saja pelayan besar ini sebagai menteri atau anggota kabinet. Keju besar.', 'Seorang pelayan besar lebih besar dari pelayan lainnya. Salah satu jenis pelayan adalah orang yang melayani masyarakat (seperti halnya yang satu ini). Seorang pelayan besar adalah seseorang yang berkedudukan tinggi dalam bidang melayani rakyat. Jadi, sebut saja pelayan besar ini sebagai menteri atau anggota kabinet. Keju besar.') ON CONFLICT (id) DO NOTHING;
