INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ba0094d1-8c5b-4808-9b89-15d49c1a89dd', 'vocabulary', '直航', '直航', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Ingat bagaimana 直行 adalah "nonstop"? Nah, dengan 直航 sama saja, tapi hanya digunakan untuk penerbangan dan perjalanan perahu, menjadikannya penerbangan nonstop atau pelayaran langsung.', 'Ingat bagaimana 直行 adalah "nonstop"? Nah, dengan 直航 sama saja, tapi hanya digunakan untuk penerbangan dan perjalanan perahu, menjadikannya penerbangan nonstop atau pelayaran langsung.') ON CONFLICT (id) DO NOTHING;
