INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('59f1625e-0225-4c13-bbb8-623a6044adbc', 'お弁当にご飯を詰めといてくれない？', 'Bisakah kamu memasukkan nasi ke dalam kotak bento untukku?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5de0d439-d2ba-494e-a7c4-e0f9c9591f05', 'vocabulary', '詰まる', '詰まる', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya diisi. Kata kosakatanya adalah diisi, seperti ada sesuatu yang diisi dan Anda tidak mengisinya. Anda mengetahui hal ini karena jika menyangkut まる si kucing, dia memasukkan dirinya sendiri ke dalam kotak, jadi Anda tidak perlu memasukkannya ke dalam kotak untuknya. Itu terjadi begitu saja, dan Anda dapat menonton dan terhibur (tentu saja Anda perlu menonton beberapa video Maru jika Anda belum ada di YouTube, katakan saja).', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya diisi. Kata kosakatanya adalah diisi, seperti ada sesuatu yang diisi dan Anda tidak mengisinya. Anda mengetahui hal ini karena jika menyangkut まる si kucing, dia memasukkan dirinya sendiri ke dalam kotak, jadi Anda tidak perlu memasukkannya ke dalam kotak untuknya. Itu terjadi begitu saja, dan Anda dapat menonton dan terhibur (tentu saja Anda perlu menonton beberapa video Maru jika Anda belum ada di YouTube, katakan saja).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5de0d439-d2ba-494e-a7c4-e0f9c9591f05', 'Untuk Diisi', true) ON CONFLICT DO NOTHING;
