INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('90371fa9-be28-4087-bd06-1efc065e45c5', 'vocabulary', '外務大臣', '外務大臣', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Menteri tugas luar negeri (大臣) adalah seseorang yang bertugas menangani hal-hal yang berada di luar negeri. Ini adalah menteri luar negeri.', 'Menteri tugas luar negeri (大臣) adalah seseorang yang bertugas menangani hal-hal yang berada di luar negeri. Ini adalah menteri luar negeri.') ON CONFLICT (id) DO NOTHING;
