INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('90371fa9-be28-4087-bd06-1efc065e45c5', 'とにかく、手短に言うとね、フグと僕は外務大臣について口論をして、それ以来、僕は彼に会っていないんだ。', 'Singkat cerita, Fugu dan saya bertengkar tentang Menteri Luar Negeri dan saya tidak bertemu dengannya lagi sejak itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d028e8cb-c590-440f-8190-287aa5a0401e', 'vocabulary', '総理大臣', '総理大臣', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Menteri "perdana menteri" (総理) adalah kata lengkap untuk perdana menteri.', 'Menteri "perdana menteri" (総理) adalah kata lengkap untuk perdana menteri.') ON CONFLICT (id) DO NOTHING;
