INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d028e8cb-c590-440f-8190-287aa5a0401e', 'ぼくのおじいちゃんは昔、総理大臣だったんだって。', 'Saya mendengar bahwa kakek saya pernah menjadi perdana menteri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d028e8cb-c590-440f-8190-287aa5a0401e', '政治家のキャリア40年にしてようやく総理大臣にまで登りつめました。', 'Setelah empat puluh tahun berkarir di dunia politik, saya akhirnya menjadi perdana menteri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d028e8cb-c590-440f-8190-287aa5a0401e', 'よぉみんな！コウイチ総理大臣がここに登場だぜ！チェケラ！', 'Hai kalian semua. Perdana Menteri Koichi ada di rumah, yo! Coba lihat!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ce3d71e0-e0e8-43d2-ae00-57e8b834cf03', 'vocabulary', '移る', '移る', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri berarti pergeseran dan versi vocab verbanya adalah bergeser. Kamu tahu kalau di sinilah ada sesuatu yang digeser (dan kamu tidak melakukan perpindahan itu), karena itu sangat tidak sopan (る) untuk digeser, dan kamu tidak suka kalau orang lain melakukan itu padamu (karena anehnya hal itu sering terjadi).', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri berarti pergeseran dan versi vocab verbanya adalah bergeser. Kamu tahu kalau di sinilah ada sesuatu yang digeser (dan kamu tidak melakukan perpindahan itu), karena itu sangat tidak sopan (る) untuk digeser, dan kamu tidak suka kalau orang lain melakukan itu padamu (karena anehnya hal itu sering terjadi).') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ce3d71e0-e0e8-43d2-ae00-57e8b834cf03', 'Akan Digeser', true) ON CONFLICT DO NOTHING;
