INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ce3d71e0-e0e8-43d2-ae00-57e8b834cf03', '臭いが服に移るから、焼肉は好きじゃないの。', 'Saya tidak suka barbekyu Korea karena baunya menyengat pakaian Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('58f096b3-a338-4684-8c67-3898b3cda7f5', 'vocabulary', '出版する', '出版する', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Jika 出版 adalah penerbitan, maka versi kosakata kata kerjanya adalah menerbitkan.', 'Jika 出版 adalah penerbitan, maka versi kosakata kata kerjanya adalah menerbitkan.') ON CONFLICT (id) DO NOTHING;
