INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('58f096b3-a338-4684-8c67-3898b3cda7f5', '彼は有名な小説家だが、時々自費出版することもあるんだよ。', 'Meskipun ia seorang penulis fiksi terkenal, ia terkadang menerbitkan sendiri bukunya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f4af27dc-08f8-41a7-88e4-37f41a933cd2', 'vocabulary', '出版社', '出版社', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Jika 出版 berarti penerbitan, maka perusahaan yang melakukan penerbitan tersebut adalah perusahaan penerbitan.', 'Jika 出版 berarti penerbitan, maka perusahaan yang melakukan penerbitan tersebut adalah perusahaan penerbitan.') ON CONFLICT (id) DO NOTHING;
