INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f4af27dc-08f8-41a7-88e4-37f41a933cd2', 'その出版社では、入館の際に身分証明書を提示しなければなりません。', 'Anda harus menunjukkan kartu identitas Anda untuk masuk ke perusahaan penerbitan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eef43e0f-f481-43a8-97a5-4c9d787b437a', 'vocabulary', '照り焼き', '照り焼き', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Anda menerangi dan kemudian memanggang makanan. Untuk meneranginya, Anda menaruh saus yang mengkilat. Lalu, kamu memasaknya. Terdengar familiar, dari segi jenis makanannya? Ini teriyaki, meskipun saya harus memperingatkan Anda bahwa ini sangat berbeda dari apa yang Anda dapatkan di "toko teriyaki" di barat.', 'Anda menerangi dan kemudian memanggang makanan. Untuk meneranginya, Anda menaruh saus yang mengkilat. Lalu, kamu memasaknya. Terdengar familiar, dari segi jenis makanannya? Ini teriyaki, meskipun saya harus memperingatkan Anda bahwa ini sangat berbeda dari apa yang Anda dapatkan di "toko teriyaki" di barat.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('eef43e0f-f481-43a8-97a5-4c9d787b437a', 'Teriyaki', true) ON CONFLICT DO NOTHING;
