INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('eef43e0f-f481-43a8-97a5-4c9d787b437a', '「コウイチ、忘れ物は無い？」「無いよ。」「あ、ちょっと待って。あんたのお弁当に照り焼きサーモン入れるの忘れてたわ。」「ええっ！母さん、早くしてよ。」', '"Apakah kamu punya segalanya, Koichi?" "Ya, Bu." "Oh, tunggu. Aku lupa memasukkan salmon teriyaki ke dalam kotak bentomu." "Apa! Cepat, Bu!"') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('059a2a0b-3b3f-4edf-9727-876c826190d9', 'vocabulary', '延長する', '延長する', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Jika 延長 memanjang, maka versi kata kerjanya adalah memanjang.', 'Jika 延長 memanjang, maka versi kata kerjanya adalah memanjang.') ON CONFLICT (id) DO NOTHING;
