INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('98c5490b-7aa3-4c87-b5cb-d0fdcaf64dba', '今オフィスで資料の要約を編集しているところよ。', 'Saya sedang mengedit ringkasan dokumen di kantor sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f6daef18-0e0c-49e1-aa50-73c173d8c777', 'vocabulary', '乾かす', '乾かす', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', '乾く adalah "untuk dikeringkan." Ini adalah versi di mana Anda melakukan pengeringan, menjadikannya mengeringkan sesuatu.', '乾く adalah "untuk dikeringkan." Ini adalah versi di mana Anda melakukan pengeringan, menjadikannya mengeringkan sesuatu.') ON CONFLICT (id) DO NOTHING;
