INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f6daef18-0e0c-49e1-aa50-73c173d8c777', 'あなたを愛しています。僕にはあなたが必要なんです。太陽さん、どうか僕の濡れたシャツを今すぐ乾かしてくれませんか？お願いします！！！', 'Aku sangat mencintaimu. aku membutuhkanmu. Bisakah Anda mengeringkan baju saya yang basah sekarang, Tuan Sun? Silakan!!!!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0a5b16e8-8a24-40bd-a37a-d6eb57e368d0', 'vocabulary', '詰め込む', '詰め込む', 2, '3c2d7e4f-5a6b-7c8d-9e0f-1a2b3c4d5e6f', 'Anda tahu bahwa 詰める berarti "memasukkan barang" dan 込む berarti "menjadi ramai". Jadi saat kamu mengisi sesuatu dan memadatinya, kamu akan mengisi atau menjejalkannya.', 'Anda tahu bahwa 詰める berarti "memasukkan barang" dan 込む berarti "menjadi ramai". Jadi saat kamu mengisi sesuatu dan memadatinya, kamu akan mengisi atau menjejalkannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0a5b16e8-8a24-40bd-a37a-d6eb57e368d0', 'Untuk Mengisi', true) ON CONFLICT DO NOTHING;
