INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3e71e706-23ea-4379-af46-ad23ab7153c9', 'radical', '系', 'lineage', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Seutas benang menembus tanah. Ini menelusuri garis keturunan Anda. Anda mengikuti alur cerita ini dari generasi ke generasi, untuk mengetahui bahwa garis keturunan Anda melibatkan Jenghis Khan. Rasakan benang dan kotoran di tangan Anda dan lacak garis keturunannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3e71e706-23ea-4379-af46-ad23ab7153c9', 'Silsilah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7d687fe2-3e38-44af-8ec2-5e6ed2e6e8d4', 'radical', '夜', 'night', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Radikal ini sama dengan kanji. Artinya malam.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7d687fe2-3e38-44af-8ec2-5e6ed2e6e8d4', 'Malam', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('25d62f12-8680-43d1-be21-f84d28347218', 'radical', '舎', 'cottage', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Radikal ini tampak seperti sebuah rumah kecil, yang sempurna di antah berantah, dikelilingi bambu dan aliran sungai kecil di pegunungan. Lihat atap dan pintu yang terbuka? Itu sebabnya ini adalah pondok radikal.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('25d62f12-8680-43d1-be21-f84d28347218', 'Pondok', true) ON CONFLICT DO NOTHING;
