INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('31d76474-7c56-4da9-8ec6-bd70cfc98d03', 'vocabulary', '久しい', '久しい', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Ini adalah kanji tunggal dengan しい di akhir, artinya merupakan kata sifat. Apa bentuk kata sifat dari waktu yang lama? Ya, itu sudah lama sekali, atau bisa berarti sudah lama sekali.', 'Ini adalah kanji tunggal dengan しい di akhir, artinya merupakan kata sifat. Apa bentuk kata sifat dari waktu yang lama? Ya, itu sudah lama sekali, atau bisa berarti sudah lama sekali.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('31d76474-7c56-4da9-8ec6-bd70cfc98d03', 'Dahulu kala', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('31d76474-7c56-4da9-8ec6-bd70cfc98d03', 'For a Long Time', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('31d76474-7c56-4da9-8ec6-bd70cfc98d03', 'ひさしい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('31d76474-7c56-4da9-8ec6-bd70cfc98d03', 'わたしがベーコンをたべなくなって久しい。', 'Sudah lama sekali saya tidak berhenti makan bacon.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('31d76474-7c56-4da9-8ec6-bd70cfc98d03', 'へいわボケして久しい日本人には、おそらくりかいできないだろう。', 'Masyarakat Jepang sudah begitu lama menganggap remeh perdamaian sehingga mereka mungkin tidak dapat memahaminya lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('31d76474-7c56-4da9-8ec6-bd70cfc98d03', 'かれが生のきんぎょをたべてしんでから久しい。', 'Dia makan ikan mas mentah dan sudah lama mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c443c545-f6d9-4b38-a392-f2f14db1b95f', 'vocabulary', '久しぶり', '久しぶり', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Ini semacam "frasa tetap" dalam bahasa Jepang, meskipun di sini kita akan memperlakukannya seperti kata vocab (karena ini sangat umum dan berguna!). Anda tahu bahwa 久 berarti "waktu yang lama" - jadi sekarang mari kita perhatikan kananya: しぶり. Bayangkan saja dia menguburmu hidup-hidup, lalu beberapa hari kemudian datang kembali untuk menggalimu. Hal pertama yang dia katakan adalah "LAMA TIDAK BERLIHAT!"', 'Ini semacam "frasa tetap" dalam bahasa Jepang, meskipun di sini kita akan memperlakukannya seperti kata vocab (karena ini sangat umum dan berguna!). Anda tahu bahwa 久 berarti "waktu yang lama" - jadi sekarang mari kita perhatikan kananya: しぶり. Bayangkan saja dia menguburmu hidup-hidup, lalu beberapa hari kemudian datang kembali untuk menggalimu. Hal pertama yang dia katakan adalah "LAMA TIDAK BERLIHAT!"') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c443c545-f6d9-4b38-a392-f2f14db1b95f', 'Lama Tidak Bertemu', true) ON CONFLICT DO NOTHING;
