INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c443c545-f6d9-4b38-a392-f2f14db1b95f', '久しぶりですね！', 'Lama tak jumpa!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c443c545-f6d9-4b38-a392-f2f14db1b95f', '久しぶりのビールは、なみだが出るほどおいしかった。', 'Bir setelah sekian lama tidak mabuk, rasanya begitu enak hingga membuatku menangis.') ON CONFLICT DO NOTHING;
