INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a20dfd4a-cbed-42aa-8ed3-de0ac8d16588', 'vocabulary', '地帯', '地帯', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Sabuk bumi ini adalah wilayah di dalam sabuk, yang menampung wilayah bumi ini. Terpisah dari wilayah bumi lainnya, sehingga menjadikannya zona atau distrik tersendiri.', 'Sabuk bumi ini adalah wilayah di dalam sabuk, yang menampung wilayah bumi ini. Terpisah dari wilayah bumi lainnya, sehingga menjadikannya zona atau distrik tersendiri.') ON CONFLICT (id) DO NOTHING;
