INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('53969444-ac57-4422-b455-8740155da8cb', 'vocabulary', '自民党', '自民党', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Partai Rakyat Perorangan adalah kelompok politik yang mempercayai setiap individu masyarakat (atau apa?). Terjemahannya tidak terlalu mengisyaratkan makna tersebut, namun kelompok tersebut adalah Partai Demokrat Liberal alias LDP.', 'Partai Rakyat Perorangan adalah kelompok politik yang mempercayai setiap individu masyarakat (atau apa?). Terjemahannya tidak terlalu mengisyaratkan makna tersebut, namun kelompok tersebut adalah Partai Demokrat Liberal alias LDP.') ON CONFLICT (id) DO NOTHING;
