INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('53969444-ac57-4422-b455-8740155da8cb', '我らが自民党が今年は熱いな。もう誰も我々のことを「愚民党」なんて呼ぶことはないだろう。', 'Partai Demokrat Liberal kita sedang menjadi topik hangat tahun ini. Tidak ada lagi yang akan menyebut kami Partai Demokrat Gila.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1202caaa-4d91-4db6-bfa0-73b6b4004c7e', 'vocabulary', '共産党', '共産党', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Gagasan bahwa setiap orang berbagi properti di antara mereka berasal dari pihak mana? Itu adalah Partai Komunis.', 'Gagasan bahwa setiap orang berbagi properti di antara mereka berasal dari pihak mana? Itu adalah Partai Komunis.') ON CONFLICT (id) DO NOTHING;
