INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('66603532-e538-40ba-959e-a9b9da464952', '「卵がかえる前にひなを数えるな」という諺は、日本語では「とらぬ狸の皮算用をするな」です。', 'Pepatah "Jangan hitung ayammu sebelum menetas" adalah "Jangan berasumsi kamu bisa mengambil tanuki" dalam bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('85e9f52c-714c-4ddf-a005-35a62e1ca696', 'vocabulary', '生卵', '生卵', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Ingat bagaimana 生 bisa berarti mentah? Ya, sekarang memang demikian. Jadi, telur mentah? Pertama-tama, enak. Kedua, artinya telur mentah.', 'Ingat bagaimana 生 bisa berarti mentah? Ya, sekarang memang demikian. Jadi, telur mentah? Pertama-tama, enak. Kedua, artinya telur mentah.') ON CONFLICT (id) DO NOTHING;
