INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85e9f52c-714c-4ddf-a005-35a62e1ca696', '「生卵アレルギーはありますか？」「私の知る限りではありません。」', '“Apakah kamu alergi telur mentah?” "Aku tidak mengetahuinya."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('20544a88-52c1-4881-b377-1ce1edf0b508', 'vocabulary', 'ゆで卵', 'ゆで卵', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'ゆ berasal dari 湯, yang berarti "air panas". Jadi "telur air panas" adalah telur rebus.', 'ゆ berasal dari 湯, yang berarti "air panas". Jadi "telur air panas" adalah telur rebus.') ON CONFLICT (id) DO NOTHING;
