INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('20544a88-52c1-4881-b377-1ce1edf0b508', '僕が君のゆで卵を盗んだと思っているのなら、とんだお門違いだよ。', 'Jika Anda mengira saya mencuri telur rebus Anda, Anda salah menggonggong.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7bf66233-1842-42e0-9673-847fd6373c14', 'vocabulary', '捨てる', '捨てる', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membuang, jadi versi verbanya adalah membuang.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membuang, jadi versi verbanya adalah membuang.') ON CONFLICT (id) DO NOTHING;
