INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7bf66233-1842-42e0-9673-847fd6373c14', '私の主人は、たとえ一日でも賞味期限が過ぎていたら捨てるんですよ。', 'Suamiku membuang makanan yang sudah melewati tanggal kesegarannya, padahal hanya satu hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('eb969d96-5b60-4ab8-9b87-cb83c646d22d', 'vocabulary', '汚れる', '汚れる', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya kotor jadi versi vocab verbanya adalah menjadi kotor. Anda tahu bahwa Anda tidak melakukan hal yang kotor, karena (れる) jarang sekali Anda mengotori sesuatu, meskipun segala sesuatunya akan menjadi kotor dengan sendirinya.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya kotor jadi versi vocab verbanya adalah menjadi kotor. Anda tahu bahwa Anda tidak melakukan hal yang kotor, karena (れる) jarang sekali Anda mengotori sesuatu, meskipun segala sesuatunya akan menjadi kotor dengan sendirinya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('eb969d96-5b60-4ab8-9b87-cb83c646d22d', 'Menjadi Kotor', true) ON CONFLICT DO NOTHING;
