INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('012c2433-3484-4fc7-99e4-7eb425619249', '「今朝は4時から起きてるよ。」「嘘でしょ？いったい何してるの？」「えっと…家を大掃除してるの。」', '"Aku sudah bangun sejak jam empat pagi ini." "Tidak mungkin! Apa yang sedang kamu lakukan?" "Yah, hanya membersihkan sekitar rumah."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f16f51c6-f41b-4bd5-9aed-826c7685cb31', 'vocabulary', '複数形', '複数形', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Jika 複数 berlipat ganda, dan 形 berbentuk, maka ketika sesuatu berada dalam "bentuk ganda", ia mempunyai lebih dari satu versinya sendiri. Itu bentuk jamak, atau bentuk jamak.', 'Jika 複数 berlipat ganda, dan 形 berbentuk, maka ketika sesuatu berada dalam "bentuk ganda", ia mempunyai lebih dari satu versinya sendiri. Itu bentuk jamak, atau bentuk jamak.') ON CONFLICT (id) DO NOTHING;
