INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f16f51c6-f41b-4bd5-9aed-826c7685cb31', 'Sheepの複数形はsheepです。', 'Bentuk jamak dari domba adalah domba.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f16f51c6-f41b-4bd5-9aed-826c7685cb31', '「この単語の複数形も知らないの？」って友達に笑われて、とても傷つきました。', 'Teman saya berkata, "Kamu bahkan tidak tahu bentuk jamak dari kata ini?" dan menertawakanku, dan aku sangat terluka.') ON CONFLICT DO NOTHING;
