INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ee381ac4-c508-44d7-a588-b156d6febd61', 'vocabulary', '使い捨て', '使い捨て', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Setelah Anda menggunakannya, Anda membuangnya, sehingga apa pun yang Anda gunakan menjadi barang sekali pakai.', 'Setelah Anda menggunakannya, Anda membuangnya, sehingga apa pun yang Anda gunakan menjadi barang sekali pakai.') ON CONFLICT (id) DO NOTHING;
