INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d99140ea-990c-4f0a-bcf0-cca3788493bc', 'vocabulary', '著作権', '著作権', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', '著作 adalah "menulis" atau "penulis". Hak yang dimiliki oleh sebuah tulisan disebut dengan hak cipta.', '著作 adalah "menulis" atau "penulis". Hak yang dimiliki oleh sebuah tulisan disebut dengan hak cipta.') ON CONFLICT (id) DO NOTHING;
