INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6c8689b3-bf9b-488a-ae9d-d3b7306fb2f1', 'vocabulary', '汚い', '汚い', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Ini adalah bentuk kata sifat dari 汚, yaitu kotor. Kata ini adalah kata sifat kotor, tapi Anda juga bisa menggunakannya untuk mengatakan hal-hal seperti kotor, busuk, atau najis.', 'Ini adalah bentuk kata sifat dari 汚, yaitu kotor. Kata ini adalah kata sifat kotor, tapi Anda juga bisa menggunakannya untuk mengatakan hal-hal seperti kotor, busuk, atau najis.') ON CONFLICT (id) DO NOTHING;
