INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('343dc920-a3fc-42f7-a74b-58b092e8f89b', 'vocabulary', '砂利', '砂利', 2, '4d3e8f5a-6b7c-8d9e-0f1a-2b3c4d5e6f7a', 'Jika pasir menghasilkan banyak keuntungan, maka pasir akan membengkak dan menjadi kerikil. Mereka seperti kucing gemuk di pantai.', 'Jika pasir menghasilkan banyak keuntungan, maka pasir akan membengkak dan menjadi kerikil. Mereka seperti kucing gemuk di pantai.') ON CONFLICT (id) DO NOTHING;
