INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('343dc920-a3fc-42f7-a74b-58b092e8f89b', 'ウラン鉱山はこの砂利道の先にあります。', 'Tambang uranium berada di ujung jalan berkerikil ini.') ON CONFLICT DO NOTHING;
