INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1d4234a9-b5c8-451f-bcfc-b1a1b997c30b', 'radical', '[coral]', 'coral', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Di dalam air ada duri di tanah. Itu karang. Karang mungkin terlihat cantik, tetapi jika Anda terpeleset ke dalam air dan menginjaknya, Anda akan tergores. Hal itu sangat bagus.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1d4234a9-b5c8-451f-bcfc-b1a1b997c30b', 'Karang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('643330c1-b686-49e6-aa75-cd87d6f68860', 'radical', '蔵', 'storehouse', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Bungamu menjadi pelayanmu. Anda menanamnya, Anda menyiraminya, Anda membesarkannya, lalu Anda menebangnya dan menaruhnya di gudang Anda. Mereka melakukan apa yang Anda inginkan karena mereka menjadi hamba ANDA, bukan sebaliknya. Itu sebabnya Anda bisa menyuruh mereka duduk di gudang tempat mereka menunggu sampai Anda datang untuk memakannya.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('643330c1-b686-49e6-aa75-cd87d6f68860', 'Gudang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e208b573-a7b8-4819-b07a-58b9798ff350', 'radical', '衣', 'clothes', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Anda membuka tutup kotak. Di dalam kotak itu ada sekumpulan pakaian. Radikal ini akan sama dengan kanji yang akan Anda pelajari nanti, jadi akan sangat membantu jika mempelajarinya sebagai pakaian meskipun tidak terlihat seperti pakaian.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e208b573-a7b8-4819-b07a-58b9798ff350', 'Pakaian', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('07d8c26f-5b42-4d3f-bb17-86a15280b11d', 'radical', '員', 'member', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Radikal ini sama dengan kanji. Artinya anggota.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('07d8c26f-5b42-4d3f-bb17-86a15280b11d', 'Anggota', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('b19acaab-bb3e-4e62-95eb-2bcbb49d686b', 'radical', '同', 'same', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Radikal ini sama dengan kanji. Artinya sama.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('b19acaab-bb3e-4e62-95eb-2bcbb49d686b', 'Sama', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8a8a63b7-7fc7-46c9-855d-7130d46d8b68', 'radical', '将', 'commander', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Siapa yang memakai cleat dan melakukan pengukuran terlalu lama hingga es mulai terbentuk di tubuh Anda? Komandan Anda. Komandannya sangat, sangat khusus. Dan semua orang tahu bahwa komandan harus melakukan segalanya dengan benar. Jadi melakukan pengukuran membutuhkan waktu SANGAT lama hingga es keluar dari hidung Anda. Tapi tidak apa-apa. Anda harus mengesankan komandan baru Anda, sialan!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8a8a63b7-7fc7-46c9-855d-7130d46d8b68', 'Komandan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('71e81399-4d73-40de-8201-e3d8cc2ddd2d', 'radical', '甘', 'sweet', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Radikal ini adalah matahari dengan rambutnya yang mencuat. Mengapa rambut matahari mencuat seperti ini? Ia memakan terlalu banyak makanan manis yang menyebabkannya memiliki terlalu banyak energi, membuat bulunya berdiri. Bentuknya juga seperti permen yang manis dan manis dengan bungkusnya yang menonjol. Ingatlah sesuai keinginan Anda.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('71e81399-4d73-40de-8201-e3d8cc2ddd2d', 'Manis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8f8508bf-b5d9-4d4c-8892-a99e19776447', 'radical', '尞', 'charcoal', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Saat matahari mulai kecil, Anda perlu memanaskannya dengan melemparkan beberapa tanduk besar ke dalam api. Ini berubah menjadi arang. Arang yang enak dan hangat yang membuat Anda tetap hangat saat matahari mulai terbenam.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8f8508bf-b5d9-4d4c-8892-a99e19776447', 'Arang', true) ON CONFLICT DO NOTHING;
