INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('96fd4917-299e-46f3-b990-bc682879fb0c', 'vocabulary', '蒸れる', '蒸れる', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Jika ada yang mengepul, maka ruangan menjadi lembap, sehingga kata ini menjadi lembab (karena Anda tidak melakukan pelembapan).', 'Jika ada yang mengepul, maka ruangan menjadi lembap, sehingga kata ini menjadi lembab (karena Anda tidak melakukan pelembapan).') ON CONFLICT (id) DO NOTHING;
