INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2d70476b-7798-4db7-80e7-dc5b41629d9a', 'vocabulary', '蒸気', '蒸気', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Energi uap adalah uap atau uap.', 'Energi uap adalah uap atau uap.') ON CONFLICT (id) DO NOTHING;
