INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a8c421c0-da8d-45a9-b891-0f6e5da12f38', 'vocabulary', '蔵', '蔵', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO NOTHING;
