INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6cc03652-67aa-49bd-ab1b-888b0ab8f55f', 'vocabulary', '冷蔵庫', '冷蔵庫', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Gudang penyimpanan yang sejuk adalah tempat Anda menaruh barang-barang (seperti makanan) agar tetap dingin. Ini adalah lemari es.', 'Gudang penyimpanan yang sejuk adalah tempat Anda menaruh barang-barang (seperti makanan) agar tetap dingin. Ini adalah lemari es.') ON CONFLICT (id) DO NOTHING;
