INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6cc03652-67aa-49bd-ab1b-888b0ab8f55f', 'なんでタトゥーで冷蔵庫なんて彫ったの？', 'Mengapa Anda membuat tato bertuliskan kulkas?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('42940a7f-f6ef-4d6b-8614-1fb296872eec', 'vocabulary', '地蔵', '地蔵', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Gudang tanah mengacu pada nama seseorang. Mungkin akan lebih mudah untuk mempelajari bacaan yang satu ini terlebih dahulu karena itu. Bagaimanapun, orang ini adalah Jizo(u), seorang Bodhisattva, dan pelindung anak-anak.', 'Gudang tanah mengacu pada nama seseorang. Mungkin akan lebih mudah untuk mempelajari bacaan yang satu ini terlebih dahulu karena itu. Bagaimanapun, orang ini adalah Jizo(u), seorang Bodhisattva, dan pelindung anak-anak.') ON CONFLICT (id) DO NOTHING;
