INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7f9a7a71-43bf-4304-b200-adc370c2d899', 'vocabulary', '装置', '装置', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Pakaian ini dimasukkan ke dalam peralatan ini, lalu diubah menjadi sesuatu yang lain. Perangkat pakaian ini aneh dan menarik. Bayangkan sesuatu yang berdampak pada pakaian Anda.', 'Pakaian ini dimasukkan ke dalam peralatan ini, lalu diubah menjadi sesuatu yang lain. Perangkat pakaian ini aneh dan menarik. Bayangkan sesuatu yang berdampak pada pakaian Anda.') ON CONFLICT (id) DO NOTHING;
