INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('952a4869-010b-47e1-b204-c67611388069', 'vocabulary', '変装', '変装', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Ubah pakaian Anda agar terlihat seperti orang lain. Ini adalah penyamaran.', 'Ubah pakaian Anda agar terlihat seperti orang lain. Ini adalah penyamaran.') ON CONFLICT (id) DO NOTHING;
