INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cfcf49e7-92cb-4dd8-9ff4-26547837f48b', 'vocabulary', '服装', '服装', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Pakaianmu yang mendandanimu adalah pakaianmu. Begitulah cara Anda berpakaian.', 'Pakaianmu yang mendandanimu adalah pakaianmu. Begitulah cara Anda berpakaian.') ON CONFLICT (id) DO NOTHING;
