INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d8f7193-eb49-4130-9918-3040fdf98318', 'vocabulary', '諸々', '諸々', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Anda memiliki berbagai hal yang berbeda. Mereka bermacam-macam. Anda memiliki semua jenisnya.', 'Anda memiliki berbagai hal yang berbeda. Mereka bermacam-macam. Anda memiliki semua jenisnya.') ON CONFLICT (id) DO NOTHING;
