INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('09e7be3a-2132-439a-ba04-d03c78de3471', 'またかよ。女はすぐ昔の話を蒸し返すよな。やってられないわ。', 'Ini dia lagi. Anak perempuan selalu mengungkit masalah lama. Saya tidak ingin menghadapi hal itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('315a91f9-d058-40af-b4f7-778276fd1b40', 'vocabulary', '装う', '装う', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Jika Anda berpakaian sendiri, Anda menutupi siapa diri Anda dan mencoba menjadi orang lain. Anda mencoba berpura-pura. Anda mencoba untuk berbohong. Anda mencoba berpura-pura.', 'Jika Anda berpakaian sendiri, Anda menutupi siapa diri Anda dan mencoba menjadi orang lain. Anda mencoba berpura-pura. Anda mencoba untuk berbohong. Anda mencoba berpura-pura.') ON CONFLICT (id) DO NOTHING;
