INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('b7476933-db77-492f-8500-e6203fd4d4e4', 'シャツを入れないと、お客さんに甘く見られるかもしれないよ。', 'Selipkan baju Anda atau klien Anda mungkin tidak menganggap Anda serius.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('19a4cb31-8093-4186-b43e-c55d7d936164', 'vocabulary', '甘党', '甘党', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Kelompok manis adalah sekelompok orang yang menyukai hal-hal manis. Mereka benar-benar menyukai makanan manis.', 'Kelompok manis adalah sekelompok orang yang menyukai hal-hal manis. Mereka benar-benar menyukai makanan manis.') ON CONFLICT (id) DO NOTHING;
