INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('07b3017b-481d-4495-b055-9e683540b7ca', 'vocabulary', '換気', '換気', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Sesuatu yang akan menukarkan energi adalah sesuatu yang menarik udara, mengeluarkan benda-benda buruk, dan kemudian mengeluarkan udara baik, menukarnya dengan udara buruk. Itu adalah ventilasi.', 'Sesuatu yang akan menukarkan energi adalah sesuatu yang menarik udara, mengeluarkan benda-benda buruk, dan kemudian mengeluarkan udara baik, menukarnya dengan udara buruk. Itu adalah ventilasi.') ON CONFLICT (id) DO NOTHING;
