INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('204e4261-b0de-49fe-85f9-a849a2e8dc92', 'vocabulary', '貿易会社', '貿易会社', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Perusahaan dagang (貿易) (会社) adalah perusahaan yang banyak melakukan perdagangan, karena mudahnya mereka menjadikan kata ini sebagai perusahaan dagang.', 'Perusahaan dagang (貿易) (会社) adalah perusahaan yang banyak melakukan perdagangan, karena mudahnya mereka menjadikan kata ini sebagai perusahaan dagang.') ON CONFLICT (id) DO NOTHING;
