INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d218f317-51c1-45f2-90b2-4f69d2f09e1b', '新宿駅で中央線から山手線に乗り換えて上野駅まで来てください。', 'Datanglah ke Stasiun Ueno dengan transfer dari Chuo Line ke Yamanote Line di stasiun Shinjuku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d218f317-51c1-45f2-90b2-4f69d2f09e1b', '飛行機をうまく乗り換えることができるかどうか心配しています。', 'Saya khawatir tentang seberapa baik saya bisa berpindah pesawat.') ON CONFLICT DO NOTHING;
