INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('037a68d1-701b-43ae-9edc-23b54622b448', 'vocabulary', '伸ばす', '伸ばす', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Jika 伸びる berarti "diregangkan" maka 伸ばす berarti meregangkan sesuatu, di mana Anda melakukan peregangan. Anda mengetahui hal ini karena Anda naik bus dan merentangkannya menjadi bus yang lebih panjang.', 'Jika 伸びる berarti "diregangkan" maka 伸ばす berarti meregangkan sesuatu, di mana Anda melakukan peregangan. Anda mengetahui hal ini karena Anda naik bus dan merentangkannya menjadi bus yang lebih panjang.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('037a68d1-701b-43ae-9edc-23b54622b448', 'Untuk Meregangkan Sesuatu', true) ON CONFLICT DO NOTHING;
