INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('037a68d1-701b-43ae-9edc-23b54622b448', '子供がいたずらでゴムを伸ばしすぎて使い物にならなくなりました。', 'Anak saya dengan nakal meregangkan karet elastis secara berlebihan dan membuatnya tidak dapat digunakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('037a68d1-701b-43ae-9edc-23b54622b448', '祖母は死ぬ間際、私の顔に手を伸ばし、「愛してるよ」と言ってくれました。', 'Nenekku mengulurkan tangannya ke wajahku dan mengatakan padaku, "Aku mencintaimu," tepat sebelum dia meninggal.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('218d72b2-a23c-414a-811e-afc8160a753e', 'vocabulary', '換える', '換える', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Kanjinya adalah pertukaran, jadi kata kerja ini adalah pertukaran. Jika Anda menukar suatu barang dengan barang lain, Anda akan menukarnya. Kata ini mengacu pada menukar satu barang dengan barang serupa.', 'Kanjinya adalah pertukaran, jadi kata kerja ini adalah pertukaran. Jika Anda menukar suatu barang dengan barang lain, Anda akan menukarnya. Kata ini mengacu pada menukar satu barang dengan barang serupa.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('218d72b2-a23c-414a-811e-afc8160a753e', 'Untuk Bertukar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('218d72b2-a23c-414a-811e-afc8160a753e', 'かえる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('218d72b2-a23c-414a-811e-afc8160a753e', '一つ大きいサイズの靴に換えてもらえませんか。', 'Bisakah Anda menukarkan sepatu ini dengan sepasang yang ukurannya satu lebih besar?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('79882992-27ce-45de-b63d-462852f7b388', 'vocabulary', '大幅', '大幅', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Sesuatu yang lebarnya besar tetaplah besar, bahkan ukurannya cukup besar.', 'Sesuatu yang lebarnya besar tetaplah besar, bahkan ukurannya cukup besar.') ON CONFLICT (id) DO NOTHING;
