INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('79882992-27ce-45de-b63d-462852f7b388', '会議の資料が大幅に変更されました。', 'Dokumen pertemuan tersebut sebagian besar telah diubah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('082dec72-3328-4ab6-b3ad-51ddaa7b2784', 'vocabulary', '欠伸', '欠伸', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Ketika Anda kurang melakukan peregangan, tubuh Anda harus mengeluarkan energi tersebut, sehingga Anda akhirnya menguap.', 'Ketika Anda kurang melakukan peregangan, tubuh Anda harus mengeluarkan energi tersebut, sehingga Anda akhirnya menguap.') ON CONFLICT (id) DO NOTHING;
