INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('89a8112d-062d-4352-a97e-6a04bb4ff34c', 'vocabulary', '武装', '武装', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Bagian terpenting dari pakaian militer Anda adalah lengan Anda (bukan yang melekat pada tubuh Anda, senjata Anda, dan sebagainya). Senjata itulah yang membuat Anda menjadi orang militer sejati.', 'Bagian terpenting dari pakaian militer Anda adalah lengan Anda (bukan yang melekat pada tubuh Anda, senjata Anda, dan sebagainya). Senjata itulah yang membuat Anda menjadi orang militer sejati.') ON CONFLICT (id) DO NOTHING;
