INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4962c54d-a7f6-4be8-a173-6e570799785d', 'vocabulary', '石油', '石油', 2, '5e4f9a6b-7c8d-9e0f-1a2b-3c4d5e6f7a8b', 'Minyak yang didalamnya terdapat batu-batuan, berasal dari dalam tanah. Ini bukan minyak zaitun, tapi minyak bumi!', 'Minyak yang didalamnya terdapat batu-batuan, berasal dari dalam tanah. Ini bukan minyak zaitun, tapi minyak bumi!') ON CONFLICT (id) DO NOTHING;
