INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ba28321a-2b21-4343-8f11-2342a9ce5149', 'vocabulary', '超〜', '超〜', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Ini memiliki arti yang sama dengan kanji. Tempelkan ini ke kata lain dan Anda akan mendapatkan "ultra _____".', 'Ini memiliki arti yang sama dengan kanji. Tempelkan ini ke kata lain dan Anda akan mendapatkan "ultra _____".') ON CONFLICT (id) DO NOTHING;
