INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ba28321a-2b21-4343-8f11-2342a9ce5149', '今超貧乏でさ〜。砂糖も切らしてるんだけど、それすら新しいの買えないんだわ。', 'Saya sangat bangkrut sekarang. Saya kehabisan gula dan saya bahkan tidak bisa membeli lebih banyak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('697de9c0-4cff-43fc-b10b-362cedf2e2dd', 'vocabulary', '超自然的', '超自然的', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Sesuatu yang sangat alami (自然的) bersifat supranatural. Terlalu alami! Super!', 'Sesuatu yang sangat alami (自然的) bersifat supranatural. Terlalu alami! Super!') ON CONFLICT (id) DO NOTHING;
