INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('697de9c0-4cff-43fc-b10b-362cedf2e2dd', 'そういえば、私の超自然的な力についてお話したことってありましたっけ？', 'Pernahkah saya bercerita tentang kesaktian saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a18012ec-a5c9-4e78-b304-55045f6dcfe4', 'vocabulary', '超音速', '超音速-6013', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Suara super yang cepat adalah kecepatan supersonik.', 'Suara super yang cepat adalah kecepatan supersonik.') ON CONFLICT (id) DO NOTHING;
