INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a18012ec-a5c9-4e78-b304-55045f6dcfe4', '僕のパンダロボットは、超音速で空を飛べるんだぜ。', 'Robot panda saya bisa terbang dengan kecepatan supersonik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('bef76460-d22f-42c3-aa64-9ea030c1fca8', 'vocabulary', '超音波', '超音波', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Gelombang suara ultra adalah gelombang ultrasonik.', 'Gelombang suara ultra adalah gelombang ultrasonik.') ON CONFLICT (id) DO NOTHING;
