INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bef76460-d22f-42c3-aa64-9ea030c1fca8', '超音波なら脂肪細胞を永久に破壊することができると言われたので、この3000ドルもする機械を買ったんですよ。', 'Saya diberitahu bahwa gelombang ultrasonik menghancurkan sel-sel lemak secara permanen, jadi saya membeli mesin ini seharga $3.000.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5cb7f3ac-2cbb-435e-bb79-b642c57186ea', 'vocabulary', '依頼', '依頼', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Saya bergantung pada Anda dan saya percaya Anda. Oleh karena itu, aku punya permintaan untukmu yang ingin aku percayakan padamu.', 'Saya bergantung pada Anda dan saya percaya Anda. Oleh karena itu, aku punya permintaan untukmu yang ingin aku percayakan padamu.') ON CONFLICT (id) DO NOTHING;
