INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c5f5d544-3a5c-473f-914b-eb331b043904', 'vocabulary', '傾く', '傾く', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bersandar, dan versi vocab verbanya artinya bersandar atau miring. Anda tidak sedang mencondongkan atau memiringkan, Anda hanya menonton, itulah sebabnya Anda mengatakan "keren" (く) ketika Anda melihatnya, karena sudah selesai.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya bersandar, dan versi vocab verbanya artinya bersandar atau miring. Anda tidak sedang mencondongkan atau memiringkan, Anda hanya menonton, itulah sebabnya Anda mengatakan "keren" (く) ketika Anda melihatnya, karena sudah selesai.') ON CONFLICT (id) DO NOTHING;
