INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7d3808bb-fd62-4abe-bdfc-cb6f86ced55e', 'vocabulary', '奥さん', '奥さん', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Orang dalam (kehormatan さん menunjukkan seseorang) adalah orang yang berdiri di bagian dalam rumah dan tidak keluar, menjadikan orang itu istri Anda. Aduh. Kanji seksis muncul lagi.', 'Orang dalam (kehormatan さん menunjukkan seseorang) adalah orang yang berdiri di bagian dalam rumah dan tidak keluar, menjadikan orang itu istri Anda. Aduh. Kanji seksis muncul lagi.') ON CONFLICT (id) DO NOTHING;
