INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ebd0269a-ef79-4745-92dd-e03280c8102e', 'vocabulary', '贈る', '贈る', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti hadiah, jadi jika Anda memberikan hadiah, Anda memberikannya, menjadikannya sebagai hadiah.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti hadiah, jadi jika Anda memberikan hadiah, Anda memberikannya, menjadikannya sebagai hadiah.') ON CONFLICT (id) DO NOTHING;
