INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('cbe6ba45-d118-4b13-8c3a-fd8f8ec34639', 'vocabulary', '超す', '超す', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya ultra atau super, jadi versi verbanya adalah apa yang terjadi ketika Anda melakukan sesuatu yang ultra atau super. Anda mulai melebihi jumlah yang seharusnya Anda lakukan. Jika Anda mengendarai mobil secara ultra, Anda melebihi batas kecepatan. Jika Anda terlalu banyak belajar, Anda melebihi kapasitas otak Anda. Mengerti?', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya ultra atau super, jadi versi verbanya adalah apa yang terjadi ketika Anda melakukan sesuatu yang ultra atau super. Anda mulai melebihi jumlah yang seharusnya Anda lakukan. Jika Anda mengendarai mobil secara ultra, Anda melebihi batas kecepatan. Jika Anda terlalu banyak belajar, Anda melebihi kapasitas otak Anda. Mengerti?') ON CONFLICT (id) DO NOTHING;
