INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('69f41267-f29b-400b-8927-32b573ff5569', 'vocabulary', '鋭利', '鋭利', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Sesuatu yang tajam akan mendapat manfaat dari ketajamannya, karena hanya itu yang dimilikinya, kok.', 'Sesuatu yang tajam akan mendapat manfaat dari ketajamannya, karena hanya itu yang dimilikinya, kok.') ON CONFLICT (id) DO NOTHING;
