INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8904971d-8717-465f-8ec8-2fe08a53edf0', 'vocabulary', '新鋭', '新鋭', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Sesuatu yang baru dan tajam (mungkin karena sangat baru) sedang menjadi yang terdepan. Ini sedang naik daun, hal besar berikutnya!', 'Sesuatu yang baru dan tajam (mungkin karena sangat baru) sedang menjadi yang terdepan. Ini sedang naik daun, hal besar berikutnya!') ON CONFLICT (id) DO NOTHING;
