INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('888b045c-bd81-4ee2-a25e-e93700d1174e', 'vocabulary', '〜殿', '〜殿', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Kanjinya berarti tuanku, dan kata ini dulunya merupakan akhiran nama yang mirip dengan gelar bahasa Inggris Lord, namun saat ini lebih dekat dengan Mr. Jika ragu, lebih baik Anda memilih nama ender 様 karena lebih banyak digunakan, dan juga lebih sopan dibandingkan 殿.', 'Kanjinya berarti tuanku, dan kata ini dulunya merupakan akhiran nama yang mirip dengan gelar bahasa Inggris Lord, namun saat ini lebih dekat dengan Mr. Jika ragu, lebih baik Anda memilih nama ender 様 karena lebih banyak digunakan, dan juga lebih sopan dibandingkan 殿.') ON CONFLICT (id) DO NOTHING;
