INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fa4ce942-f731-4727-a6e2-4b3820d46a98', '暇つぶしにイケメンの殿様の絵を描きました。', 'Saya menggambar tuan feodal yang tampan untuk membuang waktu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f926d7c-1714-4475-a96f-b02ca28f2db2', 'vocabulary', '殿堂', '殿堂', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Aula Tuanku adalah tempat yang bagus. Di sanalah seorang bangsawan akan tinggal. Sebuah istana. Lebih jauh lagi, ini juga bisa berarti tempat perlindungan, dan bahkan hall of fame.', 'Aula Tuanku adalah tempat yang bagus. Di sanalah seorang bangsawan akan tinggal. Sebuah istana. Lebih jauh lagi, ini juga bisa berarti tempat perlindungan, dan bahkan hall of fame.') ON CONFLICT (id) DO NOTHING;
