INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f926d7c-1714-4475-a96f-b02ca28f2db2', 'その殿堂の屋根は、たくさんの柱で支えられています。', 'Atap istana ditopang oleh banyak tiang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f926d7c-1714-4475-a96f-b02ca28f2db2', '東大は学問の殿堂と言われています。', 'Universitas Tokyo dikatakan sebagai tempat perlindungan pembelajaran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f926d7c-1714-4475-a96f-b02ca28f2db2', 'お前にとって、殿堂入りを果たした選手といえば、誰になる？', 'Menurut Anda, siapa pemain yang harus dilantik ke dalam hall of fame?') ON CONFLICT DO NOTHING;
