INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('83933b3b-794d-4b34-82b3-2d58ed76c478', 'vocabulary', '埋もれる', '埋もれる', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', 'Anda tahu bahwa 埋める berarti "mengubur". Kata kerjanya adalah dikuburkan atau dikuburkan. Anda mengetahui hal ini karena lebih jarang (もれる) dikuburkan dibandingkan Anda menguburkan orang lain. Sejujurnya, Anda hanya bisa dikuburkan sekali saja, karena Anda mungkin akan mati.', 'Anda tahu bahwa 埋める berarti "mengubur". Kata kerjanya adalah dikuburkan atau dikuburkan. Anda mengetahui hal ini karena lebih jarang (もれる) dikuburkan dibandingkan Anda menguburkan orang lain. Sejujurnya, Anda hanya bisa dikuburkan sekali saja, karena Anda mungkin akan mati.') ON CONFLICT (id) DO NOTHING;
