INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('728e4f16-e9f1-4d8a-aeaf-d6c796d9588c', 'vocabulary', '埋め合わせる', '埋め合わせる', 2, '6f5a0b7c-8d9e-0f1a-2b3c-4d5e6f7a8b9c', '埋める berarti "mengubur". 合わせる berarti "menyatukan bersama". Jika Anda mengubur seseorang untuk menyatukan mereka dengan Anda, Anda hampir pasti mencoba memberikan kompensasi atas sesuatu.', '埋める berarti "mengubur". 合わせる berarti "menyatukan bersama". Jika Anda mengubur seseorang untuk menyatukan mereka dengan Anda, Anda hampir pasti mencoba memberikan kompensasi atas sesuatu.') ON CONFLICT (id) DO NOTHING;
