INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('8de24883-9afa-4649-b094-d101b17f1829', 'radical', '広', 'wide', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Radikal ini sama dengan kanji. Artinya luas.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('8de24883-9afa-4649-b094-d101b17f1829', 'Lebar', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('bcb0b9e1-963a-4d2f-b6bc-4db1752d6ea6', 'radical', '出', 'exit', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Radikal ini sama dengan kanji. Artinya keluar.') ON CONFLICT (id) DO NOTHING;
