INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('669e9b34-2597-40a1-8095-15e6b22e4160', 'radical', '耒', 'plow', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Anda menggeser tanah dengan pohon yang Anda tebang. Alat yang Anda buat ini disebut bajak. Gunakan untuk mendorong kotoran!') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('669e9b34-2597-40a1-8095-15e6b22e4160', 'Bajak', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('cbeb105c-adf1-44e1-bc97-ac2c0805b038', 'radical', '冘', 'pirate', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Ini terlihat seperti besar (大), yang menurut saya Anda akan ingat bahwa Anda mempelajarinya dengan berpura-pura ini adalah orang besar. Namun pria besar ini mempunyai kaki yang lucu... kaki pasak. Itu membuatnya menjadi bajak laut. Selain itu, lengannya berada pada posisi "YARRRR".') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('cbeb105c-adf1-44e1-bc97-ac2c0805b038', 'Bajak laut', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('3bbccf98-7661-4fd3-93d5-080a4deb406d', 'radical', '缶', 'can', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Agak sulit untuk melihatnya, tetapi jika Anda melihatnya dengan benar, ini terlihat seperti kaleng. Garis di tengah menunjukkan keliling, dan garis di bagian atas dan samping menunjukkan garis luar kaleng.') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3bbccf98-7661-4fd3-93d5-080a4deb406d', 'Bisa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('74644584-95ad-4e39-a889-ccc02c1628c5', 'radical', '更', 'again', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Radikal ini sama dengan kanji. Artinya lagi.') ON CONFLICT (id) DO NOTHING;
