INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8930d576-4870-43f4-9ae8-6b10296aa107', '自分が六歳の子どもだってことは分かってたけど、父さんが勝手に封を開けて友達からの手紙を読んだことにはすごく腹が立ったわ。', 'Aku tahu aku hanyalah seorang anak berusia 6 tahun, tapi aku menjadi sangat marah ketika ayahku membuka amplop dan membaca surat dari temanku tanpa bertanya terlebih dahulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2856b087-2d26-43a8-8720-6cb333290775', 'vocabulary', '開封', '開封', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Bukalah surat yang sudah tersegel, maka menjadi surat yang tidak tersegel.', 'Bukalah surat yang sudah tersegel, maka menjadi surat yang tidak tersegel.') ON CONFLICT (id) DO NOTHING;
