INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2531f933-8d92-4b3c-9db3-6369b71e0d08', '契約書にサインをして封筒に入れてありますが、まだその封書を郵送していません。', 'Saya menandatangani kontrak dan memasukkannya ke dalam amplop, tetapi saya belum mengirimkan surat tersegelnya kepada mereka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e1c4d7ba-b519-4fbf-a319-a11ed5d6ebd7', 'vocabulary', '封筒', '封筒', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Segel di dalam silinder. Silinder yang disegel ini adalah sebuah amplop. Anda hanya perlu mengingat kembali hari itu, ketika segala sesuatunya lebih seperti dalam bentuk gulungan. Jadi, amplop gulungan akan berbentuk seperti silinder, menjadikannya sebuah amplop.', 'Segel di dalam silinder. Silinder yang disegel ini adalah sebuah amplop. Anda hanya perlu mengingat kembali hari itu, ketika segala sesuatunya lebih seperti dalam bentuk gulungan. Jadi, amplop gulungan akan berbentuk seperti silinder, menjadikannya sebuah amplop.') ON CONFLICT (id) DO NOTHING;
