INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1c4d7ba-b519-4fbf-a319-a11ed5d6ebd7', '金はきっちり人数分に山分けして、お前の取り分はその封筒に入れておいたぜ。', 'Kami membagi uangnya dan memasukkan bagian Anda ke dalam amplop.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2aa53afe-eedd-4050-9374-e025d261f77e', 'vocabulary', '筒', '筒', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Anda akan melihat ini lebih sering berarti pipa daripada silinder.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Anda akan melihat ini lebih sering berarti pipa daripada silinder.') ON CONFLICT (id) DO NOTHING;
