INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('87f86b22-3668-479a-9347-0df7aa072898', 'うちの子、幼稚園のお泊まり会をすごく楽しみにしてたんだけど、風邪を引いちゃって、今抗生物質を飲ませたところなんです。だから、残念ながら今夜は欠席させて頂きます。', 'Anak saya sangat menantikan acara menginap di taman kanak-kanak, tapi dia masuk angin dan saya menyuruhnya minum antibiotik. Jadi, sayangnya, dia akan absen malam ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0eecb65a-083e-4bc9-a64c-2f3f2ebc61b3', 'vocabulary', '泊める', '泊める', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', '泊まる berarti "menginap." Sekarang Anda mengizinkan orang lain menginap, yang berarti membiarkan seseorang menginap atau membiarkan seseorang menginap.', '泊まる berarti "menginap." Sekarang Anda mengizinkan orang lain menginap, yang berarti membiarkan seseorang menginap atau membiarkan seseorang menginap.') ON CONFLICT (id) DO NOTHING;
