INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6e912a27-035d-4e00-b237-b5d626a3613a', 'vocabulary', '辛い', '辛い', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Meskipun demikian, ini juga bisa berarti sulit atau menyakitkan. Saya kira jika Anda berada dalam situasi yang pedas, itu akan menjadi situasi yang sulit.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Meskipun demikian, ini juga bisa berarti sulit atau menyakitkan. Saya kira jika Anda berada dalam situasi yang pedas, itu akan menjadi situasi yang sulit.') ON CONFLICT (id) DO NOTHING;
