INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f04c160d-3308-477b-82d6-bc55fcbefc8d', 'vocabulary', '香辛料', '香辛料', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Biaya untuk wewangian dan pedas dalam makananmu adalah biaya rempah-rempah. Jika kamu tidak membayar biaya rempah-rempah, kamu tidak akan memiliki bumbu atau wewangian apa pun dalam makananmu. Jika ya, kamu akan mendapatkan hal-hal itu dan makananmu akan enak!', 'Biaya untuk wewangian dan pedas dalam makananmu adalah biaya rempah-rempah. Jika kamu tidak membayar biaya rempah-rempah, kamu tidak akan memiliki bumbu atau wewangian apa pun dalam makananmu. Jika ya, kamu akan mendapatkan hal-hal itu dan makananmu akan enak!') ON CONFLICT (id) DO NOTHING;
