INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1670bb90-ddb2-4de4-8614-961fb2cb5b40', '窓の曇りが中々とれない。', 'Saya mengalami masalah saat menghilangkan kabut pada jendela.') ON CONFLICT DO NOTHING;
