INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0d88ef1d-cc3a-4ed0-b721-e8beaf8cd28b', 'vocabulary', '歯を磨く', '歯を磨く', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', '磨く adalah "memoles" atau "bersinar". Jika Anda melakukan itu pada gigi Anda, Anda sedang menyikatnya. Itu sebabnya ini untuk menyikat gigi.', '磨く adalah "memoles" atau "bersinar". Jika Anda melakukan itu pada gigi Anda, Anda sedang menyikatnya. Itu sebabnya ini untuk menyikat gigi.') ON CONFLICT (id) DO NOTHING;
