INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9912e616-5104-4e50-98b3-b31381506daf', 'vocabulary', '辛口', '辛口', 2, '7a6b1c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d', 'Jika Anda memasukkan sesuatu yang pedas ke dalam mulut Anda, Anda akan mendapatkan rasa pedas atau rasa kering di sana. Rempah-rempah menyedot semua kelembapan mulut Anda.', 'Jika Anda memasukkan sesuatu yang pedas ke dalam mulut Anda, Anda akan mendapatkan rasa pedas atau rasa kering di sana. Rempah-rempah menyedot semua kelembapan mulut Anda.') ON CONFLICT (id) DO NOTHING;
