INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('83b7844e-528c-447d-b909-8f200cab2df9', '祖母は財布の中に硬貨を貯めていました。', 'Nenek saya menyimpan koin di dompetnya.') ON CONFLICT DO NOTHING;
