INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3b4d9e39-0435-4842-88eb-a7255fb14a62', 'vocabulary', '〜畳', '〜畳', 2, '8b7c2d9e-0f1a-2b3c-4d5e-6f7a8b9c0d1e', 'Huruf 〜 menunjukkan jumlah tikar tatami, dan bagian 畳 tentu saja adalah "tatami". Jadi, ini adalah counter untuk tikar tatami. Biasanya digunakan untuk menunjukkan seberapa besar sebuah apartemen atau sesuatu. Oh, apartemenmu 12 tikar tatami? Bagus dan besar!', 'Huruf 〜 menunjukkan jumlah tikar tatami, dan bagian 畳 tentu saja adalah "tatami". Jadi, ini adalah counter untuk tikar tatami. Biasanya digunakan untuk menunjukkan seberapa besar sebuah apartemen atau sesuatu. Oh, apartemenmu 12 tikar tatami? Bagus dan besar!') ON CONFLICT (id) DO NOTHING;
