INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68eff1ab-48d6-4918-8c73-54a1ccc374e8', 'vocabulary', '賢人', '賢人', 2, '8b7c2d9e-0f1a-2b3c-4d5e-6f7a8b9c0d1e', 'Orang yang pandai adalah orang yang bijaksana atau orang yang bijaksana. Kata ini mempunyai kesan yang cukup kuno, jadi Anda sering melihatnya di cerita-cerita lama!', 'Orang yang pandai adalah orang yang bijaksana atau orang yang bijaksana. Kata ini mempunyai kesan yang cukup kuno, jadi Anda sering melihatnya di cerita-cerita lama!') ON CONFLICT (id) DO NOTHING;
