INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('45ec7029-a7c7-4455-acef-9781210ef1f8', 'vocabulary', '咲く', '咲く', 2, '8b7c2d9e-0f1a-2b3c-4d5e-6f7a8b9c0d1e', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mekar atau mekar dan versi kata kerjanya adalah mekar.', 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti mekar atau mekar dan versi kata kerjanya adalah mekar.') ON CONFLICT (id) DO NOTHING;
