INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8ed6ba0-beab-409f-921d-8f17e7938caf', 'vocabulary', '返り咲き', '返り咲き', 2, '8b7c2d9e-0f1a-2b3c-4d5e-6f7a8b9c0d1e', 'Bunga kembali adalah saat bunga kembali mekar. Mekar kedua. Ini adalah kata lain dari kembalinya.', 'Bunga kembali adalah saat bunga kembali mekar. Mekar kedua. Ini adalah kata lain dari kembalinya.') ON CONFLICT (id) DO NOTHING;
