INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4d5613b1-1924-41da-b771-91db5e12857e', 'vocabulary', '悪賢い', '悪賢い', 2, '8b7c2d9e-0f1a-2b3c-4d5e-6f7a8b9c0d1e', 'Seseorang yang jahat tetapi juga pintar (賢い) adalah seseorang yang menggunakan kepintarannya untuk kejahatan. Ketika Anda menyebut orang jahat yang pandai, biasanya Anda menggambarkan mereka bukan sebagai "pintar" tetapi sebagai orang yang licik, licik, atau hal lainnya.', 'Seseorang yang jahat tetapi juga pintar (賢い) adalah seseorang yang menggunakan kepintarannya untuk kejahatan. Ketika Anda menyebut orang jahat yang pandai, biasanya Anda menggambarkan mereka bukan sebagai "pintar" tetapi sebagai orang yang licik, licik, atau hal lainnya.') ON CONFLICT (id) DO NOTHING;
