INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c125fe29-8906-4bf0-991b-65df8e74f636', 'vocabulary', '肯定', '肯定', 2, '8b7c2d9e-0f1a-2b3c-4d5e-6f7a8b9c0d1e', 'Anda bertekad untuk mendapatkan persetujuan dari orang lain sehingga Anda memutuskan untuk bersikap positif terhadap mereka. Selama Anda membuatnya tampak seolah segala sesuatunya luar biasa, dan sangat baik bagi mereka, mereka pada akhirnya akan setuju dengan semua yang Anda katakan.', 'Anda bertekad untuk mendapatkan persetujuan dari orang lain sehingga Anda memutuskan untuk bersikap positif terhadap mereka. Selama Anda membuatnya tampak seolah segala sesuatunya luar biasa, dan sangat baik bagi mereka, mereka pada akhirnya akan setuju dengan semua yang Anda katakan.') ON CONFLICT (id) DO NOTHING;
