INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d5c7eba-d612-4659-97de-6cd67267bb3e', 'おならをした瞬間、目から涙が零れた。', 'Saat saya kentut, setetes air mata jatuh dari mata saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d5c7eba-d612-4659-97de-6cd67267bb3e', 'ソファに紅茶が零れてるんだけど！誰が犯人だ？', 'Seseorang menumpahkan teh di sofa! Siapa yang bersalah?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5d5c7eba-d612-4659-97de-6cd67267bb3e', '窓から美しいメロディが零れてきた。', 'Melodi yang indah keluar dari jendela.') ON CONFLICT DO NOTHING;
